window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["GEN"]={"book":"GEN","editions":{"epo-londona":[[1,1,"En la komenco Dio kreis la ĉielon kaj la teron.","En la komenco Dio kreis la ĉielon kaj la teron."],[1,2,"Kaj la tero estis senforma kaj dezerta, kaj mallumo estis super la abismo; kaj la spirito de Dio ŝvebis super la akvo.","Kaj la tero estis senforma kaj dezerta, kaj mallumo estis super la abismo; kaj la spirito de Dio ŝvebis super la akvo."],[1,3,"Kaj Dio diris: Estu lumo; kaj fariĝis lumo.","Kaj Dio diris: Estu lumo; kaj fariĝis lumo."],[1,4,"Kaj Dio vidis la lumon, ke ĝi estas bona; kaj Dio apartigis la lumon de la mallumo.","Kaj Dio vidis la lumon, ke ĝi estas bona; kaj Dio apartigis la lumon de la mallumo."],[1,5,"Kaj Dio nomis la lumon Tago, kaj la mallumon Li nomis Nokto. Kaj estis vespero, kaj estis mateno, unu tago.","Kaj Dio nomis la lumon Tago, kaj la mallumon Li nomis Nokto. Kaj estis vespero, kaj estis mateno, unu tago."],[1,6,"Kaj Dio diris: Estu firmaĵo inter la akvo, kaj ĝi apartigu akvon de akvo.","Kaj Dio diris: Estu firmaĵo inter la akvo, kaj ĝi apartigu akvon de akvo."],[1,7,"Kaj Dio kreis la firmaĵon, kaj apartigis la akvon, kiu estas sub la firmaĵo, de la akvo, kiu estas super la firmaĵo; kaj fariĝis tiel.","Kaj Dio kreis la firmaĵon, kaj apartigis la akvon, kiu estas sub la firmaĵo, de la akvo, kiu estas super la firmaĵo; kaj fariĝis tiel."],[1,8,"Kaj Dio nomis la firmaĵon Ĉielo. Kaj estis vespero, kaj estis mateno, la dua tago.","Kaj Dio nomis la firmaĵon Ĉielo. Kaj estis vespero, kaj estis mateno, la dua tago."],[1,9,"Kaj Dio diris: Kolektiĝu la akvo de sub la ĉielo en unu lokon, kaj aperu la sekaĵo; kaj fariĝis tiel.","Kaj Dio diris: Kolektiĝu la akvo de sub la ĉielo en unu lokon, kaj aperu la sekaĵo; kaj fariĝis tiel."],[1,10,"Kaj Dio nomis la sekaĵon Tero, kaj la kolektiĝojn de la akvo Li nomis Maroj. Kaj Dio vidis, ke ĝi estas bona.","Kaj Dio nomis la sekaĵon Tero, kaj la kolektiĝojn de la akvo Li nomis Maroj. Kaj Dio vidis, ke ĝi estas bona."],[1,11,"Kaj Dio diris: Kreskigu la tero verdaĵon, herbon, kiu naskas semon, fruktarbon, kiu donas laŭ sia speco frukton, kies semo estas en ĝi mem, sur la tero; kaj fariĝis tiel.","Kaj Dio diris: Kreskigu la tero verdaĵon, herbon, kiu naskas semon, fruktarbon, kiu donas laŭ sia speco frukton, kies semo estas en ĝi mem, sur la tero; kaj fariĝis tiel."],[1,12,"Kaj la tero elkreskigis verdaĵon, herbon, kiu naskas semon laŭ sia speco, kaj arbon, kiu donas frukton, kies semo estas en ĝi mem laŭ sia speco. Kaj Dio vidis, ke ĝi estas bona.","Kaj la tero elkreskigis verdaĵon, herbon, kiu naskas semon laŭ sia speco, kaj arbon, kiu donas frukton, kies semo estas en ĝi mem laŭ sia speco. Kaj Dio vidis, ke ĝi estas bona."],[1,13,"Kaj estis vespero, kaj estis mateno, la tria tago.","Kaj estis vespero, kaj estis mateno, la tria tago."],[1,14,"Kaj Dio diris: Estu lumaĵoj en la ĉiela firmaĵo, por apartigi la tagon de la nokto, kaj ili prezentu signojn, tempojn, tagojn, kaj jarojn;","Kaj Dio diris: Estu lumaĵoj en la ĉiela firmaĵo, por apartigi la tagon de la nokto, kaj ili prezentu signojn, tempojn, tagojn, kaj jarojn;"],[1,15,"kaj ili estu lumaĵoj en la ĉiela firmaĵo, por lumi super la tero; kaj fariĝis tiel.","kaj ili estu lumaĵoj en la ĉiela firmaĵo, por lumi super la tero; kaj fariĝis tiel."],[1,16,"Kaj Dio faris la du grandajn lumaĵojn: la pli grandan lumaĵon, por regi la tagon, kaj la malpli grandan lumaĵon, por regi la nokton, kaj la stelojn.","Kaj Dio faris la du grandajn lumaĵojn: la pli grandan lumaĵon, por regi la tagon, kaj la malpli grandan lumaĵon, por regi la nokton, kaj la stelojn."],[1,17,"Kaj Dio starigis ilin sur la ĉiela firmaĵo, por ke ili lumu sur la teron,","Kaj Dio starigis ilin sur la ĉiela firmaĵo, por ke ili lumu sur la teron,"],[1,18,"kaj por ke ili regu la tagon kaj la nokton kaj faru diferencon inter la lumo kaj la mallumo. Kaj Dio vidis, ke ĝi estas bona.","kaj por ke ili regu la tagon kaj la nokton kaj faru diferencon inter la lumo kaj la mallumo. Kaj Dio vidis, ke ĝi estas bona."],[1,19,"Kaj estis vespero, kaj estis mateno, la kvara tago.","Kaj estis vespero, kaj estis mateno, la kvara tago."],[1,20,"Kaj Dio diris: La akvo aperigu moviĝantaĵojn, vivajn estaĵojn, kaj birdoj ekflugu super la tero, sub la ĉiela firmaĵo.","Kaj Dio diris: La akvo aperigu moviĝantaĵojn, vivajn estaĵojn, kaj birdoj ekflugu super la tero, sub la ĉiela firmaĵo."],[1,21,"Kaj Dio kreis la grandajn balenojn, kaj ĉiujn vivajn estaĵojn moviĝantajn, kiujn aperigis la akvo, laŭ ilia speco, kaj ĉiujn flugilhavajn birdojn laŭ ilia speco. Kaj Dio vidis, ke ĝi estas bona.","Kaj Dio kreis la grandajn balenojn, kaj ĉiujn vivajn estaĵojn moviĝantajn, kiujn aperigis la akvo, laŭ ilia speco, kaj ĉiujn flugilhavajn birdojn laŭ ilia speco. Kaj Dio vidis, ke ĝi estas bona."],[1,22,"Kaj Dio ilin benis, dirante: Fruktu kaj multiĝu, kaj plenigu la akvon en la maroj, kaj la birdoj multiĝu sur la tero.","Kaj Dio ilin benis, dirante: Fruktu kaj multiĝu, kaj plenigu la akvon en la maroj, kaj la birdoj multiĝu sur la tero."],[1,23,"Kaj estis vespero, kaj estis mateno, la kvina tago.","Kaj estis vespero, kaj estis mateno, la kvina tago."],[1,24,"Kaj Dio diris: La tero aperigu vivajn estaĵojn, laŭ ilia speco, brutojn kaj rampaĵojn kaj surterajn bestojn, laŭ ilia speco; kaj fariĝis tiel.","Kaj Dio diris: La tero aperigu vivajn estaĵojn, laŭ ilia speco, brutojn kaj rampaĵojn kaj surterajn bestojn, laŭ ilia speco; kaj fariĝis tiel."],[1,25,"Kaj Dio kreis la bestojn de la tero, laŭ ilia speco, kaj la brutojn, laŭ ilia speco, kaj ĉiujn rampaĵojn de la tero, laŭ ilia speco. Kaj Dio vidis, ke ĝi estas bona.","Kaj Dio kreis la bestojn de la tero, laŭ ilia speco, kaj la brutojn, laŭ ilia speco, kaj ĉiujn rampaĵojn de la tero, laŭ ilia speco. Kaj Dio vidis, ke ĝi estas bona."],[1,26,"Kaj Dio diris: Ni kreu homon laŭ Nia bildo, similan al Ni; kaj ili regu super la fiŝoj de la maro kaj super la birdoj de la ĉielo kaj super la brutoj, kaj super ĉiuj rampaĵoj, kiuj rampas sur la tero.","Kaj Dio diris: Ni kreu homon laŭ Nia bildo, similan al Ni; kaj ili regu super la fiŝoj de la maro kaj super la birdoj de la ĉielo kaj super la brutoj, kaj super ĉiuj rampaĵoj, kiuj rampas sur la tero."],[1,27,"Kaj Dio kreis la homon laŭ Sia bildo, laŭ la bildo de Dio Li kreis lin; en formo de viro kaj virino Li kreis ilin.","Kaj Dio kreis la homon laŭ Sia bildo, laŭ la bildo de Dio Li kreis lin; en formo de viro kaj virino Li kreis ilin."],[1,28,"Kaj Dio benis ilin, kaj Dio diris al ili: Fruktu kaj multiĝu, kaj plenigu la teron kaj submetu ĝin al vi, kaj regu super la fiŝoj de la maro kaj super la birdoj de la ĉielo, kaj super ĉiuj bestoj, kiuj moviĝas sur la tero.","Kaj Dio benis ilin, kaj Dio diris al ili: Fruktu kaj multiĝu, kaj plenigu la teron kaj submetu ĝin al vi, kaj regu super la fiŝoj de la maro kaj super la birdoj de la ĉielo, kaj super ĉiuj bestoj, kiuj moviĝas sur la tero."],[1,29,"Kaj Dio diris: Jen Mi donis al vi ĉiujn herbojn, kiuj semas semon, kiuj troviĝas sur la tuta tero, kaj ĉiujn arbojn, kiuj havas en si arban frukton, kiu semas semon; tio estu por vi manĝaĵo.","Kaj Dio diris: Jen Mi donis al vi ĉiujn herbojn, kiuj semas semon, kiuj troviĝas sur la tuta tero, kaj ĉiujn arbojn, kiuj havas en si arban frukton, kiu semas semon; tio estu por vi manĝaĵo."],[1,30,"Kaj al ĉiuj bestoj de la tero kaj al ĉiuj birdoj de la ĉielo kaj al ĉiuj rampaĵoj sur la tero, kiuj havas en si vivan animon, la tutan verdan herbaĵon kiel manĝaĵon. Kaj fariĝis tiel.","Kaj al ĉiuj bestoj de la tero kaj al ĉiuj birdoj de la ĉielo kaj al ĉiuj rampaĵoj sur la tero, kiuj havas en si vivan animon, la tutan verdan herbaĵon kiel manĝaĵon. Kaj fariĝis tiel."],[1,31,"Kaj Dio rigardis ĉion, kion Li kreis, kaj vidis, ke ĝi estas tre bona. Kaj estis vespero, kaj estis mateno, la sesa tago.","Kaj Dio rigardis ĉion, kion Li kreis, kaj vidis, ke ĝi estas tre bona. Kaj estis vespero, kaj estis mateno, la sesa tago."],[2,1,"Kaj estis finitaj la ĉielo kaj la tero kaj ĉiuj iliaj apartenaĵoj.","Kaj estis finitaj la ĉielo kaj la tero kaj ĉiuj iliaj apartenaĵoj."],[2,2,"Kaj Dio finis en la sepa tago Sian laboron, kiun Li faris, kaj Li ripozis en la sepa tago de la tuta laboro, kiun Li faris.","Kaj Dio finis en la sepa tago Sian laboron, kiun Li faris, kaj Li ripozis en la sepa tago de la tuta laboro, kiun Li faris."],[2,3,"Kaj Dio benis la sepan tagon kaj sanktigis ĝin, ĉar en ĝi Li ripozis de Sia tuta laboro, kiun Li faris kreante.","Kaj Dio benis la sepan tagon kaj sanktigis ĝin, ĉar en ĝi Li ripozis de Sia tuta laboro, kiun Li faris kreante."],[2,4,"Tia estas la naskiĝo de la ĉielo kaj la tero, kiam ili estis kreitaj, kiam Dio la Eternulo faris la teron kaj la ĉielon.","Tia estas la naskiĝo de la ĉielo kaj la tero, kiam ili estis kreitaj, kiam Dio la Eternulo faris la teron kaj la ĉielon."],[2,5,"Kaj nenia kampa arbetaĵo ankoraŭ estis sur la tero, kaj nenia kampa herbo ankoraŭ kreskis, ĉar Dio la Eternulo ne pluvigis sur la teron, kaj ne ekzistis homo, por prilabori la teron.","Kaj nenia kampa arbetaĵo ankoraŭ estis sur la tero, kaj nenia kampa herbo ankoraŭ kreskis, ĉar Dio la Eternulo ne pluvigis sur la teron, kaj ne ekzistis homo, por prilabori la teron."],[2,6,"Sed nebulo leviĝadis de la tero kaj donadis malsekecon al la tuta supraĵo de la tero.","Sed nebulo leviĝadis de la tero kaj donadis malsekecon al la tuta supraĵo de la tero."],[2,7,"Kaj Dio la Eternulo kreis la homon el polvo de la tero, kaj Li enblovis en lian nazon spiron de vivo, kaj la homo fariĝis viva animo.","Kaj Dio la Eternulo kreis la homon el polvo de la tero, kaj Li enblovis en lian nazon spiron de vivo, kaj la homo fariĝis viva animo."],[2,8,"Kaj Dio la Eternulo plantis ĝardenon en Eden en la Oriento, kaj Li metis tien la homon, kiun Li kreis.","Kaj Dio la Eternulo plantis ĝardenon en Eden en la Oriento, kaj Li metis tien la homon, kiun Li kreis."],[2,9,"Kaj Dio la Eternulo elkreskigis el la tero ĉiun arbon ĉarman por la vido kaj bonan por la manĝo, kaj la arbon de vivo en la mezo de la ĝardeno, kaj la arbon de sciado pri bono kaj malbono.","Kaj Dio la Eternulo elkreskigis el la tero ĉiun arbon ĉarman por la vido kaj bonan por la manĝo, kaj la arbon de vivo en la mezo de la ĝardeno, kaj la arbon de sciado pri bono kaj malbono."],[2,10,"Kaj rivero eliras el Eden, por akvoprovizi la ĝardenon, kaj de tie ĝi dividiĝas kaj fariĝas kvar ĉefpartoj.","Kaj rivero eliras el Eden, por akvoprovizi la ĝardenon, kaj de tie ĝi dividiĝas kaj fariĝas kvar ĉefpartoj."],[2,11,"La nomo de unu estas Piŝon; ĝi estas tiu, kiu ĉirkaŭas la tutan landon Ĥavila, kie estas la oro.","La nomo de unu estas Piŝon; ĝi estas tiu, kiu ĉirkaŭas la tutan landon Ĥavila, kie estas la oro."],[2,12,"Kaj la oro de tiu lando estas bona; tie troviĝas bedelio kaj la ŝtono onikso.","Kaj la oro de tiu lando estas bona; tie troviĝas bedelio kaj la ŝtono onikso."],[2,13,"Kaj la nomo de la dua rivero estas Giĥon; ĝi estas tiu, kiu ĉirkaŭas la tutan landon Etiopujo.","Kaj la nomo de la dua rivero estas Giĥon; ĝi estas tiu, kiu ĉirkaŭas la tutan landon Etiopujo."],[2,14,"Kaj la nomo de la tria rivero estas Ĥidekel; ĝi estas tiu, kiu fluas antaŭ Asirio. Kaj la kvara rivero estas Eŭfrato.","Kaj la nomo de la tria rivero estas Ĥidekel; ĝi estas tiu, kiu fluas antaŭ Asirio. Kaj la kvara rivero estas Eŭfrato."],[2,15,"Kaj Dio la Eternulo prenis la homon kaj enloĝigis lin en la ĝardeno Edena, por ke li prilaboradu ĝin kaj gardu ĝin.","Kaj Dio la Eternulo prenis la homon kaj enloĝigis lin en la ĝardeno Edena, por ke li prilaboradu ĝin kaj gardu ĝin."],[2,16,"Kaj Dio la Eternulo ordonis al la homo, dirante: De ĉiu arbo de la ĝardeno vi manĝu;","Kaj Dio la Eternulo ordonis al la homo, dirante: De ĉiu arbo de la ĝardeno vi manĝu;"],[2,17,"sed de la arbo de sciado pri bono kaj malbono vi ne manĝu, ĉar en la tago, en kiu vi manĝos de ĝi, vi mortos.","sed de la arbo de sciado pri bono kaj malbono vi ne manĝu, ĉar en la tago, en kiu vi manĝos de ĝi, vi mortos."],[2,18,"Kaj Dio la Eternulo diris: Ne estas bone, ke la homo estu sola; Mi kreos al li helpanton similan al li.","Kaj Dio la Eternulo diris: Ne estas bone, ke la homo estu sola; Mi kreos al li helpanton similan al li."],[2,19,"Kaj Dio la Eternulo kreis el la tero ĉiujn bestojn de la kampo kaj ĉiujn birdojn de la ĉielo, kaj venigis ilin al la homo, por vidi, kiel li nomos ilin; kaj kiel la homo nomis ĉiun vivan estaĵon, tiel restis ĝia nomo.","Kaj Dio la Eternulo kreis el la tero ĉiujn bestojn de la kampo kaj ĉiujn birdojn de la ĉielo, kaj venigis ilin al la homo, por vidi, kiel li nomos ilin; kaj kiel la homo nomis ĉiun vivan estaĵon, tiel restis ĝia nomo."],[2,20,"Kaj la homo donis nomojn al ĉiuj brutoj kaj al la birdoj de la ĉielo kaj al ĉiuj bestoj de la kampo; sed por la homo ne troviĝis helpanto simila al li.","Kaj la homo donis nomojn al ĉiuj brutoj kaj al la birdoj de la ĉielo kaj al ĉiuj bestoj de la kampo; sed por la homo ne troviĝis helpanto simila al li."],[2,21,"Kaj Dio la Eternulo faligis profundan dormon sur la homon, kaj ĉi tiu endormiĝis; kaj Li prenis unu el liaj ripoj kaj fermis la lokon per karno.","Kaj Dio la Eternulo faligis profundan dormon sur la homon, kaj ĉi tiu endormiĝis; kaj Li prenis unu el liaj ripoj kaj fermis la lokon per karno."],[2,22,"Kaj Dio la Eternulo konstruis el la ripo, kiun Li prenis de la homo, virinon, kaj Li venigis ŝin al la homo.","Kaj Dio la Eternulo konstruis el la ripo, kiun Li prenis de la homo, virinon, kaj Li venigis ŝin al la homo."],[2,23,"Kaj la homo diris: Jen nun ŝi estas osto el miaj ostoj kaj karno el mia karno; ŝi estu nomata Virino, ĉar el Viro ŝi estas prenita.","Kaj la homo diris: Jen nun ŝi estas osto el miaj ostoj kaj karno el mia karno; ŝi estu nomata Virino, ĉar el Viro ŝi estas prenita."],[2,24,"Tial viro forlasos sian patron kaj sian patrinon, kaj aliĝos al sia edzino, kaj ili estos unu karno.","Tial viro forlasos sian patron kaj sian patrinon, kaj aliĝos al sia edzino, kaj ili estos unu karno."],[2,25,"Kaj ili ambaŭ estis nudaj, la homo kaj lia edzino, kaj ili ne hontis.","Kaj ili ambaŭ estis nudaj, la homo kaj lia edzino, kaj ili ne hontis."],[3,1,"Kaj la serpento estis pli ruza, ol ĉiuj kampaj bestoj, kiujn kreis Dio la Eternulo. Kaj ĝi diris al la virino: Ĉu Dio diris, ke vi ne manĝu de ĉiuj arboj de la ĝardeno?","Kaj la serpento estis pli ruza, ol ĉiuj kampaj bestoj, kiujn kreis Dio la Eternulo. Kaj ĝi diris al la virino: Ĉu Dio diris, ke vi ne manĝu de ĉiuj arboj de la ĝardeno?"],[3,2,"Kaj la virino diris al la serpento: La fruktojn de la arboj de la ĝardeno ni povas manĝi;","Kaj la virino diris al la serpento: La fruktojn de la arboj de la ĝardeno ni povas manĝi;"],[3,3,"sed pri la fruktoj de la arbo, kiu estas en la mezo de la ĝardeno, Dio diris: Ne manĝu ion de ili kaj ne tuŝu ilin, por ke vi ne mortu.","sed pri la fruktoj de la arbo, kiu estas en la mezo de la ĝardeno, Dio diris: Ne manĝu ion de ili kaj ne tuŝu ilin, por ke vi ne mortu."],[3,4,"Kaj la serpento diris al la virino: Ne, vi ne mortos;","Kaj la serpento diris al la virino: Ne, vi ne mortos;"],[3,5,"sed Dio scias, ke en la tago, en kiu vi manĝos ion de ili, malfermiĝos viaj okuloj kaj vi estos kiel Dio, vi scios bonon kaj malbonon.","sed Dio scias, ke en la tago, en kiu vi manĝos ion de ili, malfermiĝos viaj okuloj kaj vi estos kiel Dio, vi scios bonon kaj malbonon."],[3,6,"Kaj la virino vidis, ke la arbo estas bona por manĝi kaj ĝi estas ĉarma por la okuloj, kaj la arbo estas dezirinda por saĝiĝi; kaj ŝi prenis de ĝiaj fruktoj, kaj ŝi manĝis, kaj ŝi donis kune ankaŭ al sia edzo, kaj li manĝis.","Kaj la virino vidis, ke la arbo estas bona por manĝi kaj ĝi estas ĉarma por la okuloj, kaj la arbo estas dezirinda por saĝiĝi; kaj ŝi prenis de ĝiaj fruktoj, kaj ŝi manĝis, kaj ŝi donis kune ankaŭ al sia edzo, kaj li manĝis."],[3,7,"Kaj malfermiĝis la okuloj de ili ambaŭ, kaj ili sciiĝis, ke ili estas nudaj; kaj ili kunkudris foliojn de figarbo kaj faris al si zonaĵojn.","Kaj malfermiĝis la okuloj de ili ambaŭ, kaj ili sciiĝis, ke ili estas nudaj; kaj ili kunkudris foliojn de figarbo kaj faris al si zonaĵojn."],[3,8,"Kaj ili aŭdis la voĉon de Dio la Eternulo, kiu marŝis en la ĝardeno dum la malvarmeto de la tago; kaj Adam kaj lia edzino kaŝiĝis de Dio la Eternulo inter la arboj de la ĝardeno.","Kaj ili aŭdis la voĉon de Dio la Eternulo, kiu marŝis en la ĝardeno dum la malvarmeto de la tago; kaj Adam kaj lia edzino kaŝiĝis de Dio la Eternulo inter la arboj de la ĝardeno."],[3,9,"Kaj Dio la Eternulo vokis Adamon, kaj diris al li: Kie vi estas?","Kaj Dio la Eternulo vokis Adamon, kaj diris al li: Kie vi estas?"],[3,10,"Kaj tiu diris: Vian voĉon mi aŭdis en la ĝardeno, kaj mi ektimis, ĉar mi estas nuda; kaj mi kaŝis min.","Kaj tiu diris: Vian voĉon mi aŭdis en la ĝardeno, kaj mi ektimis, ĉar mi estas nuda; kaj mi kaŝis min."],[3,11,"Kaj Dio diris: Kiu diris al vi, ke vi estas nuda? ĉu vi ne manĝis de la arbo, pri kiu Mi ordonis al vi, ke vi ne manĝu de ĝi?","Kaj Dio diris: Kiu diris al vi, ke vi estas nuda? ĉu vi ne manĝis de la arbo, pri kiu Mi ordonis al vi, ke vi ne manĝu de ĝi?"],[3,12,"Kaj Adam diris: La edzino, kiun Vi donis al mi kiel kunulinon, ŝi donis al mi de la arbo, kaj mi manĝis.","Kaj Adam diris: La edzino, kiun Vi donis al mi kiel kunulinon, ŝi donis al mi de la arbo, kaj mi manĝis."],[3,13,"Kaj Dio la Eternulo diris al la virino: Kial vi tion faris? Kaj la virino diris: La serpento tromplogis min, kaj mi manĝis.","Kaj Dio la Eternulo diris al la virino: Kial vi tion faris? Kaj la virino diris: La serpento tromplogis min, kaj mi manĝis."],[3,14,"Kaj Dio la Eternulo diris al la serpento: Ĉar vi tion faris, tial estu malbenita inter ĉiuj brutoj kaj inter ĉiuj bestoj de la kampo; sur via ventro vi irados kaj teron vi manĝados dum via tuta vivo.","Kaj Dio la Eternulo diris al la serpento: Ĉar vi tion faris, tial estu malbenita inter ĉiuj brutoj kaj inter ĉiuj bestoj de la kampo; sur via ventro vi irados kaj teron vi manĝados dum via tuta vivo."],[3,15,"Kaj Mi metos malamikecon inter vi kaj la virino kaj inter via idaro kaj ŝia idaro; ĝi frapados vian kapon, kaj vi pikados ĝian kalkanon.","Kaj Mi metos malamikecon inter vi kaj la virino kaj inter via idaro kaj ŝia idaro; ĝi frapados vian kapon, kaj vi pikados ĝian kalkanon."],[3,16,"Al la virino Li diris: Mi multigos viajn suferojn dum via gravedeco; en doloro vi naskados infanojn; kaj al via viro vi vin tiros, kaj li regos super vi.","Al la virino Li diris: Mi multigos viajn suferojn dum via gravedeco; en doloro vi naskados infanojn; kaj al via viro vi vin tiros, kaj li regos super vi."],[3,17,"Kaj al Adam Li diris: Ĉar vi obeis la voĉon de via edzino, kaj vi manĝis de la arbo, pri kiu Mi ordonis al vi, dirante, ke vi ne manĝu de ĝi, tial malbenita estu la tero pro vi; kun suferoj vi manĝados de ĝi dum via tuta vivo.","Kaj al Adam Li diris: Ĉar vi obeis la voĉon de via edzino, kaj vi manĝis de la arbo, pri kiu Mi ordonis al vi, dirante, ke vi ne manĝu de ĝi, tial malbenita estu la tero pro vi; kun suferoj vi manĝados de ĝi dum via tuta vivo."],[3,18,"Kaj dornojn kaj pikaĵojn ĝi kreskigos por vi, kaj vi manĝados herbojn de la kampo.","Kaj dornojn kaj pikaĵojn ĝi kreskigos por vi, kaj vi manĝados herbojn de la kampo."],[3,19,"En la ŝvito de via vizaĝo vi manĝados panon, ĝis vi revenos en la teron, el kiu vi estas prenita; ĉar vi estas polvo kaj refariĝos polvo.","En la ŝvito de via vizaĝo vi manĝados panon, ĝis vi revenos en la teron, el kiu vi estas prenita; ĉar vi estas polvo kaj refariĝos polvo."],[3,20,"Kaj Adam donis al sia edzino la nomon Eva, ĉar ŝi estis patrino de ĉiuj vivantoj.","Kaj Adam donis al sia edzino la nomon Eva, ĉar ŝi estis patrino de ĉiuj vivantoj."],[3,21,"Kaj Dio la Eternulo faris por Adam kaj por lia edzino vestojn el felo, kaj Li vestis ilin.","Kaj Dio la Eternulo faris por Adam kaj por lia edzino vestojn el felo, kaj Li vestis ilin."],[3,22,"Kaj Dio la Eternulo diris: Jen Adam fariĝis kiel unu el Ni, sciante bonon kaj malbonon; nun eble li etendos sian manon kaj prenos ankaŭ de la arbo de vivo kaj manĝos kaj vivos eterne.","Kaj Dio la Eternulo diris: Jen Adam fariĝis kiel unu el Ni, sciante bonon kaj malbonon; nun eble li etendos sian manon kaj prenos ankaŭ de la arbo de vivo kaj manĝos kaj vivos eterne."],[3,23,"Kaj Dio la Eternulo eligis lin el la Edena ĝardeno, por ke li prilaboradu la teron, el kiu li estis prenita.","Kaj Dio la Eternulo eligis lin el la Edena ĝardeno, por ke li prilaboradu la teron, el kiu li estis prenita."],[3,24,"Kaj Li elpelis Adamon, kaj lokis antaŭ la Edena ĝardeno la kerubon kaj la turniĝantan flaman glavon, por gardi la vojon al la arbo de vivo.","Kaj Li elpelis Adamon, kaj lokis antaŭ la Edena ĝardeno la kerubon kaj la turniĝantan flaman glavon, por gardi la vojon al la arbo de vivo."],[4,1,"Kaj Adam ekkonis Evan, sian edzinon, kaj ŝi gravediĝis, kaj ŝi naskis Kainon; kaj ŝi diris: Mi akiris homon de la Eternulo.","Kaj Adam ekkonis Evan, sian edzinon, kaj ŝi gravediĝis, kaj ŝi naskis Kainon; kaj ŝi diris: Mi akiris homon de la Eternulo."],[4,2,"Kaj plue ŝi naskis lian fraton Habel. Kaj Habel fariĝis ŝafpaŝtisto, kaj Kain fariĝis terlaboristo.","Kaj plue ŝi naskis lian fraton Habel. Kaj Habel fariĝis ŝafpaŝtisto, kaj Kain fariĝis terlaboristo."],[4,3,"Kaj post ia tempo fariĝis, ke Kain alportis el la fruktoj de la tero donacoferon al la Eternulo.","Kaj post ia tempo fariĝis, ke Kain alportis el la fruktoj de la tero donacoferon al la Eternulo."],[4,4,"Kaj Habel ankaŭ alportis el la unuenaskitoj de siaj ŝafoj kaj el ilia graso. Kaj la Eternulo atentis Habelon kaj lian donacoferon;","Kaj Habel ankaŭ alportis el la unuenaskitoj de siaj ŝafoj kaj el ilia graso. Kaj la Eternulo atentis Habelon kaj lian donacoferon;"],[4,5,"sed Kainon kaj lian donacoferon Li ne atentis. Kaj Kain tre ekkoleris, kaj lia vizaĝo kliniĝis.","sed Kainon kaj lian donacoferon Li ne atentis. Kaj Kain tre ekkoleris, kaj lia vizaĝo kliniĝis."],[4,6,"Kaj la Eternulo diris al Kain: Kial vi koleras? kaj kial kliniĝis via vizaĝo?","Kaj la Eternulo diris al Kain: Kial vi koleras? kaj kial kliniĝis via vizaĝo?"],[4,7,"Ja se vi agos bone, vi estos forta; sed se vi agos malbone, la peko kuŝos ĉe la pordo, kaj vin ĝi aspiros, sed vi regu super ĝi.","Ja se vi agos bone, vi estos forta; sed se vi agos malbone, la peko kuŝos ĉe la pordo, kaj vin ĝi aspiros, sed vi regu super ĝi."],[4,8,"Kaj Kain parolis kun sia frato Habel; kaj kiam ili estis sur la kampo, Kain leviĝis kontraŭ sian fraton Habel kaj mortigis lin.","Kaj Kain parolis kun sia frato Habel; kaj kiam ili estis sur la kampo, Kain leviĝis kontraŭ sian fraton Habel kaj mortigis lin."],[4,9,"Kaj la Eternulo diris al Kain: Kie estas via frato Habel? Kaj tiu diris: Mi ne scias; ĉu mi estas gardisto de mia frato?","Kaj la Eternulo diris al Kain: Kie estas via frato Habel? Kaj tiu diris: Mi ne scias; ĉu mi estas gardisto de mia frato?"],[4,10,"Kaj Li diris: Kion vi faris? la voĉo de la sango de via frato krias al Mi de la tero.","Kaj Li diris: Kion vi faris? la voĉo de la sango de via frato krias al Mi de la tero."],[4,11,"Kaj nun estu malbenita de sur la tero, kiu malfermis sian buŝon, por preni la sangon de via frato el via mano.","Kaj nun estu malbenita de sur la tero, kiu malfermis sian buŝon, por preni la sangon de via frato el via mano."],[4,12,"Kiam vi prilaboros la teron, ĝi ne plu donos al vi sian forton; vaganto kaj forkuranto vi estos sur la tero.","Kiam vi prilaboros la teron, ĝi ne plu donos al vi sian forton; vaganto kaj forkuranto vi estos sur la tero."],[4,13,"Kaj Kain diris al la Eternulo: Pli granda estas mia puno, ol kiom mi povos elporti.","Kaj Kain diris al la Eternulo: Pli granda estas mia puno, ol kiom mi povos elporti."],[4,14,"Jen Vi forpelas min hodiaŭ de sur la tero, kaj mi devas min kaŝi de antaŭ Via vizaĝo, kaj mi estos vaganto kaj forkuranto sur la tero, kaj iu ajn, kiu min renkontos, mortigos min.","Jen Vi forpelas min hodiaŭ de sur la tero, kaj mi devas min kaŝi de antaŭ Via vizaĝo, kaj mi estos vaganto kaj forkuranto sur la tero, kaj iu ajn, kiu min renkontos, mortigos min."],[4,15,"Kaj la Eternulo diris al li: Sciu, ke al iu, kiu mortigos Kainon, estos venĝite sepoble. Kaj la Eternulo faris sur Kain signon, ke ne mortigu lin iu, kiu lin renkontos.","Kaj la Eternulo diris al li: Sciu, ke al iu, kiu mortigos Kainon, estos venĝite sepoble. Kaj la Eternulo faris sur Kain signon, ke ne mortigu lin iu, kiu lin renkontos."],[4,16,"Kaj Kain foriris de antaŭ la Eternulo, kaj loĝiĝis en la lando Nod, oriente de Eden.","Kaj Kain foriris de antaŭ la Eternulo, kaj loĝiĝis en la lando Nod, oriente de Eden."],[4,17,"Kaj Kain ekkonis sian edzinon, kaj ŝi gravediĝis, kaj ŝi naskis Ĥanoĥon. Kaj li konstruis urbon, kaj li donis al la urbo nomon laŭ la nomo de sia filo: Ĥanoĥ.","Kaj Kain ekkonis sian edzinon, kaj ŝi gravediĝis, kaj ŝi naskis Ĥanoĥon. Kaj li konstruis urbon, kaj li donis al la urbo nomon laŭ la nomo de sia filo: Ĥanoĥ."],[4,18,"Kaj al Ĥanoĥ naskiĝis Irad, kaj al Irad naskiĝis Meĥujael, kaj al Meĥujael naskiĝis Metuŝael, kaj al Metuŝael naskiĝis Lemeĥ.","Kaj al Ĥanoĥ naskiĝis Irad, kaj al Irad naskiĝis Meĥujael, kaj al Meĥujael naskiĝis Metuŝael, kaj al Metuŝael naskiĝis Lemeĥ."],[4,19,"Kaj Lemeĥ prenis al si du edzinojn: unu havis la nomon Ada, kaj la dua havis la nomon Cila.","Kaj Lemeĥ prenis al si du edzinojn: unu havis la nomon Ada, kaj la dua havis la nomon Cila."],[4,20,"Kaj Ada naskis Jabalon; li estis la patro de tiuj, kiuj loĝas en tendoj kaj paŝtas brutojn.","Kaj Ada naskis Jabalon; li estis la patro de tiuj, kiuj loĝas en tendoj kaj paŝtas brutojn."],[4,21,"Kaj la nomo de lia frato estis Jubal; li estis la patro de ĉiuj, kiuj ludas harpon kaj fluton.","Kaj la nomo de lia frato estis Jubal; li estis la patro de ĉiuj, kiuj ludas harpon kaj fluton."],[4,22,"Cila ankaŭ naskis Tubal-Kainon, forĝanton de diversaj majstraĵoj el kupro kaj fero. Kaj la fratino de Tubal-Kain estis Naama.","Cila ankaŭ naskis Tubal-Kainon, forĝanton de diversaj majstraĵoj el kupro kaj fero. Kaj la fratino de Tubal-Kain estis Naama."],[4,23,"Kaj Lemeĥ diris al siaj edzinoj Ada kaj Cila: Aŭskultu mian voĉon, edzinoj de Lemeĥ, Atentu mian parolon! Ĉar viron mi mortigis por vundo al mi Kaj junulon por tubero al mi;","Kaj Lemeĥ diris al siaj edzinoj Ada kaj Cila: Aŭskultu mian voĉon, edzinoj de Lemeĥ, Atentu mian parolon! Ĉar viron mi mortigis por vundo al mi Kaj junulon por tubero al mi;"],[4,24,"Se sepoble estos venĝite por Kain, Por Lemeĥ estos sepdek-sepoble.","Se sepoble estos venĝite por Kain, Por Lemeĥ estos sepdek-sepoble."],[4,25,"Kaj denove Adam ekkonis sian edzinon, kaj ŝi naskis filon, kaj donis al li la nomon Set: Ĉar Dio metis al mi alian semon anstataŭ Habel, kiun mortigis Kain.","Kaj denove Adam ekkonis sian edzinon, kaj ŝi naskis filon, kaj donis al li la nomon Set: Ĉar Dio metis al mi alian semon anstataŭ Habel, kiun mortigis Kain."],[4,26,"Kaj al Set ankaŭ naskiĝis filo, kaj li donis al li la nomon Enoŝ. Tiam oni komencis alvokadi la nomon de la Eternulo.","Kaj al Set ankaŭ naskiĝis filo, kaj li donis al li la nomon Enoŝ. Tiam oni komencis alvokadi la nomon de la Eternulo."],[5,1,"Jen estas la libro de naskoj de Adam. Kiam Dio kreis la homon, Li faris lin laŭ la bildo de Dio;","Jen estas la libro de naskoj de Adam. Kiam Dio kreis la homon, Li faris lin laŭ la bildo de Dio;"],[5,2,"kiel viron kaj virinon Li kreis ilin, kaj Li benis ilin kaj donis al ili la nomon Homo en la tago de ilia naskiĝo.","kiel viron kaj virinon Li kreis ilin, kaj Li benis ilin kaj donis al ili la nomon Homo en la tago de ilia naskiĝo."],[5,3,"Kaj Adam vivis cent tridek jarojn, kaj al li naskiĝis filo laŭ lia bildo kaj simileco, kaj li donis al li la nomon Set.","Kaj Adam vivis cent tridek jarojn, kaj al li naskiĝis filo laŭ lia bildo kaj simileco, kaj li donis al li la nomon Set."],[5,4,"Kaj Adam vivis, post kiam naskiĝis al li Set, okcent jarojn, kaj naskiĝis al li filoj kaj filinoj.","Kaj Adam vivis, post kiam naskiĝis al li Set, okcent jarojn, kaj naskiĝis al li filoj kaj filinoj."],[5,5,"Kaj la tuta vivo, kiun travivis Adam, estis naŭcent tridek jaroj, kaj li mortis.","Kaj la tuta vivo, kiun travivis Adam, estis naŭcent tridek jaroj, kaj li mortis."],[5,6,"Kaj Set vivis cent kvin jarojn, kaj naskiĝis al li Enoŝ.","Kaj Set vivis cent kvin jarojn, kaj naskiĝis al li Enoŝ."],[5,7,"Kaj Set vivis, post kiam naskiĝis al li Enoŝ, okcent sep jarojn, kaj naskiĝis al li filoj kaj filinoj.","Kaj Set vivis, post kiam naskiĝis al li Enoŝ, okcent sep jarojn, kaj naskiĝis al li filoj kaj filinoj."],[5,8,"Kaj la tuta vivo de Set estis naŭcent dek du jaroj, kaj li mortis.","Kaj la tuta vivo de Set estis naŭcent dek du jaroj, kaj li mortis."],[5,9,"Kaj Enoŝ vivis naŭdek jarojn, kaj naskiĝis al li Kenan.","Kaj Enoŝ vivis naŭdek jarojn, kaj naskiĝis al li Kenan."],[5,10,"Kaj Enoŝ vivis, post kiam naskiĝis al li Kenan, okcent dek kvin jarojn, kaj naskiĝis al li filoj kaj filinoj.","Kaj Enoŝ vivis, post kiam naskiĝis al li Kenan, okcent dek kvin jarojn, kaj naskiĝis al li filoj kaj filinoj."],[5,11,"Kaj la tuta vivo de Enoŝ estis naŭcent kvin jaroj, kaj li mortis.","Kaj la tuta vivo de Enoŝ estis naŭcent kvin jaroj, kaj li mortis."],[5,12,"Kaj Kenan vivis sepdek jarojn, kaj naskiĝis al li Mahalalel.","Kaj Kenan vivis sepdek jarojn, kaj naskiĝis al li Mahalalel."],[5,13,"Kaj Kenan vivis, post kiam naskiĝis al li Mahalalel, okcent kvardek jarojn, kaj naskiĝis al li filoj kaj filinoj.","Kaj Kenan vivis, post kiam naskiĝis al li Mahalalel, okcent kvardek jarojn, kaj naskiĝis al li filoj kaj filinoj."],[5,14,"Kaj la tuta vivo de Kenan estis naŭcent dek jaroj, kaj li mortis.","Kaj la tuta vivo de Kenan estis naŭcent dek jaroj, kaj li mortis."],[5,15,"Kaj Mahalalel vivis sesdek kvin jarojn, kaj naskiĝis al li Jared.","Kaj Mahalalel vivis sesdek kvin jarojn, kaj naskiĝis al li Jared."],[5,16,"Kaj Mahalalel vivis, post kiam naskiĝis al li Jared, okcent tridek jarojn, kaj naskiĝis al li filoj kaj filinoj.","Kaj Mahalalel vivis, post kiam naskiĝis al li Jared, okcent tridek jarojn, kaj naskiĝis al li filoj kaj filinoj."],[5,17,"Kaj la tuta vivo de Mahalalel estis okcent naŭdek kvin jaroj, kaj li mortis.","Kaj la tuta vivo de Mahalalel estis okcent naŭdek kvin jaroj, kaj li mortis."],[5,18,"Kaj Jared vivis cent sesdek du jarojn, kaj naskiĝis al li Ĥanoĥ.","Kaj Jared vivis cent sesdek du jarojn, kaj naskiĝis al li Ĥanoĥ."],[5,19,"Kaj Jared vivis, post kiam naskiĝis al li Ĥanoĥ, okcent jarojn, kaj naskiĝis al li filoj kaj filinoj.","Kaj Jared vivis, post kiam naskiĝis al li Ĥanoĥ, okcent jarojn, kaj naskiĝis al li filoj kaj filinoj."],[5,20,"Kaj la tuta vivo de Jared estis naŭcent sesdek du jaroj, kaj li mortis.","Kaj la tuta vivo de Jared estis naŭcent sesdek du jaroj, kaj li mortis."],[5,21,"Kaj Ĥanoĥ vivis sesdek kvin jarojn, kaj naskiĝis al li Metuŝelaĥ.","Kaj Ĥanoĥ vivis sesdek kvin jarojn, kaj naskiĝis al li Metuŝelaĥ."],[5,22,"Kaj Ĥanoĥ iradis kun Dio, post kiam naskiĝis al li Metuŝelaĥ, tricent jarojn, kaj naskiĝis al li filoj kaj filinoj.","Kaj Ĥanoĥ iradis kun Dio, post kiam naskiĝis al li Metuŝelaĥ, tricent jarojn, kaj naskiĝis al li filoj kaj filinoj."],[5,23,"Kaj la tuta vivo de Ĥanoĥ estis tricent sesdek kvin jaroj.","Kaj la tuta vivo de Ĥanoĥ estis tricent sesdek kvin jaroj."],[5,24,"Kaj Ĥanoĥ iradis kun Dio; kaj li malaperis, ĉar Dio lin prenis.","Kaj Ĥanoĥ iradis kun Dio; kaj li malaperis, ĉar Dio lin prenis."],[5,25,"Kaj Metuŝelaĥ vivis cent okdek sep jarojn, kaj naskiĝis al li Lemeĥ.","Kaj Metuŝelaĥ vivis cent okdek sep jarojn, kaj naskiĝis al li Lemeĥ."],[5,26,"Kaj Metuŝelaĥ vivis, post kiam naskiĝis al li Lemeĥ, sepcent okdek du jarojn, kaj naskiĝis al li filoj kaj filinoj.","Kaj Metuŝelaĥ vivis, post kiam naskiĝis al li Lemeĥ, sepcent okdek du jarojn, kaj naskiĝis al li filoj kaj filinoj."],[5,27,"Kaj la tuta vivo de Metuŝelaĥ estis naŭcent sesdek naŭ jaroj, kaj li mortis.","Kaj la tuta vivo de Metuŝelaĥ estis naŭcent sesdek naŭ jaroj, kaj li mortis."],[5,28,"Kaj Lemeĥ vivis cent okdek du jarojn, kaj naskiĝis al li filo.","Kaj Lemeĥ vivis cent okdek du jarojn, kaj naskiĝis al li filo."],[5,29,"Kaj li donis al li la nomon Noa, dirante: Ĉi tiu konsolos nin en niaj faroj kaj en la laboroj de niaj manoj sur la tero, kiun la Eternulo malbenis.","Kaj li donis al li la nomon Noa, dirante: Ĉi tiu konsolos nin en niaj faroj kaj en la laboroj de niaj manoj sur la tero, kiun la Eternulo malbenis."],[5,30,"Kaj Lemeĥ vivis, post kiam naskiĝis al li Noa, kvincent naŭdek kvin jarojn, kaj naskiĝis al li filoj kaj filinoj.","Kaj Lemeĥ vivis, post kiam naskiĝis al li Noa, kvincent naŭdek kvin jarojn, kaj naskiĝis al li filoj kaj filinoj."],[5,31,"Kaj la tuta vivo de Lemeĥ estis sepcent sepdek sep jaroj, kaj li mortis.","Kaj la tuta vivo de Lemeĥ estis sepcent sepdek sep jaroj, kaj li mortis."],[5,32,"Kaj Noa havis la aĝon de kvincent jaroj, kaj al Noa naskiĝis Ŝem, Ĥam, kaj Jafet.","Kaj Noa havis la aĝon de kvincent jaroj, kaj al Noa naskiĝis Ŝem, Ĥam, kaj Jafet."],[6,1,"Kaj kiam la homoj komencis multiĝi sur la tero kaj al ili naskiĝis filinoj,","Kaj kiam la homoj komencis multiĝi sur la tero kaj al ili naskiĝis filinoj,"],[6,2,"tiam la filoj de Dio vidis la filinojn de la homoj, ke ili estas belaj; kaj ili prenis al si edzinojn el ĉiuj, kiujn ili elektis.","tiam la filoj de Dio vidis la filinojn de la homoj, ke ili estas belaj; kaj ili prenis al si edzinojn el ĉiuj, kiujn ili elektis."],[6,3,"Kaj la Eternulo diris: Ne regos Mia spirito inter la homoj eterne, pro iliaj pekoj, ĉar ili estas karno; ilia vivo estu cent dudek jaroj.","Kaj la Eternulo diris: Ne regos Mia spirito inter la homoj eterne, pro iliaj pekoj, ĉar ili estas karno; ilia vivo estu cent dudek jaroj."],[6,4,"Gigantoj estis sur la tero en tiu tempo, eĉ post kiam la filoj de Dio venis al la filinoj de la homoj kaj ĉi tiuj naskis al ili. Tio estis la fortuloj, tre famaj de plej antikva tempo.","Gigantoj estis sur la tero en tiu tempo, eĉ post kiam la filoj de Dio venis al la filinoj de la homoj kaj ĉi tiuj naskis al ili. Tio estis la fortuloj, tre famaj de plej antikva tempo."],[6,5,"Kaj la Eternulo vidis, ke granda estas la malboneco de la homoj sur la tero kaj ke ĉiuj pensoj kaj intencoj de iliaj koroj estas nur malbono en ĉiu tempo;","Kaj la Eternulo vidis, ke granda estas la malboneco de la homoj sur la tero kaj ke ĉiuj pensoj kaj intencoj de iliaj koroj estas nur malbono en ĉiu tempo;"],[6,6,"tiam la Eternulo pentis, ke Li kreis la homon sur la tero, kaj Li afliktiĝis en Sia koro.","tiam la Eternulo pentis, ke Li kreis la homon sur la tero, kaj Li afliktiĝis en Sia koro."],[6,7,"Kaj la Eternulo diris: Mi ekstermos de sur la tero la homon, kiun Mi kreis, de la homo ĝis la brutoj, ĝis la rampaĵoj, kaj ĝis la birdoj de la ĉielo; ĉar Mi pentas, ke Mi ilin kreis.","Kaj la Eternulo diris: Mi ekstermos de sur la tero la homon, kiun Mi kreis, de la homo ĝis la brutoj, ĝis la rampaĵoj, kaj ĝis la birdoj de la ĉielo; ĉar Mi pentas, ke Mi ilin kreis."],[6,8,"Sed Noa akiris plaĉon en la okuloj de la Eternulo.","Sed Noa akiris plaĉon en la okuloj de la Eternulo."],[6,9,"Jen estas la historio de Noa: Noa estis homo virta kaj senmakula en sia generacio; kun Dio Noa iradis.","Jen estas la historio de Noa: Noa estis homo virta kaj senmakula en sia generacio; kun Dio Noa iradis."],[6,10,"Kaj naskiĝis al Noa tri filoj: Ŝem, Ĥam, kaj Jafet.","Kaj naskiĝis al Noa tri filoj: Ŝem, Ĥam, kaj Jafet."],[6,11,"Kaj la tero malvirtiĝis antaŭ Dio, kaj la tero pleniĝis de maljustaĵoj.","Kaj la tero malvirtiĝis antaŭ Dio, kaj la tero pleniĝis de maljustaĵoj."],[6,12,"Kaj Dio vidis la teron, ke ĝi malvirtiĝis, ĉar ĉiu karno malvirtigis sian vojon sur la tero.","Kaj Dio vidis la teron, ke ĝi malvirtiĝis, ĉar ĉiu karno malvirtigis sian vojon sur la tero."],[6,13,"Kaj Dio diris al Noa: La fino de ĉiu karno venis antaŭ Min, ĉar la tero pleniĝis de maljustaĵoj per ili, kaj jen Mi pereigos ilin kun la tero.","Kaj Dio diris al Noa: La fino de ĉiu karno venis antaŭ Min, ĉar la tero pleniĝis de maljustaĵoj per ili, kaj jen Mi pereigos ilin kun la tero."],[6,14,"Faru al vi arkeon el ligno gofera; apartaĵojn faru en la arkeo, kaj ŝmiru ĝin per peĉo interne kaj ekstere.","Faru al vi arkeon el ligno gofera; apartaĵojn faru en la arkeo, kaj ŝmiru ĝin per peĉo interne kaj ekstere."],[6,15,"Kaj faru ĝin tiamaniere: tricent ulnoj estu la longo de la arkeo, kvindek ulnoj ĝia larĝo, kaj tridek ulnoj ĝia alto.","Kaj faru ĝin tiamaniere: tricent ulnoj estu la longo de la arkeo, kvindek ulnoj ĝia larĝo, kaj tridek ulnoj ĝia alto."],[6,16,"Fenestron faru en la arkeo, supre, kun la alto de unu ulno, kaj la pordon de la arkeo vi faros en la flanko; malsupran spacon, duan spacon, kaj trian spacon faru en ĝi.","Fenestron faru en la arkeo, supre, kun la alto de unu ulno, kaj la pordon de la arkeo vi faros en la flanko; malsupran spacon, duan spacon, kaj trian spacon faru en ĝi."],[6,17,"Kaj jen Mi venigos akvan diluvon sur la teron, por ekstermi ĉiun karnon, kiu havas en si spiriton de vivo sub la ĉielo; ĉio, kio estas sur la tero, pereos.","Kaj jen Mi venigos akvan diluvon sur la teron, por ekstermi ĉiun karnon, kiu havas en si spiriton de vivo sub la ĉielo; ĉio, kio estas sur la tero, pereos."],[6,18,"Kaj Mi starigos Mian interligon kun vi; kaj vi eniros en la arkeon, vi kaj viaj filoj kaj via edzino kaj la edzinoj de viaj filoj kune kun vi.","Kaj Mi starigos Mian interligon kun vi; kaj vi eniros en la arkeon, vi kaj viaj filoj kaj via edzino kaj la edzinoj de viaj filoj kune kun vi."],[6,19,"Kaj el ĉiuj vivaĵoj, el ĉiu karno, enkonduku po unu paro el ĉiuj en la arkeon, ke ili restu vivaj kun vi; virbesto kaj virinbesto ili estu.","Kaj el ĉiuj vivaĵoj, el ĉiu karno, enkonduku po unu paro el ĉiuj en la arkeon, ke ili restu vivaj kun vi; virbesto kaj virinbesto ili estu."],[6,20,"El la birdoj laŭ iliaj specoj, kaj el la brutoj laŭ iliaj specoj, el ĉiuj rampaĵoj de la tero laŭ iliaj specoj, po paro el ĉiuj eniru kun vi, por resti vivaj.","El la birdoj laŭ iliaj specoj, kaj el la brutoj laŭ iliaj specoj, el ĉiuj rampaĵoj de la tero laŭ iliaj specoj, po paro el ĉiuj eniru kun vi, por resti vivaj."],[6,21,"Kaj vi prenu al vi el ĉiuj manĝaĵoj, kiuj estas manĝataj, kaj kolektu al vi; kaj ĝi estu por vi kaj por ili por manĝi.","Kaj vi prenu al vi el ĉiuj manĝaĵoj, kiuj estas manĝataj, kaj kolektu al vi; kaj ĝi estu por vi kaj por ili por manĝi."],[6,22,"Kaj Noa tion faris; ĉion, kiel Dio al li ordonis, tiel li faris.","Kaj Noa tion faris; ĉion, kiel Dio al li ordonis, tiel li faris."],[7,1,"Kaj la Eternulo diris al Noa: Eniru vi kaj via tuta familio en la arkeon, ĉar vin Mi vidis, ke vi estas virtulo antaŭ Mi en ĉi tiu generacio.","Kaj la Eternulo diris al Noa: Eniru vi kaj via tuta familio en la arkeon, ĉar vin Mi vidis, ke vi estas virtulo antaŭ Mi en ĉi tiu generacio."],[7,2,"El ĉiuj brutoj puraj prenu al vi po sep paroj, virbestojn kaj iliajn inojn; kaj el la brutoj, kiuj ne estas puraj, po du, virbeston kaj ĝian inon.","El ĉiuj brutoj puraj prenu al vi po sep paroj, virbestojn kaj iliajn inojn; kaj el la brutoj, kiuj ne estas puraj, po du, virbeston kaj ĝian inon."],[7,3,"Ankaŭ el la birdoj de la ĉielo po sep paroj, virbestojn kaj virinbestojn, por ke semo restu sur la tuta tero.","Ankaŭ el la birdoj de la ĉielo po sep paroj, virbestojn kaj virinbestojn, por ke semo restu sur la tuta tero."],[7,4,"Ĉar post sep tagoj Mi pluvigos sur la teron dum kvardek tagoj kaj kvardek noktoj, kaj Mi ekstermos de sur la tero ĉiujn ekzistaĵojn, kiujn Mi kreis.","Ĉar post sep tagoj Mi pluvigos sur la teron dum kvardek tagoj kaj kvardek noktoj, kaj Mi ekstermos de sur la tero ĉiujn ekzistaĵojn, kiujn Mi kreis."],[7,5,"Kaj Noa faris ĉion, kion la Eternulo al li ordonis.","Kaj Noa faris ĉion, kion la Eternulo al li ordonis."],[7,6,"Kaj Noa havis la aĝon de sescent jaroj, kiam la akva diluvo venis sur la teron.","Kaj Noa havis la aĝon de sescent jaroj, kiam la akva diluvo venis sur la teron."],[7,7,"Kaj eniris Noa kaj liaj filoj kaj lia edzino kaj la edzinoj de liaj filoj kune kun li en la arkeon, pro la akvo de la diluvo.","Kaj eniris Noa kaj liaj filoj kaj lia edzino kaj la edzinoj de liaj filoj kune kun li en la arkeon, pro la akvo de la diluvo."],[7,8,"El la brutoj puraj, kaj el la brutoj, kiuj ne estas puraj, kaj el la birdoj, kaj el ĉiuj rampaĵoj sur la tero,","El la brutoj puraj, kaj el la brutoj, kiuj ne estas puraj, kaj el la birdoj, kaj el ĉiuj rampaĵoj sur la tero,"],[7,9,"po paro venis al Noa en la arkeon, virbesto kaj ino, kiel Dio ordonis al Noa.","po paro venis al Noa en la arkeon, virbesto kaj ino, kiel Dio ordonis al Noa."],[7,10,"Kaj kiam pasis la sep tagoj, la diluva akvo venis sur la teron.","Kaj kiam pasis la sep tagoj, la diluva akvo venis sur la teron."],[7,11,"En la sescenta jaro de la vivo de Noa, en la dua monato, en la dek-sepa tago de la monato, en tiu tago disfendiĝis ĉiuj fontoj de la granda abismo kaj la aperturoj de la ĉielo malfermiĝis.","En la sescenta jaro de la vivo de Noa, en la dua monato, en la dek-sepa tago de la monato, en tiu tago disfendiĝis ĉiuj fontoj de la granda abismo kaj la aperturoj de la ĉielo malfermiĝis."],[7,12,"Kaj estis pluvo sur la tero dum kvardek tagoj kaj kvardek noktoj.","Kaj estis pluvo sur la tero dum kvardek tagoj kaj kvardek noktoj."],[7,13,"Ĝuste en tiu tago eniris en la arkeon Noa, kaj Ŝem kaj Ĥam kaj Jafet, la filoj de Noa, kaj la edzino de Noa, kaj la tri edzinoj de liaj filoj kune kun ili;","Ĝuste en tiu tago eniris en la arkeon Noa, kaj Ŝem kaj Ĥam kaj Jafet, la filoj de Noa, kaj la edzino de Noa, kaj la tri edzinoj de liaj filoj kune kun ili;"],[7,14,"ili, kaj ĉiuj bestoj laŭ siaj specoj, kaj ĉiuj brutoj laŭ siaj specoj, kaj ĉiuj rampaĵoj, kiuj rampas sur la tero, laŭ siaj specoj, kaj ĉiuj flugaĵoj laŭ siaj specoj, ĉiuj birdoj, ĉiuj flugilhavantoj.","ili, kaj ĉiuj bestoj laŭ siaj specoj, kaj ĉiuj brutoj laŭ siaj specoj, kaj ĉiuj rampaĵoj, kiuj rampas sur la tero, laŭ siaj specoj, kaj ĉiuj flugaĵoj laŭ siaj specoj, ĉiuj birdoj, ĉiuj flugilhavantoj."],[7,15,"Kaj eniris al Noa en la arkeon po du el ĉiu karno, kiu havas en si spiriton de vivo.","Kaj eniris al Noa en la arkeon po du el ĉiu karno, kiu havas en si spiriton de vivo."],[7,16,"Kaj la venintoj, virbesto kaj ino el ĉiu karno, eniris, kiel ordonis al ili Dio; kaj la Eternulo fermis post ili.","Kaj la venintoj, virbesto kaj ino el ĉiu karno, eniris, kiel ordonis al ili Dio; kaj la Eternulo fermis post ili."],[7,17,"Kaj estis diluvo dum kvardek tagoj sur la tero; kaj multiĝis la akvo kaj levis la arkeon, kaj ĝi estis alte super la tero.","Kaj estis diluvo dum kvardek tagoj sur la tero; kaj multiĝis la akvo kaj levis la arkeon, kaj ĝi estis alte super la tero."],[7,18,"Kaj la akvo fortiĝis sur la tero, kaj la arkeo naĝis sur la supraĵo de la akvo.","Kaj la akvo fortiĝis sur la tero, kaj la arkeo naĝis sur la supraĵo de la akvo."],[7,19,"Kaj la akvo treege fortiĝis kaj tre multiĝis sur la tero; kaj kovriĝis ĉiuj altaj montoj, kiuj estas sub la ĉielo.","Kaj la akvo treege fortiĝis kaj tre multiĝis sur la tero; kaj kovriĝis ĉiuj altaj montoj, kiuj estas sub la ĉielo."],[7,20,"Dek kvin ulnojn pli alte leviĝis la akvo kaj kovris la montojn.","Dek kvin ulnojn pli alte leviĝis la akvo kaj kovris la montojn."],[7,21,"Kaj pereis ĉiu karno, kiu moviĝas sur la tero, la birdoj kaj la brutoj kaj la bestoj, kaj ĉiuj rampaĵoj, kiuj rampas sur la tero, kaj ĉiuj homoj.","Kaj pereis ĉiu karno, kiu moviĝas sur la tero, la birdoj kaj la brutoj kaj la bestoj, kaj ĉiuj rampaĵoj, kiuj rampas sur la tero, kaj ĉiuj homoj."],[7,22,"Ĉio, kio havis en si spiriton de vivo, el ĉio, kio estis sur la seka tero, mortis.","Ĉio, kio havis en si spiriton de vivo, el ĉio, kio estis sur la seka tero, mortis."],[7,23,"Kaj ekstermiĝis ĉiuj ekzistaĵoj, kiuj estis sur la tero, de homo ĝis brutoj kaj rampaĵoj kaj birdoj de la ĉielo; ili ekstermiĝis de sur la tero; kaj restis nur Noa kaj kio estis kun li en la arkeo.","Kaj ekstermiĝis ĉiuj ekzistaĵoj, kiuj estis sur la tero, de homo ĝis brutoj kaj rampaĵoj kaj birdoj de la ĉielo; ili ekstermiĝis de sur la tero; kaj restis nur Noa kaj kio estis kun li en la arkeo."],[7,24,"Kaj la akvo okupis la teron dum cent kvindek tagoj.","Kaj la akvo okupis la teron dum cent kvindek tagoj."],[8,1,"Kaj Dio rememoris Noan, kaj ĉiujn bestojn kaj ĉiujn brutojn, kiuj estis kun li en la arkeo; kaj Dio venigis venton sur la teron, kaj la akvo kvietiĝis.","Kaj Dio rememoris Noan, kaj ĉiujn bestojn kaj ĉiujn brutojn, kiuj estis kun li en la arkeo; kaj Dio venigis venton sur la teron, kaj la akvo kvietiĝis."],[8,2,"Kaj fermiĝis la fontoj de la abismo kaj la aperturoj de la ĉielo, kaj ĉesiĝis la pluvo el la ĉielo.","Kaj fermiĝis la fontoj de la abismo kaj la aperturoj de la ĉielo, kaj ĉesiĝis la pluvo el la ĉielo."],[8,3,"Kaj iom post iom reforiĝis la akvo de sur la tero, kaj la akvo komencis malmultiĝi post la paso de cent kvindek tagoj.","Kaj iom post iom reforiĝis la akvo de sur la tero, kaj la akvo komencis malmultiĝi post la paso de cent kvindek tagoj."],[8,4,"Kaj la arkeo haltis en la sepa monato, en la dek-sepa tago de la monato, sur la montoj Ararat.","Kaj la arkeo haltis en la sepa monato, en la dek-sepa tago de la monato, sur la montoj Ararat."],[8,5,"Kaj la akvo konstante malpliiĝadis ĝis la deka monato; en la unua tago de la deka monato montriĝis la suproj de la montoj.","Kaj la akvo konstante malpliiĝadis ĝis la deka monato; en la unua tago de la deka monato montriĝis la suproj de la montoj."],[8,6,"Kaj post kvardek tagoj Noa malfermis la fenestron de la arkeo, kiun li faris.","Kaj post kvardek tagoj Noa malfermis la fenestron de la arkeo, kiun li faris."],[8,7,"Kaj li ellasis korvon, kaj ĝi elflugis, forflugadis kaj revenadis, ĝis forsekiĝis la akvo sur la tero.","Kaj li ellasis korvon, kaj ĝi elflugis, forflugadis kaj revenadis, ĝis forsekiĝis la akvo sur la tero."],[8,8,"Kaj li ellasis de si kolombon, por vidi, ĉu jam malfortiĝis la akvo sur la tero.","Kaj li ellasis de si kolombon, por vidi, ĉu jam malfortiĝis la akvo sur la tero."],[8,9,"Sed la kolombo ne trovis ripozejon por siaj piedoj, kaj ĝi revenis al li en la arkeon, ĉar akvo estis sur la supraĵo de la tuta tero. Kaj li etendis sian manon kaj prenis la kolombon kaj envenigis ĝin al si en la arkeon.","Sed la kolombo ne trovis ripozejon por siaj piedoj, kaj ĝi revenis al li en la arkeon, ĉar akvo estis sur la supraĵo de la tuta tero. Kaj li etendis sian manon kaj prenis la kolombon kaj envenigis ĝin al si en la arkeon."],[8,10,"Kaj li atendis ankoraŭ aliajn sep tagojn, kaj li denove ellasis la kolombon el la arkeo.","Kaj li atendis ankoraŭ aliajn sep tagojn, kaj li denove ellasis la kolombon el la arkeo."],[8,11,"Kaj revenis al li la kolombo en tempo vespera, kaj jen ĝi havis en sia buŝo deŝiritan folion de olivarbo; kaj Noa konvinkiĝis, ke la akvo malfortiĝis sur la tero.","Kaj revenis al li la kolombo en tempo vespera, kaj jen ĝi havis en sia buŝo deŝiritan folion de olivarbo; kaj Noa konvinkiĝis, ke la akvo malfortiĝis sur la tero."],[8,12,"Kaj li atendis ankoraŭ aliajn sep tagojn, kaj li ellasis la kolombon, kaj ĉi tiu jam ne plu revenis al li.","Kaj li atendis ankoraŭ aliajn sep tagojn, kaj li ellasis la kolombon, kaj ĉi tiu jam ne plu revenis al li."],[8,13,"Kaj en la sescent-unua jaro, en la unua tago de la unua monato, forsekiĝis la akvo sur la tero; kaj Noa malfermis la tegmenton de la arkeo, kaj li vidis, ke sekiĝis la supraĵo de la tero.","Kaj en la sescent-unua jaro, en la unua tago de la unua monato, forsekiĝis la akvo sur la tero; kaj Noa malfermis la tegmenton de la arkeo, kaj li vidis, ke sekiĝis la supraĵo de la tero."],[8,14,"Kaj en la dua monato, en la dudek-sepa tago de la monato, la tero elsekiĝis.","Kaj en la dua monato, en la dudek-sepa tago de la monato, la tero elsekiĝis."],[8,15,"Kaj Dio diris al Noa jene:","Kaj Dio diris al Noa jene:"],[8,16,"Eliru el la arkeo, vi kaj via edzino kaj viaj filoj kaj la edzinoj de viaj filoj kune kun vi;","Eliru el la arkeo, vi kaj via edzino kaj viaj filoj kaj la edzinoj de viaj filoj kune kun vi;"],[8,17,"ĉiujn bestojn, kiuj estas kun vi, el ĉiu karno, el la birdoj kaj brutoj, kaj el ĉiuj rampaĵoj, kiuj rampas sur la tero, elirigu kune kun vi; kaj ili moviĝu sur la tero kaj fruktu kaj multiĝu sur la tero.","ĉiujn bestojn, kiuj estas kun vi, el ĉiu karno, el la birdoj kaj brutoj, kaj el ĉiuj rampaĵoj, kiuj rampas sur la tero, elirigu kune kun vi; kaj ili moviĝu sur la tero kaj fruktu kaj multiĝu sur la tero."],[8,18,"Kaj eliris Noa kaj liaj filoj kaj lia edzino kaj la edzinoj de liaj filoj kune kun li.","Kaj eliris Noa kaj liaj filoj kaj lia edzino kaj la edzinoj de liaj filoj kune kun li."],[8,19,"Ĉiuj bestoj, ĉiuj rampaĵoj, kaj ĉiuj birdoj, ĉio, kio moviĝas sur la tero, laŭ siaj familioj, eliris el la arkeo.","Ĉiuj bestoj, ĉiuj rampaĵoj, kaj ĉiuj birdoj, ĉio, kio moviĝas sur la tero, laŭ siaj familioj, eliris el la arkeo."],[8,20,"Kaj Noa konstruis altaron al la Eternulo, kaj li prenis el ĉiuj puraj brutoj kaj el ĉiuj puraj birdoj kaj oferis bruloferojn sur la altaro.","Kaj Noa konstruis altaron al la Eternulo, kaj li prenis el ĉiuj puraj brutoj kaj el ĉiuj puraj birdoj kaj oferis bruloferojn sur la altaro."],[8,21,"Kaj la Eternulo flaris la agrablan odoron, kaj la Eternulo diris en Sia koro: Mi ne plu malbenos la teron pro la homo, ĉar la penso de la homa koro estas malbona jam de lia juneco; kaj Mi ne batos plu ĉion vivantan, kiel Mi faris.","Kaj la Eternulo flaris la agrablan odoron, kaj la Eternulo diris en Sia koro: Mi ne plu malbenos la teron pro la homo, ĉar la penso de la homa koro estas malbona jam de lia juneco; kaj Mi ne batos plu ĉion vivantan, kiel Mi faris."],[8,22,"De nun tiel longe, kiel la tero ekzistos, semado kaj rikoltado, malvarmo kaj varmo, somero kaj vintro, tago kaj nokto ne ĉesiĝos.","De nun tiel longe, kiel la tero ekzistos, semado kaj rikoltado, malvarmo kaj varmo, somero kaj vintro, tago kaj nokto ne ĉesiĝos."],[9,1,"Kaj Dio benis Noan kaj liajn filojn, kaj diris al ili: Fruktu kaj multiĝu, kaj plenigu la teron.","Kaj Dio benis Noan kaj liajn filojn, kaj diris al ili: Fruktu kaj multiĝu, kaj plenigu la teron."],[9,2,"Kaj ili timu vin kaj tremu antaŭ vi, ĉiuj bestoj de la tero kaj ĉiuj birdoj de la ĉielo, ĉio, kio moviĝas sur la tero, kaj ĉiuj fiŝoj de la maro; en viajn manojn ili estas transdonitaj.","Kaj ili timu vin kaj tremu antaŭ vi, ĉiuj bestoj de la tero kaj ĉiuj birdoj de la ĉielo, ĉio, kio moviĝas sur la tero, kaj ĉiuj fiŝoj de la maro; en viajn manojn ili estas transdonitaj."],[9,3,"Ĉio, kio moviĝas kaj vivas, servu al vi kiel manĝaĵo; kiel verdan herbon, Mi donis al vi ĉion.","Ĉio, kio moviĝas kaj vivas, servu al vi kiel manĝaĵo; kiel verdan herbon, Mi donis al vi ĉion."],[9,4,"Nur karnon kune kun ĝia animo, la sango, ne manĝu.","Nur karnon kune kun ĝia animo, la sango, ne manĝu."],[9,5,"Ankaŭ vian sangon kaj animon Mi repostulos, el la manoj de ĉiuj bestoj Mi ĝin repostulos, kaj el la manoj de homo, el la manoj de ĉiu homo pro lia frato Mi repostulos la animon de homo.","Ankaŭ vian sangon kaj animon Mi repostulos, el la manoj de ĉiuj bestoj Mi ĝin repostulos, kaj el la manoj de homo, el la manoj de ĉiu homo pro lia frato Mi repostulos la animon de homo."],[9,6,"Se iu verŝos sangon de homo, lia sango ankaŭ estos verŝita de homo; ĉar laŭ la bildo de Dio estas farita la homo.","Se iu verŝos sangon de homo, lia sango ankaŭ estos verŝita de homo; ĉar laŭ la bildo de Dio estas farita la homo."],[9,7,"Kaj vi fruktu kaj multiĝu, moviĝadu sur la tero kaj multiĝu sur ĝi.","Kaj vi fruktu kaj multiĝu, moviĝadu sur la tero kaj multiĝu sur ĝi."],[9,8,"Kaj Dio diris al Noa kaj al liaj filoj kune kun li jene:","Kaj Dio diris al Noa kaj al liaj filoj kune kun li jene:"],[9,9,"Jen Mi starigas Mian interligon kun vi kaj kun via idaro post vi;","Jen Mi starigas Mian interligon kun vi kaj kun via idaro post vi;"],[9,10,"kaj kun ĉiu viva ekzistaĵo, kiu estas kun vi, el birdoj, el brutoj, kaj el ĉiuj bestoj de la tero kun vi, el ĉiuj, kiuj eliris el la arkeo, kun ĉiuj bestoj de la tero.","kaj kun ĉiu viva ekzistaĵo, kiu estas kun vi, el birdoj, el brutoj, kaj el ĉiuj bestoj de la tero kun vi, el ĉiuj, kiuj eliris el la arkeo, kun ĉiuj bestoj de la tero."],[9,11,"Kaj Mi starigas Mian interligon kun vi, ke ne ekstermiĝos plu ĉiu karno per akvo de diluvo, kaj ne estos plu diluvo, por pereigi la teron.","Kaj Mi starigas Mian interligon kun vi, ke ne ekstermiĝos plu ĉiu karno per akvo de diluvo, kaj ne estos plu diluvo, por pereigi la teron."],[9,12,"Kaj Dio diris: Ĉi tio estas la signo de la interligo, kiun Mi metas inter Mi kaj inter vi kaj inter ĉiu viva ekzistaĵo, kiu estas kun vi, por eternaj generacioj:","Kaj Dio diris: Ĉi tio estas la signo de la interligo, kiun Mi metas inter Mi kaj inter vi kaj inter ĉiu viva ekzistaĵo, kiu estas kun vi, por eternaj generacioj:"],[9,13,"Mian arkon Mi metas en la nubon, kaj ĝi estu signo de la interligo inter Mi kaj la tero.","Mian arkon Mi metas en la nubon, kaj ĝi estu signo de la interligo inter Mi kaj la tero."],[9,14,"Kaj kiam Mi venigos nubon super la teron, montriĝos la arko en la nubo;","Kaj kiam Mi venigos nubon super la teron, montriĝos la arko en la nubo;"],[9,15,"kaj Mi rememoros Mian interligon, kiu ekzistas inter Mi kaj vi kaj ĉiu viva ekzistaĵo el ĉiu karno, kaj la akvo ne fariĝos plu diluvo, por pereigi ĉiun karnon.","kaj Mi rememoros Mian interligon, kiu ekzistas inter Mi kaj vi kaj ĉiu viva ekzistaĵo el ĉiu karno, kaj la akvo ne fariĝos plu diluvo, por pereigi ĉiun karnon."],[9,16,"Kaj la arko estos en la nubo; kaj Mi ĝin vidos, por memori pri la eterna interligo inter Dio kaj ĉiu viva ekzistaĵo el ĉiu karno, kiu estas sur la tero.","Kaj la arko estos en la nubo; kaj Mi ĝin vidos, por memori pri la eterna interligo inter Dio kaj ĉiu viva ekzistaĵo el ĉiu karno, kiu estas sur la tero."],[9,17,"Kaj Dio diris al Noa: Ĉi tio estas la signo de la interligo, kiun Mi starigis inter Mi kaj ĉiu karno, kiu estas sur la tero.","Kaj Dio diris al Noa: Ĉi tio estas la signo de la interligo, kiun Mi starigis inter Mi kaj ĉiu karno, kiu estas sur la tero."],[9,18,"Kaj la filoj de Noa, kiuj eliris el la arkeo, estis: Ŝem, Ĥam, kaj Jafet; kaj Ĥam estis la patro de Kanaan.","Kaj la filoj de Noa, kiuj eliris el la arkeo, estis: Ŝem, Ĥam, kaj Jafet; kaj Ĥam estis la patro de Kanaan."],[9,19,"Tio estis la tri filoj de Noa; kaj de ili diskreskis la tuta loĝantaro de la tero.","Tio estis la tri filoj de Noa; kaj de ili diskreskis la tuta loĝantaro de la tero."],[9,20,"Kaj Noa komencis terkultivan laboron kaj plantis vinberĝardenon.","Kaj Noa komencis terkultivan laboron kaj plantis vinberĝardenon."],[9,21,"Kaj li trinkis el la vino kaj ebriiĝis, kaj nudiĝis en sia tendo.","Kaj li trinkis el la vino kaj ebriiĝis, kaj nudiĝis en sia tendo."],[9,22,"Kaj Ĥam, la patro de Kanaan, vidis la nudecon de sia patro, kaj li diris tion al siaj du fratoj ekstere.","Kaj Ĥam, la patro de Kanaan, vidis la nudecon de sia patro, kaj li diris tion al siaj du fratoj ekstere."],[9,23,"Kaj Ŝem kaj Jafet prenis la veston kaj metis ĝin sur siajn ŝultrojn, kaj iris dorsdirekte kaj kovris la nudecon de sia patro; kaj iliaj vizaĝoj estis turnitaj malantaŭen, kaj la nudecon de sia patro ili ne vidis.","Kaj Ŝem kaj Jafet prenis la veston kaj metis ĝin sur siajn ŝultrojn, kaj iris dorsdirekte kaj kovris la nudecon de sia patro; kaj iliaj vizaĝoj estis turnitaj malantaŭen, kaj la nudecon de sia patro ili ne vidis."],[9,24,"Kaj Noa vekiĝis de sia ebrieco, kaj li sciiĝis, kiel agis kun li lia pli juna filo.","Kaj Noa vekiĝis de sia ebrieco, kaj li sciiĝis, kiel agis kun li lia pli juna filo."],[9,25,"Kaj li diris: Malbenita estu Kanaan; Sklavo de sklavoj li estu ĉe siaj fratoj. Kaj li diris:","Kaj li diris: Malbenita estu Kanaan; Sklavo de sklavoj li estu ĉe siaj fratoj. Kaj li diris:"],[9,26,"Glorata estu la Eternulo, la Dio de Ŝem; Kaj Kanaan estu sklavo al ili;","Glorata estu la Eternulo, la Dio de Ŝem; Kaj Kanaan estu sklavo al ili;"],[9,27,"Dio disvastigu Jafeton, Kaj li loĝu en la tendoj de Ŝem, Kaj Kanaan estu sklavo al ili.","Dio disvastigu Jafeton, Kaj li loĝu en la tendoj de Ŝem, Kaj Kanaan estu sklavo al ili."],[9,28,"Kaj Noa vivis post la diluvo tricent kvindek jarojn.","Kaj Noa vivis post la diluvo tricent kvindek jarojn."],[9,29,"Kaj la tuta vivo de Noa estis naŭcent kvindek jaroj, kaj li mortis.","Kaj la tuta vivo de Noa estis naŭcent kvindek jaroj, kaj li mortis."],[10,1,"Jen estas la generaciaro de la filoj de Noa: Ŝem, Ĥam, kaj Jafet. Kaj naskiĝis al ili filoj post la diluvo.","Jen estas la generaciaro de la filoj de Noa: Ŝem, Ĥam, kaj Jafet. Kaj naskiĝis al ili filoj post la diluvo."],[10,2,"La filoj de Jafet: Gomer kaj Magog kaj Madaj kaj Javan kaj Tubal kaj Meŝeĥ kaj Tiras.","La filoj de Jafet: Gomer kaj Magog kaj Madaj kaj Javan kaj Tubal kaj Meŝeĥ kaj Tiras."],[10,3,"Kaj la filoj de Gomer: Aŝkenaz kaj Rifat kaj Togarma.","Kaj la filoj de Gomer: Aŝkenaz kaj Rifat kaj Togarma."],[10,4,"Kaj la filoj de Javan: Eliŝa kaj Tarŝiŝ, Kitim kaj Dodanim.","Kaj la filoj de Javan: Eliŝa kaj Tarŝiŝ, Kitim kaj Dodanim."],[10,5,"De ĉi tiuj dissemiĝis la insuloj da popoloj en siaj landoj, ĉiu laŭ sia lingvo, laŭ siaj gentoj kaj nacioj.","De ĉi tiuj dissemiĝis la insuloj da popoloj en siaj landoj, ĉiu laŭ sia lingvo, laŭ siaj gentoj kaj nacioj."],[10,6,"Kaj la filoj de Ĥam: Kuŝ kaj Micraim kaj Put kaj Kanaan.","Kaj la filoj de Ĥam: Kuŝ kaj Micraim kaj Put kaj Kanaan."],[10,7,"Kaj la filoj de Kuŝ: Seba kaj Ĥavila kaj Sabta kaj Raama kaj Sabteĥa; kaj la filoj de Raama; Ŝeba kaj Dedan.","Kaj la filoj de Kuŝ: Seba kaj Ĥavila kaj Sabta kaj Raama kaj Sabteĥa; kaj la filoj de Raama; Ŝeba kaj Dedan."],[10,8,"Kaj Kuŝ naskigis Nimrodon; kiu komencis esti potenca sur la tero.","Kaj Kuŝ naskigis Nimrodon; kiu komencis esti potenca sur la tero."],[10,9,"Li estis potenca ĉasisto antaŭ la Eternulo; tial oni diras: Kiel Nimrod, potenca ĉasisto antaŭ la Eternulo.","Li estis potenca ĉasisto antaŭ la Eternulo; tial oni diras: Kiel Nimrod, potenca ĉasisto antaŭ la Eternulo."],[10,10,"Kaj la komenco de lia regno estis Babel kaj Ereĥ kaj Akad kaj Kalne en la lando Ŝinar.","Kaj la komenco de lia regno estis Babel kaj Ereĥ kaj Akad kaj Kalne en la lando Ŝinar."],[10,11,"El ĉi tiu lando li eliris en Asirion kaj konstruis la urbojn Nineve kaj Reĥobot kaj Kalaĥ,","El ĉi tiu lando li eliris en Asirion kaj konstruis la urbojn Nineve kaj Reĥobot kaj Kalaĥ,"],[10,12,"kaj Resen inter Nineve kaj Kalaĥ (ĝi estis la granda urbo).","kaj Resen inter Nineve kaj Kalaĥ (ĝi estis la granda urbo)."],[10,13,"Kaj Micraim naskigis la Ludidojn kaj la Anamidojn kaj la Lehabidojn kaj la Naftuĥidojn","Kaj Micraim naskigis la Ludidojn kaj la Anamidojn kaj la Lehabidojn kaj la Naftuĥidojn"],[10,14,"kaj la Patrusidojn kaj la Kasluĥidojn (de kiuj devenis la Filiŝtoj) kaj la Kaftoridojn.","kaj la Patrusidojn kaj la Kasluĥidojn (de kiuj devenis la Filiŝtoj) kaj la Kaftoridojn."],[10,15,"Kaj de Kanaan naskiĝis Cidon, lia unuenaskito, kaj Ĥet,","Kaj de Kanaan naskiĝis Cidon, lia unuenaskito, kaj Ĥet,"],[10,16,"kaj la Jebusidoj kaj la Amoridoj kaj la Girgaŝidoj","kaj la Jebusidoj kaj la Amoridoj kaj la Girgaŝidoj"],[10,17,"kaj la Ĥividoj kaj la Arkidoj kaj la Sinidoj","kaj la Ĥividoj kaj la Arkidoj kaj la Sinidoj"],[10,18,"kaj la Arvadidoj kaj la Cemaridoj kaj la Ĥamatidoj; kaj poste la gentoj Kanaanaj disiĝis.","kaj la Arvadidoj kaj la Cemaridoj kaj la Ĥamatidoj; kaj poste la gentoj Kanaanaj disiĝis."],[10,19,"Kaj la limoj de la Kanaanidoj estis de Cidon ĝis Gerar kaj Gaza, ĝis Sodom kaj Gomora, Adma kaj Ceboim ĝis Laŝa.","Kaj la limoj de la Kanaanidoj estis de Cidon ĝis Gerar kaj Gaza, ĝis Sodom kaj Gomora, Adma kaj Ceboim ĝis Laŝa."],[10,20,"Tio estas la filoj de Ĥam laŭ siaj gentoj kaj lingvoj, en siaj landoj kaj nacioj.","Tio estas la filoj de Ĥam laŭ siaj gentoj kaj lingvoj, en siaj landoj kaj nacioj."],[10,21,"Naskiĝis infanoj ankaŭ al Ŝem, la patro de ĉiuj Eberidoj, pli maljuna frato de Jafet.","Naskiĝis infanoj ankaŭ al Ŝem, la patro de ĉiuj Eberidoj, pli maljuna frato de Jafet."],[10,22,"La filoj de Ŝem: Elam kaj Aŝur kaj Arpaĥŝad kaj Lud kaj Aram.","La filoj de Ŝem: Elam kaj Aŝur kaj Arpaĥŝad kaj Lud kaj Aram."],[10,23,"Kaj la filoj de Aram: Uc kaj Ĥul kaj Geter kaj Maŝ.","Kaj la filoj de Aram: Uc kaj Ĥul kaj Geter kaj Maŝ."],[10,24,"Kaj al Arpaĥŝad naskiĝis Ŝelaĥ, kaj al Ŝelaĥ naskiĝis Eber.","Kaj al Arpaĥŝad naskiĝis Ŝelaĥ, kaj al Ŝelaĥ naskiĝis Eber."],[10,25,"Kaj al Eber naskiĝis du filoj: la nomo de unu estis Peleg, ĉar dum lia vivo dividiĝis la tero; kaj la nomo de lia frato estis Joktan.","Kaj al Eber naskiĝis du filoj: la nomo de unu estis Peleg, ĉar dum lia vivo dividiĝis la tero; kaj la nomo de lia frato estis Joktan."],[10,26,"Kaj al Joktan naskiĝis Almodad kaj Ŝelef kaj Ĥacarmavet kaj Jeraĥ","Kaj al Joktan naskiĝis Almodad kaj Ŝelef kaj Ĥacarmavet kaj Jeraĥ"],[10,27,"kaj Hadoram kaj Uzal kaj Dikla","kaj Hadoram kaj Uzal kaj Dikla"],[10,28,"kaj Obal kaj Abimael kaj Ŝeba","kaj Obal kaj Abimael kaj Ŝeba"],[10,29,"kaj Ofir kaj Ĥavila kaj Jobab. Ĉiuj ĉi tiuj estis filoj de Joktan.","kaj Ofir kaj Ĥavila kaj Jobab. Ĉiuj ĉi tiuj estis filoj de Joktan."],[10,30,"Kaj ilia loĝloko estis de Meŝa ĝis Sefar, la orienta monto.","Kaj ilia loĝloko estis de Meŝa ĝis Sefar, la orienta monto."],[10,31,"Tio estas la filoj de Ŝem laŭ siaj gentoj kaj lingvoj, en siaj landoj, laŭ siaj nacioj.","Tio estas la filoj de Ŝem laŭ siaj gentoj kaj lingvoj, en siaj landoj, laŭ siaj nacioj."],[10,32,"Tio estas la gentoj de la filoj de Noa, laŭ siaj generacioj, en siaj nacioj; kaj de ili disiĝis la popoloj sur la tero post la diluvo.","Tio estas la gentoj de la filoj de Noa, laŭ siaj generacioj, en siaj nacioj; kaj de ili disiĝis la popoloj sur la tero post la diluvo."],[11,1,"Sur la tuta tero estis unu lingvo kaj unu parolmaniero.","Sur la tuta tero estis unu lingvo kaj unu parolmaniero."],[11,2,"Kaj kiam ili ekiris de la oriento, ili trovis valon en la lando Ŝinar kaj tie ekloĝis.","Kaj kiam ili ekiris de la oriento, ili trovis valon en la lando Ŝinar kaj tie ekloĝis."],[11,3,"Kaj ili diris unu al alia: Venu, ni faru brikojn kaj ni brulpretigu ilin per fajro. Kaj la brikoj fariĝis por ili ŝtonoj, kaj la bitumo fariĝis por ili kalko.","Kaj ili diris unu al alia: Venu, ni faru brikojn kaj ni brulpretigu ilin per fajro. Kaj la brikoj fariĝis por ili ŝtonoj, kaj la bitumo fariĝis por ili kalko."],[11,4,"Kaj ili diris: Venu, ni konstruu al ni urbon, kaj turon, kies supro atingos la ĉielon, kaj ni akiru al ni gloron, antaŭ ol ni disiĝos sur la supraĵo de la tuta tero.","Kaj ili diris: Venu, ni konstruu al ni urbon, kaj turon, kies supro atingos la ĉielon, kaj ni akiru al ni gloron, antaŭ ol ni disiĝos sur la supraĵo de la tuta tero."],[11,5,"Kaj la Eternulo malleviĝis, por vidi la urbon kaj la turon, kiujn konstruis la homidoj.","Kaj la Eternulo malleviĝis, por vidi la urbon kaj la turon, kiujn konstruis la homidoj."],[11,6,"Kaj la Eternulo diris: Jen estas unu popolo, kaj unu lingvon ili ĉiuj havas; kaj jen, kion ili komencis fari, kaj ili ne estos malhelpataj en ĉio, kion ili decidis fari.","Kaj la Eternulo diris: Jen estas unu popolo, kaj unu lingvon ili ĉiuj havas; kaj jen, kion ili komencis fari, kaj ili ne estos malhelpataj en ĉio, kion ili decidis fari."],[11,7,"Ni malleviĝu do, kaj Ni konfuzu tie ilian lingvon, por ke unu ne komprenu la parolon de alia.","Ni malleviĝu do, kaj Ni konfuzu tie ilian lingvon, por ke unu ne komprenu la parolon de alia."],[11,8,"Kaj la Eternulo disigis ilin de tie sur la supraĵon de la tuta tero, kaj ili ĉesis konstrui la urbon.","Kaj la Eternulo disigis ilin de tie sur la supraĵon de la tuta tero, kaj ili ĉesis konstrui la urbon."],[11,9,"Tial oni donis al ĝi la nomon Babel, ĉar tie la Eternulo konfuzis la lingvon de la tuta tero kaj de tie la Eternulo disigis ilin sur la supraĵon de la tuta tero.","Tial oni donis al ĝi la nomon Babel, ĉar tie la Eternulo konfuzis la lingvon de la tuta tero kaj de tie la Eternulo disigis ilin sur la supraĵon de la tuta tero."],[11,10,"Jen estas la generaciaro de Ŝem: Ŝem havis la aĝon de cent jaroj, kaj naskiĝis al li Arpaĥŝad, du jarojn post la diluvo.","Jen estas la generaciaro de Ŝem: Ŝem havis la aĝon de cent jaroj, kaj naskiĝis al li Arpaĥŝad, du jarojn post la diluvo."],[11,11,"Kaj Ŝem vivis post la naskiĝo de Arpaĥŝad kvincent jarojn, kaj naskiĝis al li filoj kaj filinoj.","Kaj Ŝem vivis post la naskiĝo de Arpaĥŝad kvincent jarojn, kaj naskiĝis al li filoj kaj filinoj."],[11,12,"Kaj Arpaĥŝad vivis tridek kvin jarojn, kaj naskiĝis al li Ŝelaĥ.","Kaj Arpaĥŝad vivis tridek kvin jarojn, kaj naskiĝis al li Ŝelaĥ."],[11,13,"Kaj Arpaĥŝad vivis post la naskiĝo de Ŝelaĥ kvarcent tri jarojn, kaj naskiĝis al li filoj kaj filinoj.","Kaj Arpaĥŝad vivis post la naskiĝo de Ŝelaĥ kvarcent tri jarojn, kaj naskiĝis al li filoj kaj filinoj."],[11,14,"Kaj Ŝelaĥ vivis tridek jarojn, kaj naskiĝis al li Eber.","Kaj Ŝelaĥ vivis tridek jarojn, kaj naskiĝis al li Eber."],[11,15,"Kaj Ŝelaĥ vivis post la naskiĝo de Eber kvarcent tri jarojn, kaj naskiĝis al li filoj kaj filinoj.","Kaj Ŝelaĥ vivis post la naskiĝo de Eber kvarcent tri jarojn, kaj naskiĝis al li filoj kaj filinoj."],[11,16,"Kaj Eber vivis tridek kvar jarojn, kaj naskiĝis al li Peleg.","Kaj Eber vivis tridek kvar jarojn, kaj naskiĝis al li Peleg."],[11,17,"Kaj Eber vivis post la naskiĝo de Peleg kvarcent tridek jarojn, kaj naskiĝis al li filoj kaj filinoj.","Kaj Eber vivis post la naskiĝo de Peleg kvarcent tridek jarojn, kaj naskiĝis al li filoj kaj filinoj."],[11,18,"Kaj Peleg vivis tridek jarojn, kaj naskiĝis al li Reu.","Kaj Peleg vivis tridek jarojn, kaj naskiĝis al li Reu."],[11,19,"Kaj Peleg vivis post la naskiĝo de Reu ducent naŭ jarojn, kaj naskiĝis al li filoj kaj filinoj.","Kaj Peleg vivis post la naskiĝo de Reu ducent naŭ jarojn, kaj naskiĝis al li filoj kaj filinoj."],[11,20,"Kaj Reu vivis tridek du jarojn, kaj naskiĝis al li Serug.","Kaj Reu vivis tridek du jarojn, kaj naskiĝis al li Serug."],[11,21,"Kaj Reu vivis post la naskiĝo de Serug ducent sep jarojn, kaj naskiĝis al li filoj kaj filinoj.","Kaj Reu vivis post la naskiĝo de Serug ducent sep jarojn, kaj naskiĝis al li filoj kaj filinoj."],[11,22,"Kaj Serug vivis tridek jarojn, kaj naskiĝis al li Naĥor.","Kaj Serug vivis tridek jarojn, kaj naskiĝis al li Naĥor."],[11,23,"Kaj Serug vivis post la naskiĝo de Naĥor ducent jarojn, kaj naskiĝis al li filoj kaj filinoj.","Kaj Serug vivis post la naskiĝo de Naĥor ducent jarojn, kaj naskiĝis al li filoj kaj filinoj."],[11,24,"Kaj Naĥor vivis dudek naŭ jarojn, kaj naskiĝis al li Teraĥ.","Kaj Naĥor vivis dudek naŭ jarojn, kaj naskiĝis al li Teraĥ."],[11,25,"Kaj Naĥor vivis post la naskiĝo de Teraĥ cent dek naŭ jarojn, kaj naskiĝis al li filoj kaj filinoj.","Kaj Naĥor vivis post la naskiĝo de Teraĥ cent dek naŭ jarojn, kaj naskiĝis al li filoj kaj filinoj."],[11,26,"Kaj Teraĥ vivis sepdek jarojn, kaj naskiĝis al li Abram, Naĥor, kaj Haran.","Kaj Teraĥ vivis sepdek jarojn, kaj naskiĝis al li Abram, Naĥor, kaj Haran."],[11,27,"Kaj jen estas la generaciaro de Teraĥ: al Teraĥ naskiĝis Abram, Naĥor, kaj Haran; kaj al Haran naskiĝis Lot.","Kaj jen estas la generaciaro de Teraĥ: al Teraĥ naskiĝis Abram, Naĥor, kaj Haran; kaj al Haran naskiĝis Lot."],[11,28,"Kaj Haran mortis antaŭ sia patro Teraĥ en sia lando de naskiĝo, en Ur la Ĥaldea.","Kaj Haran mortis antaŭ sia patro Teraĥ en sia lando de naskiĝo, en Ur la Ĥaldea."],[11,29,"Kaj Abram kaj Naĥor prenis al si edzinojn; la nomo de la edzino de Abram estis Saraj, kaj la nomo de la edzino de Naĥor estis Milka, filino de Haran, kiu estis la patro de Milka kaj la patro de Jiska.","Kaj Abram kaj Naĥor prenis al si edzinojn; la nomo de la edzino de Abram estis Saraj, kaj la nomo de la edzino de Naĥor estis Milka, filino de Haran, kiu estis la patro de Milka kaj la patro de Jiska."],[11,30,"Kaj Saraj estis senfrukta kaj ne havis infanon.","Kaj Saraj estis senfrukta kaj ne havis infanon."],[11,31,"Kaj Teraĥ prenis sian filon Abram kaj sian nepon Lot, filo de Haran, kaj sian bofilinon Saraj, edzino de lia filo Abram; kaj ili eliris kune el Ur la Ĥaldea, por iri en la landon Kanaanan; kaj ili venis ĝis Ĥaran kaj enloĝiĝis tie.","Kaj Teraĥ prenis sian filon Abram kaj sian nepon Lot, filo de Haran, kaj sian bofilinon Saraj, edzino de lia filo Abram; kaj ili eliris kune el Ur la Ĥaldea, por iri en la landon Kanaanan; kaj ili venis ĝis Ĥaran kaj enloĝiĝis tie."],[11,32,"Kaj Teraĥ atingis la aĝon de ducent kvin jaroj, kaj Teraĥ mortis en Ĥaran.","Kaj Teraĥ atingis la aĝon de ducent kvin jaroj, kaj Teraĥ mortis en Ĥaran."],[12,1,"Kaj la Eternulo diris al Abram: Iru el via lando, el inter via parencaro, kaj el la domo de via patro, al la lando, kiun Mi montros al vi.","Kaj la Eternulo diris al Abram: Iru el via lando, el inter via parencaro, kaj el la domo de via patro, al la lando, kiun Mi montros al vi."],[12,2,"Kaj Mi faros vin granda popolo, kaj Mi benos vin kaj grandigos vian nomon, kaj vi estos beno.","Kaj Mi faros vin granda popolo, kaj Mi benos vin kaj grandigos vian nomon, kaj vi estos beno."],[12,3,"Kaj Mi benos viajn benantojn, kaj viajn malbenantojn Mi malbenos, kaj beniĝos per vi ĉiuj gentoj de la tero.","Kaj Mi benos viajn benantojn, kaj viajn malbenantojn Mi malbenos, kaj beniĝos per vi ĉiuj gentoj de la tero."],[12,4,"Kaj Abram iris, kiel la Eternulo diris al li, kaj kun li iris Lot. Kaj Abram havis la aĝon de sepdek kvin jaroj, kiam li eliris el Ĥaran.","Kaj Abram iris, kiel la Eternulo diris al li, kaj kun li iris Lot. Kaj Abram havis la aĝon de sepdek kvin jaroj, kiam li eliris el Ĥaran."],[12,5,"Kaj Abram prenis sian edzinon Saraj kaj sian nevon Lot, kaj ilian tutan havon, kiun ili akiris, kaj la homojn, kiujn ili akiris en Ĥaran; kaj ili eliris, por iri al la lando Kanaana; kaj ili venis en la landon Kanaanan.","Kaj Abram prenis sian edzinon Saraj kaj sian nevon Lot, kaj ilian tutan havon, kiun ili akiris, kaj la homojn, kiujn ili akiris en Ĥaran; kaj ili eliris, por iri al la lando Kanaana; kaj ili venis en la landon Kanaanan."],[12,6,"Kaj Abram trapasis la landon ĝis la loko Ŝeĥem, ĝis la kverko More; kaj la Kanaanidoj tiam loĝis en la lando.","Kaj Abram trapasis la landon ĝis la loko Ŝeĥem, ĝis la kverko More; kaj la Kanaanidoj tiam loĝis en la lando."],[12,7,"Kaj la Eternulo aperis al Abram, kaj diris: Al via idaro Mi donos ĉi tiun teron. Kaj li konstruis tie altaron al la Eternulo, kiu aperis al li.","Kaj la Eternulo aperis al Abram, kaj diris: Al via idaro Mi donos ĉi tiun teron. Kaj li konstruis tie altaron al la Eternulo, kiu aperis al li."],[12,8,"Kaj de tie li transloĝiĝis al la monto, kiu estas oriente de Bet-El, kaj aranĝis sian tendon tiamaniere, ke Bet-El estis okcidente kaj Aj oriente; kaj li konstruis tie altaron al la Eternulo kaj preĝadis al la Eternulo.","Kaj de tie li transloĝiĝis al la monto, kiu estas oriente de Bet-El, kaj aranĝis sian tendon tiamaniere, ke Bet-El estis okcidente kaj Aj oriente; kaj li konstruis tie altaron al la Eternulo kaj preĝadis al la Eternulo."],[12,9,"Kaj Abram iris pluen, ĉiam pluen al sudo.","Kaj Abram iris pluen, ĉiam pluen al sudo."],[12,10,"Kaj estis malsato en la lando. Kaj Abram malsupreniris Egiptujon, por tie loĝi kelktempe, ĉar malfacila estis la malsato en la lando.","Kaj estis malsato en la lando. Kaj Abram malsupreniris Egiptujon, por tie loĝi kelktempe, ĉar malfacila estis la malsato en la lando."],[12,11,"Kaj kiam li estis jam proksime de Egiptujo, li diris al sia edzino Saraj: Mi scias ja, ke vi estas virino belaspekta;","Kaj kiam li estis jam proksime de Egiptujo, li diris al sia edzino Saraj: Mi scias ja, ke vi estas virino belaspekta;"],[12,12,"kaj kiam la Egiptoj vin vidos, ili diros: Tio estas lia edzino; kaj ili mortigos min, kaj vin ili lasos viva.","kaj kiam la Egiptoj vin vidos, ili diros: Tio estas lia edzino; kaj ili mortigos min, kaj vin ili lasos viva."],[12,13,"Diru do, ke vi estas mia fratino, por ke al mi estu bone pro vi kaj por ke mia animo restu viva pro vi.","Diru do, ke vi estas mia fratino, por ke al mi estu bone pro vi kaj por ke mia animo restu viva pro vi."],[12,14,"Kaj kiam Abram venis Egiptujon, la Egiptoj vidis, ke la virino estas tre bela;","Kaj kiam Abram venis Egiptujon, la Egiptoj vidis, ke la virino estas tre bela;"],[12,15,"kaj vidis ŝin la eminentuloj de Faraono, kaj ili laŭdis ŝin al Faraono; kaj oni prenis la virinon en la domon de Faraono.","kaj vidis ŝin la eminentuloj de Faraono, kaj ili laŭdis ŝin al Faraono; kaj oni prenis la virinon en la domon de Faraono."],[12,16,"Kaj al Abram estis bone pro ŝi, kaj li havis ŝafojn kaj bovojn kaj azenojn kaj sklavojn kaj sklavinojn kaj azeninojn kaj kamelojn.","Kaj al Abram estis bone pro ŝi, kaj li havis ŝafojn kaj bovojn kaj azenojn kaj sklavojn kaj sklavinojn kaj azeninojn kaj kamelojn."],[12,17,"Kaj la Eternulo punis per grandaj suferoj Faraonon kaj lian domon pro Saraj, la edzino de Abram.","Kaj la Eternulo punis per grandaj suferoj Faraonon kaj lian domon pro Saraj, la edzino de Abram."],[12,18,"Kaj Faraono alvokis Abramon, kaj diris: Kion vi faris al mi? kial vi ne diris al mi, ke ŝi estas via edzino?","Kaj Faraono alvokis Abramon, kaj diris: Kion vi faris al mi? kial vi ne diris al mi, ke ŝi estas via edzino?"],[12,19,"kial vi diris: Ŝi estas mia fratino? Kaj mi prenis ŝin al mi kiel edzinon. Kaj nun jen estas via edzino; prenu kaj foriru.","kial vi diris: Ŝi estas mia fratino? Kaj mi prenis ŝin al mi kiel edzinon. Kaj nun jen estas via edzino; prenu kaj foriru."],[12,20,"Kaj Faraono ordonis pri li al homoj, kaj ili forkondukis lin kaj lian edzinon kaj lian tutan havon.","Kaj Faraono ordonis pri li al homoj, kaj ili forkondukis lin kaj lian edzinon kaj lian tutan havon."],[13,1,"Kaj Abram supreniris el Egiptujo, li kaj lia edzino, kaj ĉio, kio estis kun li, kaj kun li ankaŭ Lot, direktante sin al sudo.","Kaj Abram supreniris el Egiptujo, li kaj lia edzino, kaj ĉio, kio estis kun li, kaj kun li ankaŭ Lot, direktante sin al sudo."],[13,2,"Kaj Abram estis tre riĉa je brutoj, arĝento, kaj oro.","Kaj Abram estis tre riĉa je brutoj, arĝento, kaj oro."],[13,3,"Kaj li daŭrigis sian migradon de sudo ĝis Bet-El, ĝis la loko, kie antaŭe estis lia tendo inter Bet-El kaj Aj,","Kaj li daŭrigis sian migradon de sudo ĝis Bet-El, ĝis la loko, kie antaŭe estis lia tendo inter Bet-El kaj Aj,"],[13,4,"al la loko de la altaro, kiun li tie faris antaŭe; kaj Abram tie preĝis al la Eternulo.","al la loko de la altaro, kiun li tie faris antaŭe; kaj Abram tie preĝis al la Eternulo."],[13,5,"Kaj ankaŭ Lot, kiu iris kun Abram, havis ŝafojn kaj bovojn kaj tendojn.","Kaj ankaŭ Lot, kiu iris kun Abram, havis ŝafojn kaj bovojn kaj tendojn."],[13,6,"Kaj ne sufiĉis por ili la tero, ke ili loĝu kune, ĉar ilia havo estis granda kaj ili ne povis loĝi kune.","Kaj ne sufiĉis por ili la tero, ke ili loĝu kune, ĉar ilia havo estis granda kaj ili ne povis loĝi kune."],[13,7,"Kaj estis malpaco inter la paŝtistoj de la brutaro de Abram kaj la paŝtistoj de la brutaro de Lot; kaj la Kanaanidoj kaj Perizidoj tiam loĝis en la lando.","Kaj estis malpaco inter la paŝtistoj de la brutaro de Abram kaj la paŝtistoj de la brutaro de Lot; kaj la Kanaanidoj kaj Perizidoj tiam loĝis en la lando."],[13,8,"Kaj Abram diris al Lot: Ne estu malpaco inter mi kaj vi kaj inter miaj paŝtistoj kaj viaj paŝtistoj, ĉar ni estas fratoj.","Kaj Abram diris al Lot: Ne estu malpaco inter mi kaj vi kaj inter miaj paŝtistoj kaj viaj paŝtistoj, ĉar ni estas fratoj."],[13,9,"La tuta tero estas ja antaŭ vi; apartiĝu do de mi: se vi iros maldekstren, mi iros dekstren; se vi iros dekstren, mi iros maldekstren.","La tuta tero estas ja antaŭ vi; apartiĝu do de mi: se vi iros maldekstren, mi iros dekstren; se vi iros dekstren, mi iros maldekstren."],[13,10,"Kaj Lot levis siajn okulojn kaj vidis, ke la tuta ĉirkaŭaĵo de Jordan, antaŭ ol la Eternulo pereigis Sodomon kaj Gomoran, tuta estas akvumata kiel ĝardeno de la Eternulo, kiel la lando Egipta, ĝis Coar.","Kaj Lot levis siajn okulojn kaj vidis, ke la tuta ĉirkaŭaĵo de Jordan, antaŭ ol la Eternulo pereigis Sodomon kaj Gomoran, tuta estas akvumata kiel ĝardeno de la Eternulo, kiel la lando Egipta, ĝis Coar."],[13,11,"Kaj Lot elektis al si la tutan ĉirkaŭaĵon de Jordan; kaj Lot ekiris orienten; kaj ili apartiĝis unu de la alia:","Kaj Lot elektis al si la tutan ĉirkaŭaĵon de Jordan; kaj Lot ekiris orienten; kaj ili apartiĝis unu de la alia:"],[13,12,"Abram enloĝiĝis en la lando Kanaana, kaj Lot enloĝiĝis en la urboj de la ĉirkaŭaĵo kaj starigis siajn tendojn ĝis Sodom.","Abram enloĝiĝis en la lando Kanaana, kaj Lot enloĝiĝis en la urboj de la ĉirkaŭaĵo kaj starigis siajn tendojn ĝis Sodom."],[13,13,"Kaj la loĝantoj de Sodom estis malbonaj kaj tre pekaj kontraŭ la Eternulo.","Kaj la loĝantoj de Sodom estis malbonaj kaj tre pekaj kontraŭ la Eternulo."],[13,14,"Kaj la Eternulo diris al Abram, post kiam Lot apartiĝis de li: Levu viajn okulojn, kaj rigardu de la loko, sur kiu vi nun estas, norden kaj suden kaj orienten kaj okcidenten;","Kaj la Eternulo diris al Abram, post kiam Lot apartiĝis de li: Levu viajn okulojn, kaj rigardu de la loko, sur kiu vi nun estas, norden kaj suden kaj orienten kaj okcidenten;"],[13,15,"ĉar la tutan teron, kiun vi vidas, Mi donos al vi kaj al via idaro por eterne.","ĉar la tutan teron, kiun vi vidas, Mi donos al vi kaj al via idaro por eterne."],[13,16,"Kaj Mi faros vian idaron kiel polvo de la tero; se iu povos kalkuli la polvon de la tero, li kalkulos ankaŭ vian idaron.","Kaj Mi faros vian idaron kiel polvo de la tero; se iu povos kalkuli la polvon de la tero, li kalkulos ankaŭ vian idaron."],[13,17,"Leviĝu, trairu la landon laŭlonge kaj laŭlarĝe, ĉar al vi Mi ĝin donos.","Leviĝu, trairu la landon laŭlonge kaj laŭlarĝe, ĉar al vi Mi ĝin donos."],[13,18,"Kaj Abram forprenis sian tendon, kaj iris kaj ekloĝis en la arbareto Mamre, kiu estas en Ĥebron; kaj li konstruis tie altaron al la Eternulo.","Kaj Abram forprenis sian tendon, kaj iris kaj ekloĝis en la arbareto Mamre, kiu estas en Ĥebron; kaj li konstruis tie altaron al la Eternulo."],[14,1,"Kaj estis en la tempo de Amrafel, reĝo de Ŝinar, Arjoĥ, reĝo de Elasar, Kedorlaomer, reĝo de Elam, kaj Tidal, reĝo de Gojim;","Kaj estis en la tempo de Amrafel, reĝo de Ŝinar, Arjoĥ, reĝo de Elasar, Kedorlaomer, reĝo de Elam, kaj Tidal, reĝo de Gojim;"],[14,2,"ili faris militon kontraŭ Bera, reĝo de Sodom, kaj Birŝa, reĝo de Gomora, Ŝinab, reĝo de Adma, kaj Ŝemeber, reĝo de Ceboim, kaj la reĝo de Bela, kiu estas Coar.","ili faris militon kontraŭ Bera, reĝo de Sodom, kaj Birŝa, reĝo de Gomora, Ŝinab, reĝo de Adma, kaj Ŝemeber, reĝo de Ceboim, kaj la reĝo de Bela, kiu estas Coar."],[14,3,"Ĉiuj ĉi tiuj kunvenis en la valo Sidim, kiu nun estas la Sala Maro.","Ĉiuj ĉi tiuj kunvenis en la valo Sidim, kiu nun estas la Sala Maro."],[14,4,"Dek du jarojn ili servis al Kedorlaomer, kaj en la dek-tria ili ribeliĝis.","Dek du jarojn ili servis al Kedorlaomer, kaj en la dek-tria ili ribeliĝis."],[14,5,"Kaj en la dek-kvara jaro venis Kedorlaomer, kaj la reĝoj, kiuj estis kun li, kaj ili venkobatis la Rafaidojn en Aŝterot-Karnaim, kaj la Zuzidojn en Ham, kaj la Emidojn en Ŝave-Kirjataim,","Kaj en la dek-kvara jaro venis Kedorlaomer, kaj la reĝoj, kiuj estis kun li, kaj ili venkobatis la Rafaidojn en Aŝterot-Karnaim, kaj la Zuzidojn en Ham, kaj la Emidojn en Ŝave-Kirjataim,"],[14,6,"kaj la Ĥoridojn sur ilia monto Seir ĝis El-Paran, kiu estas ĉe la dezerto.","kaj la Ĥoridojn sur ilia monto Seir ĝis El-Paran, kiu estas ĉe la dezerto."],[14,7,"Kaj ili reiris kaj venis al En-Miŝpat, kiu estas Kadeŝ, kaj venkobatis la tutan kampon de la Amalekidoj, kaj ankaŭ la Amoridojn, kiuj loĝis en Ĥacacon-Tamar.","Kaj ili reiris kaj venis al En-Miŝpat, kiu estas Kadeŝ, kaj venkobatis la tutan kampon de la Amalekidoj, kaj ankaŭ la Amoridojn, kiuj loĝis en Ĥacacon-Tamar."],[14,8,"Kaj eliris la reĝo de Sodom kaj la reĝo de Gomora kaj la reĝo de Adma kaj la reĝo de Ceboim, kaj la reĝo de Bela, kiu estas Coar, kaj komencis batalon kontraŭ ili en la valo Sidim,","Kaj eliris la reĝo de Sodom kaj la reĝo de Gomora kaj la reĝo de Adma kaj la reĝo de Ceboim, kaj la reĝo de Bela, kiu estas Coar, kaj komencis batalon kontraŭ ili en la valo Sidim,"],[14,9,"kontraŭ Kedorlaomer, reĝo de Elam, kaj Tidal, reĝo de Gojim, kaj Amrafel, reĝo de Ŝinar, kaj Arjoĥ, reĝo de Elasar; kvar reĝoj kontraŭ kvin.","kontraŭ Kedorlaomer, reĝo de Elam, kaj Tidal, reĝo de Gojim, kaj Amrafel, reĝo de Ŝinar, kaj Arjoĥ, reĝo de Elasar; kvar reĝoj kontraŭ kvin."],[14,10,"Kaj en la valo Sidim estis multe da bitumaj kavoj; kaj la reĝoj de Sodom kaj Gomora forkuris kaj falis tien, kaj la restintoj kuris sur la monton.","Kaj en la valo Sidim estis multe da bitumaj kavoj; kaj la reĝoj de Sodom kaj Gomora forkuris kaj falis tien, kaj la restintoj kuris sur la monton."],[14,11,"Kaj ili prenis la tutan havon de Sodom kaj Gomora kaj ilian tutan manĝeblaĵon, kaj foriris.","Kaj ili prenis la tutan havon de Sodom kaj Gomora kaj ilian tutan manĝeblaĵon, kaj foriris."],[14,12,"Ili prenis Loton, la nevon de Abram, kaj lian havon, ĉar li loĝis en Sodom, kaj ili foriris.","Ili prenis Loton, la nevon de Abram, kaj lian havon, ĉar li loĝis en Sodom, kaj ili foriris."],[14,13,"Kaj venis forsaviĝinto kaj diris al Abram la Hebreo, kiu loĝis en la arbareto de Mamre la Amorido, frato de Eŝkol kaj frato de Aner, kiuj estis en interligo kun Abram.","Kaj venis forsaviĝinto kaj diris al Abram la Hebreo, kiu loĝis en la arbareto de Mamre la Amorido, frato de Eŝkol kaj frato de Aner, kiuj estis en interligo kun Abram."],[14,14,"Kaj Abram aŭdis, ke lia frato estas kaptita, kaj li elkondukis siajn ekzercitojn, naskitajn en lia domo, tricent dek ok, kaj persekutis ĝis Dan.","Kaj Abram aŭdis, ke lia frato estas kaptita, kaj li elkondukis siajn ekzercitojn, naskitajn en lia domo, tricent dek ok, kaj persekutis ĝis Dan."],[14,15,"Kaj li dividis sin kontraŭ ili en la nokto, li kaj liaj domanoj, kaj venkobatis ilin, kaj persekutis ilin ĝis Ĥoba, kiu estas maldekstre de Damasko.","Kaj li dividis sin kontraŭ ili en la nokto, li kaj liaj domanoj, kaj venkobatis ilin, kaj persekutis ilin ĝis Ĥoba, kiu estas maldekstre de Damasko."],[14,16,"Kaj li revenigis la tutan havon, kaj ankaŭ sian fraton Lot kaj lian havon li revenigis, kaj ankaŭ la virinojn kaj la popolon.","Kaj li revenigis la tutan havon, kaj ankaŭ sian fraton Lot kaj lian havon li revenigis, kaj ankaŭ la virinojn kaj la popolon."],[14,17,"Kaj la reĝo de Sodom eliris al li renkonte, kiam li revenis, venkinte Kedorlaomeron kaj la reĝojn, kiuj estis kun li, en la valon Ŝave, kiu estas Valo de la Reĝo.","Kaj la reĝo de Sodom eliris al li renkonte, kiam li revenis, venkinte Kedorlaomeron kaj la reĝojn, kiuj estis kun li, en la valon Ŝave, kiu estas Valo de la Reĝo."],[14,18,"Kaj Melkicedek, reĝo de Salem, elportis panon kaj vinon. Li estis pastro de Dio Plejsupra.","Kaj Melkicedek, reĝo de Salem, elportis panon kaj vinon. Li estis pastro de Dio Plejsupra."],[14,19,"Kaj li benis lin kaj diris: Benata estu Abram de Dio Plejsupra, la Kreinto de la ĉielo kaj la tero;","Kaj li benis lin kaj diris: Benata estu Abram de Dio Plejsupra, la Kreinto de la ĉielo kaj la tero;"],[14,20,"kaj benata estu Dio Plejsupra, kiu transdonis viajn malamikojn en viajn manojn. Kaj Abram donis al li dekonaĵon el ĉio.","kaj benata estu Dio Plejsupra, kiu transdonis viajn malamikojn en viajn manojn. Kaj Abram donis al li dekonaĵon el ĉio."],[14,21,"Kaj la reĝo de Sodom diris al Abram: Donu al mi la homojn, kaj la havon prenu al vi.","Kaj la reĝo de Sodom diris al Abram: Donu al mi la homojn, kaj la havon prenu al vi."],[14,22,"Kaj Abram diris al la reĝo de Sodom: Mi levas mian manon al la Eternulo, Dio Plejsupra, la Kreinto de la ĉielo kaj la tero,","Kaj Abram diris al la reĝo de Sodom: Mi levas mian manon al la Eternulo, Dio Plejsupra, la Kreinto de la ĉielo kaj la tero,"],[14,23,"ke eĉ fadenon aŭ rimenon de ŝuo mi ne prenos el ĉio, kio apartenas al vi, por ke vi ne diru: Mi riĉigis Abramon;","ke eĉ fadenon aŭ rimenon de ŝuo mi ne prenos el ĉio, kio apartenas al vi, por ke vi ne diru: Mi riĉigis Abramon;"],[14,24,"escepto estos nur tio, kion manĝis la junuloj, kaj la parto de la homoj, kiuj iris kun mi: Aner, Eŝkol, kaj Mamre; ili prenu sian parton.","escepto estos nur tio, kion manĝis la junuloj, kaj la parto de la homoj, kiuj iris kun mi: Aner, Eŝkol, kaj Mamre; ili prenu sian parton."],[15,1,"Post tiuj fariĝoj la Eternulo diris al Abram en vizio jene: Ne timu, Abram, Mi estas via ŝildo; via rekompenco estas tre granda.","Post tiuj fariĝoj la Eternulo diris al Abram en vizio jene: Ne timu, Abram, Mi estas via ŝildo; via rekompenco estas tre granda."],[15,2,"Kaj Abram diris: Ho Eternulo, mia Sinjoro, kion Vi donos al mi? mi vagas ja seninfane, kaj la administranto de mia domo estas Eliezer el Damasko.","Kaj Abram diris: Ho Eternulo, mia Sinjoro, kion Vi donos al mi? mi vagas ja seninfane, kaj la administranto de mia domo estas Eliezer el Damasko."],[15,3,"Kaj Abram diris: Al mi Vi ne donis ja idaron, kaj jen mia domano estos mia heredanto.","Kaj Abram diris: Al mi Vi ne donis ja idaron, kaj jen mia domano estos mia heredanto."],[15,4,"Kaj tiam la Eternulo diris al li jene: Ĉi tiu ne estos via heredanto; nur tiu, kiu eliros el via internaĵo, estos via heredanto.","Kaj tiam la Eternulo diris al li jene: Ĉi tiu ne estos via heredanto; nur tiu, kiu eliros el via internaĵo, estos via heredanto."],[15,5,"Kaj Li elirigis lin eksteren, kaj diris: Rigardu al la ĉielo kaj kalkulu la stelojn, se vi povas ilin kalkuli. Kaj Li diris al li: Tiel estos via idaro.","Kaj Li elirigis lin eksteren, kaj diris: Rigardu al la ĉielo kaj kalkulu la stelojn, se vi povas ilin kalkuli. Kaj Li diris al li: Tiel estos via idaro."],[15,6,"Kaj li kredis al la Eternulo; kaj tio estis kalkulita al li kiel virto.","Kaj li kredis al la Eternulo; kaj tio estis kalkulita al li kiel virto."],[15,7,"Kaj Li diris al li: Mi estas la Eternulo, kiu elirigis vin el Ur la Ĥaldea, por doni al vi ĉi tiun landon kiel posedaĵon.","Kaj Li diris al li: Mi estas la Eternulo, kiu elirigis vin el Ur la Ĥaldea, por doni al vi ĉi tiun landon kiel posedaĵon."],[15,8,"Kaj li diris: Ho Eternulo, mia Sinjoro, per kio mi povas scii, ke mi ĝin posedos?","Kaj li diris: Ho Eternulo, mia Sinjoro, per kio mi povas scii, ke mi ĝin posedos?"],[15,9,"Kaj Li diris al li: Prenu por Mi bovinon trijaran kaj kaprinon trijaran kaj ŝafon trijaran kaj turton kaj junan kolombon.","Kaj Li diris al li: Prenu por Mi bovinon trijaran kaj kaprinon trijaran kaj ŝafon trijaran kaj turton kaj junan kolombon."],[15,10,"Kaj li alportis al Li ĉion ĉi tion, kaj Li distranĉis ilin laŭ la mezo kaj metis ĉiujn partojn unu kontraŭ la alia, sed la birdojn Li ne distranĉis.","Kaj li alportis al Li ĉion ĉi tion, kaj Li distranĉis ilin laŭ la mezo kaj metis ĉiujn partojn unu kontraŭ la alia, sed la birdojn Li ne distranĉis."],[15,11,"Kaj la rabobirdoj malleviĝis sur la kadavrojn, sed Abram ilin forpelis.","Kaj la rabobirdoj malleviĝis sur la kadavrojn, sed Abram ilin forpelis."],[15,12,"Ĉe la subiro de la suno profunda dormo falis sur Abramon; kaj jen timego pro la granda mallumo atakis lin.","Ĉe la subiro de la suno profunda dormo falis sur Abramon; kaj jen timego pro la granda mallumo atakis lin."],[15,13,"Kaj Li diris al Abram: Sciu, ke via idaro estos fremduloj en lando, kiu ne apartenos al ili; kaj oni sklavigos kaj turmentos ilin dum kvarcent jaroj.","Kaj Li diris al Abram: Sciu, ke via idaro estos fremduloj en lando, kiu ne apartenos al ili; kaj oni sklavigos kaj turmentos ilin dum kvarcent jaroj."],[15,14,"Tamen la popolon, ĉe kiu ili estos sklavoj, Mi juĝos; kaj poste ili eliros kun granda havo.","Tamen la popolon, ĉe kiu ili estos sklavoj, Mi juĝos; kaj poste ili eliros kun granda havo."],[15,15,"Kaj vi foriros al viaj prapatroj en paco; vi estos entombigita en bona maljuneco.","Kaj vi foriros al viaj prapatroj en paco; vi estos entombigita en bona maljuneco."],[15,16,"Kaj en la kvara generacio ili revenos ĉi tien; ĉar la krimoj de la Amoridoj ankoraŭ ne atingis plenecon.","Kaj en la kvara generacio ili revenos ĉi tien; ĉar la krimoj de la Amoridoj ankoraŭ ne atingis plenecon."],[15,17,"Kiam la suno subiris kaj fariĝis mallumo, subite forna fumo kaj fajra flamo trakuris inter tiuj distranĉitaĵoj.","Kiam la suno subiris kaj fariĝis mallumo, subite forna fumo kaj fajra flamo trakuris inter tiuj distranĉitaĵoj."],[15,18,"En tiu tago la Eternulo faris interligon kun Abram, dirante: Al via idaro Mi donos ĉi tiun landon, de la rivero de Egiptujo ĝis la granda rivero, la rivero Eŭfrato:","En tiu tago la Eternulo faris interligon kun Abram, dirante: Al via idaro Mi donos ĉi tiun landon, de la rivero de Egiptujo ĝis la granda rivero, la rivero Eŭfrato:"],[15,19,"la Kenidojn kaj la Kenizidojn kaj la Kadmonidojn","la Kenidojn kaj la Kenizidojn kaj la Kadmonidojn"],[15,20,"kaj la Ĥetidojn kaj la Perizidojn kaj la Rafaidojn","kaj la Ĥetidojn kaj la Perizidojn kaj la Rafaidojn"],[15,21,"kaj la Amoridojn kaj la Kanaanidojn kaj la Girgaŝidojn kaj la Jebusidojn.","kaj la Amoridojn kaj la Kanaanidojn kaj la Girgaŝidojn kaj la Jebusidojn."],[16,1,"Kaj Saraj, la edzino de Abram, ne naskis al li; sed ŝi havis sklavinon, Egiptinon, kies nomo estis Hagar.","Kaj Saraj, la edzino de Abram, ne naskis al li; sed ŝi havis sklavinon, Egiptinon, kies nomo estis Hagar."],[16,2,"Kaj Saraj diris al Abram: Jen la Eternulo ŝlosis min, ke mi ne nasku; eniru do al mia sklavino, eble mi havos infanojn per ŝi. Kaj Abram obeis la voĉon de Saraj.","Kaj Saraj diris al Abram: Jen la Eternulo ŝlosis min, ke mi ne nasku; eniru do al mia sklavino, eble mi havos infanojn per ŝi. Kaj Abram obeis la voĉon de Saraj."],[16,3,"Kaj Saraj, la edzino de Abram, prenis Hagaron la Egiptinon, sian sklavinon, kiam pasis dek jaroj de la tempo, kiam Abram ekloĝis en la lando Kanaana, kaj ŝi donis ŝin al sia edzo Abram kiel edzinon.","Kaj Saraj, la edzino de Abram, prenis Hagaron la Egiptinon, sian sklavinon, kiam pasis dek jaroj de la tempo, kiam Abram ekloĝis en la lando Kanaana, kaj ŝi donis ŝin al sia edzo Abram kiel edzinon."],[16,4,"Kaj li venis al Hagar, kaj ŝi gravediĝis. Kaj ŝi vidis, ke ŝi gravediĝis, kaj tiam ŝia sinjorino senvaloriĝis en ŝiaj okuloj.","Kaj li venis al Hagar, kaj ŝi gravediĝis. Kaj ŝi vidis, ke ŝi gravediĝis, kaj tiam ŝia sinjorino senvaloriĝis en ŝiaj okuloj."],[16,5,"Kaj Saraj diris al Abram: Vi estas maljusta kontraŭ mi; mi donis mian sklavinon en viajn brakojn, sed kiam ŝi vidis, ke ŝi gravediĝis, mi senvaloriĝis en ŝiaj okuloj; la Eternulo juĝu inter mi kaj vi.","Kaj Saraj diris al Abram: Vi estas maljusta kontraŭ mi; mi donis mian sklavinon en viajn brakojn, sed kiam ŝi vidis, ke ŝi gravediĝis, mi senvaloriĝis en ŝiaj okuloj; la Eternulo juĝu inter mi kaj vi."],[16,6,"Kaj Abram diris al Saraj: Jen via sklavino estas en viaj manoj, faru kun ŝi ĉion, kio plaĉas al vi. Kaj Saraj komencis premi ŝin, kaj ŝi forkuris.","Kaj Abram diris al Saraj: Jen via sklavino estas en viaj manoj, faru kun ŝi ĉion, kio plaĉas al vi. Kaj Saraj komencis premi ŝin, kaj ŝi forkuris."],[16,7,"Kaj trovis ŝin anĝelo de la Eternulo ĉe akva fonto en la dezerto, ĉe la fonto sur la vojo al Ŝur.","Kaj trovis ŝin anĝelo de la Eternulo ĉe akva fonto en la dezerto, ĉe la fonto sur la vojo al Ŝur."],[16,8,"Kaj li diris: Hagar, sklavino de Saraj, de kie vi venas kaj kien vi iras? Kaj ŝi diris: De Saraj, mia sinjorino, mi forkuras.","Kaj li diris: Hagar, sklavino de Saraj, de kie vi venas kaj kien vi iras? Kaj ŝi diris: De Saraj, mia sinjorino, mi forkuras."],[16,9,"Kaj la anĝelo de la Eternulo diris al ŝi: Reiru al via sinjorino, kaj humiliĝu sub ŝiaj manoj.","Kaj la anĝelo de la Eternulo diris al ŝi: Reiru al via sinjorino, kaj humiliĝu sub ŝiaj manoj."],[16,10,"Kaj la anĝelo de la Eternulo diris al ŝi: Mi multigos vian idaron tiel, ke pro multeco oni ne povos ĝin kalkuli.","Kaj la anĝelo de la Eternulo diris al ŝi: Mi multigos vian idaron tiel, ke pro multeco oni ne povos ĝin kalkuli."],[16,11,"Kaj la anĝelo de la Eternulo diris al ŝi: Jen vi estas graveda, kaj vi naskos filon; kaj vi donos al li la nomon Iŝmael, ĉar la Eternulo aŭdis vian suferon.","Kaj la anĝelo de la Eternulo diris al ŝi: Jen vi estas graveda, kaj vi naskos filon; kaj vi donos al li la nomon Iŝmael, ĉar la Eternulo aŭdis vian suferon."],[16,12,"Kaj li estos homo sovaĝa; lia mano estos kontraŭ ĉiuj, kaj la manoj de ĉiuj kontraŭ li, kaj li loĝos antaŭ ĉiuj siaj fratoj.","Kaj li estos homo sovaĝa; lia mano estos kontraŭ ĉiuj, kaj la manoj de ĉiuj kontraŭ li, kaj li loĝos antaŭ ĉiuj siaj fratoj."],[16,13,"Kaj la Eternulon, kiu parolis al ŝi, ŝi nomis: Dio-kiu-min-vidis; ĉar ŝi diris: Ĉi tie mi vidis Tiun, kiu min vidas; kaj ĉu mi poste vivas?","Kaj la Eternulon, kiu parolis al ŝi, ŝi nomis: Dio-kiu-min-vidis; ĉar ŝi diris: Ĉi tie mi vidis Tiun, kiu min vidas; kaj ĉu mi poste vivas?"],[16,14,"Tial oni nomis tiun puton puto de la Vivanto-Vidanto; ĝi estas inter Kadeŝ kaj Bered.","Tial oni nomis tiun puton puto de la Vivanto-Vidanto; ĝi estas inter Kadeŝ kaj Bered."],[16,15,"Kaj Hagar naskis al Abram filon; kaj Abram donis al sia filo, kiun naskis Hagar, la nomon Iŝmael.","Kaj Hagar naskis al Abram filon; kaj Abram donis al sia filo, kiun naskis Hagar, la nomon Iŝmael."],[16,16,"Kaj Abram havis la aĝon de okdek ses jaroj, kiam Hagar naskis Iŝmaelon al Abram.","Kaj Abram havis la aĝon de okdek ses jaroj, kiam Hagar naskis Iŝmaelon al Abram."],[17,1,"Kiam Abram havis la aĝon de naŭdek naŭ jaroj, aperis la Eternulo al Abram, kaj diris al li: Mi estas Dio la Plejpotenca; iradu antaŭ Mi kaj estu senpeka.","Kiam Abram havis la aĝon de naŭdek naŭ jaroj, aperis la Eternulo al Abram, kaj diris al li: Mi estas Dio la Plejpotenca; iradu antaŭ Mi kaj estu senpeka."],[17,2,"Kaj Mi faros Mian interligon inter Mi kaj vi, kaj Mi multigos vin tre forte.","Kaj Mi faros Mian interligon inter Mi kaj vi, kaj Mi multigos vin tre forte."],[17,3,"Kaj Abram ĵetis sin vizaĝaltere, kaj Dio parolis al li, dirante:","Kaj Abram ĵetis sin vizaĝaltere, kaj Dio parolis al li, dirante:"],[17,4,"Jen estas Mia interligo kun vi: vi estos patro de multe da popoloj.","Jen estas Mia interligo kun vi: vi estos patro de multe da popoloj."],[17,5,"Kaj via nomo ne estos plu Abram, sed via nomo estos Abraham, ĉar Mi faris vin patro de multe da popoloj.","Kaj via nomo ne estos plu Abram, sed via nomo estos Abraham, ĉar Mi faris vin patro de multe da popoloj."],[17,6,"Kaj Mi fruktigos vin tre multe, kaj Mi devenigos de vi popolojn, kaj reĝoj devenos de vi.","Kaj Mi fruktigos vin tre multe, kaj Mi devenigos de vi popolojn, kaj reĝoj devenos de vi."],[17,7,"Kaj Mi starigos Mian interligon inter Mi kaj vi kaj via idaro post vi en iliaj generacioj, eternan interligon, ke Mi estos Dio por vi kaj por via idaro post vi.","Kaj Mi starigos Mian interligon inter Mi kaj vi kaj via idaro post vi en iliaj generacioj, eternan interligon, ke Mi estos Dio por vi kaj por via idaro post vi."],[17,8,"Kaj Mi donos al vi kaj al via idaro post vi la landon, en kiu vi loĝas kiel fremdulo, la tutan landon Kanaanan, por eterna posedaĵo, kaj Mi estos Dio por ili.","Kaj Mi donos al vi kaj al via idaro post vi la landon, en kiu vi loĝas kiel fremdulo, la tutan landon Kanaanan, por eterna posedaĵo, kaj Mi estos Dio por ili."],[17,9,"Kaj Dio diris al Abraham: Kaj vi gardu Mian interligon, vi kaj via idaro post vi en iliaj generacioj.","Kaj Dio diris al Abraham: Kaj vi gardu Mian interligon, vi kaj via idaro post vi en iliaj generacioj."],[17,10,"Jen estas Mia interligo, kiun vi devas gardi inter Mi kaj vi kaj via idaro post vi: ĉiu virseksulo ĉe vi estu cirkumcidata.","Jen estas Mia interligo, kiun vi devas gardi inter Mi kaj vi kaj via idaro post vi: ĉiu virseksulo ĉe vi estu cirkumcidata."],[17,11,"Kaj cirkumcidu la karnon de via prepucio, kaj tio estu signo de interligo inter Mi kaj vi.","Kaj cirkumcidu la karnon de via prepucio, kaj tio estu signo de interligo inter Mi kaj vi."],[17,12,"Kaj en la aĝo de ok tagoj estu cirkumcidata ĉe vi en viaj generacioj ĉiu virseksulo naskita en la domo aŭ aĉetita per mono ĉe iu aligentulo, kiu ne estas el via idaro.","Kaj en la aĝo de ok tagoj estu cirkumcidata ĉe vi en viaj generacioj ĉiu virseksulo naskita en la domo aŭ aĉetita per mono ĉe iu aligentulo, kiu ne estas el via idaro."],[17,13,"Cirkumcidata estu ĉiu naskita en via domo aŭ aĉetita per via mono, kaj Mia interligo estu sur via karno kiel interligo eterna.","Cirkumcidata estu ĉiu naskita en via domo aŭ aĉetita per via mono, kaj Mia interligo estu sur via karno kiel interligo eterna."],[17,14,"Kaj se estos prepucihava virseksulo, kiu ne cirkumcidos la karnon de sia prepucio, tiu animo ekstermiĝos el sia popolo: Mian interligon ĝi rompis.","Kaj se estos prepucihava virseksulo, kiu ne cirkumcidos la karnon de sia prepucio, tiu animo ekstermiĝos el sia popolo: Mian interligon ĝi rompis."],[17,15,"Kaj Dio diris al Abraham: Vian edzinon Saraj ne nomu Saraj, sed ŝia nomo estu Sara.","Kaj Dio diris al Abraham: Vian edzinon Saraj ne nomu Saraj, sed ŝia nomo estu Sara."],[17,16,"Kaj Mi benos ŝin, kaj Mi donos de ŝi al vi filon; kaj Mi benos ŝin, kaj de ŝi devenos popoloj, reĝoj de popoloj devenos de ŝi.","Kaj Mi benos ŝin, kaj Mi donos de ŝi al vi filon; kaj Mi benos ŝin, kaj de ŝi devenos popoloj, reĝoj de popoloj devenos de ŝi."],[17,17,"Kaj Abraham ĵetis sin vizaĝaltere, kaj ekridis, kaj diris en sia koro: Ĉu de homo centjara fariĝos nasko, kaj ĉu Sara la naŭdekjara naskos?","Kaj Abraham ĵetis sin vizaĝaltere, kaj ekridis, kaj diris en sia koro: Ĉu de homo centjara fariĝos nasko, kaj ĉu Sara la naŭdekjara naskos?"],[17,18,"Kaj Abraham diris al Dio: Ho, ke Iŝmael vivu antaŭ Vi!","Kaj Abraham diris al Dio: Ho, ke Iŝmael vivu antaŭ Vi!"],[17,19,"Kaj Dio diris: Efektive Sara, via edzino, naskos al vi filon, kaj vi donos al li la nomon Isaak; kaj Mi starigos Mian interligon kun li kiel interligon eternan por lia idaro post li.","Kaj Dio diris: Efektive Sara, via edzino, naskos al vi filon, kaj vi donos al li la nomon Isaak; kaj Mi starigos Mian interligon kun li kiel interligon eternan por lia idaro post li."],[17,20,"Ankaŭ pri Iŝmael Mi aŭdis vin: jen Mi benis lin, kaj Mi fruktigos lin kaj Mi multigos lin tre forte; dek du princoj naskiĝos de li, kaj Mi devenigos de li grandan popolon.","Ankaŭ pri Iŝmael Mi aŭdis vin: jen Mi benis lin, kaj Mi fruktigos lin kaj Mi multigos lin tre forte; dek du princoj naskiĝos de li, kaj Mi devenigos de li grandan popolon."],[17,21,"Sed Mian interligon Mi starigos kun Isaak, kiun naskos al vi Sara en ĉi tiu tempo en la venonta jaro.","Sed Mian interligon Mi starigos kun Isaak, kiun naskos al vi Sara en ĉi tiu tempo en la venonta jaro."],[17,22,"Kaj Li ĉesis paroli kun li, kaj Dio leviĝis for de Abraham.","Kaj Li ĉesis paroli kun li, kaj Dio leviĝis for de Abraham."],[17,23,"Kaj Abraham prenis sian filon Iŝmael kaj ĉiujn naskitajn en lia domo kaj ĉiujn aĉetitajn per lia mono, ĉiun virseksulon el la homoj de la domo de Abraham, kaj li cirkumcidis la karnon de ilia prepucio en tiu sama tago, kiel diris al li Dio.","Kaj Abraham prenis sian filon Iŝmael kaj ĉiujn naskitajn en lia domo kaj ĉiujn aĉetitajn per lia mono, ĉiun virseksulon el la homoj de la domo de Abraham, kaj li cirkumcidis la karnon de ilia prepucio en tiu sama tago, kiel diris al li Dio."],[17,24,"Kaj Abraham havis la aĝon de naŭdek naŭ jaroj, kiam li cirkumcidis la karnon de sia prepucio.","Kaj Abraham havis la aĝon de naŭdek naŭ jaroj, kiam li cirkumcidis la karnon de sia prepucio."],[17,25,"Kaj lia filo Iŝmael havis la aĝon de dek tri jaroj, kiam la karno de lia prepucio estis cirkumcidita.","Kaj lia filo Iŝmael havis la aĝon de dek tri jaroj, kiam la karno de lia prepucio estis cirkumcidita."],[17,26,"En tiu sama tago estis cirkumciditaj Abraham kaj lia filo Iŝmael;","En tiu sama tago estis cirkumciditaj Abraham kaj lia filo Iŝmael;"],[17,27,"kaj ĉiuj liaj domanoj, kiuj naskiĝis en la domo aŭ estis aĉetitaj per mono ĉe aligentulo, estis cirkumciditaj kune kun li.","kaj ĉiuj liaj domanoj, kiuj naskiĝis en la domo aŭ estis aĉetitaj per mono ĉe aligentulo, estis cirkumciditaj kune kun li."],[18,1,"Kaj aperis al li la Eternulo en la arbareto Mamre, kiam li sidis ĉe la pordo de la tendo dum la varmego de la tago.","Kaj aperis al li la Eternulo en la arbareto Mamre, kiam li sidis ĉe la pordo de la tendo dum la varmego de la tago."],[18,2,"Kiam li levis siajn okulojn, li vidis, ke jen tri viroj staras antaŭ li. Ekvidinte, li kuris al ili renkonte de la pordo de la tendo kaj kliniĝis antaŭ ili ĝis la tero.","Kiam li levis siajn okulojn, li vidis, ke jen tri viroj staras antaŭ li. Ekvidinte, li kuris al ili renkonte de la pordo de la tendo kaj kliniĝis antaŭ ili ĝis la tero."],[18,3,"Kaj li diris: Mia sinjoro! se mi trovis plaĉon en viaj okuloj, ne pasu preter vian sklavon.","Kaj li diris: Mia sinjoro! se mi trovis plaĉon en viaj okuloj, ne pasu preter vian sklavon."],[18,4,"Oni alportos iom da akvo, kaj vi lavu viajn piedojn kaj ripozu sub la arbo.","Oni alportos iom da akvo, kaj vi lavu viajn piedojn kaj ripozu sub la arbo."],[18,5,"Kaj mi alportos pecon da pano, por ke vi fortigu viajn korojn; poste vi foriros; ĉar por tio vi pasis preter via sklavo. Kaj ili diris: Faru tiel, kiel vi diris.","Kaj mi alportos pecon da pano, por ke vi fortigu viajn korojn; poste vi foriros; ĉar por tio vi pasis preter via sklavo. Kaj ili diris: Faru tiel, kiel vi diris."],[18,6,"Kaj Abraham rapidis en la tendon al Sara, kaj diris: Rapide prenu tri mezurojn da plej bona faruno, knedu, kaj faru kukojn.","Kaj Abraham rapidis en la tendon al Sara, kaj diris: Rapide prenu tri mezurojn da plej bona faruno, knedu, kaj faru kukojn."],[18,7,"Kaj ankaŭ al la bovoj Abraham kuris, kaj li prenis bovidon delikatan kaj bonan kaj donis al la junulo, kaj tiu rapide pretigis ĝin.","Kaj ankaŭ al la bovoj Abraham kuris, kaj li prenis bovidon delikatan kaj bonan kaj donis al la junulo, kaj tiu rapide pretigis ĝin."],[18,8,"Kaj li prenis buteron kaj lakton kaj la pretigitan bovidon kaj metis antaŭ ilin, kaj li staris apud ili sub la arbo, kaj ili manĝis.","Kaj li prenis buteron kaj lakton kaj la pretigitan bovidon kaj metis antaŭ ilin, kaj li staris apud ili sub la arbo, kaj ili manĝis."],[18,9,"Kaj ili diris al li: Kie estas Sara, via edzino? Kaj li respondis: Jen ŝi estas en la tendo.","Kaj ili diris al li: Kie estas Sara, via edzino? Kaj li respondis: Jen ŝi estas en la tendo."],[18,10,"Kaj Li diris: Mi revenos al vi en la sama jartempo, kaj tiam estos filo ĉe Sara, via edzino. Kaj Sara aŭskultis ĉe la pordo de la tendo, kiu estis malantaŭ Li.","Kaj Li diris: Mi revenos al vi en la sama jartempo, kaj tiam estos filo ĉe Sara, via edzino. Kaj Sara aŭskultis ĉe la pordo de la tendo, kiu estis malantaŭ Li."],[18,11,"Kaj Abraham kaj Sara estis maljunuloj de profunda aĝo; ĉe Sara ĉesiĝis la virinaj ordinaraĵoj.","Kaj Abraham kaj Sara estis maljunuloj de profunda aĝo; ĉe Sara ĉesiĝis la virinaj ordinaraĵoj."],[18,12,"Kaj Sara ekridis interne, dirante: Ĉu kiam mi kadukiĝis, mi havus ankoraŭ volupton? kaj mia sinjoro estas ja maljuna!","Kaj Sara ekridis interne, dirante: Ĉu kiam mi kadukiĝis, mi havus ankoraŭ volupton? kaj mia sinjoro estas ja maljuna!"],[18,13,"Kaj la Eternulo diris al Abraham: Kial do Sara ridas, dirante: Ĉu efektive mi naskos, kiam mi maljuniĝis?","Kaj la Eternulo diris al Abraham: Kial do Sara ridas, dirante: Ĉu efektive mi naskos, kiam mi maljuniĝis?"],[18,14,"Ĉu por la Eternulo io estas malfacila? en la difinita tempo Mi revenos al vi en la venonta jaro, kaj Sara havos filon.","Ĉu por la Eternulo io estas malfacila? en la difinita tempo Mi revenos al vi en la venonta jaro, kaj Sara havos filon."],[18,15,"Sed Sara malkonfesis, dirante: Mi ne ridis; ĉar ŝi timis. Sed Li diris: Ne, vi ridis.","Sed Sara malkonfesis, dirante: Mi ne ridis; ĉar ŝi timis. Sed Li diris: Ne, vi ridis."],[18,16,"Kaj leviĝis de tie la viroj kaj direktiĝis al Sodom: kaj Abraham iris kun ili, por akompani ilin.","Kaj leviĝis de tie la viroj kaj direktiĝis al Sodom: kaj Abraham iris kun ili, por akompani ilin."],[18,17,"Kaj la Eternulo diris: Ĉu mi kaŝos antaŭ Abraham, kion Mi faras?","Kaj la Eternulo diris: Ĉu mi kaŝos antaŭ Abraham, kion Mi faras?"],[18,18,"Abraham fariĝos ja popolo granda kaj potenca, kaj per li beniĝos ĉiuj popoloj de la tero.","Abraham fariĝos ja popolo granda kaj potenca, kaj per li beniĝos ĉiuj popoloj de la tero."],[18,19,"Ĉar Mi lin elektis, por ke li ordonu al siaj filoj kaj al sia domo post si, ke ili observu la vojon de la Eternulo, agante virte kaj juste; por ke la Eternulo plenumu pri Abraham, kion Li diris pri li.","Ĉar Mi lin elektis, por ke li ordonu al siaj filoj kaj al sia domo post si, ke ili observu la vojon de la Eternulo, agante virte kaj juste; por ke la Eternulo plenumu pri Abraham, kion Li diris pri li."],[18,20,"Kaj la Eternulo diris: Ĉar la kriado de Sodom kaj Gomora estas granda kaj ilia pekado estas tre peza,","Kaj la Eternulo diris: Ĉar la kriado de Sodom kaj Gomora estas granda kaj ilia pekado estas tre peza,"],[18,21,"tial Mi malsupreniros, kaj rigardos, ĉu ili plene agas tiel, kiel estas la kriado, kiu venis al Mi, aŭ ne; Mi sciiĝos.","tial Mi malsupreniros, kaj rigardos, ĉu ili plene agas tiel, kiel estas la kriado, kiu venis al Mi, aŭ ne; Mi sciiĝos."],[18,22,"Kaj la viroj turniĝis de tie kaj iris al Sodom; kaj Abraham staris ankoraŭ antaŭ la Eternulo.","Kaj la viroj turniĝis de tie kaj iris al Sodom; kaj Abraham staris ankoraŭ antaŭ la Eternulo."],[18,23,"Kaj Abraham alproksimiĝis, kaj diris: Ĉu Vi ankaŭ pereigos virtulon kune kun malvirtulo?","Kaj Abraham alproksimiĝis, kaj diris: Ĉu Vi ankaŭ pereigos virtulon kune kun malvirtulo?"],[18,24,"Eble ekzistas kvindek virtuloj en la urbo: ĉu Vi tiam pereigos kaj ne indulgos la lokon pro la kvindek virtuloj, kiuj estas en ĝi?","Eble ekzistas kvindek virtuloj en la urbo: ĉu Vi tiam pereigos kaj ne indulgos la lokon pro la kvindek virtuloj, kiuj estas en ĝi?"],[18,25,"Ne decas por Vi agi tiamaniere, ke Vi mortigu virtulon kune kun malvirtulo, ke virtulo estu kiel malvirtulo; ne decas por Vi, ke la Juĝanto de la tuta tero agu maljuste.","Ne decas por Vi agi tiamaniere, ke Vi mortigu virtulon kune kun malvirtulo, ke virtulo estu kiel malvirtulo; ne decas por Vi, ke la Juĝanto de la tuta tero agu maljuste."],[18,26,"Kaj la Eternulo diris: Se Mi trovos en Sodom kvindek virtulojn en la urbo, Mi indulgos la tutan lokon pro ili.","Kaj la Eternulo diris: Se Mi trovos en Sodom kvindek virtulojn en la urbo, Mi indulgos la tutan lokon pro ili."],[18,27,"Kaj Abraham respondis, dirante: Jen mi ekkuraĝis paroli al mia Sinjoro, kvankam mi estas polvo kaj cindro;","Kaj Abraham respondis, dirante: Jen mi ekkuraĝis paroli al mia Sinjoro, kvankam mi estas polvo kaj cindro;"],[18,28,"eble al la kvindeko da virtuloj mankos kvin: ĉu Vi pereigos pro la kvin la tutan urbon? Kaj Li diris: Mi ne pereigos, se Mi trovos tie kvardek kvin.","eble al la kvindeko da virtuloj mankos kvin: ĉu Vi pereigos pro la kvin la tutan urbon? Kaj Li diris: Mi ne pereigos, se Mi trovos tie kvardek kvin."],[18,29,"Kaj li plue parolis al Li kaj diris: Eble troviĝos tie kvardek? Kaj Li diris: Mi ne faros tion pro la kvardek.","Kaj li plue parolis al Li kaj diris: Eble troviĝos tie kvardek? Kaj Li diris: Mi ne faros tion pro la kvardek."],[18,30,"Kaj li diris: Ne koleru, mia Sinjoro, ke mi parolos plue: eble troviĝos tie tridek? Kaj Li diris: Mi ne faros, se Mi trovos tie tridek.","Kaj li diris: Ne koleru, mia Sinjoro, ke mi parolos plue: eble troviĝos tie tridek? Kaj Li diris: Mi ne faros, se Mi trovos tie tridek."],[18,31,"Kaj li diris: Jen mi ekkuraĝis paroli al mia Sinjoro: eble troviĝos dudek? Kaj Li diris: Mi ne pereigos pro la dudek.","Kaj li diris: Jen mi ekkuraĝis paroli al mia Sinjoro: eble troviĝos dudek? Kaj Li diris: Mi ne pereigos pro la dudek."],[18,32,"Kaj li diris: Ne koleru, mia Sinjoro, ke mi parolos ankoraŭ nur unu fojon: eble troviĝos tie dek? Kaj Li diris: Mi ne pereigos pro la dek.","Kaj li diris: Ne koleru, mia Sinjoro, ke mi parolos ankoraŭ nur unu fojon: eble troviĝos tie dek? Kaj Li diris: Mi ne pereigos pro la dek."],[18,33,"Kaj la Eternulo foriris, kiam Li ĉesis paroli kun Abraham; kaj Abraham reiris al sia loko.","Kaj la Eternulo foriris, kiam Li ĉesis paroli kun Abraham; kaj Abraham reiris al sia loko."],[19,1,"Kaj la du anĝeloj venis Sodomon vespere, kaj Lot tiam sidis ĉe la pordego de Sodom. Kiam Lot ilin ekvidis, li leviĝis renkonte al ili kaj kliniĝis vizaĝaltere.","Kaj la du anĝeloj venis Sodomon vespere, kaj Lot tiam sidis ĉe la pordego de Sodom. Kiam Lot ilin ekvidis, li leviĝis renkonte al ili kaj kliniĝis vizaĝaltere."],[19,2,"Kaj li diris: Mi petas vin, sinjoroj, envenu en la domon de via sklavo kaj pasigu la nokton kaj lavu viajn piedojn, kaj vi leviĝos matene kaj iros vian vojon. Kaj ili diris: Ne, ni pasigos la nokton sur la strato.","Kaj li diris: Mi petas vin, sinjoroj, envenu en la domon de via sklavo kaj pasigu la nokton kaj lavu viajn piedojn, kaj vi leviĝos matene kaj iros vian vojon. Kaj ili diris: Ne, ni pasigos la nokton sur la strato."],[19,3,"Kaj li tre petegis ilin, kaj ili direktis sin al li kaj envenis en lian domon; kaj li faris al ili festenon, kaj li bakis macojn, kaj ili manĝis.","Kaj li tre petegis ilin, kaj ili direktis sin al li kaj envenis en lian domon; kaj li faris al ili festenon, kaj li bakis macojn, kaj ili manĝis."],[19,4,"Antaŭ ol ili kuŝiĝis, la homoj de la urbo, la homoj de Sodom, ĉirkaŭis la domon, de la junuloj ĝis la maljunuloj, la tuta popolo, de ĉiuj finoj.","Antaŭ ol ili kuŝiĝis, la homoj de la urbo, la homoj de Sodom, ĉirkaŭis la domon, de la junuloj ĝis la maljunuloj, la tuta popolo, de ĉiuj finoj."],[19,5,"Kaj ili vokis Loton, kaj diris al li: Kie estas la viroj, kiuj venis al vi dum la nokto? elirigu ilin al ni, por ke ni ilin ekkonu.","Kaj ili vokis Loton, kaj diris al li: Kie estas la viroj, kiuj venis al vi dum la nokto? elirigu ilin al ni, por ke ni ilin ekkonu."],[19,6,"Kaj Lot eliris al ili antaŭ la sojlon, kaj la pordon li ŝlosis post si.","Kaj Lot eliris al ili antaŭ la sojlon, kaj la pordon li ŝlosis post si."],[19,7,"Kaj li diris: Ho, miaj fratoj, ne agu malbone!","Kaj li diris: Ho, miaj fratoj, ne agu malbone!"],[19,8,"Jen mi havas du filinojn, kiuj ankoraŭ ne ekkonis viron; mi elirigos ilin al vi, kaj faru kun ili, kion vi deziras; nur al tiuj viroj nenion faru, ĉar por tio ili venis sub la ombron de mia tegmento.","Jen mi havas du filinojn, kiuj ankoraŭ ne ekkonis viron; mi elirigos ilin al vi, kaj faru kun ili, kion vi deziras; nur al tiuj viroj nenion faru, ĉar por tio ili venis sub la ombron de mia tegmento."],[19,9,"Sed ili diris: Iru for! Kaj ili diris plue: Vi venis ĉi tien kiel fremdulo, kaj vi volas juĝi! nun ni pli malbone agos kun vi, ol kun ili. Kaj ili tre insiste postulis de la viro, de Lot, kaj ili aliris, por elrompi la pordon.","Sed ili diris: Iru for! Kaj ili diris plue: Vi venis ĉi tien kiel fremdulo, kaj vi volas juĝi! nun ni pli malbone agos kun vi, ol kun ili. Kaj ili tre insiste postulis de la viro, de Lot, kaj ili aliris, por elrompi la pordon."],[19,10,"Tiam tiuj viroj etendis siajn manojn kaj envenigis Loton al si en la domon, kaj la pordon ili ŝlosis;","Tiam tiuj viroj etendis siajn manojn kaj envenigis Loton al si en la domon, kaj la pordon ili ŝlosis;"],[19,11,"kaj la homojn, kiuj estis antaŭ la sojlo de la domo, ili frapis per blindeco, de la malgrandaj ĝis la grandaj, tiel ke tiuj laciĝis, serĉante la pordon.","kaj la homojn, kiuj estis antaŭ la sojlo de la domo, ili frapis per blindeco, de la malgrandaj ĝis la grandaj, tiel ke tiuj laciĝis, serĉante la pordon."],[19,12,"Kaj la viroj diris al Lot: Kiun vi havas ĉi tie? bofilon, aŭ viajn filojn aŭ viajn filinojn, aŭ ĉiun ajn, kiun vi havas en la urbo, elirigu ilin el ĉi tiu loko;","Kaj la viroj diris al Lot: Kiun vi havas ĉi tie? bofilon, aŭ viajn filojn aŭ viajn filinojn, aŭ ĉiun ajn, kiun vi havas en la urbo, elirigu ilin el ĉi tiu loko;"],[19,13,"ĉar ni ekstermos ĉi tiun lokon, ĉar granda fariĝis ilia kriado antaŭ la Eternulo, kaj la Eternulo sendis nin, por ĝin pereigi.","ĉar ni ekstermos ĉi tiun lokon, ĉar granda fariĝis ilia kriado antaŭ la Eternulo, kaj la Eternulo sendis nin, por ĝin pereigi."],[19,14,"Kaj Lot eliris, kaj parolis kun siaj bofiloj, prenontaj liajn filinojn, kaj diris: Leviĝu, eliru el ĉi tiu loko, ĉar la Eternulo pereigos la urbon. Sed liaj bofiloj rigardis lin kiel ŝercanton.","Kaj Lot eliris, kaj parolis kun siaj bofiloj, prenontaj liajn filinojn, kaj diris: Leviĝu, eliru el ĉi tiu loko, ĉar la Eternulo pereigos la urbon. Sed liaj bofiloj rigardis lin kiel ŝercanton."],[19,15,"Kiam leviĝis la matenruĝo, la anĝeloj rapidigis Loton, dirante: Leviĝu, prenu vian edzinon kaj ambaŭ viajn filinojn, kiuj ĉi tie troviĝas, por ke vi ne pereu pro la krimeco de la urbo.","Kiam leviĝis la matenruĝo, la anĝeloj rapidigis Loton, dirante: Leviĝu, prenu vian edzinon kaj ambaŭ viajn filinojn, kiuj ĉi tie troviĝas, por ke vi ne pereu pro la krimeco de la urbo."],[19,16,"Sed ĉar li malrapidis, tial la viroj kaptis lian manon kaj la manon de lia edzino kaj la manojn de liaj du filinoj, pro kompato de la Eternulo al li, kaj ili elirigis lin kaj metis lin ekster la urbon.","Sed ĉar li malrapidis, tial la viroj kaptis lian manon kaj la manon de lia edzino kaj la manojn de liaj du filinoj, pro kompato de la Eternulo al li, kaj ili elirigis lin kaj metis lin ekster la urbon."],[19,17,"Kaj kiam ili elkondukis lin eksteren, ili diris al li: Savu vin pro via animo; ne rigardu malantaŭen kaj haltu nenie en la tuta ĉirkaŭaĵo; sur la monton savu vin, por ke vi ne pereu.","Kaj kiam ili elkondukis lin eksteren, ili diris al li: Savu vin pro via animo; ne rigardu malantaŭen kaj haltu nenie en la tuta ĉirkaŭaĵo; sur la monton savu vin, por ke vi ne pereu."],[19,18,"Kaj Lot diris al ili: Ho, ne, mia Sinjoro!","Kaj Lot diris al ili: Ho, ne, mia Sinjoro!"],[19,19,"Jen Via sklavo plaĉis al Vi, kaj granda estas la favorkoreco, kiun Vi montris al mi, konservante la vivon al mia animo; sed mi ne povas savi min sur la monton, ĉar povus trafi min malfeliĉo kaj mi mortus.","Jen Via sklavo plaĉis al Vi, kaj granda estas la favorkoreco, kiun Vi montris al mi, konservante la vivon al mia animo; sed mi ne povas savi min sur la monton, ĉar povus trafi min malfeliĉo kaj mi mortus."],[19,20,"Jen ĉi tiu urbo estas sufiĉe proksima, por kuri tien, kaj ĝi estas malgranda; mi savos min tien; ĝi estas ja malgranda; kaj mia animo restos viva.","Jen ĉi tiu urbo estas sufiĉe proksima, por kuri tien, kaj ĝi estas malgranda; mi savos min tien; ĝi estas ja malgranda; kaj mia animo restos viva."],[19,21,"Kaj Li diris al li: Jen Mi komplezos al vi ankaŭ en ĉi tiu afero, kaj Mi ne renversos la urbon, pri kiu vi parolis.","Kaj Li diris al li: Jen Mi komplezos al vi ankaŭ en ĉi tiu afero, kaj Mi ne renversos la urbon, pri kiu vi parolis."],[19,22,"Rapide savu vin tien, ĉar Mi nenion povas fari, ĝis vi venos tien. Tial tiu urbo ricevis la nomon Coar.","Rapide savu vin tien, ĉar Mi nenion povas fari, ĝis vi venos tien. Tial tiu urbo ricevis la nomon Coar."],[19,23,"La suno leviĝis super la teron, kiam Lot venis Coaron.","La suno leviĝis super la teron, kiam Lot venis Coaron."],[19,24,"Kaj la Eternulo pluvigis sur Sodomon kaj Gomoran sulfuron kaj fajron de la Eternulo el la ĉielo.","Kaj la Eternulo pluvigis sur Sodomon kaj Gomoran sulfuron kaj fajron de la Eternulo el la ĉielo."],[19,25,"Kaj Li ruinigis tiujn urbojn kaj la tutan ĉirkaŭaĵon kaj ĉiujn loĝantojn de la urboj kaj la kreskaĵojn de la tero.","Kaj Li ruinigis tiujn urbojn kaj la tutan ĉirkaŭaĵon kaj ĉiujn loĝantojn de la urboj kaj la kreskaĵojn de la tero."],[19,26,"Kaj lia edzino ekrigardis malantaŭen, kaj ŝi fariĝis kolono el salo.","Kaj lia edzino ekrigardis malantaŭen, kaj ŝi fariĝis kolono el salo."],[19,27,"Kaj matene Abraham leviĝis kaj iris al la loko, kie li estis starinta antaŭ la Eternulo;","Kaj matene Abraham leviĝis kaj iris al la loko, kie li estis starinta antaŭ la Eternulo;"],[19,28,"kaj li ekrigardis en la direkto al Sodom kaj Gomora kaj al la tuta lando de la ĉirkaŭaĵo, kaj li vidis, ke jen fumo leviĝas de la tero kiel fumo el forno.","kaj li ekrigardis en la direkto al Sodom kaj Gomora kaj al la tuta lando de la ĉirkaŭaĵo, kaj li vidis, ke jen fumo leviĝas de la tero kiel fumo el forno."],[19,29,"Kaj kiam Dio estis pereiganta la urbojn de la ĉirkaŭaĵo, Li rememoris pri Abraham, kaj Li elirigis Loton el la mezo de la ruinigado, kiam Li estis ruiniganta la urbojn, en kiuj loĝis Lot.","Kaj kiam Dio estis pereiganta la urbojn de la ĉirkaŭaĵo, Li rememoris pri Abraham, kaj Li elirigis Loton el la mezo de la ruinigado, kiam Li estis ruiniganta la urbojn, en kiuj loĝis Lot."],[19,30,"Kaj Lot eliris el Coar kaj ekloĝis sur la monto, kaj liaj du filinoj kun li; ĉar li timis loĝi en Coar. Kaj li loĝis en kaverno, li kaj liaj du filinoj.","Kaj Lot eliris el Coar kaj ekloĝis sur la monto, kaj liaj du filinoj kun li; ĉar li timis loĝi en Coar. Kaj li loĝis en kaverno, li kaj liaj du filinoj."],[19,31,"Kaj la pli maljuna diris al la pli juna: Nia patro estas maljuna, kaj en la lando ne ekzistas viro, kiu envenus al ni laŭ la moro de la tuta tero;","Kaj la pli maljuna diris al la pli juna: Nia patro estas maljuna, kaj en la lando ne ekzistas viro, kiu envenus al ni laŭ la moro de la tuta tero;"],[19,32,"tial ni ebriigu nian patron per vino, kaj ni kuŝu kun li, por ke ni aperigu de nia patro idaron.","tial ni ebriigu nian patron per vino, kaj ni kuŝu kun li, por ke ni aperigu de nia patro idaron."],[19,33,"Kaj ili ebriigis sian patron per vino en tiu nokto; kaj venis la pli maljuna kaj kuŝis kun sia patro; kaj li ne sciis, kiam ŝi kuŝiĝis kaj kiam ŝi leviĝis.","Kaj ili ebriigis sian patron per vino en tiu nokto; kaj venis la pli maljuna kaj kuŝis kun sia patro; kaj li ne sciis, kiam ŝi kuŝiĝis kaj kiam ŝi leviĝis."],[19,34,"La morgaŭan tagon la pli maljuna diris al la pli juna: Jen mi kuŝis hieraŭ kun mia patro; ni ebriigu lin per vino ankaŭ en ĉi tiu nokto, kaj vi venu, kuŝu kun li, por ke ni aperigu de nia patro idaron.","La morgaŭan tagon la pli maljuna diris al la pli juna: Jen mi kuŝis hieraŭ kun mia patro; ni ebriigu lin per vino ankaŭ en ĉi tiu nokto, kaj vi venu, kuŝu kun li, por ke ni aperigu de nia patro idaron."],[19,35,"Kaj ili ankaŭ en ĉi tiu nokto ebriigis sian patron per vino; kaj la pli juna iris kaj kuŝis kun li; kaj li ne sciis, kiam ŝi kuŝiĝis kaj kiam ŝi leviĝis.","Kaj ili ankaŭ en ĉi tiu nokto ebriigis sian patron per vino; kaj la pli juna iris kaj kuŝis kun li; kaj li ne sciis, kiam ŝi kuŝiĝis kaj kiam ŝi leviĝis."],[19,36,"Kaj ambaŭ filinoj de Lot gravediĝis de sia patro.","Kaj ambaŭ filinoj de Lot gravediĝis de sia patro."],[19,37,"Kaj la pli maljuna naskis filon, kaj ŝi donis al li la nomon Moab; li estas la prapatro de la Moabidoj ĝis nun.","Kaj la pli maljuna naskis filon, kaj ŝi donis al li la nomon Moab; li estas la prapatro de la Moabidoj ĝis nun."],[19,38,"Kaj la pli juna ankaŭ naskis filon, kaj ŝi donis al li la nomon Ben-Ami; li estas la prapatro de la Amonidoj ĝis nun.","Kaj la pli juna ankaŭ naskis filon, kaj ŝi donis al li la nomon Ben-Ami; li estas la prapatro de la Amonidoj ĝis nun."],[20,1,"Kaj Abraham ekmigris de tie al la lando suda, kaj li ekloĝis inter Kadeŝ kaj Ŝur; kaj li loĝis kiel fremdulo en Gerar.","Kaj Abraham ekmigris de tie al la lando suda, kaj li ekloĝis inter Kadeŝ kaj Ŝur; kaj li loĝis kiel fremdulo en Gerar."],[20,2,"Kaj Abraham diris pri sia edzino Sara: Ŝi estas mia fratino. Kaj Abimeleĥ, reĝo de Gerar, sendis kaj prenis Saran.","Kaj Abraham diris pri sia edzino Sara: Ŝi estas mia fratino. Kaj Abimeleĥ, reĝo de Gerar, sendis kaj prenis Saran."],[20,3,"Kaj Dio venis al Abimeleĥ nokte en la sonĝo, kaj diris al li: Vi mortos pro la virino, kiun vi prenis, ĉar ŝi estas edzino de edzo.","Kaj Dio venis al Abimeleĥ nokte en la sonĝo, kaj diris al li: Vi mortos pro la virino, kiun vi prenis, ĉar ŝi estas edzino de edzo."],[20,4,"Sed Abimeleĥ ne alproksimiĝis al ŝi, kaj li diris: Mia Sinjoro! ĉu vi mortigos ankaŭ senkulpan popolon?","Sed Abimeleĥ ne alproksimiĝis al ŝi, kaj li diris: Mia Sinjoro! ĉu vi mortigos ankaŭ senkulpan popolon?"],[20,5,"Li diris ja al mi: Ŝi estas mia fratino; kaj ŝi ankaŭ diris al mi: Li estas mia frato. En senkulpeco de mia koro kaj en pureco de miaj manoj mi faris tion.","Li diris ja al mi: Ŝi estas mia fratino; kaj ŝi ankaŭ diris al mi: Li estas mia frato. En senkulpeco de mia koro kaj en pureco de miaj manoj mi faris tion."],[20,6,"Kaj Dio diris al li en la sonĝo: Mi ankaŭ scias, ke en senkulpeco de via koro vi tion faris, kaj tial Mi detenis vin, ke vi ne peku kontraŭ Mi, tial Mi ne lasis, ke vi kuntuŝiĝu kun ŝi.","Kaj Dio diris al li en la sonĝo: Mi ankaŭ scias, ke en senkulpeco de via koro vi tion faris, kaj tial Mi detenis vin, ke vi ne peku kontraŭ Mi, tial Mi ne lasis, ke vi kuntuŝiĝu kun ŝi."],[20,7,"Kaj nun redonu la edzinon al la edzo, ĉar li estas profeto, kaj li preĝos pri vi, kaj vi restos viva; sed se vi ne redonos, tiam sciu, ke vi mortos, vi kaj ĉiuj viaj.","Kaj nun redonu la edzinon al la edzo, ĉar li estas profeto, kaj li preĝos pri vi, kaj vi restos viva; sed se vi ne redonos, tiam sciu, ke vi mortos, vi kaj ĉiuj viaj."],[20,8,"Kaj Abimeleĥ leviĝis frue matene, kaj li vokis ĉiujn siajn sklavojn kaj rakontis ĉion ĉi tion al iliaj oreloj; kaj la homoj tre ektimis.","Kaj Abimeleĥ leviĝis frue matene, kaj li vokis ĉiujn siajn sklavojn kaj rakontis ĉion ĉi tion al iliaj oreloj; kaj la homoj tre ektimis."],[20,9,"Kaj Abimeleĥ vokis Abrahamon, kaj diris al li: Kion vi faris al ni? kaj per kio mi pekis antaŭ vi, ke vi venigis sur min kaj sur mian regnon grandan pekon? aferojn, kiuj ne estas farataj, vi faris kontraŭ mi.","Kaj Abimeleĥ vokis Abrahamon, kaj diris al li: Kion vi faris al ni? kaj per kio mi pekis antaŭ vi, ke vi venigis sur min kaj sur mian regnon grandan pekon? aferojn, kiuj ne estas farataj, vi faris kontraŭ mi."],[20,10,"Kaj Abimeleĥ diris al Abraham: Kion vi vidis, kiam vi faris tiun aferon?","Kaj Abimeleĥ diris al Abraham: Kion vi vidis, kiam vi faris tiun aferon?"],[20,11,"Kaj Abraham diris: Mi pensis, ke ne ekzistas timo antaŭ Dio en ĉi tiu loko, kaj ke oni mortigos min pro mia edzino.","Kaj Abraham diris: Mi pensis, ke ne ekzistas timo antaŭ Dio en ĉi tiu loko, kaj ke oni mortigos min pro mia edzino."],[20,12,"Kaj efektive ŝi estas mia fratino, filino de mia patro, nur ne filino de mia patrino; kaj ŝi fariĝis mia edzino.","Kaj efektive ŝi estas mia fratino, filino de mia patro, nur ne filino de mia patrino; kaj ŝi fariĝis mia edzino."],[20,13,"Kaj kiam Dio elmigrigis min el la domo de mia patro, mi diris al ŝi: Faru al mi ĉi tiun komplezon, en kian ajn lokon ni venos, diru pri mi: Li estas mia frato.","Kaj kiam Dio elmigrigis min el la domo de mia patro, mi diris al ŝi: Faru al mi ĉi tiun komplezon, en kian ajn lokon ni venos, diru pri mi: Li estas mia frato."],[20,14,"Kaj Abimeleĥ prenis ŝafojn kaj bovojn kaj sklavojn kaj sklavinojn kaj donis al Abraham, kaj li redonis al li lian edzinon Sara.","Kaj Abimeleĥ prenis ŝafojn kaj bovojn kaj sklavojn kaj sklavinojn kaj donis al Abraham, kaj li redonis al li lian edzinon Sara."],[20,15,"Kaj Abimeleĥ diris: Jen mia lando estas antaŭ vi; kie plaĉas al vi, tie loĝiĝu.","Kaj Abimeleĥ diris: Jen mia lando estas antaŭ vi; kie plaĉas al vi, tie loĝiĝu."],[20,16,"Kaj al Sara li diris: Jen mi donis mil arĝentajn monerojn al via frato; tio estu al vi kovro por la okuloj antaŭ ĉiuj, kiuj estas kun vi, kaj antaŭ ĉiuj vi estas pravigita.","Kaj al Sara li diris: Jen mi donis mil arĝentajn monerojn al via frato; tio estu al vi kovro por la okuloj antaŭ ĉiuj, kiuj estas kun vi, kaj antaŭ ĉiuj vi estas pravigita."],[20,17,"Kaj Abraham ekpreĝis al Dio; kaj Dio sanigis Abimeleĥon kaj lian edzinon kaj liajn sklavinojn, kaj ili komencis naski.","Kaj Abraham ekpreĝis al Dio; kaj Dio sanigis Abimeleĥon kaj lian edzinon kaj liajn sklavinojn, kaj ili komencis naski."],[20,18,"Ĉar la Eternulo estis ŝlosinta ĉiujn uterojn en la domo de Abimeleĥ pro Sara, la edzino de Abraham.","Ĉar la Eternulo estis ŝlosinta ĉiujn uterojn en la domo de Abimeleĥ pro Sara, la edzino de Abraham."],[21,1,"Kaj la Eternulo rememoris Saran, kiel Li diris, kaj la Eternulo faris al Sara, kiel Li parolis.","Kaj la Eternulo rememoris Saran, kiel Li diris, kaj la Eternulo faris al Sara, kiel Li parolis."],[21,2,"Kaj Sara gravediĝis kaj naskis al Abraham filon en lia maljuneco, en la difinita tempo, pri kiu Dio al li diris.","Kaj Sara gravediĝis kaj naskis al Abraham filon en lia maljuneco, en la difinita tempo, pri kiu Dio al li diris."],[21,3,"Kaj Abraham donis al sia filo, kiu naskiĝis al li, kiun naskis al li Sara, la nomon Isaak.","Kaj Abraham donis al sia filo, kiu naskiĝis al li, kiun naskis al li Sara, la nomon Isaak."],[21,4,"Kaj Abraham cirkumcidis sian filon Isaak, kiam tiu havis la aĝon de ok tagoj, kiel ordonis al li Dio.","Kaj Abraham cirkumcidis sian filon Isaak, kiam tiu havis la aĝon de ok tagoj, kiel ordonis al li Dio."],[21,5,"Kaj Abraham havis la aĝon de cent jaroj, kiam naskiĝis al li lia filo Isaak.","Kaj Abraham havis la aĝon de cent jaroj, kiam naskiĝis al li lia filo Isaak."],[21,6,"Kaj Sara diris: Ridindaĵon faris al mi Dio; ĉiu, kiu aŭdos, ridos pri mi.","Kaj Sara diris: Ridindaĵon faris al mi Dio; ĉiu, kiu aŭdos, ridos pri mi."],[21,7,"Kaj ŝi diris: Kiu dirus al Abraham, ke Sara mamnutros infanojn? ĉar mi naskis filon en lia maljuneco.","Kaj ŝi diris: Kiu dirus al Abraham, ke Sara mamnutros infanojn? ĉar mi naskis filon en lia maljuneco."],[21,8,"Kaj la infano kreskis, kaj ĝi estis demamigita, kaj Abraham faris grandan festenon en la tago, en kiu Isaak estis demamigita.","Kaj la infano kreskis, kaj ĝi estis demamigita, kaj Abraham faris grandan festenon en la tago, en kiu Isaak estis demamigita."],[21,9,"Kaj Sara vidis, ke la filo de Hagar la Egiptino, kiun ĉi tiu naskis al Abraham, mokas.","Kaj Sara vidis, ke la filo de Hagar la Egiptino, kiun ĉi tiu naskis al Abraham, mokas."],[21,10,"Kaj ŝi diris al Abraham: Forpelu ĉi tiun sklavinon kaj ŝian filon; ĉar la filo de ĉi tiu sklavino ne heredos kun mia filo, kun Isaak.","Kaj ŝi diris al Abraham: Forpelu ĉi tiun sklavinon kaj ŝian filon; ĉar la filo de ĉi tiu sklavino ne heredos kun mia filo, kun Isaak."],[21,11,"Kaj la afero forte malplaĉis al Abraham pro lia filo.","Kaj la afero forte malplaĉis al Abraham pro lia filo."],[21,12,"Kaj Dio diris al Abraham: Ĝi ne malplaĉu al vi pro la knabo kaj pro via sklavino; pri ĉio, kion diros al vi Sara, obeu ŝian voĉon; ĉar per Isaak oni nomos vian idaron.","Kaj Dio diris al Abraham: Ĝi ne malplaĉu al vi pro la knabo kaj pro via sklavino; pri ĉio, kion diros al vi Sara, obeu ŝian voĉon; ĉar per Isaak oni nomos vian idaron."],[21,13,"Sed ankaŭ el la filo de la sklavino Mi kreskigos popolon, ĉar li estas via semo.","Sed ankaŭ el la filo de la sklavino Mi kreskigos popolon, ĉar li estas via semo."],[21,14,"Kaj Abraham leviĝis frue matene, kaj prenis panon kaj felsakon kun akvo kaj donis al Hagar, metante ĝin sur ŝian ŝultron, ankaŭ la infanon, kaj foririgis ŝin; kaj ŝi iris, kaj ŝi erarvagis en la dezerto Beer-Ŝeba.","Kaj Abraham leviĝis frue matene, kaj prenis panon kaj felsakon kun akvo kaj donis al Hagar, metante ĝin sur ŝian ŝultron, ankaŭ la infanon, kaj foririgis ŝin; kaj ŝi iris, kaj ŝi erarvagis en la dezerto Beer-Ŝeba."],[21,15,"Kaj konsumiĝis la akvo de la felsako, kaj ŝi ĵetis la infanon sub unu el la arbetaĵoj.","Kaj konsumiĝis la akvo de la felsako, kaj ŝi ĵetis la infanon sub unu el la arbetaĵoj."],[21,16,"Kaj ŝi iris kaj sidiĝis kontraŭe, en la malproksimeco de pafo el pafarko; ĉar ŝi diris: Mi ne povas rigardi la morton de la infano. Kaj ŝi sidiĝis kontraŭe, kaj ŝi komencis laŭte plori.","Kaj ŝi iris kaj sidiĝis kontraŭe, en la malproksimeco de pafo el pafarko; ĉar ŝi diris: Mi ne povas rigardi la morton de la infano. Kaj ŝi sidiĝis kontraŭe, kaj ŝi komencis laŭte plori."],[21,17,"Kaj Dio aŭdis la voĉon de la knabo; kaj anĝelo de Dio vokis Hagaron el la ĉielo, kaj diris al ŝi: Kio estas al vi, Hagar? ne timu, ĉar Dio aŭdis la voĉon de la knabo el la loko, kie li estas.","Kaj Dio aŭdis la voĉon de la knabo; kaj anĝelo de Dio vokis Hagaron el la ĉielo, kaj diris al ŝi: Kio estas al vi, Hagar? ne timu, ĉar Dio aŭdis la voĉon de la knabo el la loko, kie li estas."],[21,18,"Leviĝu, prenu la knabon kaj tenu lin per via mano, ĉar grandan popolon Mi faros el li.","Leviĝu, prenu la knabon kaj tenu lin per via mano, ĉar grandan popolon Mi faros el li."],[21,19,"Kaj Dio malfermis ŝiajn okulojn, kaj ŝi ekvidis puton kun akvo, kaj ŝi iris kaj plenigis la felsakon per akvo kaj trinkigis la knabon.","Kaj Dio malfermis ŝiajn okulojn, kaj ŝi ekvidis puton kun akvo, kaj ŝi iris kaj plenigis la felsakon per akvo kaj trinkigis la knabon."],[21,20,"Kaj Dio estis kun la knabo, kaj li grandiĝis kaj loĝis en la dezerto kaj fariĝis arkpafisto.","Kaj Dio estis kun la knabo, kaj li grandiĝis kaj loĝis en la dezerto kaj fariĝis arkpafisto."],[21,21,"Kaj li loĝis en la dezerto Paran; kaj lia patrino prenis al li edzinon el la lando Egipta.","Kaj li loĝis en la dezerto Paran; kaj lia patrino prenis al li edzinon el la lando Egipta."],[21,22,"Kaj en tiu tempo Abimeleĥ kaj lia militestro Piĥol diris al Abraham jene: Dio estas kun vi en ĉio, kion vi faras;","Kaj en tiu tempo Abimeleĥ kaj lia militestro Piĥol diris al Abraham jene: Dio estas kun vi en ĉio, kion vi faras;"],[21,23,"nun ĵuru do al mi per Dio, ke vi ne agos malfidele kun mi, nek kun mia filo, nek kun mia nepo; ke tiel same favorkore, kiel mi agis kun vi, vi agos kun mi, kaj kun la lando, en kiu vi loĝas kiel fremdulo.","nun ĵuru do al mi per Dio, ke vi ne agos malfidele kun mi, nek kun mia filo, nek kun mia nepo; ke tiel same favorkore, kiel mi agis kun vi, vi agos kun mi, kaj kun la lando, en kiu vi loĝas kiel fremdulo."],[21,24,"Kaj Abraham diris: Mi ĵuras.","Kaj Abraham diris: Mi ĵuras."],[21,25,"Kaj Abraham riproĉis Abimeleĥon pro la akva puto, kiun perforte forprenis la sklavoj de Abimeleĥ.","Kaj Abraham riproĉis Abimeleĥon pro la akva puto, kiun perforte forprenis la sklavoj de Abimeleĥ."],[21,26,"Kaj Abimeleĥ diris: Mi ne scias, kiu faris tion, kaj ankaŭ vi ne diris al mi; mi eĉ ne aŭdis pri tio ĝis hodiaŭ.","Kaj Abimeleĥ diris: Mi ne scias, kiu faris tion, kaj ankaŭ vi ne diris al mi; mi eĉ ne aŭdis pri tio ĝis hodiaŭ."],[21,27,"Kaj Abraham prenis ŝafojn kaj bovojn kaj donis al Abimeleĥ, kaj ili ambaŭ starigis inter si interligon.","Kaj Abraham prenis ŝafojn kaj bovojn kaj donis al Abimeleĥ, kaj ili ambaŭ starigis inter si interligon."],[21,28,"Kaj Abraham starigis sep ŝafidojn aparte.","Kaj Abraham starigis sep ŝafidojn aparte."],[21,29,"Kaj Abimeleĥ diris al Abraham: Por kio estas tiuj sep ŝafidoj, kiujn vi starigis aparte?","Kaj Abimeleĥ diris al Abraham: Por kio estas tiuj sep ŝafidoj, kiujn vi starigis aparte?"],[21,30,"Kaj tiu diris: Sep ŝafidojn prenu el mia mano, por ke ili estu por mi atesto, ke mi elfosis tiun puton.","Kaj tiu diris: Sep ŝafidojn prenu el mia mano, por ke ili estu por mi atesto, ke mi elfosis tiun puton."],[21,31,"Tial tiu loko havas la nomon Beer-Ŝeba, ĉar tie ili ambaŭ ĵuris.","Tial tiu loko havas la nomon Beer-Ŝeba, ĉar tie ili ambaŭ ĵuris."],[21,32,"Kaj ili starigis interligon en Beer-Ŝeba. Kaj Abimeleĥ kaj lia militestro Piĥol leviĝis kaj reiris en la landon de la Filiŝtoj.","Kaj ili starigis interligon en Beer-Ŝeba. Kaj Abimeleĥ kaj lia militestro Piĥol leviĝis kaj reiris en la landon de la Filiŝtoj."],[21,33,"Kaj Abraham plantis tamariskon en Beer-Ŝeba, kaj preĝis tie al la Eternulo, la Dio eterna.","Kaj Abraham plantis tamariskon en Beer-Ŝeba, kaj preĝis tie al la Eternulo, la Dio eterna."],[21,34,"Kaj Abraham loĝis en la lando de la Filiŝtoj longan tempon.","Kaj Abraham loĝis en la lando de la Filiŝtoj longan tempon."],[22,1,"Post tiuj okazintaĵoj Dio provis Abrahamon, kaj diris al li: Abraham! Kaj tiu respondis: Jen mi estas.","Post tiuj okazintaĵoj Dio provis Abrahamon, kaj diris al li: Abraham! Kaj tiu respondis: Jen mi estas."],[22,2,"Kaj Li diris: Prenu vian filon, vian solan, kiun vi amas, Isaakon, kaj iru en la landon Morija, kaj oferu lin tie kiel bruloferon sur unu el la montoj, kiun Mi montros al vi.","Kaj Li diris: Prenu vian filon, vian solan, kiun vi amas, Isaakon, kaj iru en la landon Morija, kaj oferu lin tie kiel bruloferon sur unu el la montoj, kiun Mi montros al vi."],[22,3,"Kaj Abraham leviĝis frue matene kaj selis sian azenon kaj prenis siajn du junulojn kun si kaj sian filon Isaak; kaj li fendis lignon por brulofero, kaj leviĝis kaj iris al tiu loko, pri kiu diris al li Dio.","Kaj Abraham leviĝis frue matene kaj selis sian azenon kaj prenis siajn du junulojn kun si kaj sian filon Isaak; kaj li fendis lignon por brulofero, kaj leviĝis kaj iris al tiu loko, pri kiu diris al li Dio."],[22,4,"En la tria tago Abraham levis siajn okulojn kaj ekvidis la lokon de malproksime.","En la tria tago Abraham levis siajn okulojn kaj ekvidis la lokon de malproksime."],[22,5,"Kaj Abraham diris al siaj junuloj: Restu ĉi tie kun la azeno, kaj mi kun la knabo iros tien, kaj ni adorkliniĝos kaj revenos al vi.","Kaj Abraham diris al siaj junuloj: Restu ĉi tie kun la azeno, kaj mi kun la knabo iros tien, kaj ni adorkliniĝos kaj revenos al vi."],[22,6,"Kaj Abraham prenis la lignon por la brulofero kaj metis ĝin sur sian filon Isaak, kaj li prenis en sian manon la fajron kaj la tranĉilon; kaj ili iris ambaŭ kune.","Kaj Abraham prenis la lignon por la brulofero kaj metis ĝin sur sian filon Isaak, kaj li prenis en sian manon la fajron kaj la tranĉilon; kaj ili iris ambaŭ kune."],[22,7,"Kaj Isaak diris al sia patro Abraham: Mia patro! Kaj tiu respondis: Jen mi estas, mia filo. Kaj li diris: Jen estas la fajro kaj la ligno, sed kie estas la ŝafo por la brulofero?","Kaj Isaak diris al sia patro Abraham: Mia patro! Kaj tiu respondis: Jen mi estas, mia filo. Kaj li diris: Jen estas la fajro kaj la ligno, sed kie estas la ŝafo por la brulofero?"],[22,8,"Kaj Abraham diris: Dio antaŭvidos al Si la ŝafon por la brulofero, mia filo. Kaj ili iris ambaŭ kune.","Kaj Abraham diris: Dio antaŭvidos al Si la ŝafon por la brulofero, mia filo. Kaj ili iris ambaŭ kune."],[22,9,"Kaj ili venis al la loko, pri kiu diris al li Dio; kaj Abraham konstruis tie la altaron kaj surmetis la lignon, kaj ligis sian filon Isaak kaj metis lin sur la altaron super la ligno.","Kaj ili venis al la loko, pri kiu diris al li Dio; kaj Abraham konstruis tie la altaron kaj surmetis la lignon, kaj ligis sian filon Isaak kaj metis lin sur la altaron super la ligno."],[22,10,"Kaj Abraham etendis sian manon kaj prenis la tranĉilon, por buĉi sian filon.","Kaj Abraham etendis sian manon kaj prenis la tranĉilon, por buĉi sian filon."],[22,11,"Kaj ekvokis al li anĝelo de la Eternulo el la ĉielo, kaj diris: Abraham, Abraham! Kaj li respondis: Jen mi estas.","Kaj ekvokis al li anĝelo de la Eternulo el la ĉielo, kaj diris: Abraham, Abraham! Kaj li respondis: Jen mi estas."],[22,12,"Kaj Tiu diris: Ne etendu vian manon sur la knabon, kaj faru al li nenion; ĉar nun Mi scias, ke vi timas Dion kaj vi ne indulgis pro Mi vian filon, la solan.","Kaj Tiu diris: Ne etendu vian manon sur la knabon, kaj faru al li nenion; ĉar nun Mi scias, ke vi timas Dion kaj vi ne indulgis pro Mi vian filon, la solan."],[22,13,"Kaj Abraham levis siajn okulojn, kaj vidis, ke jen virŝafo malantaŭe implikiĝis per la kornoj en la arbetaĵoj. Kaj Abraham iris kaj prenis la virŝafon, kaj oferis ĝin kiel bruloferon anstataŭ sia filo.","Kaj Abraham levis siajn okulojn, kaj vidis, ke jen virŝafo malantaŭe implikiĝis per la kornoj en la arbetaĵoj. Kaj Abraham iris kaj prenis la virŝafon, kaj oferis ĝin kiel bruloferon anstataŭ sia filo."],[22,14,"Kaj Abraham donis al tiu loko la nomon: La Eternulo Vidas; tial oni ankoraŭ nun diras: Sur la monto, kie la Eternulo aperas.","Kaj Abraham donis al tiu loko la nomon: La Eternulo Vidas; tial oni ankoraŭ nun diras: Sur la monto, kie la Eternulo aperas."],[22,15,"Kaj denove anĝelo de la Eternulo vokis al Abraham el la ĉielo,","Kaj denove anĝelo de la Eternulo vokis al Abraham el la ĉielo,"],[22,16,"kaj diris: Mi ĵuras per Mi, diras la Eternulo, ke ĉar vi faris tiun aferon kaj ne indulgis vian filon, la solan;","kaj diris: Mi ĵuras per Mi, diras la Eternulo, ke ĉar vi faris tiun aferon kaj ne indulgis vian filon, la solan;"],[22,17,"tial Mi benos vin kaj Mi multigos vian idaron simile al la steloj de la ĉielo kaj al la sablo sur la bordo de la maro; kaj via idaro posedos la pordegojn de siaj malamikoj.","tial Mi benos vin kaj Mi multigos vian idaron simile al la steloj de la ĉielo kaj al la sablo sur la bordo de la maro; kaj via idaro posedos la pordegojn de siaj malamikoj."],[22,18,"Kaj beniĝos per via idaro ĉiuj popoloj de la tero, pro tio, ke vi obeis Mian voĉon.","Kaj beniĝos per via idaro ĉiuj popoloj de la tero, pro tio, ke vi obeis Mian voĉon."],[22,19,"Kaj Abraham revenis al siaj junuloj, kaj ili leviĝis kaj iris kune al Beer-Ŝeba; kaj Abraham loĝis en Beer-Ŝeba.","Kaj Abraham revenis al siaj junuloj, kaj ili leviĝis kaj iris kune al Beer-Ŝeba; kaj Abraham loĝis en Beer-Ŝeba."],[22,20,"Post tiuj okazintaĵoj oni sciigis al Abraham, dirante: Jen ankaŭ Milka naskis infanojn al via frato Naĥor:","Post tiuj okazintaĵoj oni sciigis al Abraham, dirante: Jen ankaŭ Milka naskis infanojn al via frato Naĥor:"],[22,21,"la unuenaskiton Uc, kaj lian fraton Buz, kaj Kemuelon, la patron de Aram;","la unuenaskiton Uc, kaj lian fraton Buz, kaj Kemuelon, la patron de Aram;"],[22,22,"kaj Kesedon kaj Ĥazon kaj Pildaŝon kaj Jidlafon kaj Betuelon.","kaj Kesedon kaj Ĥazon kaj Pildaŝon kaj Jidlafon kaj Betuelon."],[22,23,"Kaj de Betuel naskiĝis Rebeka. Ĉi tiujn ok naskis Milka al Naĥor, la frato de Abraham.","Kaj de Betuel naskiĝis Rebeka. Ĉi tiujn ok naskis Milka al Naĥor, la frato de Abraham."],[22,24,"Kaj lia kromvirino, nome Reuma, ankaŭ naskis: Tebaĥon kaj Gaĥamon kaj Taĥaŝon kaj Maaĥan.","Kaj lia kromvirino, nome Reuma, ankaŭ naskis: Tebaĥon kaj Gaĥamon kaj Taĥaŝon kaj Maaĥan."],[23,1,"Kaj la vivo de Sara estis cent dudek sep jaroj; tiom estis la jaroj de la vivo de Sara.","Kaj la vivo de Sara estis cent dudek sep jaroj; tiom estis la jaroj de la vivo de Sara."],[23,2,"Kaj Sara mortis en Kirjat-Arba, kiu estas Ĥebron, en la lando Kanaana. Kaj Abraham venis, por funebri pri Sara kaj plori pri ŝi.","Kaj Sara mortis en Kirjat-Arba, kiu estas Ĥebron, en la lando Kanaana. Kaj Abraham venis, por funebri pri Sara kaj plori pri ŝi."],[23,3,"Kaj Abraham leviĝis for de sia mortintino, kaj diris al la filoj de Ĥet jene:","Kaj Abraham leviĝis for de sia mortintino, kaj diris al la filoj de Ĥet jene:"],[23,4,"Fremdulo kaj pasloĝanto mi estas ĉe vi; donu al mi posedotan lokon por tombo inter vi, por ke mi enterigu mian mortintinon, kiu estas antaŭ mi.","Fremdulo kaj pasloĝanto mi estas ĉe vi; donu al mi posedotan lokon por tombo inter vi, por ke mi enterigu mian mortintinon, kiu estas antaŭ mi."],[23,5,"Kaj la filoj de Ĥet respondis al Abraham, dirante al li:","Kaj la filoj de Ĥet respondis al Abraham, dirante al li:"],[23,6,"Aŭskultu nin, nia sinjoro! vi estas princo de Dio inter ni; en la plej elektitaj niaj tomboj enterigu vian mortintinon; neniu el ni rifuzos al vi sian tomblokon, por enterigi vian mortintinon.","Aŭskultu nin, nia sinjoro! vi estas princo de Dio inter ni; en la plej elektitaj niaj tomboj enterigu vian mortintinon; neniu el ni rifuzos al vi sian tomblokon, por enterigi vian mortintinon."],[23,7,"Kaj Abraham leviĝis, kaj profunde kliniĝis antaŭ la popolo de la lando, antaŭ la filoj de Ĥet.","Kaj Abraham leviĝis, kaj profunde kliniĝis antaŭ la popolo de la lando, antaŭ la filoj de Ĥet."],[23,8,"Kaj li diris al ili jene: Se plaĉas al vi, ke mi enterigu mian mortintinon, kiu estas antaŭ mi, tiam aŭskultu min kaj petu por mi Efronon, la filon de Coĥar,","Kaj li diris al ili jene: Se plaĉas al vi, ke mi enterigu mian mortintinon, kiu estas antaŭ mi, tiam aŭskultu min kaj petu por mi Efronon, la filon de Coĥar,"],[23,9,"ke li donu al mi la duoblan kavernon, kiun li havas en la fino de sia kampo; por plena sumo da mono li donu ĝin al mi inter vi por tomba posedaĵo.","ke li donu al mi la duoblan kavernon, kiun li havas en la fino de sia kampo; por plena sumo da mono li donu ĝin al mi inter vi por tomba posedaĵo."],[23,10,"Kaj Efron sidis inter la filoj de Ĥet, kaj respondis Efron la Ĥetido al Abraham aŭdeble por la filoj de Ĥet, antaŭ ĉiuj, kiuj venis en la pordegon de lia urbo, dirante:","Kaj Efron sidis inter la filoj de Ĥet, kaj respondis Efron la Ĥetido al Abraham aŭdeble por la filoj de Ĥet, antaŭ ĉiuj, kiuj venis en la pordegon de lia urbo, dirante:"],[23,11,"Ne, mia sinjoro, aŭskultu min! la kampon mi donas al vi, kaj la kavernon, kiu estas sur ĝi, al vi mi donas, antaŭ la okuloj de la filoj de mia popolo mi donas ĝin al vi; enterigu vian mortintinon.","Ne, mia sinjoro, aŭskultu min! la kampon mi donas al vi, kaj la kavernon, kiu estas sur ĝi, al vi mi donas, antaŭ la okuloj de la filoj de mia popolo mi donas ĝin al vi; enterigu vian mortintinon."],[23,12,"Kaj Abraham profunde kliniĝis antaŭ la popolo de la lando.","Kaj Abraham profunde kliniĝis antaŭ la popolo de la lando."],[23,13,"Kaj li diris al Efron aŭdeble por la popolo de la lando jene: Mi petas, aŭskultu min: mi donas monon por la kampo; prenu de mi, kaj mi enterigos tie mian mortintinon.","Kaj li diris al Efron aŭdeble por la popolo de la lando jene: Mi petas, aŭskultu min: mi donas monon por la kampo; prenu de mi, kaj mi enterigos tie mian mortintinon."],[23,14,"Kaj Efron respondis al Abraham, dirante al li:","Kaj Efron respondis al Abraham, dirante al li:"],[23,15,"Mia sinjoro, aŭskultu min: la tero valoras kvarcent siklojn; sed kio ĝi estas inter mi kaj vi? enterigu vian mortintinon.","Mia sinjoro, aŭskultu min: la tero valoras kvarcent siklojn; sed kio ĝi estas inter mi kaj vi? enterigu vian mortintinon."],[23,16,"Kaj Abraham aŭskultis Efronon, kaj Abraham pesis al Efron la monon, pri kiu li parolis aŭdeble por la filoj de Ĥet, kvarcent siklojn da arĝento, uzata en la komerco.","Kaj Abraham aŭskultis Efronon, kaj Abraham pesis al Efron la monon, pri kiu li parolis aŭdeble por la filoj de Ĥet, kvarcent siklojn da arĝento, uzata en la komerco."],[23,17,"Kaj la kampo de Efron kun la duobla kaverno, kiu estis antaŭ Mamre, la kampo kaj la kaverno sur ĝi kaj ĉiuj arboj sur la kampo, inter ĉiuj ĝiaj limoj ĉirkaŭe, fariĝis","Kaj la kampo de Efron kun la duobla kaverno, kiu estis antaŭ Mamre, la kampo kaj la kaverno sur ĝi kaj ĉiuj arboj sur la kampo, inter ĉiuj ĝiaj limoj ĉirkaŭe, fariĝis"],[23,18,"posedaĵo de Abraham antaŭ la okuloj de la filoj de Ĥet, de ĉiuj, kiuj venis en la pordegon de lia urbo.","posedaĵo de Abraham antaŭ la okuloj de la filoj de Ĥet, de ĉiuj, kiuj venis en la pordegon de lia urbo."],[23,19,"Kaj post tio Abraham enterigis sian edzinon Sara en la duobla kaverno de la kampo, antaŭ Mamre, kiu estas Ĥebron, en la lando Kanaana.","Kaj post tio Abraham enterigis sian edzinon Sara en la duobla kaverno de la kampo, antaŭ Mamre, kiu estas Ĥebron, en la lando Kanaana."],[23,20,"Kaj la kampo kaj la kaverno sur ĝi fariĝis tomba posedaĵo de Abraham, kiun li akiris de la filoj de Ĥet.","Kaj la kampo kaj la kaverno sur ĝi fariĝis tomba posedaĵo de Abraham, kiun li akiris de la filoj de Ĥet."],[24,1,"Kaj Abraham estis maljuna kaj en profunda aĝo. Kaj la Eternulo benis Abrahamon en ĉio.","Kaj Abraham estis maljuna kaj en profunda aĝo. Kaj la Eternulo benis Abrahamon en ĉio."],[24,2,"Kaj Abraham diris al sia sklavo, la administranto de lia domo, kiu regis ĉion, kio apartenis al li: Metu vian manon sub mian femuron;","Kaj Abraham diris al sia sklavo, la administranto de lia domo, kiu regis ĉion, kio apartenis al li: Metu vian manon sub mian femuron;"],[24,3,"kaj mi ĵurigas vin per la Eternulo, la Dio de la ĉielo kaj la Dio de la tero, ke vi ne prenos edzinon por mia filo el la filinoj de la Kanaanidoj, inter kiuj mi loĝas;","kaj mi ĵurigas vin per la Eternulo, la Dio de la ĉielo kaj la Dio de la tero, ke vi ne prenos edzinon por mia filo el la filinoj de la Kanaanidoj, inter kiuj mi loĝas;"],[24,4,"sed en mian landon kaj en mian patrujon vi iros kaj vi prenos edzinon por mia filo Isaak.","sed en mian landon kaj en mian patrujon vi iros kaj vi prenos edzinon por mia filo Isaak."],[24,5,"Kaj la sklavo diris al li: Eble la virino ne volos iri kun mi en ĉi tiun landon; ĉu mi tiam devas revenigi vian filon en la landon, el kiu vi eliris?","Kaj la sklavo diris al li: Eble la virino ne volos iri kun mi en ĉi tiun landon; ĉu mi tiam devas revenigi vian filon en la landon, el kiu vi eliris?"],[24,6,"Kaj Abraham diris al li: Gardu vin, ne revenigu mian filon tien.","Kaj Abraham diris al li: Gardu vin, ne revenigu mian filon tien."],[24,7,"La Eternulo, la Dio de la ĉielo, kiu prenis min el la domo de mia patro kaj el mia patrujo, kaj diris al mi kaj ĵuris al mi, dirante: Al via idaro Mi donos ĉi tiun landon — Li sendos Sian anĝelon antaŭ vi, kaj vi prenos edzinon por mia filo el tie.","La Eternulo, la Dio de la ĉielo, kiu prenis min el la domo de mia patro kaj el mia patrujo, kaj diris al mi kaj ĵuris al mi, dirante: Al via idaro Mi donos ĉi tiun landon — Li sendos Sian anĝelon antaŭ vi, kaj vi prenos edzinon por mia filo el tie."],[24,8,"Kaj se la virino ne volos iri kun vi, tiam vi fariĝos libera de ĉi tiu mia ĵuro; nur mian filon ne revenigu tien.","Kaj se la virino ne volos iri kun vi, tiam vi fariĝos libera de ĉi tiu mia ĵuro; nur mian filon ne revenigu tien."],[24,9,"Kaj la sklavo metis sian manon sub la femuron de sia sinjoro Abraham kaj ĵuris al li pri tiu afero.","Kaj la sklavo metis sian manon sub la femuron de sia sinjoro Abraham kaj ĵuris al li pri tiu afero."],[24,10,"Kaj la sklavo prenis dek kamelojn el la kameloj de sia sinjoro, kaj li iris; kaj ĉiaj bonaĵoj de lia sinjoro estis en liaj manoj. Kaj li leviĝis kaj iris Mezopotamion, al la urbo Naĥor.","Kaj la sklavo prenis dek kamelojn el la kameloj de sia sinjoro, kaj li iris; kaj ĉiaj bonaĵoj de lia sinjoro estis en liaj manoj. Kaj li leviĝis kaj iris Mezopotamion, al la urbo Naĥor."],[24,11,"Kaj li genuigis la kamelojn ekstere de la urbo, ĉe puto kun akvo, en vespera tempo, en la tempo, kiam eliras la virinoj, por ĉerpi akvon.","Kaj li genuigis la kamelojn ekstere de la urbo, ĉe puto kun akvo, en vespera tempo, en la tempo, kiam eliras la virinoj, por ĉerpi akvon."],[24,12,"Kaj li diris: Ho Eternulo, Dio de mia sinjoro Abraham, sukcesigu min hodiaŭ kaj faru favorkoraĵon al mia sinjoro Abraham.","Kaj li diris: Ho Eternulo, Dio de mia sinjoro Abraham, sukcesigu min hodiaŭ kaj faru favorkoraĵon al mia sinjoro Abraham."],[24,13,"Jen mi staras apud la fonto da akvo, kaj la filinoj de la urbanoj eliras, por ĉerpi akvon;","Jen mi staras apud la fonto da akvo, kaj la filinoj de la urbanoj eliras, por ĉerpi akvon;"],[24,14,"kaj la junulinon, al kiu mi diros: Volu klini vian kruĉon, ke mi trinku, kaj ŝi diros: Trinku, kaj mi trinkigos ankaŭ viajn kamelojn — ŝin Vi destinis por Via sklavo Isaak; kaj per tio mi sciiĝos, ke Vi faris favorkoraĵon al mia sinjoro.","kaj la junulinon, al kiu mi diros: Volu klini vian kruĉon, ke mi trinku, kaj ŝi diros: Trinku, kaj mi trinkigos ankaŭ viajn kamelojn — ŝin Vi destinis por Via sklavo Isaak; kaj per tio mi sciiĝos, ke Vi faris favorkoraĵon al mia sinjoro."],[24,15,"Kaj antaŭ ol li finis paroli, jen eliras Rebeka, kiu estis naskita al Betuel, la filo de Milka, edzino de Naĥor, frato de Abraham; kaj ŝia kruĉo estis sur ŝia ŝultro.","Kaj antaŭ ol li finis paroli, jen eliras Rebeka, kiu estis naskita al Betuel, la filo de Milka, edzino de Naĥor, frato de Abraham; kaj ŝia kruĉo estis sur ŝia ŝultro."],[24,16,"Kaj la junulino estis tre belaspekta, virgulino, kiun ankoraŭ ne ekkonis viro. Kaj ŝi malsupreniris al la fonto kaj plenigis sian kruĉon kaj iris supren.","Kaj la junulino estis tre belaspekta, virgulino, kiun ankoraŭ ne ekkonis viro. Kaj ŝi malsupreniris al la fonto kaj plenigis sian kruĉon kaj iris supren."],[24,17,"Kaj la sklavo kuris al ŝi renkonte, kaj diris: Volu lasi min trinki iom da akvo el via kruĉo.","Kaj la sklavo kuris al ŝi renkonte, kaj diris: Volu lasi min trinki iom da akvo el via kruĉo."],[24,18,"Kaj ŝi diris: Trinku, mia sinjoro; kaj ŝi rapide mallevis la kruĉon sur sian manon, kaj ŝi donis al li trinki.","Kaj ŝi diris: Trinku, mia sinjoro; kaj ŝi rapide mallevis la kruĉon sur sian manon, kaj ŝi donis al li trinki."],[24,19,"Kaj kiam ŝi sufiĉe lin trinkigis, ŝi diris: Ankaŭ por viaj kameloj mi ĉerpos, ĝis ili finos trinki.","Kaj kiam ŝi sufiĉe lin trinkigis, ŝi diris: Ankaŭ por viaj kameloj mi ĉerpos, ĝis ili finos trinki."],[24,20,"Kaj rapide ŝi elverŝis el sia kruĉo en la trinkujon, kaj kuris denove al la puto, por ĉerpi por ĉiuj liaj kameloj.","Kaj rapide ŝi elverŝis el sia kruĉo en la trinkujon, kaj kuris denove al la puto, por ĉerpi por ĉiuj liaj kameloj."],[24,21,"Kaj la viro admiris ŝin silente, por konvinkiĝi, ĉu la Eternulo prosperigis lian vojon aŭ ne.","Kaj la viro admiris ŝin silente, por konvinkiĝi, ĉu la Eternulo prosperigis lian vojon aŭ ne."],[24,22,"Kaj kiam la kameloj ĉesis trinki, tiam la viro prenis oran ringon, havantan la pezon de duono de siklo, kaj du braceletojn por ŝiaj manoj, havantajn la pezon de dek sikloj da oro.","Kaj kiam la kameloj ĉesis trinki, tiam la viro prenis oran ringon, havantan la pezon de duono de siklo, kaj du braceletojn por ŝiaj manoj, havantajn la pezon de dek sikloj da oro."],[24,23,"Kaj li diris: Kies filino vi estas? volu diri al mi; ĉu en la domo de via patro estas loko por ni, por tradormi la nokton?","Kaj li diris: Kies filino vi estas? volu diri al mi; ĉu en la domo de via patro estas loko por ni, por tradormi la nokton?"],[24,24,"Kaj ŝi diris al li: Mi estas filino de Betuel, filo de Milka, kiun ŝi naskis al Naĥor.","Kaj ŝi diris al li: Mi estas filino de Betuel, filo de Milka, kiun ŝi naskis al Naĥor."],[24,25,"Kaj ŝi diris al li: Ankaŭ da pajlo kaj da furaĝo ni havas multe, kaj ankaŭ lokon, por ke vi tradormu la nokton.","Kaj ŝi diris al li: Ankaŭ da pajlo kaj da furaĝo ni havas multe, kaj ankaŭ lokon, por ke vi tradormu la nokton."],[24,26,"Kaj la viro kliniĝis kaj faris adoron al la Eternulo.","Kaj la viro kliniĝis kaj faris adoron al la Eternulo."],[24,27,"Kaj li diris: Glorata estu la Eternulo, la Dio de mia sinjoro Abraham, kiu ne lasis sen Sia favorkoreco kaj vereco mian sinjoron. Per la vojo, kiun mi iris, la Eternulo alkondukis min al la domo de la frato de mia sinjoro.","Kaj li diris: Glorata estu la Eternulo, la Dio de mia sinjoro Abraham, kiu ne lasis sen Sia favorkoreco kaj vereco mian sinjoron. Per la vojo, kiun mi iris, la Eternulo alkondukis min al la domo de la frato de mia sinjoro."],[24,28,"Kaj la junulino kuris, kaj rakontis tiujn aferojn en la domo de sia patrino.","Kaj la junulino kuris, kaj rakontis tiujn aferojn en la domo de sia patrino."],[24,29,"Kaj Rebeka havis fraton, kiu estis nomata Laban. Kaj Laban kuris al la viro eksteren, al la fonto.","Kaj Rebeka havis fraton, kiu estis nomata Laban. Kaj Laban kuris al la viro eksteren, al la fonto."],[24,30,"Kaj kiam li vidis la ringon kaj la braceletojn sur la manoj de sia fratino, kaj kiam li aŭdis la vortojn de sia fratino Rebeka, kiu diris: Tiel parolis kun mi tiu viro — tiam li iris al la viro, kaj jen tiu staras ĉe la kameloj apud la fonto.","Kaj kiam li vidis la ringon kaj la braceletojn sur la manoj de sia fratino, kaj kiam li aŭdis la vortojn de sia fratino Rebeka, kiu diris: Tiel parolis kun mi tiu viro — tiam li iris al la viro, kaj jen tiu staras ĉe la kameloj apud la fonto."],[24,31,"Kaj li diris: Venu, benita de la Eternulo; kial vi staras ekstere? mi pretigis la domon kaj ankaŭ lokon por la kameloj.","Kaj li diris: Venu, benita de la Eternulo; kial vi staras ekstere? mi pretigis la domon kaj ankaŭ lokon por la kameloj."],[24,32,"Kaj li venigis la viron en la domon, kaj malligis la kamelojn, kaj donis pajlon kaj furaĝon al la kameloj, kaj akvon por lavi liajn piedojn, kaj la piedojn de la homoj, kiuj estis kun li.","Kaj li venigis la viron en la domon, kaj malligis la kamelojn, kaj donis pajlon kaj furaĝon al la kameloj, kaj akvon por lavi liajn piedojn, kaj la piedojn de la homoj, kiuj estis kun li."],[24,33,"Kaj estis metita antaŭ li manĝo; sed li diris: Mi ne manĝos, antaŭ ol mi diros mian aferon. Kaj tiu diris: Parolu.","Kaj estis metita antaŭ li manĝo; sed li diris: Mi ne manĝos, antaŭ ol mi diros mian aferon. Kaj tiu diris: Parolu."],[24,34,"Kaj li diris: Sklavo de Abraham mi estas.","Kaj li diris: Sklavo de Abraham mi estas."],[24,35,"Kaj la Eternulo forte benis mian sinjoron, kaj li fariĝis granda; kaj Li donis al li ŝafojn kaj bovojn kaj arĝenton kaj oron kaj sklavojn kaj sklavinojn kaj kamelojn kaj azenojn.","Kaj la Eternulo forte benis mian sinjoron, kaj li fariĝis granda; kaj Li donis al li ŝafojn kaj bovojn kaj arĝenton kaj oron kaj sklavojn kaj sklavinojn kaj kamelojn kaj azenojn."],[24,36,"Kaj Sara, la edzino de mia sinjoro, naskis filon al mia sinjoro, kiam ŝi maljuniĝis; kaj li donis al li ĉion, kion li havis.","Kaj Sara, la edzino de mia sinjoro, naskis filon al mia sinjoro, kiam ŝi maljuniĝis; kaj li donis al li ĉion, kion li havis."],[24,37,"Kaj mia sinjoro ĵurigis min, dirante: Ne prenu edzinon por mia filo el la filinoj de la Kanaanidoj, en kies lando mi loĝas.","Kaj mia sinjoro ĵurigis min, dirante: Ne prenu edzinon por mia filo el la filinoj de la Kanaanidoj, en kies lando mi loĝas."],[24,38,"Nur al la domo de mia patro iru kaj al mia familio, kaj prenu edzinon por mia filo.","Nur al la domo de mia patro iru kaj al mia familio, kaj prenu edzinon por mia filo."],[24,39,"Kaj mi diris al mia sinjoro: Eble la virino ne volos iri kun mi?","Kaj mi diris al mia sinjoro: Eble la virino ne volos iri kun mi?"],[24,40,"Kaj li diris al mi: La Eternulo, antaŭ kiu mi iradis, sendos Sian anĝelon kun vi kaj sukcesigos vian vojon; kaj vi prenos edzinon por mia filo el mia familio kaj el la domo de mia patro.","Kaj li diris al mi: La Eternulo, antaŭ kiu mi iradis, sendos Sian anĝelon kun vi kaj sukcesigos vian vojon; kaj vi prenos edzinon por mia filo el mia familio kaj el la domo de mia patro."],[24,41,"Tiam vi estos libera de mia ĵuro, kiam vi venos al mia familio; kaj se ili ne donos al vi, vi estos libera de mia ĵuro.","Tiam vi estos libera de mia ĵuro, kiam vi venos al mia familio; kaj se ili ne donos al vi, vi estos libera de mia ĵuro."],[24,42,"Kaj mi venis hodiaŭ al la fonto, kaj mi diris: Eternulo, Dio de mia sinjoro Abraham! ho, se Vi volus sukcesigi mian vojon, kiun mi nun iras!","Kaj mi venis hodiaŭ al la fonto, kaj mi diris: Eternulo, Dio de mia sinjoro Abraham! ho, se Vi volus sukcesigi mian vojon, kiun mi nun iras!"],[24,43,"Jen mi staras apud la fonto da akvo; la virgulino, kiu eliros, por ĉerpi, kaj al kiu mi diros: Lasu min trinki iom da akvo el via kruĉo,","Jen mi staras apud la fonto da akvo; la virgulino, kiu eliros, por ĉerpi, kaj al kiu mi diros: Lasu min trinki iom da akvo el via kruĉo,"],[24,44,"kaj kiu diros al mi: Trinku vi, kaj ankaŭ por viaj kameloj mi ĉerpos — tio estas la virino, kiun la Eternulo destinis por la filo de mia sinjoro.","kaj kiu diros al mi: Trinku vi, kaj ankaŭ por viaj kameloj mi ĉerpos — tio estas la virino, kiun la Eternulo destinis por la filo de mia sinjoro."],[24,45,"Antaŭ ol mi finis paroli en mia koro, jen Rebeka eliras, kaj ŝia kruĉo estas sur ŝia ŝultro; kaj ŝi malsupreniris al la fonto kaj ĉerpis. Kaj mi diris al ŝi: Volu trinkigi min.","Antaŭ ol mi finis paroli en mia koro, jen Rebeka eliras, kaj ŝia kruĉo estas sur ŝia ŝultro; kaj ŝi malsupreniris al la fonto kaj ĉerpis. Kaj mi diris al ŝi: Volu trinkigi min."],[24,46,"Kaj rapide ŝi deprenis sian kruĉon de la ŝultro, kaj diris: Trinku, kaj ankaŭ viajn kamelojn mi trinkigos. Kaj mi trinkis, kaj ankaŭ la kamelojn ŝi trinkigis.","Kaj rapide ŝi deprenis sian kruĉon de la ŝultro, kaj diris: Trinku, kaj ankaŭ viajn kamelojn mi trinkigos. Kaj mi trinkis, kaj ankaŭ la kamelojn ŝi trinkigis."],[24,47,"Kaj mi demandis ŝin, kaj mi diris: Kies filino vi estas? Kaj ŝi diris: Filino de Betuel, filo de Naĥor, kiun naskis al li Milka. Kaj mi metis la ringon sur ŝian nazon kaj la braceletojn sur ŝiajn manojn.","Kaj mi demandis ŝin, kaj mi diris: Kies filino vi estas? Kaj ŝi diris: Filino de Betuel, filo de Naĥor, kiun naskis al li Milka. Kaj mi metis la ringon sur ŝian nazon kaj la braceletojn sur ŝiajn manojn."],[24,48,"Kaj mi kliniĝis kaj faris adoron al la Eternulo, kaj mi gloris la Eternulon, la Dion de mia sinjoro Abraham, kiu kondukis min per ĝusta vojo, por ke mi prenu la filinon de la frato de mia sinjoro por lia filo.","Kaj mi kliniĝis kaj faris adoron al la Eternulo, kaj mi gloris la Eternulon, la Dion de mia sinjoro Abraham, kiu kondukis min per ĝusta vojo, por ke mi prenu la filinon de la frato de mia sinjoro por lia filo."],[24,49,"Kaj nun se vi volas fari favorkoraĵon kaj ĝustaĵon al mia sinjoro, diru al mi; kaj se ne, vi ankaŭ diru al mi, kaj mi turnos min dekstren aŭ maldekstren.","Kaj nun se vi volas fari favorkoraĵon kaj ĝustaĵon al mia sinjoro, diru al mi; kaj se ne, vi ankaŭ diru al mi, kaj mi turnos min dekstren aŭ maldekstren."],[24,50,"Tiam respondis Laban kaj Betuel, kaj diris: De la Eternulo venis ĉi tiu afero; ni ne povas diri al vi ion malbonan aŭ bonan.","Tiam respondis Laban kaj Betuel, kaj diris: De la Eternulo venis ĉi tiu afero; ni ne povas diri al vi ion malbonan aŭ bonan."],[24,51,"Jen Rebeka estas antaŭ vi; prenu ŝin kaj iru, kaj ŝi estu edzino al la filo de via sinjoro, kiel diris la Eternulo.","Jen Rebeka estas antaŭ vi; prenu ŝin kaj iru, kaj ŝi estu edzino al la filo de via sinjoro, kiel diris la Eternulo."],[24,52,"Kaj kiam la sklavo de Abraham aŭdis iliajn vortojn, li kliniĝis ĝis la tero al la Eternulo.","Kaj kiam la sklavo de Abraham aŭdis iliajn vortojn, li kliniĝis ĝis la tero al la Eternulo."],[24,53,"Kaj la sklavo elprenis arĝentaĵojn kaj oraĵojn kaj vestojn kaj donis al Rebeka; kaj donacojn li donis al ŝia frato kaj al ŝia patrino.","Kaj la sklavo elprenis arĝentaĵojn kaj oraĵojn kaj vestojn kaj donis al Rebeka; kaj donacojn li donis al ŝia frato kaj al ŝia patrino."],[24,54,"Kaj manĝis kaj trinkis li kaj la homoj, kiuj estis kun li, kaj ili tradormis tie la nokton. Kaj kiam ili leviĝis matene, li diris: Lasu min for al mia sinjoro.","Kaj manĝis kaj trinkis li kaj la homoj, kiuj estis kun li, kaj ili tradormis tie la nokton. Kaj kiam ili leviĝis matene, li diris: Lasu min for al mia sinjoro."],[24,55,"Tiam ŝia frato kaj ŝia patrino diris: La junulino restu kun ni almenaŭ dek tagojn, poste vi iros.","Tiam ŝia frato kaj ŝia patrino diris: La junulino restu kun ni almenaŭ dek tagojn, poste vi iros."],[24,56,"Kaj li diris al ili: Ne retenu min, ĉar la Eternulo sukcesigis mian vojon. Lasu min for, kaj mi iros al mia sinjoro.","Kaj li diris al ili: Ne retenu min, ĉar la Eternulo sukcesigis mian vojon. Lasu min for, kaj mi iros al mia sinjoro."],[24,57,"Kaj ili diris: Ni vokos la junulinon, kaj ni demandos, kion ŝi diros.","Kaj ili diris: Ni vokos la junulinon, kaj ni demandos, kion ŝi diros."],[24,58,"Kaj ili alvokis Rebekan, kaj diris al ŝi: Ĉu vi iros kun ĉi tiu viro? Kaj ŝi diris: Mi iros.","Kaj ili alvokis Rebekan, kaj diris al ŝi: Ĉu vi iros kun ĉi tiu viro? Kaj ŝi diris: Mi iros."],[24,59,"Kaj ili forsendis sian fratinon Rebeka kaj ŝian nutrintinon kaj la sklavon de Abraham kaj liajn homojn.","Kaj ili forsendis sian fratinon Rebeka kaj ŝian nutrintinon kaj la sklavon de Abraham kaj liajn homojn."],[24,60,"Kaj ili benis Rebekan, kaj diris al ŝi: Nia fratino! miloj da miloj elkresku el vi, kaj via idaro posedu la pordegojn de siaj malamikoj.","Kaj ili benis Rebekan, kaj diris al ŝi: Nia fratino! miloj da miloj elkresku el vi, kaj via idaro posedu la pordegojn de siaj malamikoj."],[24,61,"Kaj leviĝis Rebeka kaj ŝiaj servistinoj kaj sidiĝis sur la kameloj, kaj ili iris post tiu viro; kaj la sklavo prenis Rebekan kaj foriris.","Kaj leviĝis Rebeka kaj ŝiaj servistinoj kaj sidiĝis sur la kameloj, kaj ili iris post tiu viro; kaj la sklavo prenis Rebekan kaj foriris."],[24,62,"Kaj Isaak venis de la vojo, kiu kondukas al la puto de la Vivanto-Vidanto; li loĝis en la suda lando.","Kaj Isaak venis de la vojo, kiu kondukas al la puto de la Vivanto-Vidanto; li loĝis en la suda lando."],[24,63,"Kaj Isaak eliris, por mediti sur la kampo, kiam komenciĝis vespero; kaj li levis siajn okulojn kaj vidis, ke jen venas kameloj.","Kaj Isaak eliris, por mediti sur la kampo, kiam komenciĝis vespero; kaj li levis siajn okulojn kaj vidis, ke jen venas kameloj."],[24,64,"Kaj Rebeka levis siajn okulojn, kaj ŝi ekvidis Isaakon kaj desaltis de la kamelo.","Kaj Rebeka levis siajn okulojn, kaj ŝi ekvidis Isaakon kaj desaltis de la kamelo."],[24,65,"Kaj ŝi diris al la sklavo: Kiu estas tiu viro, kiu iras sur la kampo renkonte al ni? Kaj la sklavo diris: Tio estas mia sinjoro. Kaj ŝi prenis la kovrotukon kaj kovris sin.","Kaj ŝi diris al la sklavo: Kiu estas tiu viro, kiu iras sur la kampo renkonte al ni? Kaj la sklavo diris: Tio estas mia sinjoro. Kaj ŝi prenis la kovrotukon kaj kovris sin."],[24,66,"Kaj la sklavo rakontis al Isaak ĉion, kion li faris.","Kaj la sklavo rakontis al Isaak ĉion, kion li faris."],[24,67,"Kaj Isaak enkondukis ŝin en la tendon de sia patrino Sara; kaj li prenis Rebekan, kaj ŝi fariĝis lia edzino, kaj li ekamis ŝin. Kaj Isaak konsoliĝis pri sia patrino.","Kaj Isaak enkondukis ŝin en la tendon de sia patrino Sara; kaj li prenis Rebekan, kaj ŝi fariĝis lia edzino, kaj li ekamis ŝin. Kaj Isaak konsoliĝis pri sia patrino."],[25,1,"Kaj Abraham prenis alian edzinon, kiu estis nomata Ketura.","Kaj Abraham prenis alian edzinon, kiu estis nomata Ketura."],[25,2,"Kaj ŝi naskis al li Zimranon kaj Jokŝanon kaj Medanon kaj Midjanon kaj Jiŝbakon kaj Ŝuaĥon.","Kaj ŝi naskis al li Zimranon kaj Jokŝanon kaj Medanon kaj Midjanon kaj Jiŝbakon kaj Ŝuaĥon."],[25,3,"Kaj de Jokŝan naskiĝis Ŝeba kaj Dedan. Kaj la filoj de Dedan estis la Aŝuridoj, Letuŝidoj, kaj Leumidoj.","Kaj de Jokŝan naskiĝis Ŝeba kaj Dedan. Kaj la filoj de Dedan estis la Aŝuridoj, Letuŝidoj, kaj Leumidoj."],[25,4,"Kaj la filoj de Midjan estis Efa kaj Efer kaj Ĥanoĥ kaj Abida kaj Eldaa. Ĉiuj ĉi tiuj estis la filoj de Ketura.","Kaj la filoj de Midjan estis Efa kaj Efer kaj Ĥanoĥ kaj Abida kaj Eldaa. Ĉiuj ĉi tiuj estis la filoj de Ketura."],[25,5,"Kaj Abraham fordonis ĉion, kion li havis, al Isaak.","Kaj Abraham fordonis ĉion, kion li havis, al Isaak."],[25,6,"Kaj al la filoj de siaj kromvirinoj Abraham donis donacojn, kaj foririgis ilin de sia filo Isaak, ankoraŭ dum sia vivo, orienten, en landon orientan.","Kaj al la filoj de siaj kromvirinoj Abraham donis donacojn, kaj foririgis ilin de sia filo Isaak, ankoraŭ dum sia vivo, orienten, en landon orientan."],[25,7,"Kaj la nombro de la jaroj de vivo de Abraham, kiujn li travivis, estis cent sepdek kvin jaroj.","Kaj la nombro de la jaroj de vivo de Abraham, kiujn li travivis, estis cent sepdek kvin jaroj."],[25,8,"Kaj Abraham konsumiĝis kaj mortis en bona maljuneco, profundaĝa kaj sata de vivo, kaj li alkolektiĝis al sia popolo.","Kaj Abraham konsumiĝis kaj mortis en bona maljuneco, profundaĝa kaj sata de vivo, kaj li alkolektiĝis al sia popolo."],[25,9,"Kaj enterigis lin liaj filoj Isaak kaj Iŝmael en la duobla kaverno, kiu troviĝas antaŭ Mamre, sur la kampo de Efron, filo de Coĥar, la Ĥetido.","Kaj enterigis lin liaj filoj Isaak kaj Iŝmael en la duobla kaverno, kiu troviĝas antaŭ Mamre, sur la kampo de Efron, filo de Coĥar, la Ĥetido."],[25,10,"Sur la kampo, kiun aĉetis Abraham de la filoj de Ĥet, tie estas enterigitaj Abraham kaj lia edzino Sara.","Sur la kampo, kiun aĉetis Abraham de la filoj de Ĥet, tie estas enterigitaj Abraham kaj lia edzino Sara."],[25,11,"Kaj post la morto de Abraham Dio benis lian filon Isaak. Kaj Isaak loĝis ĉe la puto de la Vivanto-Vidanto.","Kaj post la morto de Abraham Dio benis lian filon Isaak. Kaj Isaak loĝis ĉe la puto de la Vivanto-Vidanto."],[25,12,"Kaj jen estas la generaciaro de Iŝmael, filo de Abraham, kiun Hagar, la Egiptino, sklavino de Sara, naskis al Abraham;","Kaj jen estas la generaciaro de Iŝmael, filo de Abraham, kiun Hagar, la Egiptino, sklavino de Sara, naskis al Abraham;"],[25,13,"kaj jen estas la nomoj de la filoj de Iŝmael, laŭ iliaj nomoj kaj generacioj: Nebajot, la unuenaskita de Iŝmael, kaj Kedar kaj Adbeel kaj Mibsam","kaj jen estas la nomoj de la filoj de Iŝmael, laŭ iliaj nomoj kaj generacioj: Nebajot, la unuenaskita de Iŝmael, kaj Kedar kaj Adbeel kaj Mibsam"],[25,14,"kaj Miŝma kaj Duma kaj Masa,","kaj Miŝma kaj Duma kaj Masa,"],[25,15,"Ĥadad kaj Tema, Jetur, Nafiŝ, kaj Kedma.","Ĥadad kaj Tema, Jetur, Nafiŝ, kaj Kedma."],[25,16,"Tio estas la filoj de Iŝmael, kaj tio estas iliaj nomoj en iliaj vilaĝoj kaj tendaroj, dek du princoj super siaj gentoj.","Tio estas la filoj de Iŝmael, kaj tio estas iliaj nomoj en iliaj vilaĝoj kaj tendaroj, dek du princoj super siaj gentoj."],[25,17,"Kaj la daŭro de la vivo de Iŝmael estis cent tridek sep jaroj; kaj li konsumiĝis kaj mortis kaj alkolektiĝis al sia popolo.","Kaj la daŭro de la vivo de Iŝmael estis cent tridek sep jaroj; kaj li konsumiĝis kaj mortis kaj alkolektiĝis al sia popolo."],[25,18,"Kaj ili loĝis de Ĥavila ĝis Ŝur, kiu estas antaŭ Egiptujo, sur la vojo al Asirio. Antaŭ ĉiuj siaj fratoj li loĝis.","Kaj ili loĝis de Ĥavila ĝis Ŝur, kiu estas antaŭ Egiptujo, sur la vojo al Asirio. Antaŭ ĉiuj siaj fratoj li loĝis."],[25,19,"Kaj jen estas la generaciaro de Isaak, filo de Abraham: de Abraham naskiĝis Isaak.","Kaj jen estas la generaciaro de Isaak, filo de Abraham: de Abraham naskiĝis Isaak."],[25,20,"Kaj Isaak havis la aĝon de kvardek jaroj, kiam li prenis kiel edzinon Rebekan, filinon de Betuel la Siriano, el Mezopotamio, fratinon de Laban la Siriano.","Kaj Isaak havis la aĝon de kvardek jaroj, kiam li prenis kiel edzinon Rebekan, filinon de Betuel la Siriano, el Mezopotamio, fratinon de Laban la Siriano."],[25,21,"Kaj Isaak preĝis al la Eternulo pri sia edzino, ĉar ŝi estis senfrukta; kaj la Eternulo cedis al lia preĝo, kaj lia edzino Rebeka gravediĝis.","Kaj Isaak preĝis al la Eternulo pri sia edzino, ĉar ŝi estis senfrukta; kaj la Eternulo cedis al lia preĝo, kaj lia edzino Rebeka gravediĝis."],[25,22,"Kaj la infanoj interpuŝiĝis en ŝia interno, kaj ŝi diris: Se estas tiel, por kio do mi gravediĝis? Kaj ŝi iris, por demandi la Eternulon.","Kaj la infanoj interpuŝiĝis en ŝia interno, kaj ŝi diris: Se estas tiel, por kio do mi gravediĝis? Kaj ŝi iris, por demandi la Eternulon."],[25,23,"Kaj la Eternulo diris al ŝi: Du popoloj estas en via ventro, Kaj du gentoj disapartiĝos el via interno; Kaj unu popolo estos pli forta ol la dua, Kaj la pli granda servos la malpli grandan.","Kaj la Eternulo diris al ŝi: Du popoloj estas en via ventro, Kaj du gentoj disapartiĝos el via interno; Kaj unu popolo estos pli forta ol la dua, Kaj la pli granda servos la malpli grandan."],[25,24,"Kaj kiam venis la tempo, ke ŝi nasku, tiam montriĝis, ke ĝemeloj estas en ŝia ventro.","Kaj kiam venis la tempo, ke ŝi nasku, tiam montriĝis, ke ĝemeloj estas en ŝia ventro."],[25,25,"Kaj la unua eliris ruĝa, li estis tuta kiel harkovrita felo; kaj oni donis al li la nomon Esav.","Kaj la unua eliris ruĝa, li estis tuta kiel harkovrita felo; kaj oni donis al li la nomon Esav."],[25,26,"Kaj poste eliris lia frato, tenante per la mano la kalkanon de Esav; kaj oni donis al li la nomon Jakob. Kaj Isaak havis la aĝon de sesdek jaroj, kiam ili naskiĝis.","Kaj poste eliris lia frato, tenante per la mano la kalkanon de Esav; kaj oni donis al li la nomon Jakob. Kaj Isaak havis la aĝon de sesdek jaroj, kiam ili naskiĝis."],[25,27,"Kaj la knaboj grandiĝis; kaj Esav fariĝis lerta ĉasisto, kampisto, kaj Jakob fariĝis homo kvieta, sidanta en la tendo.","Kaj la knaboj grandiĝis; kaj Esav fariĝis lerta ĉasisto, kampisto, kaj Jakob fariĝis homo kvieta, sidanta en la tendo."],[25,28,"Kaj Isaak amis Esavon, ĉar li manĝadis lian ĉasaĵon; sed Rebeka amis Jakobon.","Kaj Isaak amis Esavon, ĉar li manĝadis lian ĉasaĵon; sed Rebeka amis Jakobon."],[25,29,"Kaj Jakob kuiris kuiraĵon; kaj Esav venis de la kampo kaj estis laca.","Kaj Jakob kuiris kuiraĵon; kaj Esav venis de la kampo kaj estis laca."],[25,30,"Kaj Esav diris al Jakob: Donu al mi manĝi de ĉi tiu ruĝa kuiraĵo, ĉar mi estas laca. Tial oni donis al li la nomon Edom.","Kaj Esav diris al Jakob: Donu al mi manĝi de ĉi tiu ruĝa kuiraĵo, ĉar mi estas laca. Tial oni donis al li la nomon Edom."],[25,31,"Kaj Jakob diris: Vendu al mi hodiaŭ vian unuenaskitecon.","Kaj Jakob diris: Vendu al mi hodiaŭ vian unuenaskitecon."],[25,32,"Kaj Esav diris: Jen mi tuj mortos; por kio do mi bezonas la unuenaskitecon?","Kaj Esav diris: Jen mi tuj mortos; por kio do mi bezonas la unuenaskitecon?"],[25,33,"Kaj Jakob diris: Ĵuru al mi hodiaŭ; kaj tiu ĵuris al li kaj vendis sian unuenaskitecon al Jakob.","Kaj Jakob diris: Ĵuru al mi hodiaŭ; kaj tiu ĵuris al li kaj vendis sian unuenaskitecon al Jakob."],[25,34,"Kaj Jakob donis al Esav panon kaj kuiraĵon el lentoj, kaj li manĝis kaj trinkis, kaj leviĝis kaj foriris. Kaj Esav malŝatis la unuenaskitecon.","Kaj Jakob donis al Esav panon kaj kuiraĵon el lentoj, kaj li manĝis kaj trinkis, kaj leviĝis kaj foriris. Kaj Esav malŝatis la unuenaskitecon."],[26,1,"Estis malsato en la lando, krom la antaŭa malsato, kiu estis en la tempo de Abraham. Kaj Isaak iris al Abimeleĥ, la reĝo de la Filiŝtoj, en Gerar.","Estis malsato en la lando, krom la antaŭa malsato, kiu estis en la tempo de Abraham. Kaj Isaak iris al Abimeleĥ, la reĝo de la Filiŝtoj, en Gerar."],[26,2,"Kaj la Eternulo aperis al li, kaj diris: Ne iru Egiptujon, loĝu en la lando, pri kiu Mi diros al vi.","Kaj la Eternulo aperis al li, kaj diris: Ne iru Egiptujon, loĝu en la lando, pri kiu Mi diros al vi."],[26,3,"Vivu kiel fremdulo en ĉi tiu lando, kaj Mi estos kun vi, kaj Mi benos vin; ĉar al vi kaj al via idaro Mi donos ĉiujn ĉi tiujn landojn, kaj Mi plenumos la ĵuron, kiun Mi ĵuris al via patro Abraham.","Vivu kiel fremdulo en ĉi tiu lando, kaj Mi estos kun vi, kaj Mi benos vin; ĉar al vi kaj al via idaro Mi donos ĉiujn ĉi tiujn landojn, kaj Mi plenumos la ĵuron, kiun Mi ĵuris al via patro Abraham."],[26,4,"Kaj Mi multigos vian idaron simile al la steloj de la ĉielo, kaj Mi donos al via idaro ĉiujn ĉi tiujn landojn, kaj beniĝos per via idaro ĉiuj popoloj de la tero;","Kaj Mi multigos vian idaron simile al la steloj de la ĉielo, kaj Mi donos al via idaro ĉiujn ĉi tiujn landojn, kaj beniĝos per via idaro ĉiuj popoloj de la tero;"],[26,5,"pro tio, ke Abraham obeis Mian voĉon, kaj plenumadis Miajn aranĝojn, Miajn leĝojn, kaj Miajn instruojn.","pro tio, ke Abraham obeis Mian voĉon, kaj plenumadis Miajn aranĝojn, Miajn leĝojn, kaj Miajn instruojn."],[26,6,"Kaj Isaak ekloĝis en Gerar.","Kaj Isaak ekloĝis en Gerar."],[26,7,"Kaj kiam la homoj de tiu loko demandis pri lia edzino, li diris: Ŝi estas mia fratino; ĉar li timis diri: Mia edzino; por ke la homoj de la loko ne mortigu lin pro Rebeka, ĉar ŝi estis belaspekta.","Kaj kiam la homoj de tiu loko demandis pri lia edzino, li diris: Ŝi estas mia fratino; ĉar li timis diri: Mia edzino; por ke la homoj de la loko ne mortigu lin pro Rebeka, ĉar ŝi estis belaspekta."],[26,8,"Unu fojon, kiam li estis tie jam de longa tempo, Abimeleĥ, la reĝo de la Filiŝtoj, rigardis tra la fenestro, kaj vidis, ke Isaak amuziĝas kun sia edzino Rebeka.","Unu fojon, kiam li estis tie jam de longa tempo, Abimeleĥ, la reĝo de la Filiŝtoj, rigardis tra la fenestro, kaj vidis, ke Isaak amuziĝas kun sia edzino Rebeka."],[26,9,"Tiam Abimeleĥ vokis Isaakon, kaj diris: Jen, ŝi estas ja via edzino; kial do vi diris: Ŝi estas mia fratino? Kaj Isaak diris al li: Ĉar mi pensis, ke eble mi mortos pro ŝi.","Tiam Abimeleĥ vokis Isaakon, kaj diris: Jen, ŝi estas ja via edzino; kial do vi diris: Ŝi estas mia fratino? Kaj Isaak diris al li: Ĉar mi pensis, ke eble mi mortos pro ŝi."],[26,10,"Kaj Abimeleĥ diris: Kion do vi faris al ni! preskaŭ jam kuŝiĝis unu el la popolo kun via edzino, kaj vi venigus sur nin krimon.","Kaj Abimeleĥ diris: Kion do vi faris al ni! preskaŭ jam kuŝiĝis unu el la popolo kun via edzino, kaj vi venigus sur nin krimon."],[26,11,"Kaj Abimeleĥ faris ordonon al la tuta popolo jene: Kiu tuŝos ĉi tiun viron aŭ lian edzinon, tiu mortos.","Kaj Abimeleĥ faris ordonon al la tuta popolo jene: Kiu tuŝos ĉi tiun viron aŭ lian edzinon, tiu mortos."],[26,12,"Kaj Isaak semis en tiu lando, kaj havis en tiu jaro centoble-mezuran rikolton; kaj la Eternulo lin benis.","Kaj Isaak semis en tiu lando, kaj havis en tiu jaro centoble-mezuran rikolton; kaj la Eternulo lin benis."],[26,13,"Kaj tiu homo grandiĝis kaj ĉiam pli kaj pli grandiĝadis, ĝis li fariĝis tre granda.","Kaj tiu homo grandiĝis kaj ĉiam pli kaj pli grandiĝadis, ĝis li fariĝis tre granda."],[26,14,"Kaj li havis tre multe da brutoj malgrandaj kaj brutoj grandaj kaj grandan servistaron; kaj la Filiŝtoj enviis lin.","Kaj li havis tre multe da brutoj malgrandaj kaj brutoj grandaj kaj grandan servistaron; kaj la Filiŝtoj enviis lin."],[26,15,"Kaj ĉiujn putojn, kiujn elfosis la sklavoj de lia patro en la tempo de lia patro Abraham, la Filiŝtoj ŝtopis kaj plenigis ilin per tero.","Kaj ĉiujn putojn, kiujn elfosis la sklavoj de lia patro en la tempo de lia patro Abraham, la Filiŝtoj ŝtopis kaj plenigis ilin per tero."],[26,16,"Tiam Abimeleĥ diris al Isaak: Foriru de ni, ĉar vi fariĝis multe pli forta ol ni.","Tiam Abimeleĥ diris al Isaak: Foriru de ni, ĉar vi fariĝis multe pli forta ol ni."],[26,17,"Kaj Isaak foriris de tie kaj aranĝis siajn tendojn en la valo de Gerar, kaj tie li ekloĝis.","Kaj Isaak foriris de tie kaj aranĝis siajn tendojn en la valo de Gerar, kaj tie li ekloĝis."],[26,18,"Kaj Isaak denove elfosis la akvoputojn, kiujn oni elfosis en la tempo de lia patro Abraham kaj la Filiŝtoj ŝtopis post la morto de Abraham; kaj li donis al ili tiujn samajn nomojn, kiujn donis al ili lia patro.","Kaj Isaak denove elfosis la akvoputojn, kiujn oni elfosis en la tempo de lia patro Abraham kaj la Filiŝtoj ŝtopis post la morto de Abraham; kaj li donis al ili tiujn samajn nomojn, kiujn donis al ili lia patro."],[26,19,"Kaj la sklavoj de Isaak fosis en la valo kaj trovis tie puton kun freŝa akvo.","Kaj la sklavoj de Isaak fosis en la valo kaj trovis tie puton kun freŝa akvo."],[26,20,"Kaj disputis la paŝtistoj de Gerar kun la paŝtistoj de Isaak, dirante: Al ni apartenas la akvo. Kaj oni donis al la puto la nomon Esek, ĉar oni disputis pri ĝi.","Kaj disputis la paŝtistoj de Gerar kun la paŝtistoj de Isaak, dirante: Al ni apartenas la akvo. Kaj oni donis al la puto la nomon Esek, ĉar oni disputis pri ĝi."],[26,21,"Kaj ili elfosis alian puton, kaj ankaŭ pri ĝi ili disputis; kaj oni donis al ĝi la nomon Sitna.","Kaj ili elfosis alian puton, kaj ankaŭ pri ĝi ili disputis; kaj oni donis al ĝi la nomon Sitna."],[26,22,"Kaj ili foriĝis de tie kaj elfosis alian puton, kaj pri ĝi oni ne disputis. Kaj li donis al ĝi la nomon Reĥobot, dirante: Nun la Eternulo donis al ni vastan lokon, kaj ni multiĝos sur la tero.","Kaj ili foriĝis de tie kaj elfosis alian puton, kaj pri ĝi oni ne disputis. Kaj li donis al ĝi la nomon Reĥobot, dirante: Nun la Eternulo donis al ni vastan lokon, kaj ni multiĝos sur la tero."],[26,23,"Kaj de tie li formigris al Beer-Ŝeba.","Kaj de tie li formigris al Beer-Ŝeba."],[26,24,"Kaj aperis al li la Eternulo en tiu nokto, kaj diris: Mi estas la Dio de via patro Abraham; ne timu, ĉar Mi estas kun vi, kaj Mi benos vin kaj Mi multigos vian idaron pro Abraham, Mia servanto.","Kaj aperis al li la Eternulo en tiu nokto, kaj diris: Mi estas la Dio de via patro Abraham; ne timu, ĉar Mi estas kun vi, kaj Mi benos vin kaj Mi multigos vian idaron pro Abraham, Mia servanto."],[26,25,"Kaj li konstruis tie altaron kaj preĝis al la Eternulo. Kaj li aranĝis tie sian tendon, kaj la sklavoj de Isaak elfosis tie puton.","Kaj li konstruis tie altaron kaj preĝis al la Eternulo. Kaj li aranĝis tie sian tendon, kaj la sklavoj de Isaak elfosis tie puton."],[26,26,"Kaj Abimeleĥ iris al li el Gerar, kaj ankaŭ lia amiko Aĥuzat kaj lia militestro Piĥol.","Kaj Abimeleĥ iris al li el Gerar, kaj ankaŭ lia amiko Aĥuzat kaj lia militestro Piĥol."],[26,27,"Kaj Isaak diris al ili: Por kio vi venis al mi? vi min ja malamas kaj forpelis min de vi.","Kaj Isaak diris al ili: Por kio vi venis al mi? vi min ja malamas kaj forpelis min de vi."],[26,28,"Kaj ili diris: Ni vidis, ke la Eternulo estas kun vi; tial ni diris: Estu ĵuro inter ni, inter ni kaj vi, kaj ni faru interligon kun vi,","Kaj ili diris: Ni vidis, ke la Eternulo estas kun vi; tial ni diris: Estu ĵuro inter ni, inter ni kaj vi, kaj ni faru interligon kun vi,"],[26,29,"ke vi ne faru al ni malbonon, kiel ni vin ne tuŝis kaj kiel ni faris al vi nur bonon kaj lasis vin foriri en paco; vi estas nun benito de la Eternulo.","ke vi ne faru al ni malbonon, kiel ni vin ne tuŝis kaj kiel ni faris al vi nur bonon kaj lasis vin foriri en paco; vi estas nun benito de la Eternulo."],[26,30,"Kaj li faris por ili festenon, kaj ili manĝis kaj trinkis.","Kaj li faris por ili festenon, kaj ili manĝis kaj trinkis."],[26,31,"Kaj ili leviĝis frue matene kaj ĵuris al si reciproke. Kaj Isaak lasis ilin foriri, kaj ili foriris de li en paco.","Kaj ili leviĝis frue matene kaj ĵuris al si reciproke. Kaj Isaak lasis ilin foriri, kaj ili foriris de li en paco."],[26,32,"Kaj en tiu tago venis la sklavoj de Isaak, kaj raportis al li pri la puto, kiun ili elfosis, kaj diris al li: Ni trovis akvon.","Kaj en tiu tago venis la sklavoj de Isaak, kaj raportis al li pri la puto, kiun ili elfosis, kaj diris al li: Ni trovis akvon."],[26,33,"Kaj li donis al ĝi la nomon Ŝiba; pro tio la nomo de la urbo estas Beer-Ŝeba ĝis hodiaŭ.","Kaj li donis al ĝi la nomon Ŝiba; pro tio la nomo de la urbo estas Beer-Ŝeba ĝis hodiaŭ."],[26,34,"Kiam Esav havis la aĝon de kvardek jaroj, li prenis kiel edzinojn Jehuditon, filinon de Beeri la Ĥetido, kaj Basmaton, filinon de Elon la Ĥetido.","Kiam Esav havis la aĝon de kvardek jaroj, li prenis kiel edzinojn Jehuditon, filinon de Beeri la Ĥetido, kaj Basmaton, filinon de Elon la Ĥetido."],[26,35,"Kaj ili multe ĉagrenis Isaakon kaj Rebekan.","Kaj ili multe ĉagrenis Isaakon kaj Rebekan."],[27,1,"Kiam Isaak maljuniĝis kaj la vidado de liaj okuloj malakriĝis, li vokis Esavon, sian pli maljunan filon, kaj diris al li: Mia filo! Kaj tiu diris al li: Jen mi estas.","Kiam Isaak maljuniĝis kaj la vidado de liaj okuloj malakriĝis, li vokis Esavon, sian pli maljunan filon, kaj diris al li: Mia filo! Kaj tiu diris al li: Jen mi estas."],[27,2,"Kaj li diris: Jen mi maljuniĝis; mi ne scias, kiam mi mortos;","Kaj li diris: Jen mi maljuniĝis; mi ne scias, kiam mi mortos;"],[27,3,"prenu do nun viajn armilojn, vian sagujon kaj vian pafarkon, kaj iru sur la kampon kaj ĉasu por mi ĉasaĵon;","prenu do nun viajn armilojn, vian sagujon kaj vian pafarkon, kaj iru sur la kampon kaj ĉasu por mi ĉasaĵon;"],[27,4,"kaj faru por mi bongustan manĝaĵon, kian mi amas, kaj alportu al mi, kaj mi ĝin manĝos, por ke mia animo vin benu, antaŭ ol mi mortos.","kaj faru por mi bongustan manĝaĵon, kian mi amas, kaj alportu al mi, kaj mi ĝin manĝos, por ke mia animo vin benu, antaŭ ol mi mortos."],[27,5,"Sed Rebeka aŭdis, kiam Isaak parolis al sia filo Esav. Kaj Esav iris sur la kampon, por ĉasi ĉasaĵon kaj alporti.","Sed Rebeka aŭdis, kiam Isaak parolis al sia filo Esav. Kaj Esav iris sur la kampon, por ĉasi ĉasaĵon kaj alporti."],[27,6,"Kaj Rebeka diris al sia filo Jakob jene: Mi aŭdis, ke via patro diris al via frato Esav jene:","Kaj Rebeka diris al sia filo Jakob jene: Mi aŭdis, ke via patro diris al via frato Esav jene:"],[27,7,"Alportu al mi ĉasaĵon kaj faru por mi bongustan manĝaĵon, kaj mi manĝos, kaj mi benos vin antaŭ la Eternulo antaŭ mia morto.","Alportu al mi ĉasaĵon kaj faru por mi bongustan manĝaĵon, kaj mi manĝos, kaj mi benos vin antaŭ la Eternulo antaŭ mia morto."],[27,8,"Kaj nun, mia filo, aŭskultu mian voĉon, kion mi ordonas al vi:","Kaj nun, mia filo, aŭskultu mian voĉon, kion mi ordonas al vi:"],[27,9,"iru al la brutaro kaj alportu al mi de tie du bonajn kapridojn, kaj mi faros el ili bongustan manĝaĵon por via patro, kian li amas;","iru al la brutaro kaj alportu al mi de tie du bonajn kapridojn, kaj mi faros el ili bongustan manĝaĵon por via patro, kian li amas;"],[27,10,"kaj vi alportos al via patro, kaj li manĝos, por ke li benu vin antaŭ sia morto.","kaj vi alportos al via patro, kaj li manĝos, por ke li benu vin antaŭ sia morto."],[27,11,"Kaj Jakob diris al sia patrino Rebeka: Mia frato Esav estas ja homo harkovrita, kaj mi estas homo glata;","Kaj Jakob diris al sia patrino Rebeka: Mia frato Esav estas ja homo harkovrita, kaj mi estas homo glata;"],[27,12,"eble mia patro min palpos, tiam mi estos en liaj okuloj kiel trompanto, kaj mi venigos sur min malbenon, sed ne benon.","eble mia patro min palpos, tiam mi estos en liaj okuloj kiel trompanto, kaj mi venigos sur min malbenon, sed ne benon."],[27,13,"Kaj lia patrino diris al li: Sur mi estu tiu malbeno, mia filo; nur aŭskultu mian voĉon kaj iru, alportu al mi.","Kaj lia patrino diris al li: Sur mi estu tiu malbeno, mia filo; nur aŭskultu mian voĉon kaj iru, alportu al mi."],[27,14,"Kaj li iris kaj prenis kaj alportis al sia patrino, kaj lia patrino faris bongustan manĝaĵon, kian amis lia patro.","Kaj li iris kaj prenis kaj alportis al sia patrino, kaj lia patrino faris bongustan manĝaĵon, kian amis lia patro."],[27,15,"Kaj Rebeka prenis la luksajn vestojn de sia pli maljuna filo Esav, kiujn ŝi havis ĉe si en la domo, kaj ŝi vestis sian pli junan filon Jakob;","Kaj Rebeka prenis la luksajn vestojn de sia pli maljuna filo Esav, kiujn ŝi havis ĉe si en la domo, kaj ŝi vestis sian pli junan filon Jakob;"],[27,16,"kaj per la feloj de la kapridoj ŝi vestis liajn manojn kaj la glataĵon de lia kolo.","kaj per la feloj de la kapridoj ŝi vestis liajn manojn kaj la glataĵon de lia kolo."],[27,17,"Kaj ŝi donis la bongustan manĝaĵon kaj la panon, kiujn ŝi pretigis, en la manon de sia filo Jakob.","Kaj ŝi donis la bongustan manĝaĵon kaj la panon, kiujn ŝi pretigis, en la manon de sia filo Jakob."],[27,18,"Kaj li venis al sia patro, kaj diris: Mia patro! Kaj tiu diris: Jen mi estas; kiu vi estas, mia filo?","Kaj li venis al sia patro, kaj diris: Mia patro! Kaj tiu diris: Jen mi estas; kiu vi estas, mia filo?"],[27,19,"Kaj Jakob diris al sia patro: Mi estas Esav, via unuenaskito; mi faris, kiel vi diris al mi; volu leviĝi, sidiĝu, kaj manĝu mian ĉasaĵon, por ke via animo min benu.","Kaj Jakob diris al sia patro: Mi estas Esav, via unuenaskito; mi faris, kiel vi diris al mi; volu leviĝi, sidiĝu, kaj manĝu mian ĉasaĵon, por ke via animo min benu."],[27,20,"Kaj Isaak diris al sia filo: Kiamaniere vi tiel rapide trovis, mia filo? Kaj tiu diris: Ĉar la Eternulo, via Dio, sendis al mi renkonte.","Kaj Isaak diris al sia filo: Kiamaniere vi tiel rapide trovis, mia filo? Kaj tiu diris: Ĉar la Eternulo, via Dio, sendis al mi renkonte."],[27,21,"Kaj Isaak diris al Jakob: Alproksimiĝu, kaj mi vin palpos, mia filo, ĉu tio estas vi, mia filo Esav, aŭ ne.","Kaj Isaak diris al Jakob: Alproksimiĝu, kaj mi vin palpos, mia filo, ĉu tio estas vi, mia filo Esav, aŭ ne."],[27,22,"Kaj Jakob alproksimiĝis al sia patro Isaak, kaj tiu lin palpis, kaj diris: La voĉo estas voĉo de Jakob, sed la manoj estas manoj de Esav.","Kaj Jakob alproksimiĝis al sia patro Isaak, kaj tiu lin palpis, kaj diris: La voĉo estas voĉo de Jakob, sed la manoj estas manoj de Esav."],[27,23,"Kaj li ne rekonis lin, ĉar liaj manoj estis kiel la manoj de lia frato Esav, harkovritaj; kaj li benis lin.","Kaj li ne rekonis lin, ĉar liaj manoj estis kiel la manoj de lia frato Esav, harkovritaj; kaj li benis lin."],[27,24,"Kaj li diris: Ĉu tio estas vi, mia filo Esav? Kaj tiu diris: Mi.","Kaj li diris: Ĉu tio estas vi, mia filo Esav? Kaj tiu diris: Mi."],[27,25,"Kaj li diris: Alŝovu al mi, kaj mi manĝos la ĉasaĵon de mia filo, por ke mia animo vin benu. Kaj li alŝovis al li, kaj tiu manĝis; kaj li alportis al li vinon, kaj tiu trinkis.","Kaj li diris: Alŝovu al mi, kaj mi manĝos la ĉasaĵon de mia filo, por ke mia animo vin benu. Kaj li alŝovis al li, kaj tiu manĝis; kaj li alportis al li vinon, kaj tiu trinkis."],[27,26,"Kaj lia patro Isaak diris al li: Alproksimiĝu kaj kisu min, mia filo.","Kaj lia patro Isaak diris al li: Alproksimiĝu kaj kisu min, mia filo."],[27,27,"Kaj li alproksimiĝis kaj kisis lin, kaj tiu flaris la odoron de liaj vestoj, kaj li benis lin, kaj diris: Vidu, la odoro de mia filo Estas kiel la odoro de kampo, Kiun la Eternulo benis;","Kaj li alproksimiĝis kaj kisis lin, kaj tiu flaris la odoron de liaj vestoj, kaj li benis lin, kaj diris: Vidu, la odoro de mia filo Estas kiel la odoro de kampo, Kiun la Eternulo benis;"],[27,28,"Dio donu al vi roson ĉielan Kaj grason de la tero Kaj multe da greno kaj mosto.","Dio donu al vi roson ĉielan Kaj grason de la tero Kaj multe da greno kaj mosto."],[27,29,"Popoloj vin servu, Kaj gentoj kliniĝu antaŭ vi; Estu sinjoro super viaj fratoj, Kaj kliniĝu antaŭ vi la filoj de via patrino; Viaj malbenantoj estu malbenataj, Kaj viaj benantoj estu benataj.","Popoloj vin servu, Kaj gentoj kliniĝu antaŭ vi; Estu sinjoro super viaj fratoj, Kaj kliniĝu antaŭ vi la filoj de via patrino; Viaj malbenantoj estu malbenataj, Kaj viaj benantoj estu benataj."],[27,30,"Kaj kiam Isaak finis beni Jakobon kaj apenaŭ Jakob eliris de antaŭ sia patro Isaak, lia frato Esav venis de sia ĉasado.","Kaj kiam Isaak finis beni Jakobon kaj apenaŭ Jakob eliris de antaŭ sia patro Isaak, lia frato Esav venis de sia ĉasado."],[27,31,"Kaj ankaŭ li faris bongustan manĝaĵon kaj alportis al sia patro, kaj diris al sia patro: Leviĝu, mia patro, kaj manĝu la ĉasaĵon de via filo, por ke via animo min benu.","Kaj ankaŭ li faris bongustan manĝaĵon kaj alportis al sia patro, kaj diris al sia patro: Leviĝu, mia patro, kaj manĝu la ĉasaĵon de via filo, por ke via animo min benu."],[27,32,"Kaj lia patro Isaak diris al li: Kiu vi estas? Kaj li diris: Mi estas via unuenaskita filo Esav.","Kaj lia patro Isaak diris al li: Kiu vi estas? Kaj li diris: Mi estas via unuenaskita filo Esav."],[27,33,"Tiam Isaak ektremis per tre granda tremo, kaj diris: Kiu do estas tiu, kiu ĉasis ĉasaĵon kaj alportis al mi, kaj mi manĝis de ĉio, antaŭ ol vi venis, kaj mi benis lin? kaj li restos ja benita!","Tiam Isaak ektremis per tre granda tremo, kaj diris: Kiu do estas tiu, kiu ĉasis ĉasaĵon kaj alportis al mi, kaj mi manĝis de ĉio, antaŭ ol vi venis, kaj mi benis lin? kaj li restos ja benita!"],[27,34,"Kiam Esav aŭdis la vortojn de sia patro, li ekkriis per tre granda kaj maldolĉa krio, kaj diris al sia patro: Benu ankaŭ min, ho mia patro!","Kiam Esav aŭdis la vortojn de sia patro, li ekkriis per tre granda kaj maldolĉa krio, kaj diris al sia patro: Benu ankaŭ min, ho mia patro!"],[27,35,"Kaj tiu diris: Via frato venis kun ruzo kaj prenis vian benon.","Kaj tiu diris: Via frato venis kun ruzo kaj prenis vian benon."],[27,36,"Kaj li diris: Ĝuste do lia nomo estas Jakob, ĉar li submetis al mi la piedon jam du fojojn; mian unuenaskitecon li prenis, kaj jen li nun prenis mian benon! Kaj li diris: Ĉu vi ne rezervis por mi benon?","Kaj li diris: Ĝuste do lia nomo estas Jakob, ĉar li submetis al mi la piedon jam du fojojn; mian unuenaskitecon li prenis, kaj jen li nun prenis mian benon! Kaj li diris: Ĉu vi ne rezervis por mi benon?"],[27,37,"Kaj Isaak respondis kaj diris al Esav: Jen mi faris lin sinjoro super vi, kaj ĉiujn liajn fratojn mi donis al li kiel servantojn, kaj grenon kaj moston mi havigis al li; kion do mi faros por vi, mia filo?","Kaj Isaak respondis kaj diris al Esav: Jen mi faris lin sinjoro super vi, kaj ĉiujn liajn fratojn mi donis al li kiel servantojn, kaj grenon kaj moston mi havigis al li; kion do mi faros por vi, mia filo?"],[27,38,"Kaj Esav diris al sia patro: Ĉu ĝi estas la sola beno, kiun vi havas? benu ankaŭ min, ho mia patro! Kaj Esav ekploris per laŭta voĉo.","Kaj Esav diris al sia patro: Ĉu ĝi estas la sola beno, kiun vi havas? benu ankaŭ min, ho mia patro! Kaj Esav ekploris per laŭta voĉo."],[27,39,"Kaj lia patro Isaak respondis kaj diris al li: Jen la graso de la tero estu en Via loko de loĝado Kaj la ĉiela roso de supre;","Kaj lia patro Isaak respondis kaj diris al li: Jen la graso de la tero estu en Via loko de loĝado Kaj la ĉiela roso de supre;"],[27,40,"Kaj per via glavo vi vivos, Kaj vian fraton vi servos; Sed kiam vi kontraŭbatalos, Vi deĵetos lian jugon de via kolo.","Kaj per via glavo vi vivos, Kaj vian fraton vi servos; Sed kiam vi kontraŭbatalos, Vi deĵetos lian jugon de via kolo."],[27,41,"Kaj Esav ekmalamis Jakobon pro la beno, per kiu benis lin lia patro; kaj Esav diris en sia koro: Baldaŭ venos la tagoj de funebro pro mia patro, tiam mi mortigos mian fraton Jakob.","Kaj Esav ekmalamis Jakobon pro la beno, per kiu benis lin lia patro; kaj Esav diris en sia koro: Baldaŭ venos la tagoj de funebro pro mia patro, tiam mi mortigos mian fraton Jakob."],[27,42,"Kaj oni raportis al Rebeka la vortojn de ŝia pli maljuna filo Esav; tiam ŝi sendis kaj vokis sian pli junan filon Jakob, kaj diris al li: Jen via frato Esav minacas mortigi vin;","Kaj oni raportis al Rebeka la vortojn de ŝia pli maljuna filo Esav; tiam ŝi sendis kaj vokis sian pli junan filon Jakob, kaj diris al li: Jen via frato Esav minacas mortigi vin;"],[27,43,"tial nun, mia filo, aŭskultu mian voĉon; kaj leviĝu, forkuru al mia frato Laban en Ĥaran;","tial nun, mia filo, aŭskultu mian voĉon; kaj leviĝu, forkuru al mia frato Laban en Ĥaran;"],[27,44,"kaj loĝu ĉe li kelkan tempon, ĝis kvietiĝos la furiozo de via frato;","kaj loĝu ĉe li kelkan tempon, ĝis kvietiĝos la furiozo de via frato;"],[27,45,"ĝis la kolero de via frato deturniĝos de vi, kaj li forgesos, kion vi faris al li. Tiam mi sendos kaj prenos vin de tie. Kial mi perdu vin ambaŭ en unu tago?","ĝis la kolero de via frato deturniĝos de vi, kaj li forgesos, kion vi faris al li. Tiam mi sendos kaj prenos vin de tie. Kial mi perdu vin ambaŭ en unu tago?"],[27,46,"Kaj Rebeka diris al Isaak: Tedis al mi la vivo pro la Ĥetidinoj; se Jakob prenos edzinon el ĉi tiuj Ĥetidinoj, el la filinoj de la lando, tiam por kio mi vivu?","Kaj Rebeka diris al Isaak: Tedis al mi la vivo pro la Ĥetidinoj; se Jakob prenos edzinon el ĉi tiuj Ĥetidinoj, el la filinoj de la lando, tiam por kio mi vivu?"],[28,1,"Tiam Isaak alvokis Jakobon kaj benis lin, kaj ordonis al li, dirante: Ne prenu edzinon el la filinoj Kanaanaj.","Tiam Isaak alvokis Jakobon kaj benis lin, kaj ordonis al li, dirante: Ne prenu edzinon el la filinoj Kanaanaj."],[28,2,"Leviĝu, iru Mezopotamion, al la domo de Betuel, la patro de via patrino, kaj prenu al vi el tie edzinon el la filinoj de Laban, la frato de via patrino.","Leviĝu, iru Mezopotamion, al la domo de Betuel, la patro de via patrino, kaj prenu al vi el tie edzinon el la filinoj de Laban, la frato de via patrino."],[28,3,"Kaj Dio la Plejpotenca benu vin kaj fruktigu vin kaj multigu vin, kaj kreskigu el vi amason da popoloj.","Kaj Dio la Plejpotenca benu vin kaj fruktigu vin kaj multigu vin, kaj kreskigu el vi amason da popoloj."],[28,4,"Kaj Li donu al vi la benon de Abraham, al vi kaj al via idaro kune kun vi, por ke vi heredu la landon de via fremdeloĝado, kiun Dio donis al Abraham.","Kaj Li donu al vi la benon de Abraham, al vi kaj al via idaro kune kun vi, por ke vi heredu la landon de via fremdeloĝado, kiun Dio donis al Abraham."],[28,5,"Kaj Isaak forsendis Jakobon, kaj tiu iris Mezopotamion, al Laban, la filo de Betuel la Siriano, frato de Rebeka, patrino de Jakob kaj Esav.","Kaj Isaak forsendis Jakobon, kaj tiu iris Mezopotamion, al Laban, la filo de Betuel la Siriano, frato de Rebeka, patrino de Jakob kaj Esav."],[28,6,"Kiam Esav vidis, ke Isaak benis Jakobon kaj sendis lin en Mezopotamion, por ke li prenu al si el tie edzinon, kaj ke, benante lin, li ordonis al li, dirante: Ne prenu edzinon el la filinoj Kanaanaj;","Kiam Esav vidis, ke Isaak benis Jakobon kaj sendis lin en Mezopotamion, por ke li prenu al si el tie edzinon, kaj ke, benante lin, li ordonis al li, dirante: Ne prenu edzinon el la filinoj Kanaanaj;"],[28,7,"kaj ke Jakob obeis sian patron kaj sian patrinon kaj iris Mezopotamion:","kaj ke Jakob obeis sian patron kaj sian patrinon kaj iris Mezopotamion:"],[28,8,"tiam Esav vidis, ke ne plaĉas la filinoj Kanaanaj al lia patro Isaak.","tiam Esav vidis, ke ne plaĉas la filinoj Kanaanaj al lia patro Isaak."],[28,9,"Kaj Esav iris al Iŝmael kaj prenis al si Maĥalaton, filinon de Iŝmael, filo de Abraham, fratinon de Nebajot, kiel edzinon krom siaj aliaj edzinoj.","Kaj Esav iris al Iŝmael kaj prenis al si Maĥalaton, filinon de Iŝmael, filo de Abraham, fratinon de Nebajot, kiel edzinon krom siaj aliaj edzinoj."],[28,10,"Kaj Jakob eliris el Beer-Ŝeba kaj iris en la direkto al Ĥaran.","Kaj Jakob eliris el Beer-Ŝeba kaj iris en la direkto al Ĥaran."],[28,11,"Li venis al iu loko kaj restis tie, por pasigi la nokton, ĉar la suno subiris. Kaj li prenis unu el la ŝtonoj de tiu loko kaj metis ĝin sub sian kapon kaj kuŝiĝis en tiu loko.","Li venis al iu loko kaj restis tie, por pasigi la nokton, ĉar la suno subiris. Kaj li prenis unu el la ŝtonoj de tiu loko kaj metis ĝin sub sian kapon kaj kuŝiĝis en tiu loko."],[28,12,"Kaj li sonĝis: jen ŝtuparo staras sur la tero, kaj ĝia supro atingas la ĉielon, kaj jen anĝeloj de Dio iras sur ĝi supren kaj malsupren.","Kaj li sonĝis: jen ŝtuparo staras sur la tero, kaj ĝia supro atingas la ĉielon, kaj jen anĝeloj de Dio iras sur ĝi supren kaj malsupren."],[28,13,"Kaj jen la Eternulo staras sur ĝi, kaj diras: Mi estas la Eternulo, la Dio de via patro Abraham kaj la Dio de Isaak; la teron, sur kiu vi kuŝas, Mi donos al vi kaj al via idaro.","Kaj jen la Eternulo staras sur ĝi, kaj diras: Mi estas la Eternulo, la Dio de via patro Abraham kaj la Dio de Isaak; la teron, sur kiu vi kuŝas, Mi donos al vi kaj al via idaro."],[28,14,"Kaj via idaro estos kiel la polvo de la tero, kaj vi disvastiĝos okcidenten kaj orienten kaj norden kaj suden, kaj beniĝos per vi kaj per via idaro ĉiuj gentoj de la tero.","Kaj via idaro estos kiel la polvo de la tero, kaj vi disvastiĝos okcidenten kaj orienten kaj norden kaj suden, kaj beniĝos per vi kaj per via idaro ĉiuj gentoj de la tero."],[28,15,"Kaj Mi estas kun vi, kaj Mi gardos vin ĉie, kien vi iros, kaj Mi revenigos vin sur ĉi tiun teron; ĉar Mi ne forlasos vin, ĝis Mi estos farinta tion, kion Mi diris al vi.","Kaj Mi estas kun vi, kaj Mi gardos vin ĉie, kien vi iros, kaj Mi revenigos vin sur ĉi tiun teron; ĉar Mi ne forlasos vin, ĝis Mi estos farinta tion, kion Mi diris al vi."],[28,16,"Kaj Jakob vekiĝis el sia dormo, kaj li diris: Vere, la Eternulo estas en ĉi tiu loko, kaj mi ne sciis.","Kaj Jakob vekiĝis el sia dormo, kaj li diris: Vere, la Eternulo estas en ĉi tiu loko, kaj mi ne sciis."],[28,17,"Kaj li ektimis, kaj diris: Kiel timinda estas ĉi tiu loko! ĝi estas nenio alia ol domo de Dio, kaj ĉi tie estas la pordego de la ĉielo.","Kaj li ektimis, kaj diris: Kiel timinda estas ĉi tiu loko! ĝi estas nenio alia ol domo de Dio, kaj ĉi tie estas la pordego de la ĉielo."],[28,18,"Kaj Jakob leviĝis frue matene, kaj prenis la ŝtonon, kiun li estis metinta sub sian kapon, kaj starigis ĝin kiel monumenton, kaj verŝis oleon sur ĝian supron.","Kaj Jakob leviĝis frue matene, kaj prenis la ŝtonon, kiun li estis metinta sub sian kapon, kaj starigis ĝin kiel monumenton, kaj verŝis oleon sur ĝian supron."],[28,19,"Kaj li donis al tiu loko la nomon Bet-El; sed antaŭe la nomo de la urbo estis Luz.","Kaj li donis al tiu loko la nomon Bet-El; sed antaŭe la nomo de la urbo estis Luz."],[28,20,"Kaj Jakob faris sanktan promeson, dirante: Se Dio estos kun mi, kaj gardos min sur ĉi tiu vojo, kiun mi iras, kaj donos al mi panon por manĝi kaj veston por porti sur mi,","Kaj Jakob faris sanktan promeson, dirante: Se Dio estos kun mi, kaj gardos min sur ĉi tiu vojo, kiun mi iras, kaj donos al mi panon por manĝi kaj veston por porti sur mi,"],[28,21,"kaj mi revenos en paco al la domo de mia patro, kaj la Eternulo estos por mi Dio:","kaj mi revenos en paco al la domo de mia patro, kaj la Eternulo estos por mi Dio:"],[28,22,"tiam ĉi tiu ŝtono, kiun mi starigis kiel monumenton, estos domo de Dio, kaj de ĉio, kion Vi donos al mi, mi oferos al Vi dekonon.","tiam ĉi tiu ŝtono, kiun mi starigis kiel monumenton, estos domo de Dio, kaj de ĉio, kion Vi donos al mi, mi oferos al Vi dekonon."],[29,1,"Kaj Jakob levis siajn piedojn kaj iris al la lando de la orientanoj.","Kaj Jakob levis siajn piedojn kaj iris al la lando de la orientanoj."],[29,2,"Kaj li vidis: jen estas puto sur la kampo, kaj tri gregoj da ŝafoj kuŝas apud ĝi; ĉar el tiu puto oni trinkigadis la gregojn; kaj granda ŝtono estis sur la aperturo de la puto.","Kaj li vidis: jen estas puto sur la kampo, kaj tri gregoj da ŝafoj kuŝas apud ĝi; ĉar el tiu puto oni trinkigadis la gregojn; kaj granda ŝtono estis sur la aperturo de la puto."],[29,3,"Kaj kiam tie kunvenis ĉiuj gregoj, tiam oni deruladis la ŝtonon de sur la aperturo kaj trinkigadis la ŝafojn kaj denove remetadis la ŝtonon sur ĝian lokon, sur la aperturon de la puto.","Kaj kiam tie kunvenis ĉiuj gregoj, tiam oni deruladis la ŝtonon de sur la aperturo kaj trinkigadis la ŝafojn kaj denove remetadis la ŝtonon sur ĝian lokon, sur la aperturon de la puto."],[29,4,"Kaj Jakob diris al ili: Fratoj miaj, ke kie vi estas? Kaj ili diris: Ni estas el Ĥaran.","Kaj Jakob diris al ili: Fratoj miaj, ke kie vi estas? Kaj ili diris: Ni estas el Ĥaran."],[29,5,"Kaj li diris al ili: Ĉu vi konas Labanon, filon de Naĥor? Kaj ili diris: Ni konas.","Kaj li diris al ili: Ĉu vi konas Labanon, filon de Naĥor? Kaj ili diris: Ni konas."],[29,6,"Kaj li diris al ili: Ĉu li bone fartas? Kaj ili diris: Li fartas bone, kaj jen lia filino Raĥel venas kun la ŝafoj.","Kaj li diris al ili: Ĉu li bone fartas? Kaj ili diris: Li fartas bone, kaj jen lia filino Raĥel venas kun la ŝafoj."],[29,7,"Kaj li diris: De la tago restas ja ankoraŭ multe, ankoraŭ ne estas la tempo, por kolekti la gregojn; trinkigu la ŝafojn kaj iru, paŝtu.","Kaj li diris: De la tago restas ja ankoraŭ multe, ankoraŭ ne estas la tempo, por kolekti la gregojn; trinkigu la ŝafojn kaj iru, paŝtu."],[29,8,"Kaj ili diris: Ni ne povas, ĝis kolektiĝos ĉiuj gregoj kaj oni derulos la ŝtonon de sur la aperturo de la puto kaj ni trinkigos la ŝafojn.","Kaj ili diris: Ni ne povas, ĝis kolektiĝos ĉiuj gregoj kaj oni derulos la ŝtonon de sur la aperturo de la puto kaj ni trinkigos la ŝafojn."],[29,9,"Dum li ankoraŭ parolis kun ili, venis Raĥel kun la ŝafoj de sia patro, ĉar ŝi paŝtis ilin.","Dum li ankoraŭ parolis kun ili, venis Raĥel kun la ŝafoj de sia patro, ĉar ŝi paŝtis ilin."],[29,10,"Kaj kiam Jakob ekvidis Raĥelon, la filinon de Laban, frato de lia patrino, kaj la ŝafojn de Laban, frato de lia patrino, tiam Jakob alproksimiĝis, derulis la ŝtonon de sur la aperturo de la puto, kaj trinkigis la ŝafojn de Laban, la frato de lia patrino.","Kaj kiam Jakob ekvidis Raĥelon, la filinon de Laban, frato de lia patrino, kaj la ŝafojn de Laban, frato de lia patrino, tiam Jakob alproksimiĝis, derulis la ŝtonon de sur la aperturo de la puto, kaj trinkigis la ŝafojn de Laban, la frato de lia patrino."],[29,11,"Kaj Jakob kisis Raĥelon kaj laŭte ekploris.","Kaj Jakob kisis Raĥelon kaj laŭte ekploris."],[29,12,"Kaj Jakob diris al Raĥel, ke li estas parenco de ŝia patro kaj filo de Rebeka. Kaj ŝi kuris kaj diris al sia patro.","Kaj Jakob diris al Raĥel, ke li estas parenco de ŝia patro kaj filo de Rebeka. Kaj ŝi kuris kaj diris al sia patro."],[29,13,"Kaj kiam Laban aŭdis la sciigon pri Jakob, filo de lia fratino, li kuris al li renkonte kaj ĉirkaŭprenis lin kaj kisis lin kaj venigis lin en sian domon. Kaj tiu rakontis al Laban ĉion.","Kaj kiam Laban aŭdis la sciigon pri Jakob, filo de lia fratino, li kuris al li renkonte kaj ĉirkaŭprenis lin kaj kisis lin kaj venigis lin en sian domon. Kaj tiu rakontis al Laban ĉion."],[29,14,"Kaj Laban diris al li: Vi estas ja mia osto kaj mia karno! Kaj li loĝis ĉe li tutan monaton.","Kaj Laban diris al li: Vi estas ja mia osto kaj mia karno! Kaj li loĝis ĉe li tutan monaton."],[29,15,"Kaj Laban diris al Jakob: Ĉu pro tio, ke vi estas mia parenco, vi devas servi min senpage? diru al mi, kion mi devas pagi al vi?","Kaj Laban diris al Jakob: Ĉu pro tio, ke vi estas mia parenco, vi devas servi min senpage? diru al mi, kion mi devas pagi al vi?"],[29,16,"Sed Laban havis du filinojn; la nomo de la pli maljuna estis Lea, kaj la nomo de la pli juna estis Raĥel.","Sed Laban havis du filinojn; la nomo de la pli maljuna estis Lea, kaj la nomo de la pli juna estis Raĥel."],[29,17,"La okuloj de Lea estis malsanaj, sed Raĥel estis belforma kaj belvizaĝa.","La okuloj de Lea estis malsanaj, sed Raĥel estis belforma kaj belvizaĝa."],[29,18,"Kaj Jakob ekamis Raĥelon, kaj diris: Mi servos vin sep jarojn pro Raĥel, via pli juna filino.","Kaj Jakob ekamis Raĥelon, kaj diris: Mi servos vin sep jarojn pro Raĥel, via pli juna filino."],[29,19,"Tiam Laban diris: Pli bone estas, ke mi donu ŝin al vi, ol ke mi donu ŝin al alia viro; loĝu ĉe mi.","Tiam Laban diris: Pli bone estas, ke mi donu ŝin al vi, ol ke mi donu ŝin al alia viro; loĝu ĉe mi."],[29,20,"Kaj Jakob servis pro Raĥel sep jarojn, kaj ili estis en liaj okuloj kiel kelke da tagoj, ĉar li amis ŝin.","Kaj Jakob servis pro Raĥel sep jarojn, kaj ili estis en liaj okuloj kiel kelke da tagoj, ĉar li amis ŝin."],[29,21,"Kaj Jakob diris al Laban: Donu mian edzinon, ĉar finiĝis mia tempo, kaj mi envenos al ŝi.","Kaj Jakob diris al Laban: Donu mian edzinon, ĉar finiĝis mia tempo, kaj mi envenos al ŝi."],[29,22,"Kaj Laban kunvenigis ĉiujn homojn de tiu loko kaj faris festenon.","Kaj Laban kunvenigis ĉiujn homojn de tiu loko kaj faris festenon."],[29,23,"Sed vespere li prenis sian filinon Lea kaj enirigis ŝin al li; kaj tiu envenis al ŝi.","Sed vespere li prenis sian filinon Lea kaj enirigis ŝin al li; kaj tiu envenis al ŝi."],[29,24,"Kaj Laban donis sian sklavinon Zilpa al Lea kiel sklavinon.","Kaj Laban donis sian sklavinon Zilpa al Lea kiel sklavinon."],[29,25,"Sed matene montriĝis, ke tio estas Lea. Tiam li diris al Laban: Kion do vi faris al mi! ĉu ne pro Raĥel mi servis vin? kial do vi min trompis?","Sed matene montriĝis, ke tio estas Lea. Tiam li diris al Laban: Kion do vi faris al mi! ĉu ne pro Raĥel mi servis vin? kial do vi min trompis?"],[29,26,"Tiam Laban diris: En nia loko ne estas moro, ke oni donu la pli junan antaŭ ol la pli maljunan.","Tiam Laban diris: En nia loko ne estas moro, ke oni donu la pli junan antaŭ ol la pli maljunan."],[29,27,"Pasigu semajnon kun ĉi tiu, tiam mi donos al vi ankaŭ tiun, pro servo, kiun vi servos ĉe mi ankoraŭ aliajn sep jarojn.","Pasigu semajnon kun ĉi tiu, tiam mi donos al vi ankaŭ tiun, pro servo, kiun vi servos ĉe mi ankoraŭ aliajn sep jarojn."],[29,28,"Kaj Jakob faris tiel kaj pasigis semajnon kun ĉi tiu. Kaj Laban donis al li sian filinon Raĥel kiel edzinon.","Kaj Jakob faris tiel kaj pasigis semajnon kun ĉi tiu. Kaj Laban donis al li sian filinon Raĥel kiel edzinon."],[29,29,"Kaj Laban donis al sia filino Raĥel sian sklavinon Bilha kiel sklavinon.","Kaj Laban donis al sia filino Raĥel sian sklavinon Bilha kiel sklavinon."],[29,30,"Kaj Jakob envenis ankaŭ al Raĥel, kaj li amis Raĥelon pli ol Lean, kaj li servis ĉe li ankoraŭ aliajn sep jarojn.","Kaj Jakob envenis ankaŭ al Raĥel, kaj li amis Raĥelon pli ol Lean, kaj li servis ĉe li ankoraŭ aliajn sep jarojn."],[29,31,"Kiam la Eternulo vidis, ke Lea estas malamata, Li malŝlosis ŝian uteron; sed Raĥel estis senfrukta.","Kiam la Eternulo vidis, ke Lea estas malamata, Li malŝlosis ŝian uteron; sed Raĥel estis senfrukta."],[29,32,"Kaj Lea gravediĝis kaj naskis filon, kaj ŝi donis al li la nomon Ruben, ĉar ŝi diris: La Eternulo vidis mian mizeron, kaj nun mia edzo min amos.","Kaj Lea gravediĝis kaj naskis filon, kaj ŝi donis al li la nomon Ruben, ĉar ŝi diris: La Eternulo vidis mian mizeron, kaj nun mia edzo min amos."],[29,33,"Kaj ŝi denove gravediĝis kaj naskis filon. Kaj ŝi diris: La Eternulo aŭdis, ke mi estas malamata, tial Li donis al mi ankaŭ ĉi tiun; kaj ŝi donis al li la nomon Simeon.","Kaj ŝi denove gravediĝis kaj naskis filon. Kaj ŝi diris: La Eternulo aŭdis, ke mi estas malamata, tial Li donis al mi ankaŭ ĉi tiun; kaj ŝi donis al li la nomon Simeon."],[29,34,"Kaj ŝi denove gravediĝis kaj naskis filon. Kaj ŝi diris: La nunan fojon mia edzo aliĝos al mi, ĉar mi naskis al li tri filojn; tial al li estis donita la nomo Levi.","Kaj ŝi denove gravediĝis kaj naskis filon. Kaj ŝi diris: La nunan fojon mia edzo aliĝos al mi, ĉar mi naskis al li tri filojn; tial al li estis donita la nomo Levi."],[29,35,"Kaj ŝi denove gravediĝis kaj naskis filon. Kaj ŝi diris: Nun mi dankos la Eternulon; tial ŝi donis al li la nomon Jehuda. Kaj ŝi ĉesis naski.","Kaj ŝi denove gravediĝis kaj naskis filon. Kaj ŝi diris: Nun mi dankos la Eternulon; tial ŝi donis al li la nomon Jehuda. Kaj ŝi ĉesis naski."],[30,1,"Kiam Raĥel vidis, ke ŝi ne naskas al Jakob, ŝi enviis sian fratinon, kaj ŝi diris al Jakob; Donu al mi infanojn, ĉar alie mi mortos.","Kiam Raĥel vidis, ke ŝi ne naskas al Jakob, ŝi enviis sian fratinon, kaj ŝi diris al Jakob; Donu al mi infanojn, ĉar alie mi mortos."],[30,2,"Kaj Jakob forte ekkoleris Raĥelon, kaj li diris: Ĉu mi anstataŭas Dion, kiu rifuzis al vi frukton de ventro?","Kaj Jakob forte ekkoleris Raĥelon, kaj li diris: Ĉu mi anstataŭas Dion, kiu rifuzis al vi frukton de ventro?"],[30,3,"Kaj ŝi diris: Jen estas mia sklavino Bilha; envenu al ŝi, ke ŝi nasku sur miaj genuoj kaj ke mi ankaŭ ricevu filojn per ŝi.","Kaj ŝi diris: Jen estas mia sklavino Bilha; envenu al ŝi, ke ŝi nasku sur miaj genuoj kaj ke mi ankaŭ ricevu filojn per ŝi."],[30,4,"Kaj ŝi donis al li sian sklavinon Bilha kiel edzinon, kaj Jakob envenis al ŝi.","Kaj ŝi donis al li sian sklavinon Bilha kiel edzinon, kaj Jakob envenis al ŝi."],[30,5,"Kaj Bilha gravediĝis kaj naskis al Jakob filon.","Kaj Bilha gravediĝis kaj naskis al Jakob filon."],[30,6,"Kaj Raĥel diris: Dio min juĝis kaj aŭdis mian voĉon kaj donis al mi filon; tial ŝi donis al li la nomon Dan.","Kaj Raĥel diris: Dio min juĝis kaj aŭdis mian voĉon kaj donis al mi filon; tial ŝi donis al li la nomon Dan."],[30,7,"Kaj Bilha, la sklavino de Raĥel, denove gravediĝis kaj naskis duan filon al Jakob.","Kaj Bilha, la sklavino de Raĥel, denove gravediĝis kaj naskis duan filon al Jakob."],[30,8,"Tiam Raĥel diris: Per Dia lukto mi luktis kun mia fratino, kaj mi venkis; kaj ŝi donis al li la nomon Naftali.","Tiam Raĥel diris: Per Dia lukto mi luktis kun mia fratino, kaj mi venkis; kaj ŝi donis al li la nomon Naftali."],[30,9,"Kiam Lea vidis, ke ŝi ĉesis naski, ŝi prenis sian sklavinon Zilpa kaj donis ŝin al Jakob kiel edzinon.","Kiam Lea vidis, ke ŝi ĉesis naski, ŝi prenis sian sklavinon Zilpa kaj donis ŝin al Jakob kiel edzinon."],[30,10,"Kaj Zilpa, la sklavino de Lea, naskis al Jakob filon.","Kaj Zilpa, la sklavino de Lea, naskis al Jakob filon."],[30,11,"Kaj Lea diris: Venis feliĉo! kaj ŝi donis al li la nomon Gad.","Kaj Lea diris: Venis feliĉo! kaj ŝi donis al li la nomon Gad."],[30,12,"Kaj Zilpa, la sklavino de Lea, naskis duan filon al Jakob.","Kaj Zilpa, la sklavino de Lea, naskis duan filon al Jakob."],[30,13,"Kaj Lea diris: Por mia bono; ĉar la virinoj diros, ke estas al mi bone. Kaj ŝi donis al li la nomon Aŝer.","Kaj Lea diris: Por mia bono; ĉar la virinoj diros, ke estas al mi bone. Kaj ŝi donis al li la nomon Aŝer."],[30,14,"Ruben iris en la tempo de rikoltado de tritiko kaj trovis mandragorojn sur la kampo, kaj li alportis ilin al sia patrino Lea. Kaj Raĥel diris al Lea: Donu al mi el la mandragoroj de via filo.","Ruben iris en la tempo de rikoltado de tritiko kaj trovis mandragorojn sur la kampo, kaj li alportis ilin al sia patrino Lea. Kaj Raĥel diris al Lea: Donu al mi el la mandragoroj de via filo."],[30,15,"Sed tiu diris al ŝi: Ĉu ne sufiĉas al vi, ke vi prenis mian edzon, kaj vi volas preni ankaŭ la mandragorojn de mia filo? Tiam Raĥel diris: Nu, li kuŝu kun vi ĉi tiun nokton por la mandragoroj de via filo.","Sed tiu diris al ŝi: Ĉu ne sufiĉas al vi, ke vi prenis mian edzon, kaj vi volas preni ankaŭ la mandragorojn de mia filo? Tiam Raĥel diris: Nu, li kuŝu kun vi ĉi tiun nokton por la mandragoroj de via filo."],[30,16,"Kiam Jakob venis de la kampo vespere, Lea eliris al li renkonte, kaj diris: Al mi venu, ĉar mi aĉetis vin per la mandragoroj de mia filo. Kaj li kuŝis kun ŝi en tiu nokto.","Kiam Jakob venis de la kampo vespere, Lea eliris al li renkonte, kaj diris: Al mi venu, ĉar mi aĉetis vin per la mandragoroj de mia filo. Kaj li kuŝis kun ŝi en tiu nokto."],[30,17,"Kaj Dio aŭdis Lean, kaj ŝi gravediĝis kaj naskis al Jakob kvinan filon.","Kaj Dio aŭdis Lean, kaj ŝi gravediĝis kaj naskis al Jakob kvinan filon."],[30,18,"Kaj Lea diris: Dio donis al mi rekompencon por tio, ke mi donis mian sklavinon al mia edzo; kaj ŝi donis al li la nomon Isaĥar.","Kaj Lea diris: Dio donis al mi rekompencon por tio, ke mi donis mian sklavinon al mia edzo; kaj ŝi donis al li la nomon Isaĥar."],[30,19,"Kaj Lea denove gravediĝis kaj naskis sesan filon al Jakob.","Kaj Lea denove gravediĝis kaj naskis sesan filon al Jakob."],[30,20,"Kaj Lea diris: Havigis al mi Dio bonan havon; nun mia edzo loĝos ĉe mi, ĉar mi naskis al li ses filojn. Kaj ŝi donis al li la nomon Zebulun.","Kaj Lea diris: Havigis al mi Dio bonan havon; nun mia edzo loĝos ĉe mi, ĉar mi naskis al li ses filojn. Kaj ŝi donis al li la nomon Zebulun."],[30,21,"Kaj poste ŝi naskis filinon, kaj ŝi donis al ŝi la nomon Dina.","Kaj poste ŝi naskis filinon, kaj ŝi donis al ŝi la nomon Dina."],[30,22,"Kaj Dio rememoris Raĥelon, kaj Dio elaŭdis ŝin kaj malŝlosis ŝian uteron.","Kaj Dio rememoris Raĥelon, kaj Dio elaŭdis ŝin kaj malŝlosis ŝian uteron."],[30,23,"Kaj ŝi gravediĝis kaj naskis filon. Kaj ŝi diris: Dio forprenis mian malhonoron.","Kaj ŝi gravediĝis kaj naskis filon. Kaj ŝi diris: Dio forprenis mian malhonoron."],[30,24,"Kaj ŝi donis al li la nomon Jozef, dirante: La Eternulo aldonos al mi alian filon.","Kaj ŝi donis al li la nomon Jozef, dirante: La Eternulo aldonos al mi alian filon."],[30,25,"Kiam Raĥel naskis Jozefon, Jakob diris al Laban: Forliberigu min, kaj mi iros al mia loko kaj al mia lando.","Kiam Raĥel naskis Jozefon, Jakob diris al Laban: Forliberigu min, kaj mi iros al mia loko kaj al mia lando."],[30,26,"Donu miajn edzinojn kaj miajn infanojn, pro kiuj mi servis vin, kaj mi iros; ĉar vi konas la servon, per kiu mi vin servis.","Donu miajn edzinojn kaj miajn infanojn, pro kiuj mi servis vin, kaj mi iros; ĉar vi konas la servon, per kiu mi vin servis."],[30,27,"Kaj Laban diris al li: Ho, se mi povus akiri vian favoron! mi spertis, ke la Eternulo benis min pro vi.","Kaj Laban diris al li: Ho, se mi povus akiri vian favoron! mi spertis, ke la Eternulo benis min pro vi."],[30,28,"Kaj li diris: Difinu, kian rekompencon mi ŝuldas al vi, kaj mi donos.","Kaj li diris: Difinu, kian rekompencon mi ŝuldas al vi, kaj mi donos."],[30,29,"Kaj tiu diris al li: Vi scias, kiel mi servis vin kaj kia fariĝis via brutaro ĉe mi;","Kaj tiu diris al li: Vi scias, kiel mi servis vin kaj kia fariĝis via brutaro ĉe mi;"],[30,30,"ĉar malmulte vi havis antaŭ mi, sed nun ĝi multe vastiĝis; kaj la Eternulo benis vin post mia veno; kaj nun kiam mi laboros ankaŭ por mia domo?","ĉar malmulte vi havis antaŭ mi, sed nun ĝi multe vastiĝis; kaj la Eternulo benis vin post mia veno; kaj nun kiam mi laboros ankaŭ por mia domo?"],[30,31,"Kaj Laban diris: Kion mi donu al vi? Kaj Jakob diris: Donu al mi nenion; sed se vi faros al mi jenon, tiam mi denove paŝtos kaj gardos viajn ŝafojn:","Kaj Laban diris: Kion mi donu al vi? Kaj Jakob diris: Donu al mi nenion; sed se vi faros al mi jenon, tiam mi denove paŝtos kaj gardos viajn ŝafojn:"],[30,32,"mi pasos hodiaŭ tra via tuta ŝafaro; apartigu el ĝi ĉiun ŝafon mikskoloran kaj makulitan kaj ĉiun bruton nigran inter la ŝafoj, kaj makulitan kaj mikskoloran inter la kaproj; kaj ili estu mia rekompenco.","mi pasos hodiaŭ tra via tuta ŝafaro; apartigu el ĝi ĉiun ŝafon mikskoloran kaj makulitan kaj ĉiun bruton nigran inter la ŝafoj, kaj makulitan kaj mikskoloran inter la kaproj; kaj ili estu mia rekompenco."],[30,33,"Kaj respondos por mi mia justeco en la morgaŭa tago, kiam vi venos vidi mian rekompencon; ĉiu el la kaproj, kiu ne estos mikskolora aŭ makulita, kaj ĉiu el la ŝafoj, kiu ne estos nigra, estu rigardata kiel ŝtelita de mi.","Kaj respondos por mi mia justeco en la morgaŭa tago, kiam vi venos vidi mian rekompencon; ĉiu el la kaproj, kiu ne estos mikskolora aŭ makulita, kaj ĉiu el la ŝafoj, kiu ne estos nigra, estu rigardata kiel ŝtelita de mi."],[30,34,"Kaj Laban diris: Ĝi estu, kiel vi diris.","Kaj Laban diris: Ĝi estu, kiel vi diris."],[30,35,"Kaj li apartigis en tiu tago la virkaprojn striitajn kaj makulitajn kaj ĉiujn kaprinojn mikskolorajn kaj makulitajn, ĉiujn, kiuj havis sur si iom da blankaĵo, kaj ĉiujn nigrajn ŝafojn; kaj li transdonis ilin en la manojn de siaj filoj.","Kaj li apartigis en tiu tago la virkaprojn striitajn kaj makulitajn kaj ĉiujn kaprinojn mikskolorajn kaj makulitajn, ĉiujn, kiuj havis sur si iom da blankaĵo, kaj ĉiujn nigrajn ŝafojn; kaj li transdonis ilin en la manojn de siaj filoj."],[30,36,"Kaj li faris interspacon de tritaga irado inter si kaj Jakob. Kaj Jakob paŝtis la restintajn ŝafojn de Laban.","Kaj li faris interspacon de tritaga irado inter si kaj Jakob. Kaj Jakob paŝtis la restintajn ŝafojn de Laban."],[30,37,"Kaj Jakob prenis al si bastonojn el verdaj poploj, migdalarboj, kaj platanarboj, kaj senŝeligis sur ili blankajn striojn tiamaniere, ke la blankaĵo sur la bastonoj elmontriĝis.","Kaj Jakob prenis al si bastonojn el verdaj poploj, migdalarboj, kaj platanarboj, kaj senŝeligis sur ili blankajn striojn tiamaniere, ke la blankaĵo sur la bastonoj elmontriĝis."],[30,38,"Kaj li metis la skrapitajn bastonojn antaŭ la ŝafoj en la akvotrinkigajn kanalojn, al kiuj la ŝafoj venadis por trinki, kaj ili gravediĝadis, kiam ili venadis trinki.","Kaj li metis la skrapitajn bastonojn antaŭ la ŝafoj en la akvotrinkigajn kanalojn, al kiuj la ŝafoj venadis por trinki, kaj ili gravediĝadis, kiam ili venadis trinki."],[30,39,"Kaj la ŝafoj gravediĝis super la bastonoj, kaj ili naskis ŝafidojn striitajn, mikskolorajn, kaj makulitajn.","Kaj la ŝafoj gravediĝis super la bastonoj, kaj ili naskis ŝafidojn striitajn, mikskolorajn, kaj makulitajn."],[30,40,"Kaj la ŝafidojn Jakob apartigis, kaj li turnis la vizaĝojn de la brutoj kontraŭ la striitajn kaj kontraŭ la nigrajn brutojn de Laban; sed siajn brutarojn li apartigis kaj ne almiksis ilin al la brutoj de Laban.","Kaj la ŝafidojn Jakob apartigis, kaj li turnis la vizaĝojn de la brutoj kontraŭ la striitajn kaj kontraŭ la nigrajn brutojn de Laban; sed siajn brutarojn li apartigis kaj ne almiksis ilin al la brutoj de Laban."],[30,41,"Ĉiufoje, kiam pasiiĝis brutoj fortaj, Jakob metis la bastonojn en la kanalojn antaŭ la okuloj de la brutoj, por ke ili pasiiĝu antaŭ la bastonoj;","Ĉiufoje, kiam pasiiĝis brutoj fortaj, Jakob metis la bastonojn en la kanalojn antaŭ la okuloj de la brutoj, por ke ili pasiiĝu antaŭ la bastonoj;"],[30,42,"sed kiam la brutoj estis malfortaj, li ne metis. Tiamaniere la malfortaj fariĝis apartenaĵo de Laban, kaj la fortaj fariĝis apartenaĵo de Jakob.","sed kiam la brutoj estis malfortaj, li ne metis. Tiamaniere la malfortaj fariĝis apartenaĵo de Laban, kaj la fortaj fariĝis apartenaĵo de Jakob."],[30,43,"Kaj tiu homo fariĝis eksterordinare riĉa, kaj li havis multe da brutoj kaj sklavinojn kaj sklavojn kaj kamelojn kaj azenojn.","Kaj tiu homo fariĝis eksterordinare riĉa, kaj li havis multe da brutoj kaj sklavinojn kaj sklavojn kaj kamelojn kaj azenojn."],[31,1,"Li aŭdis, ke la filoj de Laban parolis jene: Jakob forprenis la tutan havon de nia patro, kaj el la havo de nia patro li akiris la tutan riĉecon.","Li aŭdis, ke la filoj de Laban parolis jene: Jakob forprenis la tutan havon de nia patro, kaj el la havo de nia patro li akiris la tutan riĉecon."],[31,2,"Kaj Jakob vidis laŭ la vizaĝo de Laban, ke li ne estas rilate al li tia, kia li estis hieraŭ kaj antaŭhieraŭ.","Kaj Jakob vidis laŭ la vizaĝo de Laban, ke li ne estas rilate al li tia, kia li estis hieraŭ kaj antaŭhieraŭ."],[31,3,"Kaj la Eternulo diris al Jakob: Reiru en la landon de viaj patroj kaj en vian naskiĝlandon, kaj Mi estos kun vi.","Kaj la Eternulo diris al Jakob: Reiru en la landon de viaj patroj kaj en vian naskiĝlandon, kaj Mi estos kun vi."],[31,4,"Tiam Jakob sendis kaj vokis Raĥelon kaj Lean sur la kampon al sia brutaro;","Tiam Jakob sendis kaj vokis Raĥelon kaj Lean sur la kampon al sia brutaro;"],[31,5,"kaj li diris al ili: Mi vidas laŭ la vizaĝo de via patro, ke li ne estas rilate al mi tia, kia li estis hieraŭ kaj antaŭhieraŭ; sed la Dio de mia patro estis kun mi.","kaj li diris al ili: Mi vidas laŭ la vizaĝo de via patro, ke li ne estas rilate al mi tia, kia li estis hieraŭ kaj antaŭhieraŭ; sed la Dio de mia patro estis kun mi."],[31,6,"Vi scias, ke per ĉiuj miaj fortoj mi servis vian patron.","Vi scias, ke per ĉiuj miaj fortoj mi servis vian patron."],[31,7,"Sed via patro trompis min kaj dekfoje ŝanĝis mian laborpagon; tamen Dio ne lasis lin fari al mi malbonon.","Sed via patro trompis min kaj dekfoje ŝanĝis mian laborpagon; tamen Dio ne lasis lin fari al mi malbonon."],[31,8,"Kiam li diris: Mikskoloraj estu via rekompenco — ĉiuj brutoj naskis idojn mikskolorajn; kaj kiam li diris: Striitaj estu via rekompenco — ĉiuj brutoj naskis striitajn.","Kiam li diris: Mikskoloraj estu via rekompenco — ĉiuj brutoj naskis idojn mikskolorajn; kaj kiam li diris: Striitaj estu via rekompenco — ĉiuj brutoj naskis striitajn."],[31,9,"Tiamaniere Dio forprenis la brutojn de via patro kaj donis al mi.","Tiamaniere Dio forprenis la brutojn de via patro kaj donis al mi."],[31,10,"En la tempo, kiam la brutoj pasiiĝis, mi levis miajn okulojn kaj vidis en sonĝo, ke la virbestoj, kiuj leviĝis sur la brutojn, estas striitaj, mikskoloraj, kaj makulitaj.","En la tempo, kiam la brutoj pasiiĝis, mi levis miajn okulojn kaj vidis en sonĝo, ke la virbestoj, kiuj leviĝis sur la brutojn, estas striitaj, mikskoloraj, kaj makulitaj."],[31,11,"Kaj anĝelo de Dio diris al mi en la sonĝo: Jakob! kaj mi diris: Jen mi estas.","Kaj anĝelo de Dio diris al mi en la sonĝo: Jakob! kaj mi diris: Jen mi estas."],[31,12,"Kaj li diris: Levu viajn okulojn kaj vidu: ĉiuj virbestoj, kiuj leviĝis sur la brutojn, estas striitaj, mikskoloraj, kaj makulitaj, ĉar Mi vidis ĉion, kion Laban faras al vi.","Kaj li diris: Levu viajn okulojn kaj vidu: ĉiuj virbestoj, kiuj leviĝis sur la brutojn, estas striitaj, mikskoloraj, kaj makulitaj, ĉar Mi vidis ĉion, kion Laban faras al vi."],[31,13,"Mi estas la Dio el Bet-El, kie vi verŝis oleon sur la monumenton kaj kie vi faris sanktan promeson al Mi. Nun leviĝu, eliru el ĉi tiu lando kaj reiru en la landon de via naskiĝo.","Mi estas la Dio el Bet-El, kie vi verŝis oleon sur la monumenton kaj kie vi faris sanktan promeson al Mi. Nun leviĝu, eliru el ĉi tiu lando kaj reiru en la landon de via naskiĝo."],[31,14,"Kaj Raĥel kaj Lea respondis kaj diris al li: Ĉu ni havas ankoraŭ parton kaj heredon en la domo de nia patro?","Kaj Raĥel kaj Lea respondis kaj diris al li: Ĉu ni havas ankoraŭ parton kaj heredon en la domo de nia patro?"],[31,15,"Li rigardas ja nin kiel fremdulinojn; ĉar li vendis nin kaj eĉ formanĝis nian monon.","Li rigardas ja nin kiel fremdulinojn; ĉar li vendis nin kaj eĉ formanĝis nian monon."],[31,16,"Ĉar la tuta riĉo, kiun Dio forprenis de nia patro, apartenas al ni kaj al niaj infanoj. Kaj nun ĉion, kion Dio al vi diris, faru.","Ĉar la tuta riĉo, kiun Dio forprenis de nia patro, apartenas al ni kaj al niaj infanoj. Kaj nun ĉion, kion Dio al vi diris, faru."],[31,17,"Jakob leviĝis, kaj metis siajn infanojn kaj siajn edzinojn sur la kamelojn.","Jakob leviĝis, kaj metis siajn infanojn kaj siajn edzinojn sur la kamelojn."],[31,18,"Kaj li forkondukis sian tutan brutaron kaj sian tutan havon, kiun li akiris, sian propraĵon, kiun li akiris en Mezopotamio, por iri al sia patro Isaak en la landon Kanaanan.","Kaj li forkondukis sian tutan brutaron kaj sian tutan havon, kiun li akiris, sian propraĵon, kiun li akiris en Mezopotamio, por iri al sia patro Isaak en la landon Kanaanan."],[31,19,"Laban estis foririnta, por tondi siajn ŝafojn; tiam Raĥel ŝtelis la domajn diojn de sia patro.","Laban estis foririnta, por tondi siajn ŝafojn; tiam Raĥel ŝtelis la domajn diojn de sia patro."],[31,20,"Jakob trompis la atenton de Laban la Siriano, ne dirante al li, ke li forkuras.","Jakob trompis la atenton de Laban la Siriano, ne dirante al li, ke li forkuras."],[31,21,"Kaj li rapide foriris kune kun ĉio, kion li havis. Kaj li transpasis la Riveron kaj direktiĝis al la monto Gilead.","Kaj li rapide foriris kune kun ĉio, kion li havis. Kaj li transpasis la Riveron kaj direktiĝis al la monto Gilead."],[31,22,"Oni diris al Laban en la tria tago, ke Jakob forkuris.","Oni diris al Laban en la tria tago, ke Jakob forkuris."],[31,23,"Tiam li prenis kun si siajn fratojn, kaj kuris post li distancon de sep tagoj kaj kuratingis lin sur la monto Gilead.","Tiam li prenis kun si siajn fratojn, kaj kuris post li distancon de sep tagoj kaj kuratingis lin sur la monto Gilead."],[31,24,"Tiam Dio aperis al Laban la Siriano nokte en la sonĝo, kaj diris al li: Gardu vin, ke vi ne parolu kun Jakob bone nek malbone.","Tiam Dio aperis al Laban la Siriano nokte en la sonĝo, kaj diris al li: Gardu vin, ke vi ne parolu kun Jakob bone nek malbone."],[31,25,"Laban kuratingis Jakobon. Jakob starigis sian tendon sur la monto, kaj Laban aranĝis siajn fratojn ankaŭ sur la monto Gilead.","Laban kuratingis Jakobon. Jakob starigis sian tendon sur la monto, kaj Laban aranĝis siajn fratojn ankaŭ sur la monto Gilead."],[31,26,"Kaj Laban diris al Jakob: Kion vi faris? vi trompis min kaj forkondukis miajn filinojn kvazaŭ militkaptitojn!","Kaj Laban diris al Jakob: Kion vi faris? vi trompis min kaj forkondukis miajn filinojn kvazaŭ militkaptitojn!"],[31,27,"Kial vi forkuris sekrete kaj kaŝe de mi, kaj ne diris al mi? Mi foririgus vin en gajeco kaj kun kantoj, kun tamburino kaj harpo.","Kial vi forkuris sekrete kaj kaŝe de mi, kaj ne diris al mi? Mi foririgus vin en gajeco kaj kun kantoj, kun tamburino kaj harpo."],[31,28,"Vi eĉ ne lasis min kisi miajn infanojn kaj filinojn! malsaĝe vi agis.","Vi eĉ ne lasis min kisi miajn infanojn kaj filinojn! malsaĝe vi agis."],[31,29,"Mi havas forton en mia mano, por fari al vi malbonon; sed la Dio de via patro hieraŭ diris al mi jene: Gardu vin, ke vi ne parolu kun Jakob bone aŭ malbone.","Mi havas forton en mia mano, por fari al vi malbonon; sed la Dio de via patro hieraŭ diris al mi jene: Gardu vin, ke vi ne parolu kun Jakob bone aŭ malbone."],[31,30,"Kaj se vi nun foriris, ĉar vi forte deziris esti en la domo de via patro, kial do vi ŝtelis miajn diojn?","Kaj se vi nun foriris, ĉar vi forte deziris esti en la domo de via patro, kial do vi ŝtelis miajn diojn?"],[31,31,"Tiam Jakob respondis kaj diris al Laban: Mi timis; mi pensis, ke eble vi forrabos de mi viajn filinojn.","Tiam Jakob respondis kaj diris al Laban: Mi timis; mi pensis, ke eble vi forrabos de mi viajn filinojn."],[31,32,"Sed tiu, ĉe kiu vi trovos viajn diojn, mortu. En la ĉeesto de niaj parencoj serĉu ĉe mi tion, kio estas via, kaj prenu al vi. Jakob ne sciis, ke Raĥel ilin ŝtelis.","Sed tiu, ĉe kiu vi trovos viajn diojn, mortu. En la ĉeesto de niaj parencoj serĉu ĉe mi tion, kio estas via, kaj prenu al vi. Jakob ne sciis, ke Raĥel ilin ŝtelis."],[31,33,"Tiam Laban eniris en la tendon de Jakob kaj en la tendon de Lea kaj en la tendon de la du sklavinoj, kaj li ne trovis. Kaj li eliris el la tendo de Lea kaj eniris en la tendon de Raĥel.","Tiam Laban eniris en la tendon de Jakob kaj en la tendon de Lea kaj en la tendon de la du sklavinoj, kaj li ne trovis. Kaj li eliris el la tendo de Lea kaj eniris en la tendon de Raĥel."],[31,34,"Sed Raĥel prenis la domajn diojn kaj metis ilin sub la selon de la kamelo kaj sidiĝis sur ili. Kaj Laban palpe esploris la tutan tendon kaj ne trovis.","Sed Raĥel prenis la domajn diojn kaj metis ilin sub la selon de la kamelo kaj sidiĝis sur ili. Kaj Laban palpe esploris la tutan tendon kaj ne trovis."],[31,35,"Kaj ŝi diris al sia patro: Mia sinjoro ne koleru, ke mi ne povas stariĝi antaŭ vi, ĉar mi havas la virinan ordinaraĵon. Kaj li serĉis kaj ne trovis la domajn diojn.","Kaj ŝi diris al sia patro: Mia sinjoro ne koleru, ke mi ne povas stariĝi antaŭ vi, ĉar mi havas la virinan ordinaraĵon. Kaj li serĉis kaj ne trovis la domajn diojn."],[31,36,"Kaj Jakob ekkoleris kaj disputis kun Laban. Kaj Jakob diris al Laban: Kia estas mia kulpo, kia estas mia peko, ke vi persekutas min?","Kaj Jakob ekkoleris kaj disputis kun Laban. Kaj Jakob diris al Laban: Kia estas mia kulpo, kia estas mia peko, ke vi persekutas min?"],[31,37,"Vi trapalpis ĉiujn miajn apartenaĵojn; kion vi trovis el la apartenaĵoj de via domo? elmetu ĉi tie antaŭ miaj parencoj kaj viaj, kaj ili juĝu inter ni ambaŭ.","Vi trapalpis ĉiujn miajn apartenaĵojn; kion vi trovis el la apartenaĵoj de via domo? elmetu ĉi tie antaŭ miaj parencoj kaj viaj, kaj ili juĝu inter ni ambaŭ."],[31,38,"Jam dudek jarojn mi estas ĉe vi; viaj ŝafoj kaj kaproj ne estis seninfanaj; la virŝafojn el via brutaro mi ne manĝis;","Jam dudek jarojn mi estas ĉe vi; viaj ŝafoj kaj kaproj ne estis seninfanaj; la virŝafojn el via brutaro mi ne manĝis;"],[31,39,"kion sovaĝaj bestoj disŝiris, tion mi ne alportis al vi: ĝi estis mia malprofito; de mi vi postulis ĉion, kio estis ŝtelita en tago aŭ ŝtelita en nokto;","kion sovaĝaj bestoj disŝiris, tion mi ne alportis al vi: ĝi estis mia malprofito; de mi vi postulis ĉion, kio estis ŝtelita en tago aŭ ŝtelita en nokto;"],[31,40,"dum la tago min konsumis la varmego, kaj dum la nokto la malvarmo; kaj dormo kuris for de miaj okuloj.","dum la tago min konsumis la varmego, kaj dum la nokto la malvarmo; kaj dormo kuris for de miaj okuloj."],[31,41,"Tiaj estis la dudek jaroj, dum kiuj mi servis vin en via domo, dek kvar jarojn pro viaj du filinoj kaj ses jarojn pro viaj brutoj; kaj vi ŝanĝis mian laborpagon dekfoje.","Tiaj estis la dudek jaroj, dum kiuj mi servis vin en via domo, dek kvar jarojn pro viaj du filinoj kaj ses jarojn pro viaj brutoj; kaj vi ŝanĝis mian laborpagon dekfoje."],[31,42,"Se ne estus kun mi la Dio de mia patro, la Dio de Abraham kaj Timo de Isaak, vi nun foririgus min kun nenio. Mian mizeron kaj la laboron de miaj manoj vidis Dio kaj ĝustigis vin hieraŭ.","Se ne estus kun mi la Dio de mia patro, la Dio de Abraham kaj Timo de Isaak, vi nun foririgus min kun nenio. Mian mizeron kaj la laboron de miaj manoj vidis Dio kaj ĝustigis vin hieraŭ."],[31,43,"Tiam Laban respondis kaj diris al Jakob: La filinoj estas miaj filinoj, kaj la infanoj estas miaj infanoj, kaj la brutoj estas miaj brutoj, kaj ĉio, kion vi vidas, estas mia; sed kion mi povas fari hodiaŭ al miaj filinoj, kaj al iliaj infanoj, kiujn ili naskis?","Tiam Laban respondis kaj diris al Jakob: La filinoj estas miaj filinoj, kaj la infanoj estas miaj infanoj, kaj la brutoj estas miaj brutoj, kaj ĉio, kion vi vidas, estas mia; sed kion mi povas fari hodiaŭ al miaj filinoj, kaj al iliaj infanoj, kiujn ili naskis?"],[31,44,"Nun ni faru interligon, mi kaj vi, kaj ĝi estu atesto inter mi kaj vi.","Nun ni faru interligon, mi kaj vi, kaj ĝi estu atesto inter mi kaj vi."],[31,45,"Tiam Jakob prenis ŝtonon kaj starigis ĝin kiel memorsignon.","Tiam Jakob prenis ŝtonon kaj starigis ĝin kiel memorsignon."],[31,46,"Kaj Jakob diris al siaj parencoj: Kolektu ŝtonojn. Kaj ili prenis ŝtonojn kaj faris monteton; kaj ili manĝis tie sur la monteto.","Kaj Jakob diris al siaj parencoj: Kolektu ŝtonojn. Kaj ili prenis ŝtonojn kaj faris monteton; kaj ili manĝis tie sur la monteto."],[31,47,"Kaj Laban donis al ĝi la nomon Jegar-Sahaduta, sed Jakob donis al ĝi la nomon Galeed.","Kaj Laban donis al ĝi la nomon Jegar-Sahaduta, sed Jakob donis al ĝi la nomon Galeed."],[31,48,"Laban diris: Ĉi tiu monteto estu nun atesto inter mi kaj vi; tial ĝi ricevis la nomon Galeed;","Laban diris: Ĉi tiu monteto estu nun atesto inter mi kaj vi; tial ĝi ricevis la nomon Galeed;"],[31,49,"ankaŭ la nomon Micpa; ĉar li diris: Dio observu inter mi kaj vi, kiam ni malaperos unu de la alia.","ankaŭ la nomon Micpa; ĉar li diris: Dio observu inter mi kaj vi, kiam ni malaperos unu de la alia."],[31,50,"Se vi agos malbone kontraŭ miaj filinoj kaj se vi prenos aliajn edzinojn krom miaj filinoj, tiam, se neniu estos ĉe ni, vidu, ke Dio estas atestanto inter mi kaj vi.","Se vi agos malbone kontraŭ miaj filinoj kaj se vi prenos aliajn edzinojn krom miaj filinoj, tiam, se neniu estos ĉe ni, vidu, ke Dio estas atestanto inter mi kaj vi."],[31,51,"Kaj Laban diris al Jakob: Jen estas ĉi tiu monteto, kaj jen estas la memorsigno, kiun mi starigis inter mi kaj vi;","Kaj Laban diris al Jakob: Jen estas ĉi tiu monteto, kaj jen estas la memorsigno, kiun mi starigis inter mi kaj vi;"],[31,52,"atesto estu ĉi tiu monteto, kaj atesto estu la memorsigno, ke mi ne transiros al vi trans ĉi tiun monteton kaj vi ne transiros al mi trans ĉi tiun monteton kaj trans la memorsignon por malbono.","atesto estu ĉi tiu monteto, kaj atesto estu la memorsigno, ke mi ne transiros al vi trans ĉi tiun monteton kaj vi ne transiros al mi trans ĉi tiun monteton kaj trans la memorsignon por malbono."],[31,53,"La Dio de Abraham kaj la Dio de Naĥor juĝu inter ni, la Dio de ilia patro. Kaj Jakob ĵuris al li per la Timo de sia patro Isaak.","La Dio de Abraham kaj la Dio de Naĥor juĝu inter ni, la Dio de ilia patro. Kaj Jakob ĵuris al li per la Timo de sia patro Isaak."],[31,54,"Kaj Jakob oferbuĉis oferon sur la monto, kaj li invitis siajn parencojn manĝi panon; kaj ili manĝis panon kaj tradormis la nokton sur la monto.","Kaj Jakob oferbuĉis oferon sur la monto, kaj li invitis siajn parencojn manĝi panon; kaj ili manĝis panon kaj tradormis la nokton sur la monto."],[31,55,"Laban leviĝis frue matene kaj kisis siajn infanojn kaj siajn filinojn kaj benis ilin, kaj foriris; kaj Laban reiris al sia loko.","Laban leviĝis frue matene kaj kisis siajn infanojn kaj siajn filinojn kaj benis ilin, kaj foriris; kaj Laban reiris al sia loko."],[32,1,"Kaj Jakob iris sian vojon. Kaj renkontiĝis kun li anĝeloj de Dio.","Kaj Jakob iris sian vojon. Kaj renkontiĝis kun li anĝeloj de Dio."],[32,2,"Kaj Jakob diris, kiam li ilin vidis: Tio estas militistaro de Dio; kaj li donis al tiu loko la nomon Maĥanaim.","Kaj Jakob diris, kiam li ilin vidis: Tio estas militistaro de Dio; kaj li donis al tiu loko la nomon Maĥanaim."],[32,3,"Jakob sendis antaŭ si senditojn al sia frato Esav, en la landon Seir, en la regionon de Edom.","Jakob sendis antaŭ si senditojn al sia frato Esav, en la landon Seir, en la regionon de Edom."],[32,4,"Kaj li ordonis al ili jene: Tiele diru al mia sinjoro Esav: Jen kion diris via sklavo Jakob: Mi loĝis ĉe Laban kaj restis tie ĝis nun.","Kaj li ordonis al ili jene: Tiele diru al mia sinjoro Esav: Jen kion diris via sklavo Jakob: Mi loĝis ĉe Laban kaj restis tie ĝis nun."],[32,5,"Mi havas bovojn kaj azenojn, ŝafojn kaj sklavojn kaj sklavinojn; kaj mi sendas, por sciigi mian sinjoron, por ke mi akiru vian favoron.","Mi havas bovojn kaj azenojn, ŝafojn kaj sklavojn kaj sklavinojn; kaj mi sendas, por sciigi mian sinjoron, por ke mi akiru vian favoron."],[32,6,"Kaj la senditoj revenis al Jakob, kaj diris: Ni venis al via frato Esav; li iras renkonte al vi, kaj kvarcent homoj iras kune kun li.","Kaj la senditoj revenis al Jakob, kaj diris: Ni venis al via frato Esav; li iras renkonte al vi, kaj kvarcent homoj iras kune kun li."],[32,7,"Tiam Jakob tre ektimis kaj afliktiĝis. Kaj li dividis la homojn, kiuj estis kun li, kaj la ŝafojn kaj la bovojn kaj la kamelojn, en du taĉmentojn;","Tiam Jakob tre ektimis kaj afliktiĝis. Kaj li dividis la homojn, kiuj estis kun li, kaj la ŝafojn kaj la bovojn kaj la kamelojn, en du taĉmentojn;"],[32,8,"kaj li diris: Se Esav venos al unu taĉmento kaj venkobatos ĝin, tiam la restinta taĉmento sin savos.","kaj li diris: Se Esav venos al unu taĉmento kaj venkobatos ĝin, tiam la restinta taĉmento sin savos."],[32,9,"Kaj Jakob diris: Dio de mia patro Abraham kaj Dio de mia patro Isaak, Eternulo, kiu diris al mi: Reiru en vian landon kaj en vian naskiĝlokon, kaj Mi faros al vi bonon;","Kaj Jakob diris: Dio de mia patro Abraham kaj Dio de mia patro Isaak, Eternulo, kiu diris al mi: Reiru en vian landon kaj en vian naskiĝlokon, kaj Mi faros al vi bonon;"],[32,10,"mi estas tro malgranda por ĉiuj favorkoraĵoj kaj por la tuta bonaĵo, kiun Vi faris al Via sklavo; ĉar kun mia bastono mi transiris ĉi tiun Jordanon, kaj nun mi havas du taĉmentojn.","mi estas tro malgranda por ĉiuj favorkoraĵoj kaj por la tuta bonaĵo, kiun Vi faris al Via sklavo; ĉar kun mia bastono mi transiris ĉi tiun Jordanon, kaj nun mi havas du taĉmentojn."],[32,11,"Savu min de la mano de mia frato, de la mano de Esav; ĉar mi timas lin, ke li eble venos kaj mortigos ĉe mi patrinon kun la infanoj.","Savu min de la mano de mia frato, de la mano de Esav; ĉar mi timas lin, ke li eble venos kaj mortigos ĉe mi patrinon kun la infanoj."],[32,12,"Vi diris ja: Mi faros al vi bonon, kaj Mi faros vian idaron tia, kia estas la apudmara sablo, kiun oni ne povas kalkuli pro multegeco.","Vi diris ja: Mi faros al vi bonon, kaj Mi faros vian idaron tia, kia estas la apudmara sablo, kiun oni ne povas kalkuli pro multegeco."],[32,13,"Kaj li pasigis tie la nokton. Kaj li prenis el tio, kion li havis sub la mano, donacon por sia frato Esav:","Kaj li pasigis tie la nokton. Kaj li prenis el tio, kion li havis sub la mano, donacon por sia frato Esav:"],[32,14,"ducent kaprinojn kaj dudek virkaprojn, ducent ŝafinojn kaj dudek virŝafojn,","ducent kaprinojn kaj dudek virkaprojn, ducent ŝafinojn kaj dudek virŝafojn,"],[32,15,"tridek mamnutrantajn kamelojn kun iliaj idoj, kvardek bovinojn kaj dek virbovojn, dudek azeninojn kaj dek azenidojn.","tridek mamnutrantajn kamelojn kun iliaj idoj, kvardek bovinojn kaj dek virbovojn, dudek azeninojn kaj dek azenidojn."],[32,16,"Kaj li transdonis en la manojn de siaj sklavoj ĉiun gregon aparte, kaj li diris al siaj sklavoj: Iru antaŭ mi kaj lasu liberan interspacon inter unu grego kaj alia.","Kaj li transdonis en la manojn de siaj sklavoj ĉiun gregon aparte, kaj li diris al siaj sklavoj: Iru antaŭ mi kaj lasu liberan interspacon inter unu grego kaj alia."],[32,17,"Kaj al la unua li ordonis jene: Se vin renkontos mia frato Esav, kaj demandos vin: Kies vi estas? kaj kien vi iras? kaj al kiu apartenas tio, kio estas antaŭ vi?","Kaj al la unua li ordonis jene: Se vin renkontos mia frato Esav, kaj demandos vin: Kies vi estas? kaj kien vi iras? kaj al kiu apartenas tio, kio estas antaŭ vi?"],[32,18,"tiam diru: Al via sklavo Jakob; ĝi estas donaco, sendata al mia sinjoro Esav, kaj jen li ankaŭ mem estas post ni.","tiam diru: Al via sklavo Jakob; ĝi estas donaco, sendata al mia sinjoro Esav, kaj jen li ankaŭ mem estas post ni."],[32,19,"Kaj li ordonis ankaŭ al la dua, ankaŭ al la tria, ankaŭ al ĉiuj, kiuj iris post la gregoj, dirante: Tiamaniere parolu al Esav, kiam vi lin renkontos.","Kaj li ordonis ankaŭ al la dua, ankaŭ al la tria, ankaŭ al ĉiuj, kiuj iris post la gregoj, dirante: Tiamaniere parolu al Esav, kiam vi lin renkontos."],[32,20,"Kaj diru: Jen ankaŭ via sklavo Jakob iras post ni. Ĉar li pensis: Mi pardonemigos lin per la donaco, kiu iras antaŭ mi, kaj poste mi vidos lian vizaĝon; eble li akceptos min favore.","Kaj diru: Jen ankaŭ via sklavo Jakob iras post ni. Ĉar li pensis: Mi pardonemigos lin per la donaco, kiu iras antaŭ mi, kaj poste mi vidos lian vizaĝon; eble li akceptos min favore."],[32,21,"Kaj la donaco pasis antaŭ li; sed li pasigis tiun nokton en la tendaro.","Kaj la donaco pasis antaŭ li; sed li pasigis tiun nokton en la tendaro."],[32,22,"Kaj li leviĝis en tiu nokto, kaj prenis siajn du edzinojn kaj siajn du sklavinojn kaj siajn dek unu infanojn, kaj transpasis la vadejon de Jabok.","Kaj li leviĝis en tiu nokto, kaj prenis siajn du edzinojn kaj siajn du sklavinojn kaj siajn dek unu infanojn, kaj transpasis la vadejon de Jabok."],[32,23,"Kaj li prenis ilin kaj transirigis ilin trans la riveron, kaj transigis tion, kion li havis.","Kaj li prenis ilin kaj transirigis ilin trans la riveron, kaj transigis tion, kion li havis."],[32,24,"Kaj Jakob restis sola. Kaj iu luktis kun li ĝis la apero de la matenruĝo.","Kaj Jakob restis sola. Kaj iu luktis kun li ĝis la apero de la matenruĝo."],[32,25,"Vidinte, ke li ne povas lin venki, tiu tuŝis la artikon de lia femuro; kaj la femuro de Jakob elartikiĝis, dum li luktis kun tiu.","Vidinte, ke li ne povas lin venki, tiu tuŝis la artikon de lia femuro; kaj la femuro de Jakob elartikiĝis, dum li luktis kun tiu."],[32,26,"Kaj tiu diris: Forliberigu min, ĉar leviĝis la matenruĝo. Sed li diris: Mi ne forliberigos vin, antaŭ ol vi min benos.","Kaj tiu diris: Forliberigu min, ĉar leviĝis la matenruĝo. Sed li diris: Mi ne forliberigos vin, antaŭ ol vi min benos."],[32,27,"Kaj tiu diris al li: Kia estas via nomo? Kaj li respondis: Jakob.","Kaj tiu diris al li: Kia estas via nomo? Kaj li respondis: Jakob."],[32,28,"Tiam tiu diris: Ne Jakob estu de nun via nomo, sed Izrael; ĉar vi luktis kun Dio kaj kun homoj, kaj vi venkis.","Tiam tiu diris: Ne Jakob estu de nun via nomo, sed Izrael; ĉar vi luktis kun Dio kaj kun homoj, kaj vi venkis."],[32,29,"Kaj Jakob demandis, dirante: Diru vian nomon. Sed tiu diris: Por kio vi demandas mian nomon? Kaj li benis lin tie.","Kaj Jakob demandis, dirante: Diru vian nomon. Sed tiu diris: Por kio vi demandas mian nomon? Kaj li benis lin tie."],[32,30,"Kaj Jakob donis al tiu loko la nomon Penuel, dirante: Ĉar mi vidis Dion vizaĝon kontraŭ vizaĝo, kaj mia animo saviĝis.","Kaj Jakob donis al tiu loko la nomon Penuel, dirante: Ĉar mi vidis Dion vizaĝon kontraŭ vizaĝo, kaj mia animo saviĝis."],[32,31,"La suno leviĝis antaŭ li, kiam li trapasis Penuelon; kaj li lamis per sia femuro.","La suno leviĝis antaŭ li, kiam li trapasis Penuelon; kaj li lamis per sia femuro."],[32,32,"Tial la Izraelidoj ne manĝas ĝis la nuna tempo la tendenon, kiu estas sur la artiko de la femuro, ĉar tiu tuŝis la femuran artikon de Jakob ĉe la tendeno.","Tial la Izraelidoj ne manĝas ĝis la nuna tempo la tendenon, kiu estas sur la artiko de la femuro, ĉar tiu tuŝis la femuran artikon de Jakob ĉe la tendeno."],[33,1,"Jakob levis siajn okulojn, kaj vidis, ke jen venas Esav kaj kun li kvarcent homoj. Tiam li dividis la infanojn de Lea kaj de Raĥel kaj de la du sklavinoj.","Jakob levis siajn okulojn, kaj vidis, ke jen venas Esav kaj kun li kvarcent homoj. Tiam li dividis la infanojn de Lea kaj de Raĥel kaj de la du sklavinoj."],[33,2,"Kaj li starigis la sklavinojn kaj iliajn infanojn antaŭe, Lean kun ŝiaj infanoj poste, kaj Raĥelon kun Jozef en la fino.","Kaj li starigis la sklavinojn kaj iliajn infanojn antaŭe, Lean kun ŝiaj infanoj poste, kaj Raĥelon kun Jozef en la fino."],[33,3,"Kaj li mem pasis preter ilin, kaj kliniĝis ĝis la tero sep fojojn, antaŭ ol li atingis sian fraton.","Kaj li mem pasis preter ilin, kaj kliniĝis ĝis la tero sep fojojn, antaŭ ol li atingis sian fraton."],[33,4,"Sed Esav kuris al li renkonte kaj ĉirkaŭprenis lin, kaj ĵetis sin sur lian kolon kaj kisis lin; kaj ili ploris.","Sed Esav kuris al li renkonte kaj ĉirkaŭprenis lin, kaj ĵetis sin sur lian kolon kaj kisis lin; kaj ili ploris."],[33,5,"Esav levis siajn okulojn kaj ekvidis la virinojn kaj la infanojn, kaj diris: Kiuj estas ĉe vi ĉi tiuj? Jakob respondis: La infanoj, kiujn Dio favore donis al via sklavo.","Esav levis siajn okulojn kaj ekvidis la virinojn kaj la infanojn, kaj diris: Kiuj estas ĉe vi ĉi tiuj? Jakob respondis: La infanoj, kiujn Dio favore donis al via sklavo."],[33,6,"Tiam alproksimiĝis la sklavinoj, ili kaj iliaj infanoj, kaj profunde kliniĝis.","Tiam alproksimiĝis la sklavinoj, ili kaj iliaj infanoj, kaj profunde kliniĝis."],[33,7,"Poste alproksimiĝis ankaŭ Lea kaj ŝiaj infanoj kaj kliniĝis; fine alproksimiĝis Jozef kaj Raĥel kaj kliniĝis.","Poste alproksimiĝis ankaŭ Lea kaj ŝiaj infanoj kaj kliniĝis; fine alproksimiĝis Jozef kaj Raĥel kaj kliniĝis."],[33,8,"Tiam Esav diris: Kio estas tiu tuta taĉmento, kiun mi renkontis? Kaj Jakob respondis: Por akiri la favoron de mia sinjoro.","Tiam Esav diris: Kio estas tiu tuta taĉmento, kiun mi renkontis? Kaj Jakob respondis: Por akiri la favoron de mia sinjoro."],[33,9,"Sed Esav diris: Mi havas multe, mia frato; kio apartenas al vi, tio restu ĉe vi.","Sed Esav diris: Mi havas multe, mia frato; kio apartenas al vi, tio restu ĉe vi."],[33,10,"Kaj Jakob diris: Ho ne! se mi akiris vian favoron, prenu mian donacon el mia mano; ĉar mi vidis vian vizaĝon, kvazaŭ mi vidus la vizaĝon de Dio, kaj vi montriĝis favora al mi.","Kaj Jakob diris: Ho ne! se mi akiris vian favoron, prenu mian donacon el mia mano; ĉar mi vidis vian vizaĝon, kvazaŭ mi vidus la vizaĝon de Dio, kaj vi montriĝis favora al mi."],[33,11,"Prenu mian benon, kiu estas alportita al vi; ĉar Dio favore donis al mi kaj mi havas ĉion. Kaj li insistis, kaj tiu prenis.","Prenu mian benon, kiu estas alportita al vi; ĉar Dio favore donis al mi kaj mi havas ĉion. Kaj li insistis, kaj tiu prenis."],[33,12,"Kaj Esav diris: Ni leviĝu kaj iru, kaj mi iros apud vi.","Kaj Esav diris: Ni leviĝu kaj iru, kaj mi iros apud vi."],[33,13,"Sed Jakob diris al li: Mia sinjoro scias, ke la infanoj estas malfortaj, kaj la ŝafoj kaj bovoj ĉe mi estas tro junaj; se oni pelos ilin dum unu tago, la brutaro mortos.","Sed Jakob diris al li: Mia sinjoro scias, ke la infanoj estas malfortaj, kaj la ŝafoj kaj bovoj ĉe mi estas tro junaj; se oni pelos ilin dum unu tago, la brutaro mortos."],[33,14,"Mia sinjoro iru antaŭ sia sklavo, kaj mi kondukos malrapide, kiel iros la brutoj, kiuj estas antaŭ mi, kaj kiel iros la infanoj, ĝis mi venos al mia sinjoro en Seir.","Mia sinjoro iru antaŭ sia sklavo, kaj mi kondukos malrapide, kiel iros la brutoj, kiuj estas antaŭ mi, kaj kiel iros la infanoj, ĝis mi venos al mia sinjoro en Seir."],[33,15,"Tiam Esav diris: Mi restigos ĉe vi iujn el la homoj, kiuj estas kun mi. Sed Jakob diris: Por kio? lasu min nur posedi la favoron de mia sinjoro.","Tiam Esav diris: Mi restigos ĉe vi iujn el la homoj, kiuj estas kun mi. Sed Jakob diris: Por kio? lasu min nur posedi la favoron de mia sinjoro."],[33,16,"Kaj en tiu tago Esav returne foriris sian vojon al Seir.","Kaj en tiu tago Esav returne foriris sian vojon al Seir."],[33,17,"Kaj Jakob ekiris al Sukot kaj konstruis al si domon, kaj por siaj brutoj li faris kabanojn; tial la loko ricevis la nomon Sukot.","Kaj Jakob ekiris al Sukot kaj konstruis al si domon, kaj por siaj brutoj li faris kabanojn; tial la loko ricevis la nomon Sukot."],[33,18,"Veninte el Mezopotamio, Jakob alvenis bonstate en la urbo de Ŝeĥem, kiu estas en la lando Kanaana; kaj li starigis sian tendaron antaŭ la urbo.","Veninte el Mezopotamio, Jakob alvenis bonstate en la urbo de Ŝeĥem, kiu estas en la lando Kanaana; kaj li starigis sian tendaron antaŭ la urbo."],[33,19,"Kaj la kampoparton, sur kiu li starigis sian tendon, li aĉetis el la manoj de la filoj de Ĥamor, la patro de Ŝeĥem, por cent kesitoj.","Kaj la kampoparton, sur kiu li starigis sian tendon, li aĉetis el la manoj de la filoj de Ĥamor, la patro de Ŝeĥem, por cent kesitoj."],[33,20,"Kaj li starigis tie altaron, kaj li nomis ĝin El, la Dio de Izrael.","Kaj li starigis tie altaron, kaj li nomis ĝin El, la Dio de Izrael."],[34,1,"Dina, la filino de Lea, kiun ŝi naskis al Jakob, eliris, por vidi la filinojn de la lando.","Dina, la filino de Lea, kiun ŝi naskis al Jakob, eliris, por vidi la filinojn de la lando."],[34,2,"Kaj vidis ŝin Ŝeĥem, filo de Ĥamor la Ĥivido, princo de la lando, kaj li prenis ŝin kaj kuŝis kun ŝi kaj faris al ŝi perfortaĵon.","Kaj vidis ŝin Ŝeĥem, filo de Ĥamor la Ĥivido, princo de la lando, kaj li prenis ŝin kaj kuŝis kun ŝi kaj faris al ŝi perfortaĵon."],[34,3,"Kaj algluiĝis lia animo al Dina, la filino de Jakob, kaj li ekamis la junulinon kaj parolis al la koro de la junulino.","Kaj algluiĝis lia animo al Dina, la filino de Jakob, kaj li ekamis la junulinon kaj parolis al la koro de la junulino."],[34,4,"Kaj Ŝeĥem diris al sia patro Ĥamor jene: Prenu por mi ĉi tiun knabinon kiel edzinon.","Kaj Ŝeĥem diris al sia patro Ĥamor jene: Prenu por mi ĉi tiun knabinon kiel edzinon."],[34,5,"Jakob aŭdis, ke li senhonorigis lian filinon Dina; sed liaj filoj estis kun liaj brutoj sur la kampo, tial Jakob silentis ĝis ilia veno.","Jakob aŭdis, ke li senhonorigis lian filinon Dina; sed liaj filoj estis kun liaj brutoj sur la kampo, tial Jakob silentis ĝis ilia veno."],[34,6,"Kaj Ĥamor, la patro de Ŝeĥem, eliris al Jakob, por paroli kun li.","Kaj Ĥamor, la patro de Ŝeĥem, eliris al Jakob, por paroli kun li."],[34,7,"Sed la filoj de Jakob venis de la kampo. Kiam ili aŭdis, la viroj ĉagreniĝis kaj forte koleriĝis, ke li faris malnoblaĵon en Izrael, kuŝinte kun la filino de Jakob, kio ne devis esti farata.","Sed la filoj de Jakob venis de la kampo. Kiam ili aŭdis, la viroj ĉagreniĝis kaj forte koleriĝis, ke li faris malnoblaĵon en Izrael, kuŝinte kun la filino de Jakob, kio ne devis esti farata."],[34,8,"Ĥamor ekparolis al ili, dirante: Ŝeĥem, mia filo, deziregas per sia animo vian filinon; donu ŝin al li kiel edzinon.","Ĥamor ekparolis al ili, dirante: Ŝeĥem, mia filo, deziregas per sia animo vian filinon; donu ŝin al li kiel edzinon."],[34,9,"Kaj boparenciĝu kun ni: viajn filinojn donu al ni, kaj niajn filinojn prenu al vi.","Kaj boparenciĝu kun ni: viajn filinojn donu al ni, kaj niajn filinojn prenu al vi."],[34,10,"Kaj loĝu kun ni, kaj la lando estos antaŭ vi; loĝu kaj faru negocojn kaj akiru posedaĵojn en ĝi.","Kaj loĝu kun ni, kaj la lando estos antaŭ vi; loĝu kaj faru negocojn kaj akiru posedaĵojn en ĝi."],[34,11,"Kaj Ŝeĥem diris al ŝia patro kaj al ŝiaj fratoj: Estu favoraj al mi; kaj kion vi diros al mi, mi donos.","Kaj Ŝeĥem diris al ŝia patro kaj al ŝiaj fratoj: Estu favoraj al mi; kaj kion vi diros al mi, mi donos."],[34,12,"Postulu de mi tre grandan doton kaj donacojn, kaj mi donos, kion vi diros al mi; nur donu al mi la junulinon kiel edzinon.","Postulu de mi tre grandan doton kaj donacojn, kaj mi donos, kion vi diros al mi; nur donu al mi la junulinon kiel edzinon."],[34,13,"Kaj la filoj de Jakob respondis al Ŝeĥem kaj al lia patro Ĥamor ruze, kaj parolis tiel pro tio, ke li senhonorigis ilian fratinon Dina;","Kaj la filoj de Jakob respondis al Ŝeĥem kaj al lia patro Ĥamor ruze, kaj parolis tiel pro tio, ke li senhonorigis ilian fratinon Dina;"],[34,14,"kaj ili diris al ili: Ni ne povas fari tion kaj doni nian fratinon al viro, kiu ne estas cirkumcidita; ĉar tio estus por ni hontindaĵo.","kaj ili diris al ili: Ni ne povas fari tion kaj doni nian fratinon al viro, kiu ne estas cirkumcidita; ĉar tio estus por ni hontindaĵo."],[34,15,"Nur tiam ni donos al vi nian konsenton, se vi estos kiel ni kaj cirkumcidos ĉe vi ĉiun virseksulon.","Nur tiam ni donos al vi nian konsenton, se vi estos kiel ni kaj cirkumcidos ĉe vi ĉiun virseksulon."],[34,16,"Tiam ni donos niajn filinojn al vi kaj viajn filinojn ni prenos al ni, kaj ni loĝos kun vi, kaj ni estos unu popolo.","Tiam ni donos niajn filinojn al vi kaj viajn filinojn ni prenos al ni, kaj ni loĝos kun vi, kaj ni estos unu popolo."],[34,17,"Sed se vi ne konsentos lasi cirkumcidi vin, tiam ni prenos nian filinon kaj foriros.","Sed se vi ne konsentos lasi cirkumcidi vin, tiam ni prenos nian filinon kaj foriros."],[34,18,"Ilia parolo plaĉis al Ĥamor, kaj al Ŝeĥem, la filo de Ĥamor.","Ilia parolo plaĉis al Ĥamor, kaj al Ŝeĥem, la filo de Ĥamor."],[34,19,"Kaj la junulo ne prokrastis fari la aferon, ĉar li deziris la filinon de Jakob; kaj li estis la plej honorata inter ĉiuj domanoj de sia patro.","Kaj la junulo ne prokrastis fari la aferon, ĉar li deziris la filinon de Jakob; kaj li estis la plej honorata inter ĉiuj domanoj de sia patro."],[34,20,"Kaj Ĥamor kaj lia filo Ŝeĥem venis al la pordego de sia urbo, kaj ekparolis al la loĝantoj de sia urbo, dirante:","Kaj Ĥamor kaj lia filo Ŝeĥem venis al la pordego de sia urbo, kaj ekparolis al la loĝantoj de sia urbo, dirante:"],[34,21,"Tiuj homoj estas pacaj kun ni; tial ili loĝu en la lando kaj faru en ĝi negocojn; la lando estas ja grandspaca por ili. Iliajn filinojn ni prenu al ni kiel edzinojn, kaj niajn filinojn ni donu al ili.","Tiuj homoj estas pacaj kun ni; tial ili loĝu en la lando kaj faru en ĝi negocojn; la lando estas ja grandspaca por ili. Iliajn filinojn ni prenu al ni kiel edzinojn, kaj niajn filinojn ni donu al ili."],[34,22,"Sed nur en tia okazo tiuj homoj konsentas loĝi kun ni kaj esti unu popolo, se ni cirkumcidos ĉe ni ĉiun virseksulon, kiel ili estas cirkumciditaj.","Sed nur en tia okazo tiuj homoj konsentas loĝi kun ni kaj esti unu popolo, se ni cirkumcidos ĉe ni ĉiun virseksulon, kiel ili estas cirkumciditaj."],[34,23,"Ilia akiritaĵo kaj havaĵo kaj ĉiuj iliaj brutoj fariĝos ja niaj, se ni nur donos al ili nian konsenton kaj ili loĝos kun ni.","Ilia akiritaĵo kaj havaĵo kaj ĉiuj iliaj brutoj fariĝos ja niaj, se ni nur donos al ili nian konsenton kaj ili loĝos kun ni."],[34,24,"Kaj obeis al Ĥamor kaj al lia filo Ŝeĥem ĉiuj elirantaj el la pordego de lia urbo; kaj cirkumcidiĝis ĉiuj virseksuloj, ĉiuj elirantaj el la pordego de lia urbo.","Kaj obeis al Ĥamor kaj al lia filo Ŝeĥem ĉiuj elirantaj el la pordego de lia urbo; kaj cirkumcidiĝis ĉiuj virseksuloj, ĉiuj elirantaj el la pordego de lia urbo."],[34,25,"En la tria tago, kiam ili estis malsanaj, du filoj de Jakob, Simeon kaj Levi, fratoj de Dina, prenis ĉiu sian glavon kaj venis sentime en la urbon kaj mortigis ĉiujn virseksulojn.","En la tria tago, kiam ili estis malsanaj, du filoj de Jakob, Simeon kaj Levi, fratoj de Dina, prenis ĉiu sian glavon kaj venis sentime en la urbon kaj mortigis ĉiujn virseksulojn."],[34,26,"Kaj Ĥamoron kaj lian filon Ŝeĥem ili mortigis per glavo, kaj prenis Dinan el la domo de Ŝeĥem kaj eliris.","Kaj Ĥamoron kaj lian filon Ŝeĥem ili mortigis per glavo, kaj prenis Dinan el la domo de Ŝeĥem kaj eliris."],[34,27,"La filoj de Jakob venis al la mortigitoj, kaj prirabis la urbon pro tio, ke ili senhonorigis ilian fratinon.","La filoj de Jakob venis al la mortigitoj, kaj prirabis la urbon pro tio, ke ili senhonorigis ilian fratinon."],[34,28,"Iliajn ŝafojn kaj iliajn bovojn kaj iliajn azenojn, kaj ĉion, kio estis en la urbo, kaj tion, kio estis sur la kampo, ili prenis.","Iliajn ŝafojn kaj iliajn bovojn kaj iliajn azenojn, kaj ĉion, kio estis en la urbo, kaj tion, kio estis sur la kampo, ili prenis."],[34,29,"Kaj ilian tutan riĉon kaj ĉiujn iliajn infanojn kaj iliajn edzinojn ili malliberigis, kaj rabis ĉion, kio estis en la domoj.","Kaj ilian tutan riĉon kaj ĉiujn iliajn infanojn kaj iliajn edzinojn ili malliberigis, kaj rabis ĉion, kio estis en la domoj."],[34,30,"Tiam Jakob diris al Simeon kaj al Levi: Vi afliktis min kaj faris min malaminda por la loĝantoj de la lando, por la Kanaanidoj kaj Perizidoj. Mi havas ja malmulte da homoj; kiam ili kolektiĝos kontraŭ mi kaj venkobatos min, tiam estos ekstermita mi kaj mia domo.","Tiam Jakob diris al Simeon kaj al Levi: Vi afliktis min kaj faris min malaminda por la loĝantoj de la lando, por la Kanaanidoj kaj Perizidoj. Mi havas ja malmulte da homoj; kiam ili kolektiĝos kontraŭ mi kaj venkobatos min, tiam estos ekstermita mi kaj mia domo."],[34,31,"Sed ili diris: Ĉu estas permesite agi kun nia fratino kiel kun publikulino?","Sed ili diris: Ĉu estas permesite agi kun nia fratino kiel kun publikulino?"],[35,1,"Kaj Dio diris al Jakob: Leviĝu, iru al Bet-El kaj loĝu tie; kaj faru tie altaron al Dio, kiu aperis al vi, kiam vi kuris de via frato Esav.","Kaj Dio diris al Jakob: Leviĝu, iru al Bet-El kaj loĝu tie; kaj faru tie altaron al Dio, kiu aperis al vi, kiam vi kuris de via frato Esav."],[35,2,"Tiam Jakob diris al sia domanaro, kaj al ĉiuj, kiuj estis kun li: Forigu la fremdajn diojn, kiuj estas inter vi, kaj puriĝu kaj ŝanĝu viajn vestojn.","Tiam Jakob diris al sia domanaro, kaj al ĉiuj, kiuj estis kun li: Forigu la fremdajn diojn, kiuj estas inter vi, kaj puriĝu kaj ŝanĝu viajn vestojn."],[35,3,"Kaj ni leviĝu, kaj ni iru al Bet-El; kaj mi faros tie altaron al Dio, kiu atentis min en la tago de mia mizero, kaj estis kun mi sur la vojo, kiun mi iris.","Kaj ni leviĝu, kaj ni iru al Bet-El; kaj mi faros tie altaron al Dio, kiu atentis min en la tago de mia mizero, kaj estis kun mi sur la vojo, kiun mi iris."],[35,4,"Kaj ili donis al Jakob ĉiujn fremdajn diojn, kiuj estis en iliaj manoj, kaj la ringojn, kiuj estis en iliaj oreloj; kaj Jakob enfosis ilin sub la kverko, kiu estis apud Ŝeĥem.","Kaj ili donis al Jakob ĉiujn fremdajn diojn, kiuj estis en iliaj manoj, kaj la ringojn, kiuj estis en iliaj oreloj; kaj Jakob enfosis ilin sub la kverko, kiu estis apud Ŝeĥem."],[35,5,"Kaj ili ekiris. Kaj timo de Dio venis sur la urbojn, kiuj estis ĉirkaŭ ili, kaj ili ne persekutis la filojn de Jakob.","Kaj ili ekiris. Kaj timo de Dio venis sur la urbojn, kiuj estis ĉirkaŭ ili, kaj ili ne persekutis la filojn de Jakob."],[35,6,"Jakob venis al la urbo Luz, kiu estas en la lando Kanaana kaj havas ankaŭ la nomon Bet-El, li kaj ĉiuj homoj, kiuj estis kun li.","Jakob venis al la urbo Luz, kiu estas en la lando Kanaana kaj havas ankaŭ la nomon Bet-El, li kaj ĉiuj homoj, kiuj estis kun li."],[35,7,"Kaj li konstruis tie altaron, kaj donis al la loko la nomon El-Bet-El; ĉar tie aperis al li Dio, kiam li kuris de sia frato.","Kaj li konstruis tie altaron, kaj donis al la loko la nomon El-Bet-El; ĉar tie aperis al li Dio, kiam li kuris de sia frato."],[35,8,"Tiam mortis Debora, la mamnutrintino de Rebeka, kaj oni ŝin enterigis apud Bet-El, sub la kverko. Kaj tiu loko ricevis la nomon Alon-Baĥut.","Tiam mortis Debora, la mamnutrintino de Rebeka, kaj oni ŝin enterigis apud Bet-El, sub la kverko. Kaj tiu loko ricevis la nomon Alon-Baĥut."],[35,9,"Kaj denove Dio aperis al Jakob, kiam li revenis el Mezopotamio, kaj benis lin.","Kaj denove Dio aperis al Jakob, kiam li revenis el Mezopotamio, kaj benis lin."],[35,10,"Kaj Dio diris al li: Via nomo estas Jakob; tamen ne plue estu nomata Jakob, sed Izrael estu via nomo. Kaj Li donis al li la nomon Izrael.","Kaj Dio diris al li: Via nomo estas Jakob; tamen ne plue estu nomata Jakob, sed Izrael estu via nomo. Kaj Li donis al li la nomon Izrael."],[35,11,"Kaj Dio diris al li: Mi estas Dio la Plejpotenca; fruktu kaj multiĝu; popolo kaj popolaro fariĝos el vi, kaj reĝoj eliros el via lumbo.","Kaj Dio diris al li: Mi estas Dio la Plejpotenca; fruktu kaj multiĝu; popolo kaj popolaro fariĝos el vi, kaj reĝoj eliros el via lumbo."],[35,12,"Kaj la landon, kiun Mi donis al Abraham kaj al Isaak, Mi donos al vi, kaj al via idaro post vi Mi donos la landon.","Kaj la landon, kiun Mi donis al Abraham kaj al Isaak, Mi donos al vi, kaj al via idaro post vi Mi donos la landon."],[35,13,"Kaj Dio forleviĝis de li sur la loko, kie Li parolis kun li.","Kaj Dio forleviĝis de li sur la loko, kie Li parolis kun li."],[35,14,"Jakob starigis monumenton sur la loko, kie Li parolis kun li, monumenton ŝtonan; kaj li verŝis sur ĝin verŝoferon kaj verŝis sur ĝin oleon.","Jakob starigis monumenton sur la loko, kie Li parolis kun li, monumenton ŝtonan; kaj li verŝis sur ĝin verŝoferon kaj verŝis sur ĝin oleon."],[35,15,"Kaj al la loko, kie Dio parolis kun li, Jakob donis la nomon Bet-El.","Kaj al la loko, kie Dio parolis kun li, Jakob donis la nomon Bet-El."],[35,16,"Kaj ili forlasis Bet-Elon. Kiam restis ankoraŭ negranda interspaco, por veni al Efrata, Raĥel naskis, kaj ŝia akuŝiĝo estis malfacila.","Kaj ili forlasis Bet-Elon. Kiam restis ankoraŭ negranda interspaco, por veni al Efrata, Raĥel naskis, kaj ŝia akuŝiĝo estis malfacila."],[35,17,"Dum ŝia akuŝiĝa suferado la akuŝistino diris al ŝi: Ne timu, ĉar ankaŭ ĉi tiu ĉe vi estas filo.","Dum ŝia akuŝiĝa suferado la akuŝistino diris al ŝi: Ne timu, ĉar ankaŭ ĉi tiu ĉe vi estas filo."],[35,18,"Dum la elirado de ŝia animo, ĉar ŝi estis mortanta, ŝi donis al li la nomon Ben-Oni; sed lia patro donis al li la nomon Benjamen.","Dum la elirado de ŝia animo, ĉar ŝi estis mortanta, ŝi donis al li la nomon Ben-Oni; sed lia patro donis al li la nomon Benjamen."],[35,19,"Kaj Raĥel mortis, kaj oni enterigis ŝin sur la vojo al Efrata, kiu estas Bet-Leĥem.","Kaj Raĥel mortis, kaj oni enterigis ŝin sur la vojo al Efrata, kiu estas Bet-Leĥem."],[35,20,"Kaj Jakob starigis monumenton super ŝia tombo. Tio estas la tomba monumento de Raĥel ĝis la nuna tago.","Kaj Jakob starigis monumenton super ŝia tombo. Tio estas la tomba monumento de Raĥel ĝis la nuna tago."],[35,21,"Kaj Izrael formigris, kaj starigis sian tendon transe de la turo Eder.","Kaj Izrael formigris, kaj starigis sian tendon transe de la turo Eder."],[35,22,"En la tempo, kiam Izrael loĝis en tiu lando, Ruben iris kaj kuŝis kun Bilha, la kromvirino de lia patro. Kaj pri tio aŭdis Izrael. La filoj de Jakob estis dek du:","En la tempo, kiam Izrael loĝis en tiu lando, Ruben iris kaj kuŝis kun Bilha, la kromvirino de lia patro. Kaj pri tio aŭdis Izrael. La filoj de Jakob estis dek du:"],[35,23,"la filoj de Lea: Ruben, la unuenaskito de Jakob, kaj Simeon kaj Levi kaj Jehuda kaj Isaĥar kaj Zebulun;","la filoj de Lea: Ruben, la unuenaskito de Jakob, kaj Simeon kaj Levi kaj Jehuda kaj Isaĥar kaj Zebulun;"],[35,24,"la filoj de Raĥel: Jozef kaj Benjamen;","la filoj de Raĥel: Jozef kaj Benjamen;"],[35,25,"kaj la filoj de Bilha, sklavino de Raĥel: Dan kaj Naftali;","kaj la filoj de Bilha, sklavino de Raĥel: Dan kaj Naftali;"],[35,26,"kaj la filoj de Zilpa, sklavino de Lea: Gad kaj Aŝer. Tio estas la filoj de Jakob, kiuj naskiĝis al li en Mezopotamio.","kaj la filoj de Zilpa, sklavino de Lea: Gad kaj Aŝer. Tio estas la filoj de Jakob, kiuj naskiĝis al li en Mezopotamio."],[35,27,"Kaj Jakob venis al sia patro Isaak en Mamre, al Kirjat-Arba (tio estas Ĥebron), kie vivis fremdule Abraham kaj Isaak.","Kaj Jakob venis al sia patro Isaak en Mamre, al Kirjat-Arba (tio estas Ĥebron), kie vivis fremdule Abraham kaj Isaak."],[35,28,"Isaak havis la aĝon de cent okdek jaroj.","Isaak havis la aĝon de cent okdek jaroj."],[35,29,"Kaj Isaak konsumiĝis kaj mortis kaj alkolektiĝis al sia popolo, estante maljuna kaj sata de vivo. Kaj lin enterigis liaj filoj Esav kaj Jakob.","Kaj Isaak konsumiĝis kaj mortis kaj alkolektiĝis al sia popolo, estante maljuna kaj sata de vivo. Kaj lin enterigis liaj filoj Esav kaj Jakob."],[36,1,"Jen estas la generaciaro de Esav, kiu ankaŭ estas Edom.","Jen estas la generaciaro de Esav, kiu ankaŭ estas Edom."],[36,2,"Esav prenis siajn edzinojn el la Kanaanidinoj: Adan, filinon de Elon la Ĥetido, kaj Oholibaman, filinon de Ana, filino de Cibeon la Ĥivido,","Esav prenis siajn edzinojn el la Kanaanidinoj: Adan, filinon de Elon la Ĥetido, kaj Oholibaman, filinon de Ana, filino de Cibeon la Ĥivido,"],[36,3,"kaj Basmaton, filinon de Iŝmael, fratinon de Nebajot.","kaj Basmaton, filinon de Iŝmael, fratinon de Nebajot."],[36,4,"Kaj Ada naskis al Esav Elifazon, kaj Basmat naskis Reuelon.","Kaj Ada naskis al Esav Elifazon, kaj Basmat naskis Reuelon."],[36,5,"Kaj Oholibama naskis Jeuŝon kaj Jalamon kaj Koraĥon. Tio estas la filoj de Esav, kiuj naskiĝis al li en la lando Kanaana.","Kaj Oholibama naskis Jeuŝon kaj Jalamon kaj Koraĥon. Tio estas la filoj de Esav, kiuj naskiĝis al li en la lando Kanaana."],[36,6,"Kaj Esav prenis siajn edzinojn kaj siajn filojn kaj siajn filinojn kaj ĉiujn siajn domanojn kaj sian havon kaj ĉiujn siajn brutojn kaj sian tutan akiritaĵon, kiun li akiris en la lando Kanaana; kaj foriris en alian landon, for de sia frato Jakob.","Kaj Esav prenis siajn edzinojn kaj siajn filojn kaj siajn filinojn kaj ĉiujn siajn domanojn kaj sian havon kaj ĉiujn siajn brutojn kaj sian tutan akiritaĵon, kiun li akiris en la lando Kanaana; kaj foriris en alian landon, for de sia frato Jakob."],[36,7,"Ĉar ilia havo estis tiel granda, ke ili ne povis loĝi kune; kaj la lando, en kiu ili vivis fremdule, ne povis teni ilin pro la grandeco de iliaj brutaroj.","Ĉar ilia havo estis tiel granda, ke ili ne povis loĝi kune; kaj la lando, en kiu ili vivis fremdule, ne povis teni ilin pro la grandeco de iliaj brutaroj."],[36,8,"Kaj Esav ekloĝis sur la monto Seir; Esav estas ankaŭ Edom.","Kaj Esav ekloĝis sur la monto Seir; Esav estas ankaŭ Edom."],[36,9,"Kaj jen estas la generaciaro de Esav, la patro de la Edomidoj, sur la monto Seir:","Kaj jen estas la generaciaro de Esav, la patro de la Edomidoj, sur la monto Seir:"],[36,10,"jen estas la nomoj de la filoj de Esav: Elifaz, filo de Ada, edzino de Esav; Reuel, filo de Basmat, edzino de Esav.","jen estas la nomoj de la filoj de Esav: Elifaz, filo de Ada, edzino de Esav; Reuel, filo de Basmat, edzino de Esav."],[36,11,"Kaj la filoj de Elifaz estis: Teman, Omar, Cefo kaj Gatam kaj Kenaz.","Kaj la filoj de Elifaz estis: Teman, Omar, Cefo kaj Gatam kaj Kenaz."],[36,12,"Kaj Timna estis kromvirino de Elifaz, filo de Esav, kaj ŝi naskis al Elifaz Amalekon. Tio estas la filoj de Ada, edzino de Esav.","Kaj Timna estis kromvirino de Elifaz, filo de Esav, kaj ŝi naskis al Elifaz Amalekon. Tio estas la filoj de Ada, edzino de Esav."],[36,13,"Kaj jen estas la filoj de Reuel: Naĥat kaj Zeraĥ, Ŝama kaj Miza. Tio estas la filoj de Basmat, edzino de Esav.","Kaj jen estas la filoj de Reuel: Naĥat kaj Zeraĥ, Ŝama kaj Miza. Tio estas la filoj de Basmat, edzino de Esav."],[36,14,"Kaj jen estas la filoj de Oholibama, filino de Ana, filino de Cibeon, edzino de Esav: ŝi naskis al Esav Jeuŝon kaj Jalamon kaj Koraĥon.","Kaj jen estas la filoj de Oholibama, filino de Ana, filino de Cibeon, edzino de Esav: ŝi naskis al Esav Jeuŝon kaj Jalamon kaj Koraĥon."],[36,15,"Jen estas la ĉefoj de la filoj de Esav: la filoj de Elifaz, unuenaskito de Esav: ĉefo Teman, ĉefo Omar, ĉefo Cefo, ĉefo Kenaz,","Jen estas la ĉefoj de la filoj de Esav: la filoj de Elifaz, unuenaskito de Esav: ĉefo Teman, ĉefo Omar, ĉefo Cefo, ĉefo Kenaz,"],[36,16,"ĉefo Koraĥ, ĉefo Gatam, ĉefo Amalek. Tio estas la ĉefoj de Elifaz en la lando de Edom. Tio estas la filoj de Ada.","ĉefo Koraĥ, ĉefo Gatam, ĉefo Amalek. Tio estas la ĉefoj de Elifaz en la lando de Edom. Tio estas la filoj de Ada."],[36,17,"Kaj jen estas la filoj de Reuel, filo de Esav: ĉefo Naĥat, ĉefo Zeraĥ, ĉefo Ŝama, ĉefo Miza. Tio estas la ĉefoj de Reuel en la lando de Edom. Tio estas la filoj de Basmat, edzino de Esav.","Kaj jen estas la filoj de Reuel, filo de Esav: ĉefo Naĥat, ĉefo Zeraĥ, ĉefo Ŝama, ĉefo Miza. Tio estas la ĉefoj de Reuel en la lando de Edom. Tio estas la filoj de Basmat, edzino de Esav."],[36,18,"Kaj jen estas la filoj de Oholibama, edzino de Esav: ĉefo Jeuŝ, ĉefo Jalam, ĉefo Koraĥ. Tio estas la ĉefoj de Oholibama, filino de Ana, edzino de Esav.","Kaj jen estas la filoj de Oholibama, edzino de Esav: ĉefo Jeuŝ, ĉefo Jalam, ĉefo Koraĥ. Tio estas la ĉefoj de Oholibama, filino de Ana, edzino de Esav."],[36,19,"Tio estas la filoj de Esav, kaj tio estas iliaj ĉefoj. Tio estas Edom.","Tio estas la filoj de Esav, kaj tio estas iliaj ĉefoj. Tio estas Edom."],[36,20,"Jen estas la filoj de Seir la Ĥorido, kiuj loĝis en la lando: Lotan kaj Ŝobal kaj Cibeon kaj Ana","Jen estas la filoj de Seir la Ĥorido, kiuj loĝis en la lando: Lotan kaj Ŝobal kaj Cibeon kaj Ana"],[36,21,"kaj Diŝon kaj Ecer kaj Diŝan. Tio estas la ĉefoj de la Ĥoridoj, filoj de Seir, en la lando de Edom.","kaj Diŝon kaj Ecer kaj Diŝan. Tio estas la ĉefoj de la Ĥoridoj, filoj de Seir, en la lando de Edom."],[36,22,"La filoj de Lotan estis: Ĥori kaj Hemam; kaj la fratino de Lotan estis Timna.","La filoj de Lotan estis: Ĥori kaj Hemam; kaj la fratino de Lotan estis Timna."],[36,23,"Kaj jen estas la filoj de Ŝobal: Alvan kaj Manaĥat kaj Ebal, Ŝefo kaj Onam.","Kaj jen estas la filoj de Ŝobal: Alvan kaj Manaĥat kaj Ebal, Ŝefo kaj Onam."],[36,24,"Kaj jen estas la infanoj de Cibeon: Aja kaj Ana. Tio estas tiu Ana, kiu trovis la varmajn akvojn en la dezerto, kiam li paŝtis la azenojn de sia patro Cibeon.","Kaj jen estas la infanoj de Cibeon: Aja kaj Ana. Tio estas tiu Ana, kiu trovis la varmajn akvojn en la dezerto, kiam li paŝtis la azenojn de sia patro Cibeon."],[36,25,"Kaj jen estas la infanoj de Ana: Diŝon, kaj Oholibama, filino de Ana.","Kaj jen estas la infanoj de Ana: Diŝon, kaj Oholibama, filino de Ana."],[36,26,"Kaj jen estas la filoj de Diŝon: Ĥemdan kaj Eŝban kaj Jitran kaj Keran.","Kaj jen estas la filoj de Diŝon: Ĥemdan kaj Eŝban kaj Jitran kaj Keran."],[36,27,"Jen estas la filoj de Ecer: Bilhan kaj Zaavan kaj Akan.","Jen estas la filoj de Ecer: Bilhan kaj Zaavan kaj Akan."],[36,28,"Jen estas la filoj de Diŝan: Uc kaj Aran.","Jen estas la filoj de Diŝan: Uc kaj Aran."],[36,29,"Jen estas la ĉefoj de la Ĥoridoj: ĉefo Lotan, ĉefo Ŝobal, ĉefo Cibeon, ĉefo Ana,","Jen estas la ĉefoj de la Ĥoridoj: ĉefo Lotan, ĉefo Ŝobal, ĉefo Cibeon, ĉefo Ana,"],[36,30,"ĉefo Diŝon, ĉefo Ecer, ĉefo Diŝan. Tio estas la ĉefoj de la Ĥoridoj, laŭ la ordo de ilia ĉefeco en la lando Seir.","ĉefo Diŝon, ĉefo Ecer, ĉefo Diŝan. Tio estas la ĉefoj de la Ĥoridoj, laŭ la ordo de ilia ĉefeco en la lando Seir."],[36,31,"Kaj jen estas la reĝoj, kiuj reĝis en la lando de Edom, antaŭ ol aperis reĝoj ĉe la Izraelidoj:","Kaj jen estas la reĝoj, kiuj reĝis en la lando de Edom, antaŭ ol aperis reĝoj ĉe la Izraelidoj:"],[36,32,"En Edom reĝis Bela, filo de Beor, kaj la nomo de lia urbo estis Dinhaba.","En Edom reĝis Bela, filo de Beor, kaj la nomo de lia urbo estis Dinhaba."],[36,33,"Kiam Bela mortis, ekreĝis anstataŭ li Jobab, filo de Zeraĥ el Bocra.","Kiam Bela mortis, ekreĝis anstataŭ li Jobab, filo de Zeraĥ el Bocra."],[36,34,"Kiam mortis Jobab, ekreĝis anstataŭ li Ĥuŝam el la lando de la Temananoj.","Kiam mortis Jobab, ekreĝis anstataŭ li Ĥuŝam el la lando de la Temananoj."],[36,35,"Kiam mortis Ĥuŝam, ekreĝis anstataŭ li Hadad, filo de Bedad, kiu venkobatis la Midjanidojn sur la kampo de Moab; kaj la nomo de lia urbo estis Avit.","Kiam mortis Ĥuŝam, ekreĝis anstataŭ li Hadad, filo de Bedad, kiu venkobatis la Midjanidojn sur la kampo de Moab; kaj la nomo de lia urbo estis Avit."],[36,36,"Kiam mortis Hadad, ekreĝis anstataŭ li Samla el Masreka.","Kiam mortis Hadad, ekreĝis anstataŭ li Samla el Masreka."],[36,37,"Kiam mortis Samla, ekreĝis anstataŭ li Ŝaul el Reĥobot ĉe la Rivero.","Kiam mortis Samla, ekreĝis anstataŭ li Ŝaul el Reĥobot ĉe la Rivero."],[36,38,"Kiam mortis Ŝaul, ekreĝis anstataŭ li Baal-Ĥanan, filo de Aĥbor.","Kiam mortis Ŝaul, ekreĝis anstataŭ li Baal-Ĥanan, filo de Aĥbor."],[36,39,"Kiam mortis Baal-Ĥanan, filo de Aĥbor, ekreĝis anstataŭ li Hadar; la nomo de lia urbo estis Pau, kaj la nomo de lia edzino estis Mehetabel, filino de Matred, filino de Me-Zahab.","Kiam mortis Baal-Ĥanan, filo de Aĥbor, ekreĝis anstataŭ li Hadar; la nomo de lia urbo estis Pau, kaj la nomo de lia edzino estis Mehetabel, filino de Matred, filino de Me-Zahab."],[36,40,"Kaj jen estas la nomoj de la ĉefoj de Esav, laŭ iliaj gentoj, lokoj, kaj nomoj: ĉefo Timna, ĉefo Alva, ĉefo Jetet,","Kaj jen estas la nomoj de la ĉefoj de Esav, laŭ iliaj gentoj, lokoj, kaj nomoj: ĉefo Timna, ĉefo Alva, ĉefo Jetet,"],[36,41,"ĉefo Oholibama, ĉefo Ela, ĉefo Pinon,","ĉefo Oholibama, ĉefo Ela, ĉefo Pinon,"],[36,42,"ĉefo Kenaz, ĉefo Teman, ĉefo Mibcar,","ĉefo Kenaz, ĉefo Teman, ĉefo Mibcar,"],[36,43,"ĉefo Magdiel, ĉefo Iram. Tio estas la ĉefoj de Edom, kiel ili loĝis en la lando, posedata de ili. Esav estis la patro de la Edomidoj.","ĉefo Magdiel, ĉefo Iram. Tio estas la ĉefoj de Edom, kiel ili loĝis en la lando, posedata de ili. Esav estis la patro de la Edomidoj."],[37,1,"Jakob loĝis en la lando, en kiu lia patro loĝis fremdule, en la lando Kanaana.","Jakob loĝis en la lando, en kiu lia patro loĝis fremdule, en la lando Kanaana."],[37,2,"Jen estas la generaciaro de Jakob. Jozef, havante la aĝon de dek sep jaroj, paŝtis kune kun siaj fratoj la brutaron; li estis knabo kune kun la filoj de Bilha kaj la filoj de Zilpa, la edzinoj de lia patro; kaj malbonajn famojn pri ili Jozef raportadis al ilia patro.","Jen estas la generaciaro de Jakob. Jozef, havante la aĝon de dek sep jaroj, paŝtis kune kun siaj fratoj la brutaron; li estis knabo kune kun la filoj de Bilha kaj la filoj de Zilpa, la edzinoj de lia patro; kaj malbonajn famojn pri ili Jozef raportadis al ilia patro."],[37,3,"Kaj Izrael amis Jozefon pli ol ĉiujn siajn filojn, ĉar li estis por li filo naskita en maljuneco; kaj li faris al li mikskoloran veston.","Kaj Izrael amis Jozefon pli ol ĉiujn siajn filojn, ĉar li estis por li filo naskita en maljuneco; kaj li faris al li mikskoloran veston."],[37,4,"Ĉar la fratoj vidis, ke lin ilia patro amas pli ol ĉiujn liajn fratojn, tial ili malamis lin kaj ne povis paroli kun li pace.","Ĉar la fratoj vidis, ke lin ilia patro amas pli ol ĉiujn liajn fratojn, tial ili malamis lin kaj ne povis paroli kun li pace."],[37,5,"Jozef havis sonĝon, kaj li rakontis ĝin al siaj fratoj; tiam ili ekmalamis lin ankoraŭ pli.","Jozef havis sonĝon, kaj li rakontis ĝin al siaj fratoj; tiam ili ekmalamis lin ankoraŭ pli."],[37,6,"Li diris al ili: Aŭskultu la sonĝon, kiun mi sonĝis:","Li diris al ili: Aŭskultu la sonĝon, kiun mi sonĝis:"],[37,7,"ni ligis garbojn meze de la kampo; kaj jen mia garbo stariĝis kaj restis starante, kaj viaj garboj ĝin ĉirkaŭis kaj profunde kliniĝis antaŭ mia garbo.","ni ligis garbojn meze de la kampo; kaj jen mia garbo stariĝis kaj restis starante, kaj viaj garboj ĝin ĉirkaŭis kaj profunde kliniĝis antaŭ mia garbo."],[37,8,"Tiam liaj fratoj diris al li: Ĉu vi estos reĝo super ni? aŭ ĉu vi regos super ni? Kaj ili ankoraŭ pli ekmalamis lin pro liaj sonĝoj kaj pro liaj vortoj.","Tiam liaj fratoj diris al li: Ĉu vi estos reĝo super ni? aŭ ĉu vi regos super ni? Kaj ili ankoraŭ pli ekmalamis lin pro liaj sonĝoj kaj pro liaj vortoj."],[37,9,"Kaj li sonĝis ankoraŭ alian sonĝon kaj rakontis ĝin al siaj fratoj, kaj diris: Mi sonĝis ankoraŭ unu sonĝon: jen la suno kaj la luno kaj dek unu steloj kliniĝas antaŭ mi.","Kaj li sonĝis ankoraŭ alian sonĝon kaj rakontis ĝin al siaj fratoj, kaj diris: Mi sonĝis ankoraŭ unu sonĝon: jen la suno kaj la luno kaj dek unu steloj kliniĝas antaŭ mi."],[37,10,"Kaj li rakontis al sia patro kaj al siaj fratoj; kaj lia patro faris al li riproĉon, kaj diris al li: Kion vi volas kun tiu sonĝo, kiun vi sonĝis? ĉu mi kaj via patrino kaj viaj fratoj venos, por kliniĝi antaŭ vi ĝis la tero?","Kaj li rakontis al sia patro kaj al siaj fratoj; kaj lia patro faris al li riproĉon, kaj diris al li: Kion vi volas kun tiu sonĝo, kiun vi sonĝis? ĉu mi kaj via patrino kaj viaj fratoj venos, por kliniĝi antaŭ vi ĝis la tero?"],[37,11,"Kaj liaj fratoj lin enviis, sed lia patro konservis en la memoro la aferon.","Kaj liaj fratoj lin enviis, sed lia patro konservis en la memoro la aferon."],[37,12,"Liaj fratoj iris paŝti la ŝafojn de sia patro en Ŝeĥem.","Liaj fratoj iris paŝti la ŝafojn de sia patro en Ŝeĥem."],[37,13,"Kaj Izrael diris al Jozef: Viaj fratoj paŝtas ja en Ŝeĥem; venu do, mi sendos vin al ili. Kaj tiu respondis al li: Jen mi estas.","Kaj Izrael diris al Jozef: Viaj fratoj paŝtas ja en Ŝeĥem; venu do, mi sendos vin al ili. Kaj tiu respondis al li: Jen mi estas."],[37,14,"Kaj Izrael diris al li: Iru, rigardu, kiel fartas viaj fratoj kaj kiel fartas la ŝafoj, kaj alportu al mi respondon. Kaj li forsendis lin el la valo de Ĥebron, kaj tiu venis Ŝeĥemon.","Kaj Izrael diris al li: Iru, rigardu, kiel fartas viaj fratoj kaj kiel fartas la ŝafoj, kaj alportu al mi respondon. Kaj li forsendis lin el la valo de Ĥebron, kaj tiu venis Ŝeĥemon."],[37,15,"Kaj iu viro trovis lin, kaj vidis, ke li erarvagas sur la kampo; kaj la viro demandis lin: Kion vi serĉas?","Kaj iu viro trovis lin, kaj vidis, ke li erarvagas sur la kampo; kaj la viro demandis lin: Kion vi serĉas?"],[37,16,"Kaj li diris: Miajn fratojn mi serĉas; diru al mi, kie ili paŝtas.","Kaj li diris: Miajn fratojn mi serĉas; diru al mi, kie ili paŝtas."],[37,17,"Kaj la viro diris: Ili foriris de ĉi tie; ĉar mi aŭdis, ke ili diris: Ni iru al Dotan. Kaj Jozef iris serĉi siajn fratojn, kaj trovis ilin en Dotan.","Kaj la viro diris: Ili foriris de ĉi tie; ĉar mi aŭdis, ke ili diris: Ni iru al Dotan. Kaj Jozef iris serĉi siajn fratojn, kaj trovis ilin en Dotan."],[37,18,"Kaj ili ekvidis lin de malproksime; kaj antaŭ ol li alproksimiĝis al ili, naskiĝis en ili la malbona intenco mortigi lin.","Kaj ili ekvidis lin de malproksime; kaj antaŭ ol li alproksimiĝis al ili, naskiĝis en ili la malbona intenco mortigi lin."],[37,19,"Kaj ili diris unu al alia: Jen tiu sonĝisto venas;","Kaj ili diris unu al alia: Jen tiu sonĝisto venas;"],[37,20,"nun ni iru kaj mortigu lin, kaj ni ĵetu lin en unu el la putoj, kaj ni diru, ke sovaĝa besto lin formanĝis; kaj ni vidos, kio fariĝos el liaj sonĝoj.","nun ni iru kaj mortigu lin, kaj ni ĵetu lin en unu el la putoj, kaj ni diru, ke sovaĝa besto lin formanĝis; kaj ni vidos, kio fariĝos el liaj sonĝoj."],[37,21,"Sed tion aŭdis Ruben kaj savis lin el iliaj manoj, kaj diris: Ni ne mortigu lin.","Sed tion aŭdis Ruben kaj savis lin el iliaj manoj, kaj diris: Ni ne mortigu lin."],[37,22,"Kaj Ruben diris al ili: Ne verŝu sangon; ĵetu lin en ĉi tiun puton, kiu estas en la dezerto, sed manon ne metu sur lin. Ĉar li intencis savi lin el iliaj manoj kaj revenigi lin al sia patro.","Kaj Ruben diris al ili: Ne verŝu sangon; ĵetu lin en ĉi tiun puton, kiu estas en la dezerto, sed manon ne metu sur lin. Ĉar li intencis savi lin el iliaj manoj kaj revenigi lin al sia patro."],[37,23,"Kaj kiam Jozef venis al siaj fratoj, ili deprenis de li lian veston, la mikskoloran veston, kiu estis sur li;","Kaj kiam Jozef venis al siaj fratoj, ili deprenis de li lian veston, la mikskoloran veston, kiu estis sur li;"],[37,24,"kaj ili prenis lin kaj ĵetis lin en la puton; sed la puto estis malplena, akvo ne estis en ĝi.","kaj ili prenis lin kaj ĵetis lin en la puton; sed la puto estis malplena, akvo ne estis en ĝi."],[37,25,"Kiam ili sidiĝis, por manĝi panon, ili levis siajn okulojn, kaj ekvidis, ke jen karavano da Iŝmaelidoj venas el Gilead, kaj iliaj kameloj portas aromaĵojn kaj balzamon kaj mirhon; ili iras, direktante sin al Egiptujo.","Kiam ili sidiĝis, por manĝi panon, ili levis siajn okulojn, kaj ekvidis, ke jen karavano da Iŝmaelidoj venas el Gilead, kaj iliaj kameloj portas aromaĵojn kaj balzamon kaj mirhon; ili iras, direktante sin al Egiptujo."],[37,26,"Kaj Jehuda diris al siaj fratoj: Kian profiton ni havos, se ni mortigos nian fraton kaj kaŝos lian sangon?","Kaj Jehuda diris al siaj fratoj: Kian profiton ni havos, se ni mortigos nian fraton kaj kaŝos lian sangon?"],[37,27,"Venu, ni vendos lin al la Iŝmaelidoj, por ke nia mano ne metiĝu sur lin; ĉar li estas nia frato, nia karno. Kaj liaj fratoj akceptis lian proponon.","Venu, ni vendos lin al la Iŝmaelidoj, por ke nia mano ne metiĝu sur lin; ĉar li estas nia frato, nia karno. Kaj liaj fratoj akceptis lian proponon."],[37,28,"Kaj kiam la Midjanidoj, la komercistoj, preteriris, ili eltiris kaj levis Jozefon el la puto kaj vendis Jozefon al la Iŝmaelidoj por dudek arĝentaj moneroj; kaj tiuj forkondukis Jozefon al Egiptujo.","Kaj kiam la Midjanidoj, la komercistoj, preteriris, ili eltiris kaj levis Jozefon el la puto kaj vendis Jozefon al la Iŝmaelidoj por dudek arĝentaj moneroj; kaj tiuj forkondukis Jozefon al Egiptujo."],[37,29,"Kiam Ruben revenis al la puto, li vidis, ke Jozef ne estas en la puto. Kaj li disŝiris siajn vestojn.","Kiam Ruben revenis al la puto, li vidis, ke Jozef ne estas en la puto. Kaj li disŝiris siajn vestojn."],[37,30,"Kaj li reiris al siaj fratoj, kaj diris: La knabo forestas, kaj kien mi nun iros?","Kaj li reiris al siaj fratoj, kaj diris: La knabo forestas, kaj kien mi nun iros?"],[37,31,"Kaj ili prenis la veston de Jozef kaj buĉis kapron kaj trempis la veston en la sango.","Kaj ili prenis la veston de Jozef kaj buĉis kapron kaj trempis la veston en la sango."],[37,32,"Kaj ili sendis la mikskoloran veston kaj venigis ĝin al sia patro, kaj dirigis: Ĉi tion ni trovis; rigardu, ĉu ĝi estas la vesto de via filo aŭ ne.","Kaj ili sendis la mikskoloran veston kaj venigis ĝin al sia patro, kaj dirigis: Ĉi tion ni trovis; rigardu, ĉu ĝi estas la vesto de via filo aŭ ne."],[37,33,"Kaj li rekonis ĝin, kaj diris: Ĝi estas la vesto de mia filo! sovaĝa besto lin formanĝis! disŝirita estas Jozef!","Kaj li rekonis ĝin, kaj diris: Ĝi estas la vesto de mia filo! sovaĝa besto lin formanĝis! disŝirita estas Jozef!"],[37,34,"Kaj Jakob disŝiris siajn vestojn kaj metis sakaĵon ĉirkaŭ sian lumbon kaj funebris pri sia filo multe da tagoj.","Kaj Jakob disŝiris siajn vestojn kaj metis sakaĵon ĉirkaŭ sian lumbon kaj funebris pri sia filo multe da tagoj."],[37,35,"Kaj ĉiuj liaj filoj kaj filinoj penis konsoli lin, sed li ne volis konsoliĝi, kaj diris: En funebro mi iros en Ŝeolon al mia filo. Tiel ploris pri li lia patro.","Kaj ĉiuj liaj filoj kaj filinoj penis konsoli lin, sed li ne volis konsoliĝi, kaj diris: En funebro mi iros en Ŝeolon al mia filo. Tiel ploris pri li lia patro."],[37,36,"Sed la Midjanidoj vendis lin en Egiptujo al Potifar, kortegano de Faraono, estro de la korpogardistoj.","Sed la Midjanidoj vendis lin en Egiptujo al Potifar, kortegano de Faraono, estro de la korpogardistoj."],[38,1,"En tiu tempo Jehuda apartiĝis for de siaj fratoj, kaj ekloĝis apud iu Adulamano, kiu estis nomata Ĥira.","En tiu tempo Jehuda apartiĝis for de siaj fratoj, kaj ekloĝis apud iu Adulamano, kiu estis nomata Ĥira."],[38,2,"Kaj Jehuda vidis tie filinon de iu Kanaanido, nomata Ŝua, kaj li prenis ŝin kaj envenis al ŝi.","Kaj Jehuda vidis tie filinon de iu Kanaanido, nomata Ŝua, kaj li prenis ŝin kaj envenis al ŝi."],[38,3,"Kaj ŝi gravediĝis kaj naskis filon; kaj li donis al li la nomon Er.","Kaj ŝi gravediĝis kaj naskis filon; kaj li donis al li la nomon Er."],[38,4,"Kaj ŝi denove gravediĝis kaj naskis filon, kaj ŝi donis al li la nomon Onan.","Kaj ŝi denove gravediĝis kaj naskis filon, kaj ŝi donis al li la nomon Onan."],[38,5,"Kaj ankoraŭ plue ŝi naskis filon, kaj donis al li la nomon Ŝela. Sed Jehuda estis en Kezib, kiam ŝi naskis tiun.","Kaj ankoraŭ plue ŝi naskis filon, kaj donis al li la nomon Ŝela. Sed Jehuda estis en Kezib, kiam ŝi naskis tiun."],[38,6,"Kaj Jehuda prenis edzinon por sia unuenaskito Er, kaj ŝia nomo estis Tamar.","Kaj Jehuda prenis edzinon por sia unuenaskito Er, kaj ŝia nomo estis Tamar."],[38,7,"Sed Er, la unuenaskito de Jehuda, estis malbona antaŭ la okuloj de la Eternulo, kaj la Eternulo lin mortigis.","Sed Er, la unuenaskito de Jehuda, estis malbona antaŭ la okuloj de la Eternulo, kaj la Eternulo lin mortigis."],[38,8,"Tiam Jehuda diris al Onan: Envenu al la edzino de via frato, kaj boedziĝu kun ŝi kaj naskigu idaron al via frato.","Tiam Jehuda diris al Onan: Envenu al la edzino de via frato, kaj boedziĝu kun ŝi kaj naskigu idaron al via frato."],[38,9,"Sed Onan sciis, ke ne por li estos la idaro; tial, envenante al la edzino de sia frato, li elverŝadis la semon sur la teron, por ne doni idaron al sia frato.","Sed Onan sciis, ke ne por li estos la idaro; tial, envenante al la edzino de sia frato, li elverŝadis la semon sur la teron, por ne doni idaron al sia frato."],[38,10,"Kaj malplaĉis al la Eternulo tio, kion li faris, kaj Li mortigis ankaŭ lin.","Kaj malplaĉis al la Eternulo tio, kion li faris, kaj Li mortigis ankaŭ lin."],[38,11,"Tiam Jehuda diris al sia bofilino Tamar: Restu kiel vidvino en la domo de via patro, ĝis grandiĝos mia filo Ŝela. Ĉar li timis, ke eble li ankaŭ mortos, kiel liaj fratoj. Kaj Tamar iris kaj ekloĝis en la domo de sia patro.","Tiam Jehuda diris al sia bofilino Tamar: Restu kiel vidvino en la domo de via patro, ĝis grandiĝos mia filo Ŝela. Ĉar li timis, ke eble li ankaŭ mortos, kiel liaj fratoj. Kaj Tamar iris kaj ekloĝis en la domo de sia patro."],[38,12,"Pasis multe da tempo, kaj mortis la filino de Ŝua, la edzino de Jehuda. Kiam Jehuda konsoliĝis, li iris Timnan, al la tondantoj de liaj ŝafoj, li kaj lia amiko, Ĥira la Adulamano.","Pasis multe da tempo, kaj mortis la filino de Ŝua, la edzino de Jehuda. Kiam Jehuda konsoliĝis, li iris Timnan, al la tondantoj de liaj ŝafoj, li kaj lia amiko, Ĥira la Adulamano."],[38,13,"Kaj oni sciigis al Tamar, dirante: Jen via bopatro iras Timnan, por tondi siajn ŝafojn.","Kaj oni sciigis al Tamar, dirante: Jen via bopatro iras Timnan, por tondi siajn ŝafojn."],[38,14,"Tiam ŝi demetis de si siajn vestojn de vidvineco kaj kovris sin per kovrotuko kaj vualis sin, kaj sidiĝis apud la pordo de Enaim, kiu troviĝas sur la vojo al Timna. Ĉar ŝi vidis, ke Ŝela grandiĝis kaj ŝi ne estas donita al li kiel edzino.","Tiam ŝi demetis de si siajn vestojn de vidvineco kaj kovris sin per kovrotuko kaj vualis sin, kaj sidiĝis apud la pordo de Enaim, kiu troviĝas sur la vojo al Timna. Ĉar ŝi vidis, ke Ŝela grandiĝis kaj ŝi ne estas donita al li kiel edzino."],[38,15,"Kaj Jehuda ŝin vidis, kaj li pensis, ke ŝi estas publikulino, ĉar ŝi kovris sian vizaĝon.","Kaj Jehuda ŝin vidis, kaj li pensis, ke ŝi estas publikulino, ĉar ŝi kovris sian vizaĝon."],[38,16,"Kaj li turnis sin al ŝi ĉe la vojo, kaj diris: Lasu min enveni al vi. Ĉar li ne sciis, ke tio estas lia bofilino. Kaj ŝi diris: Kion vi donos al mi, se vi envenos al mi?","Kaj li turnis sin al ŝi ĉe la vojo, kaj diris: Lasu min enveni al vi. Ĉar li ne sciis, ke tio estas lia bofilino. Kaj ŝi diris: Kion vi donos al mi, se vi envenos al mi?"],[38,17,"Kaj li diris: Mi sendos al vi kapron el la brutaro. Sed ŝi diris: Donu al mi garantiaĵon, ĝis vi sendos.","Kaj li diris: Mi sendos al vi kapron el la brutaro. Sed ŝi diris: Donu al mi garantiaĵon, ĝis vi sendos."],[38,18,"Kaj li diris: Kian garantiaĵon mi donu al vi? Ŝi diris: Vian sigelilon kaj vian ŝnureton, kaj vian bastonon, kiu estas en via mano. Kaj li donis al ŝi kaj envenis al ŝi, kaj ŝi gravediĝis de li.","Kaj li diris: Kian garantiaĵon mi donu al vi? Ŝi diris: Vian sigelilon kaj vian ŝnureton, kaj vian bastonon, kiu estas en via mano. Kaj li donis al ŝi kaj envenis al ŝi, kaj ŝi gravediĝis de li."],[38,19,"Kaj ŝi leviĝis kaj iris, kaj formetis de si sian kovrotukon kaj surmetis sur sin siajn vestojn de vidvineco.","Kaj ŝi leviĝis kaj iris, kaj formetis de si sian kovrotukon kaj surmetis sur sin siajn vestojn de vidvineco."],[38,20,"Kaj Jehuda sendis la kapron per sia amiko la Adulamano, por preni la garantiaĵon el la manoj de la virino; sed li ŝin ne trovis.","Kaj Jehuda sendis la kapron per sia amiko la Adulamano, por preni la garantiaĵon el la manoj de la virino; sed li ŝin ne trovis."],[38,21,"Kaj li demandis la homojn de ŝia loko, dirante: Kie estas la publikulino, kiu sidis en Enaim ĉe la vojo? Kaj ili diris: Ĉi tie ne estis publikulino.","Kaj li demandis la homojn de ŝia loko, dirante: Kie estas la publikulino, kiu sidis en Enaim ĉe la vojo? Kaj ili diris: Ĉi tie ne estis publikulino."],[38,22,"Kaj li revenis al Jehuda, kaj diris: Mi ŝin ne trovis, kaj ankaŭ la homoj de la loko diris, ke tie ne estis publikulino.","Kaj li revenis al Jehuda, kaj diris: Mi ŝin ne trovis, kaj ankaŭ la homoj de la loko diris, ke tie ne estis publikulino."],[38,23,"Tiam Jehuda diris: Ŝi prenu ĝin al si, por ke ni ne estu mokataj; mi sendis ja ĉi tiun kapron, sed vi ŝin ne trovis.","Tiam Jehuda diris: Ŝi prenu ĝin al si, por ke ni ne estu mokataj; mi sendis ja ĉi tiun kapron, sed vi ŝin ne trovis."],[38,24,"Post la paso de tri monatoj oni sciigis al Jehuda, dirante: Tamar, via bofilino, malĉastiĝis, kaj ŝi eĉ gravediĝis de malĉasteco. Tiam Jehuda diris: Elkonduku ŝin, kaj oni ŝin brulmortigu.","Post la paso de tri monatoj oni sciigis al Jehuda, dirante: Tamar, via bofilino, malĉastiĝis, kaj ŝi eĉ gravediĝis de malĉasteco. Tiam Jehuda diris: Elkonduku ŝin, kaj oni ŝin brulmortigu."],[38,25,"Kiam oni ŝin kondukis, ŝi sendis, ke oni diru al ŝia bopatro: Mi gravediĝis de la viro, al kiu apartenas ĉi tio. Kaj ŝi diris: Rekonu, al kiu apartenas la sigelilo kaj la ŝnuretoj kaj ĉi tiu bastono.","Kiam oni ŝin kondukis, ŝi sendis, ke oni diru al ŝia bopatro: Mi gravediĝis de la viro, al kiu apartenas ĉi tio. Kaj ŝi diris: Rekonu, al kiu apartenas la sigelilo kaj la ŝnuretoj kaj ĉi tiu bastono."],[38,26,"Kaj Jehuda rekonis, kaj li diris: Ŝi estas pli prava ol mi, ĉar mi ne donis ŝin al mia filo Ŝela. Kaj li ŝin ne plue konis.","Kaj Jehuda rekonis, kaj li diris: Ŝi estas pli prava ol mi, ĉar mi ne donis ŝin al mia filo Ŝela. Kaj li ŝin ne plue konis."],[38,27,"Kiam ŝi devis naski, montriĝis, ke ĝemeloj estas en ŝia ventro.","Kiam ŝi devis naski, montriĝis, ke ĝemeloj estas en ŝia ventro."],[38,28,"Kaj kiam ŝi estis naskanta, elŝoviĝis la mano de unu infano; kaj la akuŝistino prenis kaj alligis al la mano ruĝan fadenon, dirante: Ĉi tiu eliris la unua.","Kaj kiam ŝi estis naskanta, elŝoviĝis la mano de unu infano; kaj la akuŝistino prenis kaj alligis al la mano ruĝan fadenon, dirante: Ĉi tiu eliris la unua."],[38,29,"Sed kiam li retiris sian manon, eliris lia frato. Kaj ŝi diris: Kial vi faris por vi traŝiron? Kaj oni donis al li la nomon Perec.","Sed kiam li retiris sian manon, eliris lia frato. Kaj ŝi diris: Kial vi faris por vi traŝiron? Kaj oni donis al li la nomon Perec."],[38,30,"Poste eliris lia frato, kiu havis sur sia mano la ruĝan fadenon. Kaj oni donis al li la nomon Zeraĥ.","Poste eliris lia frato, kiu havis sur sia mano la ruĝan fadenon. Kaj oni donis al li la nomon Zeraĥ."],[39,1,"Jozef estis forkondukita en Egiptujon, kaj lin aĉetis Potifar, kortegano de Faraono, estro de la korpogardistoj, Egipto, el la manoj de la Iŝmaelidoj, kiuj venigis lin tien.","Jozef estis forkondukita en Egiptujon, kaj lin aĉetis Potifar, kortegano de Faraono, estro de la korpogardistoj, Egipto, el la manoj de la Iŝmaelidoj, kiuj venigis lin tien."],[39,2,"Kaj la Eternulo estis kun Jozef, kaj li estis sukcesulo; kaj li estis en la domo de sia sinjoro, la Egipto.","Kaj la Eternulo estis kun Jozef, kaj li estis sukcesulo; kaj li estis en la domo de sia sinjoro, la Egipto."],[39,3,"Kaj lia sinjoro vidis, ke la Eternulo estas kun li, kaj ke ĉion, kion li faras, la Eternulo sukcesigas en lia mano.","Kaj lia sinjoro vidis, ke la Eternulo estas kun li, kaj ke ĉion, kion li faras, la Eternulo sukcesigas en lia mano."],[39,4,"Kaj Jozef akiris lian favoron kaj servis lin; kaj li estrigis lin super sia domo, kaj transdonis en liajn manojn ĉion, kion li havis.","Kaj Jozef akiris lian favoron kaj servis lin; kaj li estrigis lin super sia domo, kaj transdonis en liajn manojn ĉion, kion li havis."],[39,5,"Kaj de tiu tempo, kiam li estrigis lin super sia domo, kaj super ĉio, kion li havis, la Eternulo benis la domon de la Egipto pro Jozef, kaj la beno de la Eternulo estis super ĉio, kion li havis, en la domo kaj sur la kampo.","Kaj de tiu tempo, kiam li estrigis lin super sia domo, kaj super ĉio, kion li havis, la Eternulo benis la domon de la Egipto pro Jozef, kaj la beno de la Eternulo estis super ĉio, kion li havis, en la domo kaj sur la kampo."],[39,6,"Kaj li lasis ĉion, kion li havis, en la manoj de Jozef, kaj li sciis pri nenio, krom nur pri la pano, kiun li manĝis. Kaj Jozef estis gracia kaj bela.","Kaj li lasis ĉion, kion li havis, en la manoj de Jozef, kaj li sciis pri nenio, krom nur pri la pano, kiun li manĝis. Kaj Jozef estis gracia kaj bela."],[39,7,"Post kelka tempo la edzino de lia sinjoro ĵetis siajn rigardojn sur Jozefon, kaj diris: Kuŝiĝu kun mi.","Post kelka tempo la edzino de lia sinjoro ĵetis siajn rigardojn sur Jozefon, kaj diris: Kuŝiĝu kun mi."],[39,8,"Sed li rifuzis, kaj li diris al la edzino de sia sinjoro: Jen, mia sinjoro kontrolas ĉe mi nenion en la domo, kaj ĉion, kion li havas, li transdonis en miajn manojn;","Sed li rifuzis, kaj li diris al la edzino de sia sinjoro: Jen, mia sinjoro kontrolas ĉe mi nenion en la domo, kaj ĉion, kion li havas, li transdonis en miajn manojn;"],[39,9,"neniu en ĉi tiu domo estas pli granda ol mi, kaj li retenis de mi nenion, krom vi, ĉar vi estas lia edzino. Kiel do mi faros ĉi tiun grandan malbonagon kaj pekos antaŭ Dio?","neniu en ĉi tiu domo estas pli granda ol mi, kaj li retenis de mi nenion, krom vi, ĉar vi estas lia edzino. Kiel do mi faros ĉi tiun grandan malbonagon kaj pekos antaŭ Dio?"],[39,10,"Dum ŝi paroladis al Jozef ĉiutage kaj li ne volis obei ŝin kaj kuŝiĝi kun ŝi kaj esti kun ŝi,","Dum ŝi paroladis al Jozef ĉiutage kaj li ne volis obei ŝin kaj kuŝiĝi kun ŝi kaj esti kun ŝi,"],[39,11,"okazis unu tagon, ke li venis en la domon, por fari sian laboron, kaj neniu el la domanoj estis en la domo;","okazis unu tagon, ke li venis en la domon, por fari sian laboron, kaj neniu el la domanoj estis en la domo;"],[39,12,"tiam ŝi kaptis lin je lia vesto, dirante: Kuŝiĝu kun mi. Sed li lasis sian veston en ŝiaj manoj kaj forkuris for el la domo.","tiam ŝi kaptis lin je lia vesto, dirante: Kuŝiĝu kun mi. Sed li lasis sian veston en ŝiaj manoj kaj forkuris for el la domo."],[39,13,"Kaj kiam ŝi vidis, ke li lasis sian veston en ŝia mano kaj forkuris el la domo,","Kaj kiam ŝi vidis, ke li lasis sian veston en ŝia mano kaj forkuris el la domo,"],[39,14,"ŝi vokis siajn domanojn, kaj diris al ili: Rigardu, li venigis al ni Hebreon, por moki nin; ĉi tiu venis al mi, por kuŝiĝi kun mi; sed mi ekkriis per laŭta voĉo;","ŝi vokis siajn domanojn, kaj diris al ili: Rigardu, li venigis al ni Hebreon, por moki nin; ĉi tiu venis al mi, por kuŝiĝi kun mi; sed mi ekkriis per laŭta voĉo;"],[39,15,"kaj kiam li aŭdis, ke mi ekkriis per laŭta voĉo, li lasis sian veston ĉe mi kaj forkuris for el la domo.","kaj kiam li aŭdis, ke mi ekkriis per laŭta voĉo, li lasis sian veston ĉe mi kaj forkuris for el la domo."],[39,16,"Kaj ŝi kuŝigis lian veston apud si, ĝis lia sinjoro venis en sian domon.","Kaj ŝi kuŝigis lian veston apud si, ĝis lia sinjoro venis en sian domon."],[39,17,"Kaj ŝi rakontis al li tion saman, dirante: La sklavo, la Hebreo, kiun vi venigis al ni, venis al mi, por petoli kun mi;","Kaj ŝi rakontis al li tion saman, dirante: La sklavo, la Hebreo, kiun vi venigis al ni, venis al mi, por petoli kun mi;"],[39,18,"sed kiam mi laŭte ekkriis, li lasis sian veston ĉe mi kaj elkuris el la domo.","sed kiam mi laŭte ekkriis, li lasis sian veston ĉe mi kaj elkuris el la domo."],[39,19,"Kiam lia sinjoro aŭdis la vortojn de sia edzino, kiujn ŝi diris al li, parolante: Tiel agis kun mi via sklavo — tiam li forte ekkoleris.","Kiam lia sinjoro aŭdis la vortojn de sia edzino, kiujn ŝi diris al li, parolante: Tiel agis kun mi via sklavo — tiam li forte ekkoleris."],[39,20,"Kaj la sinjoro de Jozef prenis lin kaj fordonis lin en malliberejon, en la lokon, kie la malliberuloj de la reĝo estis tenataj; kaj li estis tie en la malliberejo.","Kaj la sinjoro de Jozef prenis lin kaj fordonis lin en malliberejon, en la lokon, kie la malliberuloj de la reĝo estis tenataj; kaj li estis tie en la malliberejo."],[39,21,"Kaj la Eternulo estis kun Jozef kaj estis favorkora al li kaj havigis al li la favoron de la estro de la malliberejo.","Kaj la Eternulo estis kun Jozef kaj estis favorkora al li kaj havigis al li la favoron de la estro de la malliberejo."],[39,22,"Kaj la estro de la malliberejo transdonis en la manojn de Jozef ĉiujn malliberulojn, kiuj estis en la malliberejo; kaj ĉio, kion ili tie faris, estis farata sub lia kontrolo.","Kaj la estro de la malliberejo transdonis en la manojn de Jozef ĉiujn malliberulojn, kiuj estis en la malliberejo; kaj ĉio, kion ili tie faris, estis farata sub lia kontrolo."],[39,23,"La estro de la malliberejo rigardis nenion, kio estis sub lia disponado, ĉar la Eternulo estis kun li; kaj ĉion, kion li faris, la Eternulo sukcesigis.","La estro de la malliberejo rigardis nenion, kio estis sub lia disponado, ĉar la Eternulo estis kun li; kaj ĉion, kion li faris, la Eternulo sukcesigis."],[40,1,"Post tiuj okazintaĵoj la vinisto de la reĝo de Egiptujo kaj la bakisto kulpiĝis antaŭ sia sinjoro, la reĝo de Egiptujo.","Post tiuj okazintaĵoj la vinisto de la reĝo de Egiptujo kaj la bakisto kulpiĝis antaŭ sia sinjoro, la reĝo de Egiptujo."],[40,2,"Kaj Faraono koleriĝis kontraŭ siaj du korteganoj, kontraŭ la vinistestro kaj kontraŭ la bakistestro.","Kaj Faraono koleriĝis kontraŭ siaj du korteganoj, kontraŭ la vinistestro kaj kontraŭ la bakistestro."],[40,3,"Kaj li metis ilin sub gardon en la domon de la estro de la korpogardistoj, en la malliberejon, en la lokon, kie Jozef estis malliberigita.","Kaj li metis ilin sub gardon en la domon de la estro de la korpogardistoj, en la malliberejon, en la lokon, kie Jozef estis malliberigita."],[40,4,"Kaj la estro de la korpogardistoj destinis por ili Jozefon, kaj li servis ilin. Kaj ili restis kelkan tempon en la malliberejo.","Kaj la estro de la korpogardistoj destinis por ili Jozefon, kaj li servis ilin. Kaj ili restis kelkan tempon en la malliberejo."],[40,5,"Kaj ambaŭ sonĝis sonĝon, ĉiu sian apartan sonĝon en la sama nokto, ĉiu kun aparta signifo de la sonĝo, la vinisto kaj la bakisto de la reĝo de Egiptujo, kiuj estis tenataj en la malliberejo.","Kaj ambaŭ sonĝis sonĝon, ĉiu sian apartan sonĝon en la sama nokto, ĉiu kun aparta signifo de la sonĝo, la vinisto kaj la bakisto de la reĝo de Egiptujo, kiuj estis tenataj en la malliberejo."],[40,6,"Kiam Jozef venis al ili matene, li vidis, ke ili estas ĉagrenitaj.","Kiam Jozef venis al ili matene, li vidis, ke ili estas ĉagrenitaj."],[40,7,"Kaj li demandis la korteganojn de Faraono, kiuj estis kun li en malliberejo en la domo de lia sinjoro, dirante: Kial viaj vizaĝoj estas ĉagrenitaj hodiaŭ?","Kaj li demandis la korteganojn de Faraono, kiuj estis kun li en malliberejo en la domo de lia sinjoro, dirante: Kial viaj vizaĝoj estas ĉagrenitaj hodiaŭ?"],[40,8,"Kaj ili diris al li: Ni sonĝis sonĝon, sed estas ĉi tie neniu, kiu ĝin signifoklarigus. Kaj Jozef diris al ili: La signifoklarigoj apartenas ja al Dio; tamen rakontu al mi.","Kaj ili diris al li: Ni sonĝis sonĝon, sed estas ĉi tie neniu, kiu ĝin signifoklarigus. Kaj Jozef diris al ili: La signifoklarigoj apartenas ja al Dio; tamen rakontu al mi."],[40,9,"Tiam la vinistestro rakontis sian sonĝon al Jozef, kaj diris al li: En mia sonĝo mi vidis antaŭ mi vinbertrunkon;","Tiam la vinistestro rakontis sian sonĝon al Jozef, kaj diris al li: En mia sonĝo mi vidis antaŭ mi vinbertrunkon;"],[40,10,"la trunko havis tri branĉojn; apenaŭ ĝi ekfloris, tuj aperis sur ĝi beraroj kun maturaj beroj;","la trunko havis tri branĉojn; apenaŭ ĝi ekfloris, tuj aperis sur ĝi beraroj kun maturaj beroj;"],[40,11,"kaj la pokalo de Faraono estis en mia mano; kaj mi prenis la berojn, kaj mi elpremis ilin en la pokalon de Faraono, kaj mi donis la pokalon en la manon de Faraono.","kaj la pokalo de Faraono estis en mia mano; kaj mi prenis la berojn, kaj mi elpremis ilin en la pokalon de Faraono, kaj mi donis la pokalon en la manon de Faraono."],[40,12,"Kaj Jozef diris al li: Jen estas ĝia signifoklarigo: la tri branĉoj estas tri tagoj;","Kaj Jozef diris al li: Jen estas ĝia signifoklarigo: la tri branĉoj estas tri tagoj;"],[40,13,"post tri tagoj Faraono levos vian kapon kaj redonos al vi vian oficon, kaj vi donos la pokalon de Faraono en lian manon laŭ la maniero de antaŭe, kiam vi estis lia vinisto.","post tri tagoj Faraono levos vian kapon kaj redonos al vi vian oficon, kaj vi donos la pokalon de Faraono en lian manon laŭ la maniero de antaŭe, kiam vi estis lia vinisto."],[40,14,"Sed memoru min, kiam estos bone al vi, kaj faru al mi favorkoraĵon kaj memorigu pri mi Faraonon kaj elirigu min el ĉi tiu domo.","Sed memoru min, kiam estos bone al vi, kaj faru al mi favorkoraĵon kaj memorigu pri mi Faraonon kaj elirigu min el ĉi tiu domo."],[40,15,"Ĉar oni ŝtelis min el la lando de la Hebreoj, kaj ankaŭ ĉi tie mi faris nenion, pro kio oni metis min en la malliberejon.","Ĉar oni ŝtelis min el la lando de la Hebreoj, kaj ankaŭ ĉi tie mi faris nenion, pro kio oni metis min en la malliberejon."],[40,16,"Kiam la bakistestro vidis, ke la signifoklarigo estas bona, li diris al Jozef: Mi ankaŭ havis sonĝon; jen tri blankaj korboj estis sur mia kapo;","Kiam la bakistestro vidis, ke la signifoklarigo estas bona, li diris al Jozef: Mi ankaŭ havis sonĝon; jen tri blankaj korboj estis sur mia kapo;"],[40,17,"kaj en la supra korbo estis ĉiaspecaj manĝaĵoj de Faraono, bakitaĵoj, kaj la birdoj manĝis ilin el la korbo sur mia kapo.","kaj en la supra korbo estis ĉiaspecaj manĝaĵoj de Faraono, bakitaĵoj, kaj la birdoj manĝis ilin el la korbo sur mia kapo."],[40,18,"Kaj Jozef respondis, dirante: Jen estas ĝia signifoklarigo: la tri korboj estas tri tagoj;","Kaj Jozef respondis, dirante: Jen estas ĝia signifoklarigo: la tri korboj estas tri tagoj;"],[40,19,"post tri tagoj Faraono deprenos de vi vian kapon kaj pendigos vin sur arbo, kaj la birdoj formanĝos de vi vian karnon.","post tri tagoj Faraono deprenos de vi vian kapon kaj pendigos vin sur arbo, kaj la birdoj formanĝos de vi vian karnon."],[40,20,"En la tria tago, tago de naskiĝo de Faraono, li faris festenon por ĉiuj siaj servantoj; kaj li venigis la vinistestron kaj la bakistestron en la mezon de siaj servantoj.","En la tria tago, tago de naskiĝo de Faraono, li faris festenon por ĉiuj siaj servantoj; kaj li venigis la vinistestron kaj la bakistestron en la mezon de siaj servantoj."],[40,21,"Kaj li redonis al la vinistestro lian oficon, kaj tiu donis la pokalon en la manon de Faraono;","Kaj li redonis al la vinistestro lian oficon, kaj tiu donis la pokalon en la manon de Faraono;"],[40,22,"sed la bakistestron li pendigis, kiel sonĝoklarigis al ili Jozef.","sed la bakistestron li pendigis, kiel sonĝoklarigis al ili Jozef."],[40,23,"Kaj la vinistestro ne rememoris Jozefon, sed forgesis lin.","Kaj la vinistestro ne rememoris Jozefon, sed forgesis lin."],[41,1,"Post du jaroj Faraono havis sonĝon, ke jen li staras apud la Rivero.","Post du jaroj Faraono havis sonĝon, ke jen li staras apud la Rivero."],[41,2,"Kaj jen el la Rivero eliras sep bovinoj belaspektaj kaj grasaj, kaj ili paŝtiĝas en la kanejo.","Kaj jen el la Rivero eliras sep bovinoj belaspektaj kaj grasaj, kaj ili paŝtiĝas en la kanejo."],[41,3,"Kaj jen sep aliaj bovinoj eliras post ili el la Rivero, malbelaspektaj kaj malgrasaj, kaj ili stariĝas apud tiuj bovinoj sur la bordo de la Rivero.","Kaj jen sep aliaj bovinoj eliras post ili el la Rivero, malbelaspektaj kaj malgrasaj, kaj ili stariĝas apud tiuj bovinoj sur la bordo de la Rivero."],[41,4,"Kaj la bovinoj malbelaspektaj kaj malgrasaj formanĝis la sep bovinojn belaspektajn kaj grasajn. Kaj Faraono vekiĝis.","Kaj la bovinoj malbelaspektaj kaj malgrasaj formanĝis la sep bovinojn belaspektajn kaj grasajn. Kaj Faraono vekiĝis."],[41,5,"Kaj li endormiĝis kaj denove havis sonĝon: jen sep spikoj leviĝas sur unu spiktrunko, dikaj kaj bonaj.","Kaj li endormiĝis kaj denove havis sonĝon: jen sep spikoj leviĝas sur unu spiktrunko, dikaj kaj bonaj."],[41,6,"Sed jen sep spikoj, maldikaj kaj bruligitaj de la orienta vento, elkreskas post ili.","Sed jen sep spikoj, maldikaj kaj bruligitaj de la orienta vento, elkreskas post ili."],[41,7,"Kaj la maldikaj spikoj englutis la sep spikojn dikajn kaj plenajn. Kaj Faraono vekiĝis, kaj vidis, ke tio estis sonĝo.","Kaj la maldikaj spikoj englutis la sep spikojn dikajn kaj plenajn. Kaj Faraono vekiĝis, kaj vidis, ke tio estis sonĝo."],[41,8,"En la mateno lia spirito afliktiĝis; kaj li sendis kaj vokigis ĉiujn sorĉistojn de Egiptujo kaj ĉiujn ĝiajn saĝulojn, kaj Faraono rakontis al ili sian sonĝon; sed neniu povis signifoklarigi ĝin al Faraono.","En la mateno lia spirito afliktiĝis; kaj li sendis kaj vokigis ĉiujn sorĉistojn de Egiptujo kaj ĉiujn ĝiajn saĝulojn, kaj Faraono rakontis al ili sian sonĝon; sed neniu povis signifoklarigi ĝin al Faraono."],[41,9,"Tiam la vinistestro ekparolis al Faraono, dirante: Miajn pekojn mi rememoras hodiaŭ.","Tiam la vinistestro ekparolis al Faraono, dirante: Miajn pekojn mi rememoras hodiaŭ."],[41,10,"Faraono koleris siajn sklavojn, kaj metis min en malliberejon en la domon de la estro de la korpogardistoj, min kaj la bakistestron.","Faraono koleris siajn sklavojn, kaj metis min en malliberejon en la domon de la estro de la korpogardistoj, min kaj la bakistestron."],[41,11,"Kaj ni sonĝis sonĝon en unu nokto, mi kaj li; ĉiu havis sonĝon kun aparta signifo.","Kaj ni sonĝis sonĝon en unu nokto, mi kaj li; ĉiu havis sonĝon kun aparta signifo."],[41,12,"Kaj tie estis kun ni Hebrea junulo, sklavo de la estro de la korpogardistoj; kaj ni rakontis al li, kaj li signifoklarigis al ni niajn sonĝojn, al ĉiu li klarigis laŭ lia sonĝo.","Kaj tie estis kun ni Hebrea junulo, sklavo de la estro de la korpogardistoj; kaj ni rakontis al li, kaj li signifoklarigis al ni niajn sonĝojn, al ĉiu li klarigis laŭ lia sonĝo."],[41,13,"Kaj kiel li klarigis al ni, tiel fariĝis: min oni revenigis al mia ofico, kaj lin oni pendigis.","Kaj kiel li klarigis al ni, tiel fariĝis: min oni revenigis al mia ofico, kaj lin oni pendigis."],[41,14,"Tiam Faraono sendis alvoki Jozefon; kaj oni rapide eligis lin el la malliberejo, kaj li sin razis kaj ŝanĝis siajn vestojn kaj venis al Faraono.","Tiam Faraono sendis alvoki Jozefon; kaj oni rapide eligis lin el la malliberejo, kaj li sin razis kaj ŝanĝis siajn vestojn kaj venis al Faraono."],[41,15,"Kaj Faraono diris al Jozef: Mi sonĝis sonĝon, kaj neniu povas ĝin klarigi; sed pri vi mi aŭdis, ke kiam vi aŭdas sonĝon, vi tuj ĝin klarigas.","Kaj Faraono diris al Jozef: Mi sonĝis sonĝon, kaj neniu povas ĝin klarigi; sed pri vi mi aŭdis, ke kiam vi aŭdas sonĝon, vi tuj ĝin klarigas."],[41,16,"Kaj Jozef respondis al Faraono, dirante: Ĝi ne dependas de mi; Dio respondos bonon al Faraono.","Kaj Jozef respondis al Faraono, dirante: Ĝi ne dependas de mi; Dio respondos bonon al Faraono."],[41,17,"Kaj Faraono diris al Jozef: Mi sonĝis, ke jen mi staras sur la bordo de la Rivero;","Kaj Faraono diris al Jozef: Mi sonĝis, ke jen mi staras sur la bordo de la Rivero;"],[41,18,"kaj jen el la Rivero eliris sep bovinoj grasaj kaj belaspektaj kaj paŝtiĝis en la kanejo;","kaj jen el la Rivero eliris sep bovinoj grasaj kaj belaspektaj kaj paŝtiĝis en la kanejo;"],[41,19,"sed jen sep aliaj bovinoj eliris post ili, maldikaj, tre malbonaspektaj kaj malgrasaj; tiajn malbelajn, kiel ili, mi ne vidis en la tuta Egipta lando;","sed jen sep aliaj bovinoj eliris post ili, maldikaj, tre malbonaspektaj kaj malgrasaj; tiajn malbelajn, kiel ili, mi ne vidis en la tuta Egipta lando;"],[41,20,"kaj la malgrasaj kaj malbelaj bovinoj formanĝis la sep antaŭajn grasajn bovinojn;","kaj la malgrasaj kaj malbelaj bovinoj formanĝis la sep antaŭajn grasajn bovinojn;"],[41,21,"kaj tiuj eniĝis en ilian internon, sed oni ne povis rimarki, ke ili eniĝis en ilian internon, kaj ilia aspekto estis tiel maldika, kiel antaŭe. Kaj mi vekiĝis.","kaj tiuj eniĝis en ilian internon, sed oni ne povis rimarki, ke ili eniĝis en ilian internon, kaj ilia aspekto estis tiel maldika, kiel antaŭe. Kaj mi vekiĝis."],[41,22,"Kaj mi vidis en sonĝo: jen sep spikoj elkreskis sur unu spiktrunko, plenaj kaj bonaj;","Kaj mi vidis en sonĝo: jen sep spikoj elkreskis sur unu spiktrunko, plenaj kaj bonaj;"],[41,23,"sed jen sep spikoj, maldikaj, malgrasaj, kaj bruligitaj de la orienta vento, elkreskis post ili;","sed jen sep spikoj, maldikaj, malgrasaj, kaj bruligitaj de la orienta vento, elkreskis post ili;"],[41,24,"kaj la malgrasaj spikoj englutis la sep bonajn spikojn. Kaj mi rakontis al la sorĉistoj, sed neniu klarigis al mi.","kaj la malgrasaj spikoj englutis la sep bonajn spikojn. Kaj mi rakontis al la sorĉistoj, sed neniu klarigis al mi."],[41,25,"Tiam Jozef diris al Faraono: La sonĝo de Faraono estas unu; kion Dio estas faronta, Li diris al Faraono.","Tiam Jozef diris al Faraono: La sonĝo de Faraono estas unu; kion Dio estas faronta, Li diris al Faraono."],[41,26,"La sep bonaj bovinoj estas sep jaroj, kaj la sep bonaj spikoj estas sep jaroj; ĝi estas unu sonĝo.","La sep bonaj bovinoj estas sep jaroj, kaj la sep bonaj spikoj estas sep jaroj; ĝi estas unu sonĝo."],[41,27,"Kaj la sep bovinoj malgrasaj kaj malbelaj, kiuj eliris post ili, estas sep jaroj; kaj la sep spikoj, malplenaj kaj bruligitaj de la orienta vento, estos sep jaroj de malsato.","Kaj la sep bovinoj malgrasaj kaj malbelaj, kiuj eliris post ili, estas sep jaroj; kaj la sep spikoj, malplenaj kaj bruligitaj de la orienta vento, estos sep jaroj de malsato."],[41,28,"Tio estas, pri kio mi diris al Faraono, ke kion Dio estas faronta, Li montris al Faraono.","Tio estas, pri kio mi diris al Faraono, ke kion Dio estas faronta, Li montris al Faraono."],[41,29,"Jen venos sep jaroj de granda abundeco en la tuta Egipta lando.","Jen venos sep jaroj de granda abundeco en la tuta Egipta lando."],[41,30,"Sed venos sep jaroj de malsato post ili; kaj forgesiĝos la tuta abundeco en la Egipta lando, kaj la malsato konsumos la teron.","Sed venos sep jaroj de malsato post ili; kaj forgesiĝos la tuta abundeco en la Egipta lando, kaj la malsato konsumos la teron."],[41,31,"Kaj ne restos postesigno de la abundeco en la lando, pro tiu malsato, kiu venos poste, ĉar ĝi estos tre malfacila.","Kaj ne restos postesigno de la abundeco en la lando, pro tiu malsato, kiu venos poste, ĉar ĝi estos tre malfacila."],[41,32,"Kaj se la sonĝo dufoje ripetiĝis al Faraono, tio montras, ke la afero estas firme decidita de Dio, kaj Dio rapidos plenumi tion.","Kaj se la sonĝo dufoje ripetiĝis al Faraono, tio montras, ke la afero estas firme decidita de Dio, kaj Dio rapidos plenumi tion."],[41,33,"Kaj nun Faraono elserĉu homon kompetentan kaj saĝan kaj estrigu lin super la Egipta lando;","Kaj nun Faraono elserĉu homon kompetentan kaj saĝan kaj estrigu lin super la Egipta lando;"],[41,34,"Faraono ordonu, ke li starigu observistojn en la lando kaj prenadu kvinonon de ĉiuj produktoj de la Egipta tero dum la sep jaroj de abundeco.","Faraono ordonu, ke li starigu observistojn en la lando kaj prenadu kvinonon de ĉiuj produktoj de la Egipta tero dum la sep jaroj de abundeco."],[41,35,"Kaj oni kolektu la tutan manĝaĵon de tiuj venontaj bonaj jaroj, kaj oni amasigu manĝeblan grenon en la urboj sub la disponon de Faraono, kaj oni ĝin konservu.","Kaj oni kolektu la tutan manĝaĵon de tiuj venontaj bonaj jaroj, kaj oni amasigu manĝeblan grenon en la urboj sub la disponon de Faraono, kaj oni ĝin konservu."],[41,36,"Kaj tiu manĝaĵo estos provizo por la lando por la sep jaroj de malsato, kiuj estos en la Egipta lando, por ke la lando ne pereu de malsato.","Kaj tiu manĝaĵo estos provizo por la lando por la sep jaroj de malsato, kiuj estos en la Egipta lando, por ke la lando ne pereu de malsato."],[41,37,"Kaj tio plaĉis al Faraono kaj al ĉiuj liaj servantoj.","Kaj tio plaĉis al Faraono kaj al ĉiuj liaj servantoj."],[41,38,"Kaj Faraono diris al siaj servantoj: Ĉu ni povus trovi tian homon, kiel li, en kiu estas la spirito de Dio?","Kaj Faraono diris al siaj servantoj: Ĉu ni povus trovi tian homon, kiel li, en kiu estas la spirito de Dio?"],[41,39,"Kaj Faraono diris al Jozef: Ĉar Dio sciigis al vi ĉion ĉi tion, ne ekzistas kompetentulo kaj saĝulo tia, kiel vi.","Kaj Faraono diris al Jozef: Ĉar Dio sciigis al vi ĉion ĉi tion, ne ekzistas kompetentulo kaj saĝulo tia, kiel vi."],[41,40,"Vi estos super mia domo, kaj viajn vortojn obeos mia tuta popolo; nur per la trono mi estos pli alta ol vi.","Vi estos super mia domo, kaj viajn vortojn obeos mia tuta popolo; nur per la trono mi estos pli alta ol vi."],[41,41,"Kaj Faraono diris al Jozef: Vidu, mi estrigis vin super la tuta Egipta lando.","Kaj Faraono diris al Jozef: Vidu, mi estrigis vin super la tuta Egipta lando."],[41,42,"Kaj Faraono deprenis sian ringon de sia mano kaj metis ĝin sur la manon de Jozef; kaj li vestis lin per bisinaj vestoj kaj metis oran ĉenon sur lian kolon.","Kaj Faraono deprenis sian ringon de sia mano kaj metis ĝin sur la manon de Jozef; kaj li vestis lin per bisinaj vestoj kaj metis oran ĉenon sur lian kolon."],[41,43,"Kaj li veturigis lin sur sia dua ĉaro; kaj oni kriis antaŭ li: Genuiĝu! Kaj li estrigis lin super la tuta Egipta lando.","Kaj li veturigis lin sur sia dua ĉaro; kaj oni kriis antaŭ li: Genuiĝu! Kaj li estrigis lin super la tuta Egipta lando."],[41,44,"Kaj Faraono diris al Jozef: Mi estas Faraono; sed sen via ordono neniu levos sian manon aŭ sian piedon en la tuta Egipta lando.","Kaj Faraono diris al Jozef: Mi estas Faraono; sed sen via ordono neniu levos sian manon aŭ sian piedon en la tuta Egipta lando."],[41,45,"Kaj Faraono donis al Jozef la nomon Cafnat-Paneaĥ, kaj li donis al li kiel edzinon Asnaton, filinon de Poti-Fera, pastro el On. Kaj Jozef komencis veturadon tra la Egipta lando.","Kaj Faraono donis al Jozef la nomon Cafnat-Paneaĥ, kaj li donis al li kiel edzinon Asnaton, filinon de Poti-Fera, pastro el On. Kaj Jozef komencis veturadon tra la Egipta lando."],[41,46,"Jozef havis la aĝon de tridek jaroj, kiam li stariĝis antaŭ Faraono, la reĝo de Egiptujo. Kaj Jozef foriris de Faraono kaj trapasis la tutan Egiptan landon.","Jozef havis la aĝon de tridek jaroj, kiam li stariĝis antaŭ Faraono, la reĝo de Egiptujo. Kaj Jozef foriris de Faraono kaj trapasis la tutan Egiptan landon."],[41,47,"Kaj la tero alportis en la sep jaroj de abundeco grandegajn amasojn da greno.","Kaj la tero alportis en la sep jaroj de abundeco grandegajn amasojn da greno."],[41,48,"Kaj li kolektis la tutan grenon de la sep jaroj, kiuj estis en la Egipta lando, kaj li metis la grenon en la urbojn; la grenon de ĉiuj kampoj, kiuj estis ĉirkaŭ iu urbo, li metis en ĝin.","Kaj li kolektis la tutan grenon de la sep jaroj, kiuj estis en la Egipta lando, kaj li metis la grenon en la urbojn; la grenon de ĉiuj kampoj, kiuj estis ĉirkaŭ iu urbo, li metis en ĝin."],[41,49,"Kaj Jozef kolektis tre multe da greno, kiel la marborda sablo, ĝis li ĉesis kalkuli, ĉar oni ne plu povis kalkuli.","Kaj Jozef kolektis tre multe da greno, kiel la marborda sablo, ĝis li ĉesis kalkuli, ĉar oni ne plu povis kalkuli."],[41,50,"Antaŭ ol venis la jaroj de malsato, al Jozef naskiĝis du filoj, kiujn naskis al li Asnat, filino de Poti-Fera, pastro el On.","Antaŭ ol venis la jaroj de malsato, al Jozef naskiĝis du filoj, kiujn naskis al li Asnat, filino de Poti-Fera, pastro el On."],[41,51,"Kaj al la unuenaskito Jozef donis la nomon Manase, ĉar, li diris, Dio forgesigis al mi ĉiujn miajn suferojn kaj la tutan domon de mia patro.","Kaj al la unuenaskito Jozef donis la nomon Manase, ĉar, li diris, Dio forgesigis al mi ĉiujn miajn suferojn kaj la tutan domon de mia patro."],[41,52,"Kaj al la dua li donis la nomon Efraim, ĉar, li diris, Dio faris min fruktoporta en la lando de mia suferado.","Kaj al la dua li donis la nomon Efraim, ĉar, li diris, Dio faris min fruktoporta en la lando de mia suferado."],[41,53,"Kaj finiĝis la sep jaroj de abundeco, kiuj estis en la Egipta lando.","Kaj finiĝis la sep jaroj de abundeco, kiuj estis en la Egipta lando."],[41,54,"Kaj komenciĝis la sep jaroj de malsato, kiel diris Jozef; kaj estis malsato en ĉiuj landoj, sed en la tuta lando Egipta estis pano.","Kaj komenciĝis la sep jaroj de malsato, kiel diris Jozef; kaj estis malsato en ĉiuj landoj, sed en la tuta lando Egipta estis pano."],[41,55,"Kiam la tuta Egipta lando eksuferis malsaton, la popolo kriis al Faraono pri pano; tiam Faraono diris al ĉiuj Egiptoj: Iru al Jozef, kaj kion li diros al vi, tion faru.","Kiam la tuta Egipta lando eksuferis malsaton, la popolo kriis al Faraono pri pano; tiam Faraono diris al ĉiuj Egiptoj: Iru al Jozef, kaj kion li diros al vi, tion faru."],[41,56,"La malsato estis en la tuta lando. Jozef malfermis ĉiujn grenejojn, kaj vendadis al la Egiptoj. Kaj la malsato estis tre granda en la Egipta lando.","La malsato estis en la tuta lando. Jozef malfermis ĉiujn grenejojn, kaj vendadis al la Egiptoj. Kaj la malsato estis tre granda en la Egipta lando."],[41,57,"Kaj el ĉiuj landoj oni venadis Egiptujon, por aĉeti de Jozef, ĉar la malsato estis tre granda en ĉiuj landoj.","Kaj el ĉiuj landoj oni venadis Egiptujon, por aĉeti de Jozef, ĉar la malsato estis tre granda en ĉiuj landoj."],[42,1,"Kiam Jakob sciiĝis, ke oni vendas grenon en Egiptujo, li diris al siaj filoj: Kion vi rigardas?","Kiam Jakob sciiĝis, ke oni vendas grenon en Egiptujo, li diris al siaj filoj: Kion vi rigardas?"],[42,2,"Kaj li diris: Mi aŭdis, ke oni vendas grenon en Egiptujo; veturu do tien kaj aĉetu por ni tie grenon, por ke ni vivu kaj ne mortu.","Kaj li diris: Mi aŭdis, ke oni vendas grenon en Egiptujo; veturu do tien kaj aĉetu por ni tie grenon, por ke ni vivu kaj ne mortu."],[42,3,"Kaj forveturis dek fratoj de Jozef, por aĉeti grenon en Egiptujo.","Kaj forveturis dek fratoj de Jozef, por aĉeti grenon en Egiptujo."],[42,4,"Sed Benjamenon, la fraton de Jozef, Jakob ne sendis kun liaj fratoj; ĉar li timis, ke eble lin trafos malfeliĉo.","Sed Benjamenon, la fraton de Jozef, Jakob ne sendis kun liaj fratoj; ĉar li timis, ke eble lin trafos malfeliĉo."],[42,5,"Kaj la filoj de Izrael venis, por aĉeti grenon, kune kun aliaj venintoj; ĉar estis malsato en la lando Kanaana.","Kaj la filoj de Izrael venis, por aĉeti grenon, kune kun aliaj venintoj; ĉar estis malsato en la lando Kanaana."],[42,6,"Kaj Jozef estis la estro super la lando, kaj li estis la vendanto de la greno por la tuta popolo de la lando. Kaj la fratoj de Jozef venis kaj kliniĝis al li vizaĝaltere.","Kaj Jozef estis la estro super la lando, kaj li estis la vendanto de la greno por la tuta popolo de la lando. Kaj la fratoj de Jozef venis kaj kliniĝis al li vizaĝaltere."],[42,7,"Kiam Jozef ekvidis siajn fratojn, li rekonis ilin; sed li ŝajnigis sin fremda al ili kaj parolis kun ili malafable, kaj diris al ili: El kie vi venis? Kaj ili diris: El la lando Kanaana, por aĉeti manĝaĵon.","Kiam Jozef ekvidis siajn fratojn, li rekonis ilin; sed li ŝajnigis sin fremda al ili kaj parolis kun ili malafable, kaj diris al ili: El kie vi venis? Kaj ili diris: El la lando Kanaana, por aĉeti manĝaĵon."],[42,8,"Jozef rekonis siajn fratojn, sed ili lin ne rekonis.","Jozef rekonis siajn fratojn, sed ili lin ne rekonis."],[42,9,"Kaj Jozef rememoris la sonĝojn, kiujn li sonĝis pri ili. Kaj li diris al ili: Vi estas spionoj: vi venis, por vidi la malfortajn lokojn de la lando.","Kaj Jozef rememoris la sonĝojn, kiujn li sonĝis pri ili. Kaj li diris al ili: Vi estas spionoj: vi venis, por vidi la malfortajn lokojn de la lando."],[42,10,"Kaj ili diris al li: Ne, mia sinjoro! viaj sklavoj venis, por aĉeti manĝaĵon.","Kaj ili diris al li: Ne, mia sinjoro! viaj sklavoj venis, por aĉeti manĝaĵon."],[42,11,"Ni ĉiuj estas filoj de unu homo; ni estas honestaj; viaj sklavoj neniam estis spionoj.","Ni ĉiuj estas filoj de unu homo; ni estas honestaj; viaj sklavoj neniam estis spionoj."],[42,12,"Sed li diris al ili: Ne, vi venis, por vidi la malfortajn lokojn de la lando.","Sed li diris al ili: Ne, vi venis, por vidi la malfortajn lokojn de la lando."],[42,13,"Ili diris: Ni, viaj sklavoj, estas dek du fratoj, filoj de unu homo en la lando Kanaana; la plej juna estas nun kun nia patro, kaj unu malaperis.","Ili diris: Ni, viaj sklavoj, estas dek du fratoj, filoj de unu homo en la lando Kanaana; la plej juna estas nun kun nia patro, kaj unu malaperis."],[42,14,"Kaj Jozef diris al ili: Estas tio, kion mi diris al vi, vi estas spionoj.","Kaj Jozef diris al ili: Estas tio, kion mi diris al vi, vi estas spionoj."],[42,15,"Per tio mi vin elprovos: mi ĵuras per la vivo de Faraono, ke vi foriros el ĉi tie nur tiam, kiam venos ĉi tien via plej juna frato.","Per tio mi vin elprovos: mi ĵuras per la vivo de Faraono, ke vi foriros el ĉi tie nur tiam, kiam venos ĉi tien via plej juna frato."],[42,16,"Sendu unu el vi, ke li alkonduku vian fraton; sed vi estos malliberigitaj, kaj oni esploros viajn vortojn, ĉu vi diris la veron; se ne, tiam mi ĵuras per la vivo de Faraono, ke vi estas spionoj.","Sendu unu el vi, ke li alkonduku vian fraton; sed vi estos malliberigitaj, kaj oni esploros viajn vortojn, ĉu vi diris la veron; se ne, tiam mi ĵuras per la vivo de Faraono, ke vi estas spionoj."],[42,17,"Kaj li metis ilin sub gardon por la daŭro de tri tagoj.","Kaj li metis ilin sub gardon por la daŭro de tri tagoj."],[42,18,"Kaj Jozef diris al ili en la tria tago: Tion faru, kaj vi restos vivaj, ĉar mi havas timon antaŭ Dio.","Kaj Jozef diris al ili en la tria tago: Tion faru, kaj vi restos vivaj, ĉar mi havas timon antaŭ Dio."],[42,19,"Se vi estas homoj honestaj, tiam unu el viaj fratoj restu malliberigita en la domo, en kiu oni vin gardas, kaj vi iru kaj forportu hejmen la grenon, kiun vi aĉetis kontraŭ la malsato.","Se vi estas homoj honestaj, tiam unu el viaj fratoj restu malliberigita en la domo, en kiu oni vin gardas, kaj vi iru kaj forportu hejmen la grenon, kiun vi aĉetis kontraŭ la malsato."],[42,20,"Sed vian plej junan fraton venigu al mi, por ke pruviĝu la vereco de viaj vortoj kaj por ke vi ne mortu. Kaj ili faris tiel.","Sed vian plej junan fraton venigu al mi, por ke pruviĝu la vereco de viaj vortoj kaj por ke vi ne mortu. Kaj ili faris tiel."],[42,21,"Kaj ili diris unu al alia: Vere ni estas kulpaj pro nia frato; ĉar ni vidis la suferadon de lia animo, kiam li petegis nin, sed ni ne aŭskultis; por tio venis sur nin ĉi tiu sufero.","Kaj ili diris unu al alia: Vere ni estas kulpaj pro nia frato; ĉar ni vidis la suferadon de lia animo, kiam li petegis nin, sed ni ne aŭskultis; por tio venis sur nin ĉi tiu sufero."],[42,22,"Kaj Ruben respondis al ili, dirante: Mi diris ja al vi: Ne peku rilate la infanon; sed vi ne obeis; nun lia sango estas repostulata.","Kaj Ruben respondis al ili, dirante: Mi diris ja al vi: Ne peku rilate la infanon; sed vi ne obeis; nun lia sango estas repostulata."],[42,23,"Kaj ili ne sciis, ke Jozef komprenas; ĉar inter ili estis tradukanto.","Kaj ili ne sciis, ke Jozef komprenas; ĉar inter ili estis tradukanto."],[42,24,"Kaj li deturnis sin de ili kaj ekploris; poste li denove returnis sin al ili kaj parolis kun ili, kaj li prenis el inter ili Simeonon kaj ligis lin antaŭ iliaj okuloj.","Kaj li deturnis sin de ili kaj ekploris; poste li denove returnis sin al ili kaj parolis kun ili, kaj li prenis el inter ili Simeonon kaj ligis lin antaŭ iliaj okuloj."],[42,25,"Kaj Jozef ordonis plenigi iliajn sakojn per greno kaj redoni ilian monon al ĉiu en lian sakon kaj doni al ili manĝaĵon por la vojo. Tiel oni faris al ili.","Kaj Jozef ordonis plenigi iliajn sakojn per greno kaj redoni ilian monon al ĉiu en lian sakon kaj doni al ili manĝaĵon por la vojo. Tiel oni faris al ili."],[42,26,"Kaj ili metis sian grenon sur siajn azenojn kaj foriris.","Kaj ili metis sian grenon sur siajn azenojn kaj foriris."],[42,27,"Kaj unu el ili malfermis sian sakon, por doni furaĝon al sia azeno dum la nokta halto, kaj li ekvidis sian monon, kiu estis en la aperturo de lia sako.","Kaj unu el ili malfermis sian sakon, por doni furaĝon al sia azeno dum la nokta halto, kaj li ekvidis sian monon, kiu estis en la aperturo de lia sako."],[42,28,"Kaj li diris al siaj fratoj: Mia mono estas redonita; jen ĝi estas en mia sako. Tiam konsterniĝis iliaj koroj, kaj kun tremo ili diris unuj al la aliaj: Kial Dio faris tion al ni?","Kaj li diris al siaj fratoj: Mia mono estas redonita; jen ĝi estas en mia sako. Tiam konsterniĝis iliaj koroj, kaj kun tremo ili diris unuj al la aliaj: Kial Dio faris tion al ni?"],[42,29,"Kiam ili venis al sia patro Jakob en la landon Kanaanan, ili rakontis al li ĉion, kio okazis al ili, dirante:","Kiam ili venis al sia patro Jakob en la landon Kanaanan, ili rakontis al li ĉion, kio okazis al ili, dirante:"],[42,30,"La homo, kiu estas sinjoro super tiu lando, parolis kun ni malafable, kaj diris, ke ni estas spionoj en la lando.","La homo, kiu estas sinjoro super tiu lando, parolis kun ni malafable, kaj diris, ke ni estas spionoj en la lando."],[42,31,"Kaj ni diris al li: Ni estas homoj honestaj, ni neniam estis spionoj;","Kaj ni diris al li: Ni estas homoj honestaj, ni neniam estis spionoj;"],[42,32,"ni estas dek du fratoj, filoj de nia patro; unu malaperis, kaj la plej juna estas nun kun nia patro en la lando Kanaana.","ni estas dek du fratoj, filoj de nia patro; unu malaperis, kaj la plej juna estas nun kun nia patro en la lando Kanaana."],[42,33,"Tiam diris al ni la homo, kiu estas sinjoro super la lando: Per tio mi konvinkiĝos, ke vi estas homoj honestaj: unu el viaj fratoj lasu ĉe mi, kaj la necesan grenon por via hejmo prenu kaj iru;","Tiam diris al ni la homo, kiu estas sinjoro super la lando: Per tio mi konvinkiĝos, ke vi estas homoj honestaj: unu el viaj fratoj lasu ĉe mi, kaj la necesan grenon por via hejmo prenu kaj iru;"],[42,34,"kaj venigu al mi vian plej junan fraton; tiam mi scios, ke vi ne estas spionoj, ke vi estas honestaj homoj; vian fraton mi redonos al vi, kaj vi povos negoci en la lando.","kaj venigu al mi vian plej junan fraton; tiam mi scios, ke vi ne estas spionoj, ke vi estas honestaj homoj; vian fraton mi redonos al vi, kaj vi povos negoci en la lando."],[42,35,"Kiam ili malplenigis siajn sakojn, montriĝis, ke ĉiu el ili havas sian ligaĵon da mono en sia sako. Kaj ili vidis siajn ligaĵojn da mono, ili kaj ilia patro, kaj ili timiĝis.","Kiam ili malplenigis siajn sakojn, montriĝis, ke ĉiu el ili havas sian ligaĵon da mono en sia sako. Kaj ili vidis siajn ligaĵojn da mono, ili kaj ilia patro, kaj ili timiĝis."],[42,36,"Kaj ilia patro Jakob diris al ili: Vi min seninfanigis; Jozef forestas, kaj Simeon forestas, kaj Benjamenon vi volas forpreni! sur min ĉio falis!","Kaj ilia patro Jakob diris al ili: Vi min seninfanigis; Jozef forestas, kaj Simeon forestas, kaj Benjamenon vi volas forpreni! sur min ĉio falis!"],[42,37,"Tiam Ruben diris al sia patro jene: Miajn du filojn mortigu, se mi ne revenigos lin al vi; donu lin en mian manon, kaj mi revenigos lin al vi.","Tiam Ruben diris al sia patro jene: Miajn du filojn mortigu, se mi ne revenigos lin al vi; donu lin en mian manon, kaj mi revenigos lin al vi."],[42,38,"Sed li diris: Mia filo ne iros kun vi; ĉar lia frato mortis, kaj li sola restis. Se lin trafos malfeliĉo sur la vojo, kiun vi iros, tiam vi enirigos miajn grizajn harojn kun malĝojo en Ŝeolon.","Sed li diris: Mia filo ne iros kun vi; ĉar lia frato mortis, kaj li sola restis. Se lin trafos malfeliĉo sur la vojo, kiun vi iros, tiam vi enirigos miajn grizajn harojn kun malĝojo en Ŝeolon."],[43,1,"La malsato estis tre premanta en la lando.","La malsato estis tre premanta en la lando."],[43,2,"Kiam ili formanĝis la grenon, kiun ili venigis el Egiptujo, ilia patro diris al ili: Iru denove kaj aĉetu por ni iom da pano.","Kiam ili formanĝis la grenon, kiun ili venigis el Egiptujo, ilia patro diris al ili: Iru denove kaj aĉetu por ni iom da pano."],[43,3,"Tiam Jehuda diris al li jene: Tiu homo tre severe diris al ni: Ne aperu antaŭ mi, se via frato ne estos kun vi.","Tiam Jehuda diris al li jene: Tiu homo tre severe diris al ni: Ne aperu antaŭ mi, se via frato ne estos kun vi."],[43,4,"Se vi sendos nian fraton kun ni, tiam ni iros kaj aĉetos por vi panon;","Se vi sendos nian fraton kun ni, tiam ni iros kaj aĉetos por vi panon;"],[43,5,"sed se vi ne sendos, tiam ni ne iros; ĉar tiu homo diris al ni: Ne aperu antaŭ mi, se via frato ne estos kun vi.","sed se vi ne sendos, tiam ni ne iros; ĉar tiu homo diris al ni: Ne aperu antaŭ mi, se via frato ne estos kun vi."],[43,6,"Kaj Izrael diris: Kial vi faris al mi tian malbonon, kaj diris al la homo, ke vi havas ankoraŭ fraton?","Kaj Izrael diris: Kial vi faris al mi tian malbonon, kaj diris al la homo, ke vi havas ankoraŭ fraton?"],[43,7,"Kaj ili diris: La homo severe demandis pri ni kaj pri nia familio, dirante: Ĉu via patro ankoraŭ vivas? ĉu vi havas fraton? Kaj ni respondis al li tiujn demandojn. Ĉu ni povis scii, ke li diros: Venigu vian fraton?","Kaj ili diris: La homo severe demandis pri ni kaj pri nia familio, dirante: Ĉu via patro ankoraŭ vivas? ĉu vi havas fraton? Kaj ni respondis al li tiujn demandojn. Ĉu ni povis scii, ke li diros: Venigu vian fraton?"],[43,8,"Kaj Jehuda diris al sia patro Izrael: Sendu la knabon kun mi, tiam ni leviĝos kaj iros, por ke ni vivu kaj ne mortu, ni kaj vi kaj niaj infanoj.","Kaj Jehuda diris al sia patro Izrael: Sendu la knabon kun mi, tiam ni leviĝos kaj iros, por ke ni vivu kaj ne mortu, ni kaj vi kaj niaj infanoj."],[43,9,"Mi garantios por li, el miaj manoj vi lin postulos. Se mi ne revenigos lin al vi kaj ne starigos antaŭ via vizaĝo, tiam mi estos kulpa antaŭ vi dum la tuta vivo.","Mi garantios por li, el miaj manoj vi lin postulos. Se mi ne revenigos lin al vi kaj ne starigos antaŭ via vizaĝo, tiam mi estos kulpa antaŭ vi dum la tuta vivo."],[43,10,"Se ni ne prokrastus, ni jam du fojojn estus revenintaj.","Se ni ne prokrastus, ni jam du fojojn estus revenintaj."],[43,11,"Tiam diris al ili ilia patro Izrael: Se estas tiel, tiam faru jene: prenu el la plej bonaj fruktoj de la lando en viajn vazojn, kaj alportu al la homo donacon: iom da balzamo kaj iom da mielo, aromaĵon kaj mirhon, pistakojn kaj migdalojn.","Tiam diris al ili ilia patro Izrael: Se estas tiel, tiam faru jene: prenu el la plej bonaj fruktoj de la lando en viajn vazojn, kaj alportu al la homo donacon: iom da balzamo kaj iom da mielo, aromaĵon kaj mirhon, pistakojn kaj migdalojn."],[43,12,"Kaj da mono prenu duoblan sumon en viajn manojn, kaj la monon, kiu estis metita returne en la aperturojn de viaj sakoj, redonu per viaj manoj: eble okazis eraro.","Kaj da mono prenu duoblan sumon en viajn manojn, kaj la monon, kiu estis metita returne en la aperturojn de viaj sakoj, redonu per viaj manoj: eble okazis eraro."],[43,13,"Kaj vian fraton prenu, kaj leviĝu kaj iru returne al tiu homo.","Kaj vian fraton prenu, kaj leviĝu kaj iru returne al tiu homo."],[43,14,"Kaj Dio la Plejpotenca akirigu al vi kompaton de tiu homo, ke li resendu kun vi vian alian fraton kaj Benjamenon; sed mi, se mi seninfaniĝis, mi restu seninfana.","Kaj Dio la Plejpotenca akirigu al vi kompaton de tiu homo, ke li resendu kun vi vian alian fraton kaj Benjamenon; sed mi, se mi seninfaniĝis, mi restu seninfana."],[43,15,"Kaj la homoj prenis tiujn donacojn, kaj da mono ili prenis duoblan sumon en siajn manojn, kaj ankaŭ Benjamenon; kaj ili leviĝis kaj iris Egiptujon kaj stariĝis antaŭ Jozef.","Kaj la homoj prenis tiujn donacojn, kaj da mono ili prenis duoblan sumon en siajn manojn, kaj ankaŭ Benjamenon; kaj ili leviĝis kaj iris Egiptujon kaj stariĝis antaŭ Jozef."],[43,16,"Kiam Jozef vidis kun ili Benjamenon, li diris al la estro de sia domo: Enkonduku tiujn homojn en la domon, kaj buĉu bruton kaj pretigu; ĉar kun mi manĝos tiuj homoj hodiaŭ tagmeze.","Kiam Jozef vidis kun ili Benjamenon, li diris al la estro de sia domo: Enkonduku tiujn homojn en la domon, kaj buĉu bruton kaj pretigu; ĉar kun mi manĝos tiuj homoj hodiaŭ tagmeze."],[43,17,"Kaj la homo faris, kiel diris Jozef, kaj la homo enkondukis tiujn homojn en la domon de Jozef.","Kaj la homo faris, kiel diris Jozef, kaj la homo enkondukis tiujn homojn en la domon de Jozef."],[43,18,"Kaj tiuj homoj ektimis, kiam oni enkondukis ilin en la domon de Jozef, kaj ili diris: Pro la mono, kiu antaŭe estis metita returne en niajn sakojn, oni enkondukis nin, por ĵeti sur nin kalumnion kaj ataki nin, kaj preni nin kiel sklavojn kune kun niaj azenoj.","Kaj tiuj homoj ektimis, kiam oni enkondukis ilin en la domon de Jozef, kaj ili diris: Pro la mono, kiu antaŭe estis metita returne en niajn sakojn, oni enkondukis nin, por ĵeti sur nin kalumnion kaj ataki nin, kaj preni nin kiel sklavojn kune kun niaj azenoj."],[43,19,"Kaj ili aliris al la homo, kiu estis estro super la domo de Jozef, kaj ekparolis al li ĉe la pordo de la domo.","Kaj ili aliris al la homo, kiu estis estro super la domo de Jozef, kaj ekparolis al li ĉe la pordo de la domo."],[43,20,"Kaj ili diris: Pardonu, nia sinjoro! ni estis venintaj, por aĉeti panon;","Kaj ili diris: Pardonu, nia sinjoro! ni estis venintaj, por aĉeti panon;"],[43,21,"sed kiam ni venis al la noktohaltejo kaj ni malfermis niajn sakojn, ni ekvidis, ke la mono de ĉiu el ni estas en la aperturo de lia sako, nia mono laŭ ĝia plena pezo; tial ni ĝin realportis per niaj manoj.","sed kiam ni venis al la noktohaltejo kaj ni malfermis niajn sakojn, ni ekvidis, ke la mono de ĉiu el ni estas en la aperturo de lia sako, nia mono laŭ ĝia plena pezo; tial ni ĝin realportis per niaj manoj."],[43,22,"Kaj alian monon ni alportis per niaj manoj, por aĉeti panon. Ni ne scias, kiu metis nian monon en niajn sakojn.","Kaj alian monon ni alportis per niaj manoj, por aĉeti panon. Ni ne scias, kiu metis nian monon en niajn sakojn."],[43,23,"Kaj li diris: Estu trankvilaj, ne timu. Via Dio kaj la Dio de via patro donis al vi trezoron en viajn sakojn; vian monon mi ricevis. Kaj li elkondukis al ili Simeonon.","Kaj li diris: Estu trankvilaj, ne timu. Via Dio kaj la Dio de via patro donis al vi trezoron en viajn sakojn; vian monon mi ricevis. Kaj li elkondukis al ili Simeonon."],[43,24,"Kaj tiu homo enkondukis ilin en la domon de Jozef kaj donis akvon, kaj ili lavis siajn piedojn; kaj li donis manĝon al iliaj azenoj.","Kaj tiu homo enkondukis ilin en la domon de Jozef kaj donis akvon, kaj ili lavis siajn piedojn; kaj li donis manĝon al iliaj azenoj."],[43,25,"Kaj ili pretigis la donacojn por la veno de Jozef tagmeze; ĉar ili aŭdis, ke tie ili manĝos panon.","Kaj ili pretigis la donacojn por la veno de Jozef tagmeze; ĉar ili aŭdis, ke tie ili manĝos panon."],[43,26,"Kaj Jozef venis hejmen; kaj ili alportis al li en la domon la donacojn, kiujn ili havis en la manoj, kaj kliniĝis al li ĝis la tero.","Kaj Jozef venis hejmen; kaj ili alportis al li en la domon la donacojn, kiujn ili havis en la manoj, kaj kliniĝis al li ĝis la tero."],[43,27,"Kaj li demandis ilin pri ilia farto, kaj diris: Ĉu bone fartas via maljuna patro, pri kiu vi diris al mi? ĉu li vivas ankoraŭ?","Kaj li demandis ilin pri ilia farto, kaj diris: Ĉu bone fartas via maljuna patro, pri kiu vi diris al mi? ĉu li vivas ankoraŭ?"],[43,28,"Kaj ili diris: Via sklavo nia patro fartas bone; li vivas ankoraŭ. Kaj ili kliniĝis kaj ĵetis sin antaŭ li sur la teron.","Kaj ili diris: Via sklavo nia patro fartas bone; li vivas ankoraŭ. Kaj ili kliniĝis kaj ĵetis sin antaŭ li sur la teron."],[43,29,"Kaj li levis siajn okulojn, kaj ekvidis sian fraton Benjamen, la filon de lia patrino, kaj li diris: Ĉu tio estas via plej juna frato, pri kiu vi diris al mi? Kaj li diris: Dio vin favoru, mia filo.","Kaj li levis siajn okulojn, kaj ekvidis sian fraton Benjamen, la filon de lia patrino, kaj li diris: Ĉu tio estas via plej juna frato, pri kiu vi diris al mi? Kaj li diris: Dio vin favoru, mia filo."],[43,30,"Kaj Jozef forrapidis, ĉar ekflamis lia interno pro lia frato kaj li volis plori. Kaj li eniris en internan ĉambron kaj ploris tie.","Kaj Jozef forrapidis, ĉar ekflamis lia interno pro lia frato kaj li volis plori. Kaj li eniris en internan ĉambron kaj ploris tie."],[43,31,"Sed li lavis sian vizaĝon kaj eliris, kaj tenis sin forte, kaj diris: Surtabligu panon!","Sed li lavis sian vizaĝon kaj eliris, kaj tenis sin forte, kaj diris: Surtabligu panon!"],[43,32,"Kaj oni surtabligis por li aparte, kaj por ili aparte, kaj por la Egiptoj, kiuj manĝis kun li, aparte; ĉar la Egiptoj ne povas manĝi panon kun Hebreoj: tio estas abomenindaĵo por ili.","Kaj oni surtabligis por li aparte, kaj por ili aparte, kaj por la Egiptoj, kiuj manĝis kun li, aparte; ĉar la Egiptoj ne povas manĝi panon kun Hebreoj: tio estas abomenindaĵo por ili."],[43,33,"Kaj ili sidiĝis antaŭ li, pli maljuna laŭ sia maljuneco kaj pli juna laŭ sia juneco; kaj la homoj miris unu antaŭ alia.","Kaj ili sidiĝis antaŭ li, pli maljuna laŭ sia maljuneco kaj pli juna laŭ sia juneco; kaj la homoj miris unu antaŭ alia."],[43,34,"Kaj oni portis al ili manĝaĵon de lia tablo; sed la porcio de Benjamen estis kvinoble pli granda, ol la porcioj de ĉiuj. Kaj ili trinkis kaj ebriiĝis kun li.","Kaj oni portis al ili manĝaĵon de lia tablo; sed la porcio de Benjamen estis kvinoble pli granda, ol la porcioj de ĉiuj. Kaj ili trinkis kaj ebriiĝis kun li."],[44,1,"Kaj Jozef ordonis al la estro de sia domo jene: Plenigu la sakojn de tiuj homoj per greno tiom, kiom ili nur povas porti, kaj metu la monon de ĉiu en la aperturon de lia sako;","Kaj Jozef ordonis al la estro de sia domo jene: Plenigu la sakojn de tiuj homoj per greno tiom, kiom ili nur povas porti, kaj metu la monon de ĉiu en la aperturon de lia sako;"],[44,2,"kaj mian pokalon, la arĝentan pokalon, metu en la aperturon de la sako de la plej juna, kune kun la mono por lia greno. Kaj tiu faris, kiel Jozef diris.","kaj mian pokalon, la arĝentan pokalon, metu en la aperturon de la sako de la plej juna, kune kun la mono por lia greno. Kaj tiu faris, kiel Jozef diris."],[44,3,"Kiam eklumis la mateno, oni forsendis la homojn, ilin kaj iliajn azenojn.","Kiam eklumis la mateno, oni forsendis la homojn, ilin kaj iliajn azenojn."],[44,4,"Kiam ili eliris el la urbo kaj ankoraŭ ne estis malproksime, Jozef diris al la estro de sia domo: Leviĝu, kuru post tiuj homoj, kaj kiam vi atingos ilin, diru al ili: Kial vi pagis malbonon por bono?","Kiam ili eliris el la urbo kaj ankoraŭ ne estis malproksime, Jozef diris al la estro de sia domo: Leviĝu, kuru post tiuj homoj, kaj kiam vi atingos ilin, diru al ili: Kial vi pagis malbonon por bono?"],[44,5,"Ĝi estas ja tiu pokalo, el kiu trinkas mia sinjoro, kaj li ankaŭ aŭguras sur ĝi! vi agis malbone!","Ĝi estas ja tiu pokalo, el kiu trinkas mia sinjoro, kaj li ankaŭ aŭguras sur ĝi! vi agis malbone!"],[44,6,"Kaj li kuratingis ilin kaj diris al ili tiujn vortojn.","Kaj li kuratingis ilin kaj diris al ili tiujn vortojn."],[44,7,"Kaj ili diris al li: Kial mia sinjoro parolas tiajn vortojn? Dio gardu viajn sklavojn de farado de tia afero!","Kaj ili diris al li: Kial mia sinjoro parolas tiajn vortojn? Dio gardu viajn sklavojn de farado de tia afero!"],[44,8,"Jen la monon, kiun ni trovis en la aperturoj de niaj sakoj, ni realportis al vi el la lando Kanaana; kiel do ni ŝtelus el la domo de via sinjoro arĝenton aŭ oron?","Jen la monon, kiun ni trovis en la aperturoj de niaj sakoj, ni realportis al vi el la lando Kanaana; kiel do ni ŝtelus el la domo de via sinjoro arĝenton aŭ oron?"],[44,9,"Tiu el viaj sklavoj, ĉe kiu oni ĝin trovos, mortu, kaj ankaŭ ni fariĝu sklavoj al mia sinjoro.","Tiu el viaj sklavoj, ĉe kiu oni ĝin trovos, mortu, kaj ankaŭ ni fariĝu sklavoj al mia sinjoro."],[44,10,"Kaj li diris: Ĝi estu laŭ viaj vortoj: tiu, ĉe kiu ĝi troviĝos, estu mia sklavo, sed vi estos senkulpaj.","Kaj li diris: Ĝi estu laŭ viaj vortoj: tiu, ĉe kiu ĝi troviĝos, estu mia sklavo, sed vi estos senkulpaj."],[44,11,"Kaj rapide ĉiu el ili mallevis sian sakon sur la teron, kaj ĉiu malfermis sian sakon.","Kaj rapide ĉiu el ili mallevis sian sakon sur la teron, kaj ĉiu malfermis sian sakon."],[44,12,"Kaj li serĉis; de la plej maljuna li komencis, kaj per la plej juna li finis. Kaj la pokalo troviĝis en la sako de Benjamen.","Kaj li serĉis; de la plej maljuna li komencis, kaj per la plej juna li finis. Kaj la pokalo troviĝis en la sako de Benjamen."],[44,13,"Tiam ili disŝiris siajn vestojn, kaj ĉiu metis la ŝarĝon sur sian azenon, kaj ili reiris en la urbon.","Tiam ili disŝiris siajn vestojn, kaj ĉiu metis la ŝarĝon sur sian azenon, kaj ili reiris en la urbon."],[44,14,"Kaj Jehuda kaj liaj fratoj venis en la domon de Jozef, kiu estis ankoraŭ tie, kaj ili ĵetis sin antaŭ li sur la teron.","Kaj Jehuda kaj liaj fratoj venis en la domon de Jozef, kiu estis ankoraŭ tie, kaj ili ĵetis sin antaŭ li sur la teron."],[44,15,"Kaj Jozef diris al ili: Kian aferon vi faris! ĉu vi ne scias, ke tia homo, kiel mi, facile divenos?","Kaj Jozef diris al ili: Kian aferon vi faris! ĉu vi ne scias, ke tia homo, kiel mi, facile divenos?"],[44,16,"Tiam Jehuda diris: Kion ni diru al mia sinjoro? kion ni parolu kaj per kio ni nin pravigu? Dio trovis la pekon de viaj sklavoj! jen ni estas sklavoj al mia sinjoro, ni kaj ankaŭ tiu, en kies manoj troviĝis la pokalo.","Tiam Jehuda diris: Kion ni diru al mia sinjoro? kion ni parolu kaj per kio ni nin pravigu? Dio trovis la pekon de viaj sklavoj! jen ni estas sklavoj al mia sinjoro, ni kaj ankaŭ tiu, en kies manoj troviĝis la pokalo."],[44,17,"Sed li diris: Dio min gardu de tia faro! la homo, en kies mano troviĝis la pokalo, estos sklavo al mi, sed vi iru en paco al via patro.","Sed li diris: Dio min gardu de tia faro! la homo, en kies mano troviĝis la pokalo, estos sklavo al mi, sed vi iru en paco al via patro."],[44,18,"Tiam Jehuda aliris al li, kaj diris: Permesu, mia sinjoro, ke via sklavo diru vorton en la orelojn de mia sinjoro, kaj ne koleriĝu kontraŭ via sklavo, ĉar vi estas kiel Faraono.","Tiam Jehuda aliris al li, kaj diris: Permesu, mia sinjoro, ke via sklavo diru vorton en la orelojn de mia sinjoro, kaj ne koleriĝu kontraŭ via sklavo, ĉar vi estas kiel Faraono."],[44,19,"Mia sinjoro demandis siajn sklavojn, dirante: Ĉu vi havas patron aŭ fraton?","Mia sinjoro demandis siajn sklavojn, dirante: Ĉu vi havas patron aŭ fraton?"],[44,20,"Kaj ni diris al mia sinjoro: Ni havas maljunan patron, kaj malgrandan knabon, naskitan en lia maljuneco; kaj lia frato mortis, kaj li restis sola de sia patrino, kaj lia patro lin amas.","Kaj ni diris al mia sinjoro: Ni havas maljunan patron, kaj malgrandan knabon, naskitan en lia maljuneco; kaj lia frato mortis, kaj li restis sola de sia patrino, kaj lia patro lin amas."],[44,21,"Tiam vi diris al viaj sklavoj: Venigu lin al mi, ke mi lin rigardu.","Tiam vi diris al viaj sklavoj: Venigu lin al mi, ke mi lin rigardu."],[44,22,"Sed ni diris al mia sinjoro: La knabo ne povas forlasi sian patron; ĉar se li forlasos sian patron, tiu mortos.","Sed ni diris al mia sinjoro: La knabo ne povas forlasi sian patron; ĉar se li forlasos sian patron, tiu mortos."],[44,23,"Tiam vi diris al viaj sklavoj: Se ne venos kun vi via plej juna frato, tiam ne aperu plu antaŭ mia vizaĝo.","Tiam vi diris al viaj sklavoj: Se ne venos kun vi via plej juna frato, tiam ne aperu plu antaŭ mia vizaĝo."],[44,24,"Kaj kiam ni venis al via sklavo nia patro, ni diris al li la vortojn de mia sinjoro.","Kaj kiam ni venis al via sklavo nia patro, ni diris al li la vortojn de mia sinjoro."],[44,25,"Nia patro diris: Reiru, aĉetu por ni iom da greno.","Nia patro diris: Reiru, aĉetu por ni iom da greno."],[44,26,"Sed ni diris: Ni ne povas iri; se estos kun ni nia plej juna frato, tiam ni iros; ĉar ni ne povas aperi antaŭ la vizaĝo de tiu homo, se nia plej juna frato ne estos kun ni.","Sed ni diris: Ni ne povas iri; se estos kun ni nia plej juna frato, tiam ni iros; ĉar ni ne povas aperi antaŭ la vizaĝo de tiu homo, se nia plej juna frato ne estos kun ni."],[44,27,"Tiam via sklavo nia patro diris al ni: Vi scias, ke mia edzino naskis al mi du;","Tiam via sklavo nia patro diris al ni: Vi scias, ke mia edzino naskis al mi du;"],[44,28,"sed unu foriris de mi, kaj mi diris: Li estas disŝirita; kaj mi ne vidis lin ĝis nun;","sed unu foriris de mi, kaj mi diris: Li estas disŝirita; kaj mi ne vidis lin ĝis nun;"],[44,29,"se vi ankaŭ ĉi tiun prenos de mi kaj lin trafos malfeliĉo, tiam vi enirigos miajn grizajn harojn kun malĝojo en Ŝeolon.","se vi ankaŭ ĉi tiun prenos de mi kaj lin trafos malfeliĉo, tiam vi enirigos miajn grizajn harojn kun malĝojo en Ŝeolon."],[44,30,"Kaj nun se mi venos al via sklavo mia patro kaj ne estos kun ni la knabo, al kies animo estas alligita lia animo,","Kaj nun se mi venos al via sklavo mia patro kaj ne estos kun ni la knabo, al kies animo estas alligita lia animo,"],[44,31,"tiam, ekvidinte, ke la knabo forestas, li mortos; kaj viaj sklavoj enirigos la grizajn harojn de via sklavo nia patro kun malĝojo en Ŝeolon.","tiam, ekvidinte, ke la knabo forestas, li mortos; kaj viaj sklavoj enirigos la grizajn harojn de via sklavo nia patro kun malĝojo en Ŝeolon."],[44,32,"Ĉar mi, via sklavo, garantiis por la knabo antaŭ mia patro, dirante: Se mi ne revenigos lin al vi, mi estos kulpa antaŭ mia patro por ĉiam.","Ĉar mi, via sklavo, garantiis por la knabo antaŭ mia patro, dirante: Se mi ne revenigos lin al vi, mi estos kulpa antaŭ mia patro por ĉiam."],[44,33,"Tial mi, via sklavo, restu anstataŭ la knabo kiel sklavo ĉe mia sinjoro, sed la knabo iru kun siaj fratoj.","Tial mi, via sklavo, restu anstataŭ la knabo kiel sklavo ĉe mia sinjoro, sed la knabo iru kun siaj fratoj."],[44,34,"Ĉar kiel mi iros al mia patro, se la knabo ne estos kun mi? mi tiam vidus la malfeliĉon, kiu trafos mian patron.","Ĉar kiel mi iros al mia patro, se la knabo ne estos kun mi? mi tiam vidus la malfeliĉon, kiu trafos mian patron."],[45,1,"Tiam Jozef ne povis plu sin deteni antaŭ ĉiuj, kiuj staris ĉirkaŭ li, kaj li ekkriis: Elirigu ĉiujn for de mi. Kaj neniu restis ĉe li, kiam Jozef rekonigis sin al siaj fratoj.","Tiam Jozef ne povis plu sin deteni antaŭ ĉiuj, kiuj staris ĉirkaŭ li, kaj li ekkriis: Elirigu ĉiujn for de mi. Kaj neniu restis ĉe li, kiam Jozef rekonigis sin al siaj fratoj."],[45,2,"Kaj li laŭte ekploris, kaj aŭdis la Egiptoj, kaj aŭdis la domo de Faraono.","Kaj li laŭte ekploris, kaj aŭdis la Egiptoj, kaj aŭdis la domo de Faraono."],[45,3,"Kaj Jozef diris al siaj fratoj: Mi estas Jozef; ĉu mia patro vivas ankoraŭ? Sed liaj fratoj ne povis respondi al li, ĉar ili konfuziĝis antaŭ li.","Kaj Jozef diris al siaj fratoj: Mi estas Jozef; ĉu mia patro vivas ankoraŭ? Sed liaj fratoj ne povis respondi al li, ĉar ili konfuziĝis antaŭ li."],[45,4,"Kaj Jozef diris al siaj fratoj: Aliru do al mi. Kaj ili aliris. Kaj li diris: Mi estas Jozef, via frato, kiun vi vendis en Egiptujon.","Kaj Jozef diris al siaj fratoj: Aliru do al mi. Kaj ili aliris. Kaj li diris: Mi estas Jozef, via frato, kiun vi vendis en Egiptujon."],[45,5,"Sed nun ne afliktiĝu, kaj ne bedaŭru, ke vi vendis min ĉi tien; ĉar por la savo de via vivo Dio sendis min antaŭ vi.","Sed nun ne afliktiĝu, kaj ne bedaŭru, ke vi vendis min ĉi tien; ĉar por la savo de via vivo Dio sendis min antaŭ vi."],[45,6,"Ĉar nun jam du jarojn daŭras la malsato en la lando, sed ankoraŭ dum kvin jaroj ne estos plugado nek rikoltado.","Ĉar nun jam du jarojn daŭras la malsato en la lando, sed ankoraŭ dum kvin jaroj ne estos plugado nek rikoltado."],[45,7,"Kaj Dio sendis min antaŭ vi, por vin restigi sur la tero kaj por konservi vian vivon per granda savo.","Kaj Dio sendis min antaŭ vi, por vin restigi sur la tero kaj por konservi vian vivon per granda savo."],[45,8,"Sciu do, ne vi sendis min ĉi tien, sed Dio; kaj Li faris min patro al Faraono, kaj sinjoro super lia tuta domo, kaj reganto super la tuta Egipta lando.","Sciu do, ne vi sendis min ĉi tien, sed Dio; kaj Li faris min patro al Faraono, kaj sinjoro super lia tuta domo, kaj reganto super la tuta Egipta lando."],[45,9,"Iru rapide al mia patro, kaj diru al li: Tiele diris via filo Jozef: Dio faris min sinjoro super la tuta Egiptujo; venu al mi, ne prokrastu.","Iru rapide al mia patro, kaj diru al li: Tiele diris via filo Jozef: Dio faris min sinjoro super la tuta Egiptujo; venu al mi, ne prokrastu."],[45,10,"Vi loĝos en la lando Goŝen, kaj vi estos proksime de mi, vi kaj viaj filoj kaj la filoj de viaj filoj, kaj viaj ŝafoj kaj viaj bovoj, kaj ĉio, kion vi havas.","Vi loĝos en la lando Goŝen, kaj vi estos proksime de mi, vi kaj viaj filoj kaj la filoj de viaj filoj, kaj viaj ŝafoj kaj viaj bovoj, kaj ĉio, kion vi havas."],[45,11,"Kaj mi nutros vin tie, ĉar ankoraŭ kvin jarojn daŭros la malsato; por ke ne mizeriĝu vi kaj via domo, kaj ĉio, kion vi havas.","Kaj mi nutros vin tie, ĉar ankoraŭ kvin jarojn daŭros la malsato; por ke ne mizeriĝu vi kaj via domo, kaj ĉio, kion vi havas."],[45,12,"Kaj jen viaj okuloj nun vidas, kaj ankaŭ la okuloj de mia frato Benjamen, ke mia buŝo parolas al vi.","Kaj jen viaj okuloj nun vidas, kaj ankaŭ la okuloj de mia frato Benjamen, ke mia buŝo parolas al vi."],[45,13,"Kaj rakontu al mia patro pri mia tuta gloro en Egiptujo, kaj ĉion, kion vi vidis; kaj rapide venigu mian patron ĉi tien.","Kaj rakontu al mia patro pri mia tuta gloro en Egiptujo, kaj ĉion, kion vi vidis; kaj rapide venigu mian patron ĉi tien."],[45,14,"Kaj li ĵetis sin sur la kolon de sia frato Benjamen kaj ploris, kaj Benjamen ploris sur lia kolo.","Kaj li ĵetis sin sur la kolon de sia frato Benjamen kaj ploris, kaj Benjamen ploris sur lia kolo."],[45,15,"Kaj li kisis ĉiujn siajn fratojn kaj ploris super ili. Poste liaj fratoj ekparolis kun li.","Kaj li kisis ĉiujn siajn fratojn kaj ploris super ili. Poste liaj fratoj ekparolis kun li."],[45,16,"Kaj la famo venis en la domon de Faraono, ke venis la fratoj de Jozef. Kaj tio plaĉis al Faraono kaj al liaj servantoj.","Kaj la famo venis en la domon de Faraono, ke venis la fratoj de Jozef. Kaj tio plaĉis al Faraono kaj al liaj servantoj."],[45,17,"Kaj Faraono diris al Jozef: Diru al viaj fratoj: Faru tion, ŝarĝu viajn brutojn kaj iru en la landon Kanaanan;","Kaj Faraono diris al Jozef: Diru al viaj fratoj: Faru tion, ŝarĝu viajn brutojn kaj iru en la landon Kanaanan;"],[45,18,"kaj prenu vian patron kaj viajn familiojn, kaj venu al mi; mi donos al vi ĉion bonan en la Egipta lando, kaj vi manĝos la grasaĵon de la lando.","kaj prenu vian patron kaj viajn familiojn, kaj venu al mi; mi donos al vi ĉion bonan en la Egipta lando, kaj vi manĝos la grasaĵon de la lando."],[45,19,"Kaj ordonu al ili jene: Prenu al vi el la Egipta lando veturilojn por viaj infanoj kaj virinoj, kaj kunprenu vian patron kaj venu.","Kaj ordonu al ili jene: Prenu al vi el la Egipta lando veturilojn por viaj infanoj kaj virinoj, kaj kunprenu vian patron kaj venu."],[45,20,"Kaj ne tro zorgu pri viaj aĵoj; ĉar ĉio bona en la Egipta lando estas al via dispono.","Kaj ne tro zorgu pri viaj aĵoj; ĉar ĉio bona en la Egipta lando estas al via dispono."],[45,21,"Kaj la filoj de Izrael faris tiel. Kaj Jozef donis al ili veturilojn laŭ la ordono de Faraono, kaj li donis al ili provizojn por la vojo.","Kaj la filoj de Izrael faris tiel. Kaj Jozef donis al ili veturilojn laŭ la ordono de Faraono, kaj li donis al ili provizojn por la vojo."],[45,22,"Al ĉiuj li donis novajn vestojn, sed al Benjamen li donis tricent arĝentajn monerojn kaj kvin novajn vestojn.","Al ĉiuj li donis novajn vestojn, sed al Benjamen li donis tricent arĝentajn monerojn kaj kvin novajn vestojn."],[45,23,"Kaj por sia patro li sendis dek azenojn, ŝarĝitajn per bonaĵo el Egiptujo, kaj dek azeninojn, ŝarĝitajn per greno, pano, kaj manĝaĵo por lia patro por la vojo.","Kaj por sia patro li sendis dek azenojn, ŝarĝitajn per bonaĵo el Egiptujo, kaj dek azeninojn, ŝarĝitajn per greno, pano, kaj manĝaĵo por lia patro por la vojo."],[45,24,"Kaj li forsendis siajn fratojn, kaj ili iris. Kaj li diris al ili: Ne malpacu dum la vojo.","Kaj li forsendis siajn fratojn, kaj ili iris. Kaj li diris al ili: Ne malpacu dum la vojo."],[45,25,"Kaj ili eliris el Egiptujo kaj venis en la landon Kanaanan al sia patro Jakob.","Kaj ili eliris el Egiptujo kaj venis en la landon Kanaanan al sia patro Jakob."],[45,26,"Kaj ili sciigis al li, dirante: Jozef vivas ankoraŭ, kaj li regas nun super la tuta Egipta lando. Kaj lia koro konfuziĝis, ĉar li ne kredis al ili.","Kaj ili sciigis al li, dirante: Jozef vivas ankoraŭ, kaj li regas nun super la tuta Egipta lando. Kaj lia koro konfuziĝis, ĉar li ne kredis al ili."],[45,27,"Kaj ili rediris al li ĉiujn vortojn de Jozef, kiujn li diris al ili; kaj li vidis la veturilojn, kiujn Jozef sendis, por veturigi lin, kaj tiam la spirito de ilia patro Jakob reviviĝis.","Kaj ili rediris al li ĉiujn vortojn de Jozef, kiujn li diris al ili; kaj li vidis la veturilojn, kiujn Jozef sendis, por veturigi lin, kaj tiam la spirito de ilia patro Jakob reviviĝis."],[45,28,"Kaj Izrael diris: Sufiĉas, ke mia filo Jozef ankoraŭ vivas: mi iros kaj vidos lin, antaŭ ol mi mortos.","Kaj Izrael diris: Sufiĉas, ke mia filo Jozef ankoraŭ vivas: mi iros kaj vidos lin, antaŭ ol mi mortos."],[46,1,"Izrael ekiris kun ĉio, kion li havis, kaj li venis en Beer-Ŝeban, kaj li alportis oferojn al la Dio de sia patro Isaak.","Izrael ekiris kun ĉio, kion li havis, kaj li venis en Beer-Ŝeban, kaj li alportis oferojn al la Dio de sia patro Isaak."],[46,2,"Kaj Dio diris al Izrael en nokta vizio: Jakob! Jakob! Kaj tiu diris: Jen mi estas.","Kaj Dio diris al Izrael en nokta vizio: Jakob! Jakob! Kaj tiu diris: Jen mi estas."],[46,3,"Kaj Li diris: Mi estas Dio, la Dio de via patro. Ne timu iri Egiptujon, ĉar Mi tie faros vin granda popolo.","Kaj Li diris: Mi estas Dio, la Dio de via patro. Ne timu iri Egiptujon, ĉar Mi tie faros vin granda popolo."],[46,4,"Mi iros kun vi Egiptujon, kaj Mi ankaŭ revenigos vin; kaj Jozef metos sian manon sur viajn okulojn.","Mi iros kun vi Egiptujon, kaj Mi ankaŭ revenigos vin; kaj Jozef metos sian manon sur viajn okulojn."],[46,5,"Kaj Jakob leviĝis el Beer-Ŝeba; kaj la filoj de Izrael ekveturigis sian patron Jakob kaj siajn infanojn kaj siajn edzinojn sur la veturiloj, kiujn sendis Faraono, por alveturigi lin.","Kaj Jakob leviĝis el Beer-Ŝeba; kaj la filoj de Izrael ekveturigis sian patron Jakob kaj siajn infanojn kaj siajn edzinojn sur la veturiloj, kiujn sendis Faraono, por alveturigi lin."],[46,6,"Kaj ili prenis siajn brutojn, kaj sian havon, kiun ili akiris en la lando Kanaana, kaj venis Egiptujon, Jakob kaj lia tuta idaro kun li.","Kaj ili prenis siajn brutojn, kaj sian havon, kiun ili akiris en la lando Kanaana, kaj venis Egiptujon, Jakob kaj lia tuta idaro kun li."],[46,7,"Siajn filojn kaj nepojn, siajn filinojn kaj nepinojn, kaj sian tutan idaron li venigis kun si en Egiptujon.","Siajn filojn kaj nepojn, siajn filinojn kaj nepinojn, kaj sian tutan idaron li venigis kun si en Egiptujon."],[46,8,"Jen estas la nomoj de la filoj de Izrael, kiuj venis Egiptujon: Jakob kaj liaj filoj. La unuenaskito de Jabob, Ruben.","Jen estas la nomoj de la filoj de Izrael, kiuj venis Egiptujon: Jakob kaj liaj filoj. La unuenaskito de Jabob, Ruben."],[46,9,"Kaj la filoj de Ruben: Ĥanoĥ kaj Palu kaj Ĥecron kaj Karmi.","Kaj la filoj de Ruben: Ĥanoĥ kaj Palu kaj Ĥecron kaj Karmi."],[46,10,"Kaj la filoj de Simeon: Jemuel kaj Jamin kaj Ohad kaj Jaĥin kaj Coĥar, kaj Ŝaul, filo de Kanaanidino.","Kaj la filoj de Simeon: Jemuel kaj Jamin kaj Ohad kaj Jaĥin kaj Coĥar, kaj Ŝaul, filo de Kanaanidino."],[46,11,"Kaj la filoj de Levi: Gerŝon, Kehat, kaj Merari.","Kaj la filoj de Levi: Gerŝon, Kehat, kaj Merari."],[46,12,"Kaj la filoj de Jehuda: Er kaj Onan kaj Ŝela kaj Perec kaj Zeraĥ; sed Er kaj Onan mortis en la lando Kanaana. Kaj la filoj de Perec estis: Ĥecron kaj Ĥamul.","Kaj la filoj de Jehuda: Er kaj Onan kaj Ŝela kaj Perec kaj Zeraĥ; sed Er kaj Onan mortis en la lando Kanaana. Kaj la filoj de Perec estis: Ĥecron kaj Ĥamul."],[46,13,"Kaj la filoj de Isaĥar: Tola kaj Puva kaj Job kaj Ŝimron.","Kaj la filoj de Isaĥar: Tola kaj Puva kaj Job kaj Ŝimron."],[46,14,"Kaj la filoj de Zebulun: Sered kaj Elon kaj Jaĥleel.","Kaj la filoj de Zebulun: Sered kaj Elon kaj Jaĥleel."],[46,15,"Tio estas la filoj de Lea, kiujn ŝi naskis al Jakob en Mezopotamio, kaj lia filino Dina. La nombro de ĉiuj animoj de liaj filoj kaj filinoj estis tridek tri.","Tio estas la filoj de Lea, kiujn ŝi naskis al Jakob en Mezopotamio, kaj lia filino Dina. La nombro de ĉiuj animoj de liaj filoj kaj filinoj estis tridek tri."],[46,16,"Kaj la filoj de Gad: Cifjon kaj Ĥagi, Ŝuni kaj Ecbon, Eri kaj Arod kaj Areli.","Kaj la filoj de Gad: Cifjon kaj Ĥagi, Ŝuni kaj Ecbon, Eri kaj Arod kaj Areli."],[46,17,"Kaj la filoj de Aŝer: Jimna kaj Jiŝva kaj Jiŝvi kaj Beria, kaj Seraĥ, ilia fratino; kaj la filoj de Beria: Ĥeber kaj Malkiel.","Kaj la filoj de Aŝer: Jimna kaj Jiŝva kaj Jiŝvi kaj Beria, kaj Seraĥ, ilia fratino; kaj la filoj de Beria: Ĥeber kaj Malkiel."],[46,18,"Tio estas la filoj de Zilpa, kiun Laban donis al sia filino Lea; kaj ŝi naskis ilin al Jakob, dek ses animojn.","Tio estas la filoj de Zilpa, kiun Laban donis al sia filino Lea; kaj ŝi naskis ilin al Jakob, dek ses animojn."],[46,19,"La filoj de Raĥel, edzino de Jakob: Jozef kaj Benjamen.","La filoj de Raĥel, edzino de Jakob: Jozef kaj Benjamen."],[46,20,"Kaj al Jozef en la lando Egipta naskiĝis Manase kaj Efraim, kiujn naskis al li Asnat, filino de Poti-Fera, pastro el On.","Kaj al Jozef en la lando Egipta naskiĝis Manase kaj Efraim, kiujn naskis al li Asnat, filino de Poti-Fera, pastro el On."],[46,21,"Kaj la filoj de Benjamen: Bela kaj Beĥer kaj Aŝbel, Gera kaj Naaman, Eĥi kaj Roŝ, Mupim kaj Ĥupim kaj Ard.","Kaj la filoj de Benjamen: Bela kaj Beĥer kaj Aŝbel, Gera kaj Naaman, Eĥi kaj Roŝ, Mupim kaj Ĥupim kaj Ard."],[46,22,"Tio estas la filoj de Raĥel, kiuj naskiĝis al Jakob, kune dek kvar animoj.","Tio estas la filoj de Raĥel, kiuj naskiĝis al Jakob, kune dek kvar animoj."],[46,23,"Kaj la filoj de Dan: Ĥuŝim.","Kaj la filoj de Dan: Ĥuŝim."],[46,24,"Kaj la filoj de Naftali: Jaĥceel kaj Guni kaj Jecer kaj Ŝilem.","Kaj la filoj de Naftali: Jaĥceel kaj Guni kaj Jecer kaj Ŝilem."],[46,25,"Tio estas la filoj de Bilha, kiun donis Laban al sia filino Raĥel; ŝi naskis ilin al Jakob, kune sep animojn.","Tio estas la filoj de Bilha, kiun donis Laban al sia filino Raĥel; ŝi naskis ilin al Jakob, kune sep animojn."],[46,26,"La nombro de ĉiuj animoj, kiuj venis kun Jakob en Egiptujon, kiuj eliris el lia lumbo, krom la edzinoj de la filoj de Jakob, estis sesdek ses.","La nombro de ĉiuj animoj, kiuj venis kun Jakob en Egiptujon, kiuj eliris el lia lumbo, krom la edzinoj de la filoj de Jakob, estis sesdek ses."],[46,27,"Kaj la filoj de Jozef, kiuj naskiĝis al li en Egiptujo, estis du animoj. La nombro de ĉiuj animoj de la domo de Jakob, kiuj venis Egiptujon, estis sepdek.","Kaj la filoj de Jozef, kiuj naskiĝis al li en Egiptujo, estis du animoj. La nombro de ĉiuj animoj de la domo de Jakob, kiuj venis Egiptujon, estis sepdek."],[46,28,"Jehudan li sendis antaŭ si al Jozef, por ke li informu lin antaŭe pri Goŝen. Kaj ili venis en la landon Goŝen.","Jehudan li sendis antaŭ si al Jozef, por ke li informu lin antaŭe pri Goŝen. Kaj ili venis en la landon Goŝen."],[46,29,"Kaj Jozef jungis sian ĉaron kaj veturis renkonte al sia patro Izrael en la landon Goŝen. Kaj kiam li ekvidis lin, li ĵetis sin sur lian kolon kaj longe ploris sur lia kolo.","Kaj Jozef jungis sian ĉaron kaj veturis renkonte al sia patro Izrael en la landon Goŝen. Kaj kiam li ekvidis lin, li ĵetis sin sur lian kolon kaj longe ploris sur lia kolo."],[46,30,"Kaj Izrael diris al Jozef: Nun mi volonte mortos, vidinte vian vizaĝon, ĉar vi vivas ankoraŭ.","Kaj Izrael diris al Jozef: Nun mi volonte mortos, vidinte vian vizaĝon, ĉar vi vivas ankoraŭ."],[46,31,"Kaj Jozef diris al siaj fratoj kaj al la domo de sia patro: Mi iros kaj rakontos al Faraono, kaj diros al li: Miaj fratoj kaj la domo de mia patro, kiuj estis en la lando Kanaana, venis al mi;","Kaj Jozef diris al siaj fratoj kaj al la domo de sia patro: Mi iros kaj rakontos al Faraono, kaj diros al li: Miaj fratoj kaj la domo de mia patro, kiuj estis en la lando Kanaana, venis al mi;"],[46,32,"kaj tiuj homoj estas paŝtistoj, ĉar ili estas brutedukistoj; kaj siajn malgrandajn kaj grandajn brutojn, kaj ĉion, kion ili havas, ili kunportis.","kaj tiuj homoj estas paŝtistoj, ĉar ili estas brutedukistoj; kaj siajn malgrandajn kaj grandajn brutojn, kaj ĉion, kion ili havas, ili kunportis."],[46,33,"Kaj se Faraono vin alvokos, kaj diros: Kio estas via okupo?","Kaj se Faraono vin alvokos, kaj diros: Kio estas via okupo?"],[46,34,"tiam diru: Viaj sklavoj estis brutedukistoj de nia juneco ĝis nun, kiel ni, tiel ankaŭ niaj patroj; por ke vi enloĝiĝu en la lando Goŝen; ĉar ĉiu paŝtisto estas abomenindaĵo por la Egiptoj.","tiam diru: Viaj sklavoj estis brutedukistoj de nia juneco ĝis nun, kiel ni, tiel ankaŭ niaj patroj; por ke vi enloĝiĝu en la lando Goŝen; ĉar ĉiu paŝtisto estas abomenindaĵo por la Egiptoj."],[47,1,"Jozef venis kaj sciigis al Faraono, kaj diris: Mia patro kaj miaj fratoj kaj iliaj malgrandaj kaj grandaj brutoj, kaj ĉio, kio apartenas al ili, venis el la lando Kanaana, kaj nun ili estas en la lando Goŝen.","Jozef venis kaj sciigis al Faraono, kaj diris: Mia patro kaj miaj fratoj kaj iliaj malgrandaj kaj grandaj brutoj, kaj ĉio, kio apartenas al ili, venis el la lando Kanaana, kaj nun ili estas en la lando Goŝen."],[47,2,"Kaj el inter siaj fratoj li prenis kvin homojn kaj starigis ilin antaŭ Faraono.","Kaj el inter siaj fratoj li prenis kvin homojn kaj starigis ilin antaŭ Faraono."],[47,3,"Kaj Faraono diris al liaj fratoj: Kio estas via okupo? Kaj ili diris al Faraono: Viaj sklavoj estas brutedukistoj, kiel ni, tiel ankaŭ niaj patroj.","Kaj Faraono diris al liaj fratoj: Kio estas via okupo? Kaj ili diris al Faraono: Viaj sklavoj estas brutedukistoj, kiel ni, tiel ankaŭ niaj patroj."],[47,4,"Kaj ili diris al Faraono: Ni venis, por loĝi en la lando; ĉar ne ekzistas paŝtaĵo por la brutoj de viaj sklavoj, ĉar forta estas la malsato en la lando Kanaana; permesu do, ke viaj sklavoj loĝu en la lando Goŝen.","Kaj ili diris al Faraono: Ni venis, por loĝi en la lando; ĉar ne ekzistas paŝtaĵo por la brutoj de viaj sklavoj, ĉar forta estas la malsato en la lando Kanaana; permesu do, ke viaj sklavoj loĝu en la lando Goŝen."],[47,5,"Tiam Faraono diris al Jozef jene: Via patro kaj viaj fratoj venis al vi;","Tiam Faraono diris al Jozef jene: Via patro kaj viaj fratoj venis al vi;"],[47,6,"la lando Egipta estas antaŭ vi; en la plej bona loko de la lando loĝigu vian patron kaj viajn fratojn; ili loĝu en la lando Goŝen; kaj se vi scias, ke estas inter ili kapablaj homoj, faru ilin administrantoj de miaj brutoj.","la lando Egipta estas antaŭ vi; en la plej bona loko de la lando loĝigu vian patron kaj viajn fratojn; ili loĝu en la lando Goŝen; kaj se vi scias, ke estas inter ili kapablaj homoj, faru ilin administrantoj de miaj brutoj."],[47,7,"Kaj Jozef enkondukis sian patron Jakob kaj starigis lin antaŭ Faraono; kaj Jakob benis Faraonon.","Kaj Jozef enkondukis sian patron Jakob kaj starigis lin antaŭ Faraono; kaj Jakob benis Faraonon."],[47,8,"Faraono diris al Jakob: Kian aĝon vi havas?","Faraono diris al Jakob: Kian aĝon vi havas?"],[47,9,"Kaj Jakob diris al Faraono: La nombro de la jaroj de mia migrado estas cent tridek jaroj; malmultaj kaj malbonaj estis la jaroj de mia vivo, kaj ili ne atingis la nombron de la jaroj de la vivo de miaj patroj dum ilia migrado.","Kaj Jakob diris al Faraono: La nombro de la jaroj de mia migrado estas cent tridek jaroj; malmultaj kaj malbonaj estis la jaroj de mia vivo, kaj ili ne atingis la nombron de la jaroj de la vivo de miaj patroj dum ilia migrado."],[47,10,"Kaj Jakob benis Faraonon kaj foriris de Faraono.","Kaj Jakob benis Faraonon kaj foriris de Faraono."],[47,11,"Kaj Jozef enloĝigis sian patron kaj siajn fratojn, kaj donis al ili posedaĵon en la Egipta lando, en la plej bona parto de la lando Rameses, kiel Faraono ordonis.","Kaj Jozef enloĝigis sian patron kaj siajn fratojn, kaj donis al ili posedaĵon en la Egipta lando, en la plej bona parto de la lando Rameses, kiel Faraono ordonis."],[47,12,"Kaj Jozef havigis panon al sia patro kaj al siaj fratoj kaj al la tuta domo de sia patro, laŭ la nombro de la infanoj.","Kaj Jozef havigis panon al sia patro kaj al siaj fratoj kaj al la tuta domo de sia patro, laŭ la nombro de la infanoj."],[47,13,"Ne estis pano sur la tuta tero, ĉar la malsato estis tre forta; kaj senfortiĝis de la malsato la lando Egipta kaj la lando Kanaana.","Ne estis pano sur la tuta tero, ĉar la malsato estis tre forta; kaj senfortiĝis de la malsato la lando Egipta kaj la lando Kanaana."],[47,14,"Kaj Jozef kolektis la tutan monon, kiu troviĝis en la lando Egipta kaj en la lando Kanaana, pro la greno, kiun oni aĉetadis; kaj Jozef enportis la tutan monon en la domon de Faraono.","Kaj Jozef kolektis la tutan monon, kiu troviĝis en la lando Egipta kaj en la lando Kanaana, pro la greno, kiun oni aĉetadis; kaj Jozef enportis la tutan monon en la domon de Faraono."],[47,15,"Kiam ne estis plu mono en la lando Egipta kaj en la lando Kanaana, ĉiuj Egiptoj venis al Jozef, kaj diris: Donu al ni panon; kial ni mortu antaŭ vi pro tio, ke ni jam ne havas monon?","Kiam ne estis plu mono en la lando Egipta kaj en la lando Kanaana, ĉiuj Egiptoj venis al Jozef, kaj diris: Donu al ni panon; kial ni mortu antaŭ vi pro tio, ke ni jam ne havas monon?"],[47,16,"Tiam Jozef diris: Donu viajn brutojn; kaj mi donos al vi panon pro viaj brutoj, se vi jam ne havas monon.","Tiam Jozef diris: Donu viajn brutojn; kaj mi donos al vi panon pro viaj brutoj, se vi jam ne havas monon."],[47,17,"Kaj ili alkondukis siajn brutojn al Jozef; kaj Jozef donis al ili panon pro ĉevaloj, ŝafoj, bovoj, kaj azenoj, kaj li provizadis al ili panon pro ĉiuj iliaj brutoj en tiu jaro.","Kaj ili alkondukis siajn brutojn al Jozef; kaj Jozef donis al ili panon pro ĉevaloj, ŝafoj, bovoj, kaj azenoj, kaj li provizadis al ili panon pro ĉiuj iliaj brutoj en tiu jaro."],[47,18,"Kiam finiĝis tiu jaro, ili venis al li en la dua jaro, kaj diris al li: Ni ne kaŝos antaŭ nia sinjoro, ke monon ni jam ne havas, kaj la brutoj estas ĉe nia sinjoro; nenio restis antaŭ nia sinjoro krom niaj korpoj kaj nia tero;","Kiam finiĝis tiu jaro, ili venis al li en la dua jaro, kaj diris al li: Ni ne kaŝos antaŭ nia sinjoro, ke monon ni jam ne havas, kaj la brutoj estas ĉe nia sinjoro; nenio restis antaŭ nia sinjoro krom niaj korpoj kaj nia tero;"],[47,19,"kial ni pereu antaŭ viaj okuloj, ni kaj nia tero? aĉetu nin kaj nian teron pro la pano, kaj ni kaj nia tero estu sklavoj al Faraono; kaj donu semon, por ke ni vivu kaj ne mortu kaj la tero ne dezertiĝu.","kial ni pereu antaŭ viaj okuloj, ni kaj nia tero? aĉetu nin kaj nian teron pro la pano, kaj ni kaj nia tero estu sklavoj al Faraono; kaj donu semon, por ke ni vivu kaj ne mortu kaj la tero ne dezertiĝu."],[47,20,"Kaj Jozef aĉetis la tutan Egiptan teron por Faraono; ĉar la Egiptoj vendis ĉiu sian kampon, ĉar forte premis ilin la malsato. Kaj la tero fariĝis propraĵo de Faraono.","Kaj Jozef aĉetis la tutan Egiptan teron por Faraono; ĉar la Egiptoj vendis ĉiu sian kampon, ĉar forte premis ilin la malsato. Kaj la tero fariĝis propraĵo de Faraono."],[47,21,"Kaj la popolon li transirigis en la urbojn, de unu fino de Egiptujo ĝis la alia.","Kaj la popolon li transirigis en la urbojn, de unu fino de Egiptujo ĝis la alia."],[47,22,"Nur la teron de la pastroj li ne aĉetis; ĉar la pastroj havis parton, difinitan de Faraono, kaj ili manĝadis sian parton, kiun donis al ili Faraono, tial ili ne vendis sian teron.","Nur la teron de la pastroj li ne aĉetis; ĉar la pastroj havis parton, difinitan de Faraono, kaj ili manĝadis sian parton, kiun donis al ili Faraono, tial ili ne vendis sian teron."],[47,23,"Kaj Jozef diris al la popolo: Jen mi aĉetis vin hodiaŭ kaj vian teron por Faraono; jen mi donas al vi semon, kaj prisemu la teron.","Kaj Jozef diris al la popolo: Jen mi aĉetis vin hodiaŭ kaj vian teron por Faraono; jen mi donas al vi semon, kaj prisemu la teron."],[47,24,"Kaj kiam vi havos rikolton, vi donos kvinonon al Faraono, kaj kvar partoj apartenos al vi, por prisemi la kampon kaj por manĝi, por vi, por ĉio, kio estas en viaj domoj, kaj por viaj infanoj.","Kaj kiam vi havos rikolton, vi donos kvinonon al Faraono, kaj kvar partoj apartenos al vi, por prisemi la kampon kaj por manĝi, por vi, por ĉio, kio estas en viaj domoj, kaj por viaj infanoj."],[47,25,"Kaj ili diris: Vi konservis nian vivon; ni akiru favoron de nia sinjoro, kaj ni estu sklavoj al Faraono.","Kaj ili diris: Vi konservis nian vivon; ni akiru favoron de nia sinjoro, kaj ni estu sklavoj al Faraono."],[47,26,"Kaj Jozef faris ĝin leĝo ĝis la hodiaŭa tago: de la tero Egipta kvinono de la produktoj apartenas al Faraono. Nur la tero de la pastroj ne fariĝis propraĵo de Faraono.","Kaj Jozef faris ĝin leĝo ĝis la hodiaŭa tago: de la tero Egipta kvinono de la produktoj apartenas al Faraono. Nur la tero de la pastroj ne fariĝis propraĵo de Faraono."],[47,27,"Kaj Izrael ekloĝis en la lando Egipta, en la lando Goŝen; kaj ili posedis ĝin kaj fruktis kaj multiĝis forte.","Kaj Izrael ekloĝis en la lando Egipta, en la lando Goŝen; kaj ili posedis ĝin kaj fruktis kaj multiĝis forte."],[47,28,"Kaj Jakob vivis en la lando Egipta dek sep jarojn. Kaj la daŭro de la vivo de Jakob estis cent kvardek sep jaroj.","Kaj Jakob vivis en la lando Egipta dek sep jarojn. Kaj la daŭro de la vivo de Jakob estis cent kvardek sep jaroj."],[47,29,"Kiam alproksimiĝis la tempo, kiam Izrael devis morti, li alvokis sian filon Jozef, kaj diris al li: Se mi akiris vian favoron, metu vian manon sub mian femuron kaj faru al mi favorkoraĵon kaj fidelaĵon, ne enterigu min en Egiptujo;","Kiam alproksimiĝis la tempo, kiam Izrael devis morti, li alvokis sian filon Jozef, kaj diris al li: Se mi akiris vian favoron, metu vian manon sub mian femuron kaj faru al mi favorkoraĵon kaj fidelaĵon, ne enterigu min en Egiptujo;"],[47,30,"sed mi kuŝu kun miaj patroj; elportu min el Egiptujo kaj entombigu min en ilia tombujo. Kaj tiu diris: Mi faros, kiel vi diris.","sed mi kuŝu kun miaj patroj; elportu min el Egiptujo kaj entombigu min en ilia tombujo. Kaj tiu diris: Mi faros, kiel vi diris."],[47,31,"Kaj li diris: Ĵuru al mi. Kaj tiu ĵuris. Kaj Izrael adorkliniĝis sur la kapa parto de la lito.","Kaj li diris: Ĵuru al mi. Kaj tiu ĵuris. Kaj Izrael adorkliniĝis sur la kapa parto de la lito."],[48,1,"Post tiuj okazintaĵoj oni sciigis al Jozef: Jen, via patro estas malsana. Kaj li prenis kun si siajn du filojn, Manase kaj Efraim.","Post tiuj okazintaĵoj oni sciigis al Jozef: Jen, via patro estas malsana. Kaj li prenis kun si siajn du filojn, Manase kaj Efraim."],[48,2,"Kaj oni sciigis al Jakob, dirante: Jen via filo Jozef venas al vi. Tiam Izrael streĉis siajn fortojn kaj sidiĝis sur la lito.","Kaj oni sciigis al Jakob, dirante: Jen via filo Jozef venas al vi. Tiam Izrael streĉis siajn fortojn kaj sidiĝis sur la lito."],[48,3,"Kaj Jakob diris al Jozef: Dio la Plejpotenca aperis al mi en Luz, en la lando Kanaana, kaj benis min.","Kaj Jakob diris al Jozef: Dio la Plejpotenca aperis al mi en Luz, en la lando Kanaana, kaj benis min."],[48,4,"Kaj Li diris al mi: Mi fruktigos vin kaj multigos vin kaj faros vin amaso da popoloj, kaj Mi donos ĉi tiun landon al via idaro post vi kiel eternan posedaĵon.","Kaj Li diris al mi: Mi fruktigos vin kaj multigos vin kaj faros vin amaso da popoloj, kaj Mi donos ĉi tiun landon al via idaro post vi kiel eternan posedaĵon."],[48,5,"Kaj nun viaj du filoj, kiuj naskiĝis al vi en la lando Egipta antaŭ mia alveno al vi en Egiptujon, estas miaj; Efraim kaj Manase estu al mi, kiel Ruben kaj Simeon.","Kaj nun viaj du filoj, kiuj naskiĝis al vi en la lando Egipta antaŭ mia alveno al vi en Egiptujon, estas miaj; Efraim kaj Manase estu al mi, kiel Ruben kaj Simeon."],[48,6,"Sed viaj infanoj, kiuj naskiĝos al vi post ili, estu viaj; per la nomo de siaj fratoj ili estos nomataj en sia hereda parto.","Sed viaj infanoj, kiuj naskiĝos al vi post ili, estu viaj; per la nomo de siaj fratoj ili estos nomataj en sia hereda parto."],[48,7,"Kiam mi venis el Mezopotamio, mortis ĉe mi Raĥel en la lando Kanaana, dum la vojo, kiam restis ankoraŭ iom da tero ĝis Efrata; kaj mi enterigis ŝin tie sur la vojo al Efrata, kiu estas nomata ankaŭ Bet-Leĥem.","Kiam mi venis el Mezopotamio, mortis ĉe mi Raĥel en la lando Kanaana, dum la vojo, kiam restis ankoraŭ iom da tero ĝis Efrata; kaj mi enterigis ŝin tie sur la vojo al Efrata, kiu estas nomata ankaŭ Bet-Leĥem."],[48,8,"Kaj Izrael ekvidis la filojn de Jozef, kaj diris: Kiuj estas ĉi tiuj?","Kaj Izrael ekvidis la filojn de Jozef, kaj diris: Kiuj estas ĉi tiuj?"],[48,9,"Kaj Jozef diris al sia patro: Ili estas miaj filoj, kiujn donis al mi Dio ĉi tie. Kaj tiu diris: Alkonduku ilin al mi, kaj mi benos ilin.","Kaj Jozef diris al sia patro: Ili estas miaj filoj, kiujn donis al mi Dio ĉi tie. Kaj tiu diris: Alkonduku ilin al mi, kaj mi benos ilin."],[48,10,"La okuloj de Izrael malfortiĝis de maljuneco, li ne povis bone vidi. Jozef alkondukis ilin al li, kaj li kisis ilin kaj ĉirkaŭprenis ilin.","La okuloj de Izrael malfortiĝis de maljuneco, li ne povis bone vidi. Jozef alkondukis ilin al li, kaj li kisis ilin kaj ĉirkaŭprenis ilin."],[48,11,"Kaj Izrael diris al Jozef: Vidi vian vizaĝon mi ne esperis, kaj jen Dio vidigis al mi eĉ vian idaron.","Kaj Izrael diris al Jozef: Vidi vian vizaĝon mi ne esperis, kaj jen Dio vidigis al mi eĉ vian idaron."],[48,12,"Kaj Jozef forigis ilin de liaj genuoj, kaj kliniĝis antaŭ li vizaĝaltere.","Kaj Jozef forigis ilin de liaj genuoj, kaj kliniĝis antaŭ li vizaĝaltere."],[48,13,"Kaj Jozef prenis ambaŭ, Efraimon per sia dekstra mano, kontraŭ la maldekstra de Izrael, kaj Manasen per sia maldekstra mano, kontraŭ la dekstra de Izrael, kaj alkondukis ilin al li.","Kaj Jozef prenis ambaŭ, Efraimon per sia dekstra mano, kontraŭ la maldekstra de Izrael, kaj Manasen per sia maldekstra mano, kontraŭ la dekstra de Izrael, kaj alkondukis ilin al li."],[48,14,"Sed Izrael etendis sian dekstran manon kaj metis ĝin sur la kapon de Efraim, kvankam li estis la pli juna, kaj sian maldekstran sur la kapon de Manase; li intence tiel faris per siaj manoj, ĉar Manase estis la unuenaskito.","Sed Izrael etendis sian dekstran manon kaj metis ĝin sur la kapon de Efraim, kvankam li estis la pli juna, kaj sian maldekstran sur la kapon de Manase; li intence tiel faris per siaj manoj, ĉar Manase estis la unuenaskito."],[48,15,"Kaj li benis Jozefon, kaj diris: Dio, antaŭ kiu iradis miaj patroj Abraham kaj Isaak, Dio, kiu paŝtis min de mia naskiĝo ĝis la nuna tago,","Kaj li benis Jozefon, kaj diris: Dio, antaŭ kiu iradis miaj patroj Abraham kaj Isaak, Dio, kiu paŝtis min de mia naskiĝo ĝis la nuna tago,"],[48,16,"la anĝelo, kiu savis min de ĉia malbono — Li benu la knabojn; oni nomu ilin per mia nomo kaj per la nomo de miaj patroj Abraham kaj Isaak, kaj ili kresku kaj multiĝu sur la tero.","la anĝelo, kiu savis min de ĉia malbono — Li benu la knabojn; oni nomu ilin per mia nomo kaj per la nomo de miaj patroj Abraham kaj Isaak, kaj ili kresku kaj multiĝu sur la tero."],[48,17,"Jozef vidis, ke lia patro metis sian dekstran manon sur la kapon de Efraim, kaj tio ne plaĉis al li; kaj li prenis la manon de sia patro, por deturni ĝin de la kapo de Efraim sur la kapon de Manase.","Jozef vidis, ke lia patro metis sian dekstran manon sur la kapon de Efraim, kaj tio ne plaĉis al li; kaj li prenis la manon de sia patro, por deturni ĝin de la kapo de Efraim sur la kapon de Manase."],[48,18,"Kaj Jozef diris al sia patro: Ne tiel, mia patro, ĉar ĉi tiu estas la unuenaskito; metu vian dekstran manon sur lian kapon.","Kaj Jozef diris al sia patro: Ne tiel, mia patro, ĉar ĉi tiu estas la unuenaskito; metu vian dekstran manon sur lian kapon."],[48,19,"Sed lia patro rifuzis, kaj diris: Mi scias, mia filo, mi scias; li ankaŭ fariĝos popolo kaj li ankaŭ fariĝos granda, sed lia pli juna frato estos pli granda ol li, kaj lia idaro estos multenombra inter la popoloj.","Sed lia patro rifuzis, kaj diris: Mi scias, mia filo, mi scias; li ankaŭ fariĝos popolo kaj li ankaŭ fariĝos granda, sed lia pli juna frato estos pli granda ol li, kaj lia idaro estos multenombra inter la popoloj."],[48,20,"Kaj li benis ilin en tiu tago, dirante: Per vi benados Izrael, dirante: Dio vin faru kiel Efraim kaj Manase. Kaj li metis Efraimon antaŭ Manase.","Kaj li benis ilin en tiu tago, dirante: Per vi benados Izrael, dirante: Dio vin faru kiel Efraim kaj Manase. Kaj li metis Efraimon antaŭ Manase."],[48,21,"Kaj Izrael diris al Jozef: Jen mi mortas; kaj Dio estos kun vi kaj revenigos vin en la landon de viaj patroj.","Kaj Izrael diris al Jozef: Jen mi mortas; kaj Dio estos kun vi kaj revenigos vin en la landon de viaj patroj."],[48,22,"Kaj mi donas al vi unu pecon da lando preferece antaŭ viaj fratoj, kiun mi prenis el la manoj de la Amoridoj per mia glavo kaj pafarko.","Kaj mi donas al vi unu pecon da lando preferece antaŭ viaj fratoj, kiun mi prenis el la manoj de la Amoridoj per mia glavo kaj pafarko."],[49,1,"Kaj Jakob alvokis siajn filojn, kaj diris: Kolektiĝu, kaj mi sciigos al vi, kio fariĝos al vi en la tempo venonta.","Kaj Jakob alvokis siajn filojn, kaj diris: Kolektiĝu, kaj mi sciigos al vi, kio fariĝos al vi en la tempo venonta."],[49,2,"Kunvenu kaj aŭskultu, filoj de Jakob, Kaj aŭskultu Izraelon, vian patron.","Kunvenu kaj aŭskultu, filoj de Jakob, Kaj aŭskultu Izraelon, vian patron."],[49,3,"Ruben, vi estas mia unuenaskito, Mia forto kaj komenco de mia vireco, Supro de digno kaj supro de potenco;","Ruben, vi estas mia unuenaskito, Mia forto kaj komenco de mia vireco, Supro de digno kaj supro de potenco;"],[49,4,"Rapidema kiel akvo, vi ne staros plej alte, Ĉar vi supreniris sur la liton de via patro; Tiam vi malhonoris mian liton per la supreniro.","Rapidema kiel akvo, vi ne staros plej alte, Ĉar vi supreniris sur la liton de via patro; Tiam vi malhonoris mian liton per la supreniro."],[49,5,"Simeon kaj Levi, fratoj; Iloj kruelaj estas viaj glavoj.","Simeon kaj Levi, fratoj; Iloj kruelaj estas viaj glavoj."],[49,6,"En ilian konsilon mia animo ne iru, Al ilia kunveno ne aliĝu mia honoro; Ĉar en sia kolero ili mortigis viron Kaj pro sia kaprico ili kripligis bovon.","En ilian konsilon mia animo ne iru, Al ilia kunveno ne aliĝu mia honoro; Ĉar en sia kolero ili mortigis viron Kaj pro sia kaprico ili kripligis bovon."],[49,7,"Malbenita estu ilia kolero, ĉar ĝi estas forta, Kaj ilia furiozo, ĉar ĝi estas kruela. Mi dividos ilin en Jakob, Kaj mi disĵetos ilin en Izrael.","Malbenita estu ilia kolero, ĉar ĝi estas forta, Kaj ilia furiozo, ĉar ĝi estas kruela. Mi dividos ilin en Jakob, Kaj mi disĵetos ilin en Izrael."],[49,8,"Jehuda, vin laŭdos viaj fratoj; Via mano estas sur la nuko de viaj malamikoj; Kliniĝos antaŭ vi la filoj de via patro.","Jehuda, vin laŭdos viaj fratoj; Via mano estas sur la nuko de viaj malamikoj; Kliniĝos antaŭ vi la filoj de via patro."],[49,9,"Juna leono estas Jehuda; De ĉasakiro, mia filo, vi leviĝis. Li genuiĝis, kuŝiĝis kiel leono kaj kiel leonino; Kiu lin levos?","Juna leono estas Jehuda; De ĉasakiro, mia filo, vi leviĝis. Li genuiĝis, kuŝiĝis kiel leono kaj kiel leonino; Kiu lin levos?"],[49,10,"Ne forpreniĝos sceptro de Jehuda, Nek regbastono de inter liaj piedoj, Ĝis venos paco Kaj al li humiliĝos la popoloj.","Ne forpreniĝos sceptro de Jehuda, Nek regbastono de inter liaj piedoj, Ĝis venos paco Kaj al li humiliĝos la popoloj."],[49,11,"Li alligas al la vinbertrunko sian azenidon Kaj al la delikata vinberbranĉo la filon de sia azenino; Li lavas en vino sian veston Kaj en sango de vinberoj sian mantelon.","Li alligas al la vinbertrunko sian azenidon Kaj al la delikata vinberbranĉo la filon de sia azenino; Li lavas en vino sian veston Kaj en sango de vinberoj sian mantelon."],[49,12,"Liaj okuloj estas ruĝaj de vino Kaj la dentoj blankaj de lakto.","Liaj okuloj estas ruĝaj de vino Kaj la dentoj blankaj de lakto."],[49,13,"Zebulun loĝos ĉe la bordo de maro, Ĉe albordiĝejo de ŝipoj, Kaj lia limo atingos Cidonon.","Zebulun loĝos ĉe la bordo de maro, Ĉe albordiĝejo de ŝipoj, Kaj lia limo atingos Cidonon."],[49,14,"Isaĥar estas fortosta azeno; Li kuŝos inter la baraĵoj.","Isaĥar estas fortosta azeno; Li kuŝos inter la baraĵoj."],[49,15,"Kaj li vidis, ke ripozo estas bona Kaj la tero estas agrabla; Kaj li klinis sian ŝultron por portado Kaj fariĝis laboristo por tributo.","Kaj li vidis, ke ripozo estas bona Kaj la tero estas agrabla; Kaj li klinis sian ŝultron por portado Kaj fariĝis laboristo por tributo."],[49,16,"Dan juĝos sian popolon, Kiel unu el la triboj de Izrael.","Dan juĝos sian popolon, Kiel unu el la triboj de Izrael."],[49,17,"Dan estos serpento ĉe la vojo, Cerasto ĉe la irejo, Mordanto de kalkano de ĉevalo, Ke ĝia rajdanto falas malantaŭen.","Dan estos serpento ĉe la vojo, Cerasto ĉe la irejo, Mordanto de kalkano de ĉevalo, Ke ĝia rajdanto falas malantaŭen."],[49,18,"Vian helpon mi esperas, ho Eternulo.","Vian helpon mi esperas, ho Eternulo."],[49,19,"Gadon premos amaso, Sed li repremos ĝin je la kalkano.","Gadon premos amaso, Sed li repremos ĝin je la kalkano."],[49,20,"Ĉe Aŝer estas grasa lia pano, Kaj li liverados frandaĵojn al reĝoj.","Ĉe Aŝer estas grasa lia pano, Kaj li liverados frandaĵojn al reĝoj."],[49,21,"Naftali estas belkura cervo; Li donas belajn parolojn.","Naftali estas belkura cervo; Li donas belajn parolojn."],[49,22,"Fruktoporta arbo estas Jozef, Fruktoporta arbo super fonto; La branĉoj etendiĝis super la muron.","Fruktoporta arbo estas Jozef, Fruktoporta arbo super fonto; La branĉoj etendiĝis super la muron."],[49,23,"Ĉagrenis lin pafistoj Kaj pafis kaj malamikis kontraŭ li;","Ĉagrenis lin pafistoj Kaj pafis kaj malamikis kontraŭ li;"],[49,24,"Sed forta restis lia pafarko Kaj elastaj estas liaj brakoj, Per la manoj de la Potenculo de Jakob, Per la Paŝtisto, la Roko de Izrael.","Sed forta restis lia pafarko Kaj elastaj estas liaj brakoj, Per la manoj de la Potenculo de Jakob, Per la Paŝtisto, la Roko de Izrael."],[49,25,"La Dio de via patro donos al vi helpon, La Plejpotenculo benos vin Per benoj de la ĉielo supre, Per benoj de la abismo, kiu kuŝas malsupre, Per benoj de la mamoj kaj de la utero.","La Dio de via patro donos al vi helpon, La Plejpotenculo benos vin Per benoj de la ĉielo supre, Per benoj de la abismo, kiu kuŝas malsupre, Per benoj de la mamoj kaj de la utero."],[49,26,"La benoj de via patro estas pli fortaj, Ol la benoj de miaj gepatroj, Ĝis la limo de la eternaj altaĵoj. Ili estu sur la kapo de Jozef Kaj sur la verto de la elektito inter liaj fratoj.","La benoj de via patro estas pli fortaj, Ol la benoj de miaj gepatroj, Ĝis la limo de la eternaj altaĵoj. Ili estu sur la kapo de Jozef Kaj sur la verto de la elektito inter liaj fratoj."],[49,27,"Benjamen estas lupo karnoŝira; Matene li manĝos ĉasakiron, Kaj vespere li dividos rabaĵon.","Benjamen estas lupo karnoŝira; Matene li manĝos ĉasakiron, Kaj vespere li dividos rabaĵon."],[49,28,"Tio estas ĉiuj dek du triboj de Izrael; kaj tio estas, kion diris al ili ilia patro; kaj li benis ilin, ĉiun per aparta beno li benis.","Tio estas ĉiuj dek du triboj de Izrael; kaj tio estas, kion diris al ili ilia patro; kaj li benis ilin, ĉiun per aparta beno li benis."],[49,29,"Kaj li ordonis al ili, kaj diris al ili: Mi alkolektiĝas al mia popolo; enterigu min apud miaj patroj en la kaverno, kiu troviĝas sur la kampo de Efron la Ĥetido,","Kaj li ordonis al ili, kaj diris al ili: Mi alkolektiĝas al mia popolo; enterigu min apud miaj patroj en la kaverno, kiu troviĝas sur la kampo de Efron la Ĥetido,"],[49,30,"en la duobla kampa kaverno, kiu troviĝas antaŭ Mamre en la lando Kanaana kaj kiun Abraham aĉetis kune kun la kampo de Efron la Ĥetido kiel tomban posedaĵon.","en la duobla kampa kaverno, kiu troviĝas antaŭ Mamre en la lando Kanaana kaj kiun Abraham aĉetis kune kun la kampo de Efron la Ĥetido kiel tomban posedaĵon."],[49,31,"Tie oni enterigis Abrahamon kaj lian edzinon Sara, tie oni enterigis Isaakon kaj lian edzinon Rebeka, kaj tie mi enterigis Lean,","Tie oni enterigis Abrahamon kaj lian edzinon Sara, tie oni enterigis Isaakon kaj lian edzinon Rebeka, kaj tie mi enterigis Lean,"],[49,32,"sur la kampo kaj en la kaverno sur ĝi, kiuj estas aĉetitaj de el la filoj de Ĥet.","sur la kampo kaj en la kaverno sur ĝi, kiuj estas aĉetitaj de el la filoj de Ĥet."],[49,33,"Kaj Jakob finis la ordonadon al siaj filoj, kaj li kunigis siajn piedojn sur la lito, kaj mortis kaj alkolektiĝis al sia popolo.","Kaj Jakob finis la ordonadon al siaj filoj, kaj li kunigis siajn piedojn sur la lito, kaj mortis kaj alkolektiĝis al sia popolo."],[50,1,"Tiam Jozef ĵetis sin sur la vizaĝon de sia patro, kaj ploris super li kaj kisis lin.","Tiam Jozef ĵetis sin sur la vizaĝon de sia patro, kaj ploris super li kaj kisis lin."],[50,2,"Kaj Jozef ordonis al siaj servantoj kuracistoj, balzami lian patron; kaj la kuracistoj balzamis Izraelon.","Kaj Jozef ordonis al siaj servantoj kuracistoj, balzami lian patron; kaj la kuracistoj balzamis Izraelon."],[50,3,"Kaj pasis super li kvardek tagoj; ĉar tiel longe daŭras la tagoj de balzamado. Kaj la Egiptoj ploris pri li sepdek tagojn.","Kaj pasis super li kvardek tagoj; ĉar tiel longe daŭras la tagoj de balzamado. Kaj la Egiptoj ploris pri li sepdek tagojn."],[50,4,"Kiam pasis la tagoj de lia priplorado, Jozef ekparolis al la domanoj de Faraono, dirante: Se mi akiris vian favoron, diru al Faraono jene:","Kiam pasis la tagoj de lia priplorado, Jozef ekparolis al la domanoj de Faraono, dirante: Se mi akiris vian favoron, diru al Faraono jene:"],[50,5,"Mia patro ĵurigis min, dirante: Jen mi mortas; en mia tombo, kiun mi elfosis al mi en la lando Kanaana, tie vi min enterigu. Nun mi volus iri, enterigi mian patron, kaj reveni.","Mia patro ĵurigis min, dirante: Jen mi mortas; en mia tombo, kiun mi elfosis al mi en la lando Kanaana, tie vi min enterigu. Nun mi volus iri, enterigi mian patron, kaj reveni."],[50,6,"Kaj Faraono diris: Iru kaj enterigu vian patron, kiel li ĵurigis vin.","Kaj Faraono diris: Iru kaj enterigu vian patron, kiel li ĵurigis vin."],[50,7,"Kaj Jozef iris, por enterigi sian patron; kaj kun li iris ĉiuj servantoj de Faraono, la ĉefoj de lia domo kaj ĉiuj ĉefoj de la lando Egipta,","Kaj Jozef iris, por enterigi sian patron; kaj kun li iris ĉiuj servantoj de Faraono, la ĉefoj de lia domo kaj ĉiuj ĉefoj de la lando Egipta,"],[50,8,"kaj la tuta domo de Jozef, kaj liaj fratoj kaj la domo de lia patro; nur siajn infanojn kaj siajn malgrandajn kaj grandajn brutojn ili restigis en la lando Goŝen.","kaj la tuta domo de Jozef, kaj liaj fratoj kaj la domo de lia patro; nur siajn infanojn kaj siajn malgrandajn kaj grandajn brutojn ili restigis en la lando Goŝen."],[50,9,"Kun ili iris ankaŭ ĉaroj kaj rajdantoj; kaj la anaro estis tre granda.","Kun ili iris ankaŭ ĉaroj kaj rajdantoj; kaj la anaro estis tre granda."],[50,10,"Ili venis al la placo Atad, kiu estas transe de Jordan, kaj ili faris tie grandan kaj fortan priploradon; kaj li funebris pri sia patro dum sep tagoj.","Ili venis al la placo Atad, kiu estas transe de Jordan, kaj ili faris tie grandan kaj fortan priploradon; kaj li funebris pri sia patro dum sep tagoj."],[50,11,"Kiam la loĝantoj de la lando Kanaana vidis la funebron sur la placo Atad, ili diris: Ĝi estas granda funebro ĉe la Egiptoj; tial la loko ricevis la nomon Abel-Micraim. Ĝi estas transe de Jordan.","Kiam la loĝantoj de la lando Kanaana vidis la funebron sur la placo Atad, ili diris: Ĝi estas granda funebro ĉe la Egiptoj; tial la loko ricevis la nomon Abel-Micraim. Ĝi estas transe de Jordan."],[50,12,"Kaj liaj infanoj faris kun li, kiel li ordonis al ili.","Kaj liaj infanoj faris kun li, kiel li ordonis al ili."],[50,13,"Kaj liaj filoj forportis lin en la landon Kanaanan, kaj enterigis lin en la kampa duobla kaverno, kiun Abraham aĉetis kune kun la kampo kiel tomban posedaĵon de el Efron la Ĥetido, antaŭ Mamre.","Kaj liaj filoj forportis lin en la landon Kanaanan, kaj enterigis lin en la kampa duobla kaverno, kiun Abraham aĉetis kune kun la kampo kiel tomban posedaĵon de el Efron la Ĥetido, antaŭ Mamre."],[50,14,"Kaj Jozef revenis Egiptujon, li kaj liaj fratoj, kaj ĉiuj, kiuj iris kun li, por enterigi lian patron, post kiam ili enterigis lian patron.","Kaj Jozef revenis Egiptujon, li kaj liaj fratoj, kaj ĉiuj, kiuj iris kun li, por enterigi lian patron, post kiam ili enterigis lian patron."],[50,15,"Kiam la fratoj de Jozef vidis, ke ilia patro mortis, ili diris: Eble Jozef ekmalamos nin, kaj repagos al ni pro la tuta malbono, kiun ni faris al li?","Kiam la fratoj de Jozef vidis, ke ilia patro mortis, ili diris: Eble Jozef ekmalamos nin, kaj repagos al ni pro la tuta malbono, kiun ni faris al li?"],[50,16,"Tial ili sendis al Jozef, por diri al li: Via patro ordonis antaŭ sia morto jene:","Tial ili sendis al Jozef, por diri al li: Via patro ordonis antaŭ sia morto jene:"],[50,17,"Tiel diru al Jozef: Mi petas vin, pardonu la kulpon de viaj fratoj kaj ilian pekon, ĉar ili faris al vi malbonon. Nun pardonu do la kulpon de la sklavoj de la Dio de via patro. Kaj Jozef ploris, kiam ili parolis al li.","Tiel diru al Jozef: Mi petas vin, pardonu la kulpon de viaj fratoj kaj ilian pekon, ĉar ili faris al vi malbonon. Nun pardonu do la kulpon de la sklavoj de la Dio de via patro. Kaj Jozef ploris, kiam ili parolis al li."],[50,18,"Kaj iris liaj fratoj mem kaj ĵetis sin teren antaŭ li, kaj diris: Jen ni estas sklavoj al vi.","Kaj iris liaj fratoj mem kaj ĵetis sin teren antaŭ li, kaj diris: Jen ni estas sklavoj al vi."],[50,19,"Sed Jozef diris al ili: Ne timu; ĉar ĉu mi estas anstataŭ Dio?","Sed Jozef diris al ili: Ne timu; ĉar ĉu mi estas anstataŭ Dio?"],[50,20,"Vi intencis fari al mi malbonon; sed Dio aranĝis de tio bonon, por fari tiel, kiel nun estas, por konservi la vivon de multe da homoj.","Vi intencis fari al mi malbonon; sed Dio aranĝis de tio bonon, por fari tiel, kiel nun estas, por konservi la vivon de multe da homoj."],[50,21,"Kaj nun ne timu; mi nutros vin kaj viajn infanojn. Kaj li konsolis ilin kaj parolis al ili kore.","Kaj nun ne timu; mi nutros vin kaj viajn infanojn. Kaj li konsolis ilin kaj parolis al ili kore."],[50,22,"Kaj Jozef loĝis en Egiptujo, li kaj la domo de lia patro; kaj Jozef vivis cent dek jarojn.","Kaj Jozef loĝis en Egiptujo, li kaj la domo de lia patro; kaj Jozef vivis cent dek jarojn."],[50,23,"Kaj Jozef vidis ĉe Efraim infanojn ĝis la tria generacio; ankaŭ la infanoj de Maĥir, filo de Manase, naskiĝis sur la genuoj de Jozef.","Kaj Jozef vidis ĉe Efraim infanojn ĝis la tria generacio; ankaŭ la infanoj de Maĥir, filo de Manase, naskiĝis sur la genuoj de Jozef."],[50,24,"Kaj Jozef diris al siaj fratoj: Mi mortas, sed Dio rememoros vin, kaj elkondukos vin el ĉi tiu lando en la landon, pri kiu Li ĵuris al Abraham, Isaak, kaj Jakob.","Kaj Jozef diris al siaj fratoj: Mi mortas, sed Dio rememoros vin, kaj elkondukos vin el ĉi tiu lando en la landon, pri kiu Li ĵuris al Abraham, Isaak, kaj Jakob."],[50,25,"Kaj Jozef ĵurigis la filojn de Izrael, dirante: Kiam Dio rememoros vin, tiam elportu miajn ostojn el ĉi tie.","Kaj Jozef ĵurigis la filojn de Izrael, dirante: Kiam Dio rememoros vin, tiam elportu miajn ostojn el ĉi tie."],[50,26,"Kaj Jozef mortis en la aĝo de cent dek jaroj; kaj oni balzamis lin kaj metis lin en ĉerkon en Egiptujo.","Kaj Jozef mortis en la aĝo de cent dek jaroj; kaj oni balzamis lin kaj metis lin en ĉerkon en Egiptujo."]]}};